window.JVVNL_BANKS=window.JVVNL_BANKS||{};JVVNL_BANKS['management-accounting']={"slug":"management-accounting","name":"Management Accounting","count":430,"questions":[{"id":"pyq-638","sourceNumber":638,"subject":"management-accounting","subjectName":"Management Accounting","question":"Match List I with List II List I I. Inability to pay interest II. Liquidity crisis III. Inefficient collection of receivables IV. Return of shareholder’s fund being much higher than the overall return on investment List II 1. Current ratio 2. Debt turnover ratio 3. Interest coverage ratio 4. Debts equity ratio Choose the correct answer from the options given below:","options":["I-3, II-1, III-2, IV-4","I-3, II-2, III-1, IV-4","I-2, II-3, III-1, IV-4","I-1, II-2, III-3, IV-4"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why A is correct:** Inability to pay interest is measured by the Interest Coverage Ratio (I–3); a liquidity crisis is assessed using the Current Ratio (II–1); inefficient receivables collection relates to Debtors Turnover (III–2); and a high return to shareholders relative to overall return can relate to leverage/ debt-equity (IV–4) in the source’s framework. **Exam cue:** interest → coverage; liquidity → current ratio; collection → debtor turnover.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"2095980e32d270c7e979cfa8f40728b17dc6be5c8e509f79913013d32b5d36be","kind":"pyq"},{"id":"pyq-640","sourceNumber":640,"subject":"management-accounting","subjectName":"Management Accounting","question":"Net Present Value and Internal Rate of Return methods yield conflicting outcomes due to_________. I. Unconventional cash flows II. Investment size disparity III. Investment life disparity IV. Cash flow pattern disparity Choose the correct answer from the options given below:","options":["I and II only","II and III only","I, II and III only","II, III and IV only"],"answer":3,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why D is correct in the source’s framework — II, III and IV:** NPV and IRR can rank mutually exclusive projects differently when project scale, project life or the timing/pattern of cash flows differs. NPV measures absolute value added; IRR measures a percentage return, so their rankings may conflict. Unconventional cash flows can create multiple IRRs, but that is a separate issue rather than the standard scale/life/pattern ranking conflict. **Exam cue:** scale, life and timing differences → NPV/IRR ranking conflict.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"7495d5d8ac074db6d7d185c0452f8a365f9b61c16300ca70241a7855377f7a1c","kind":"pyq"},{"id":"pyq-641","sourceNumber":641,"subject":"management-accounting","subjectName":"Management Accounting","question":"The value of the firm in wealth maximisation objective is measured by","options":["Present value of all expected future cash flows","All expected future cash flows","Present value of all expected future profits","All expected future profits"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is correct:** The wealth-maximisation objective measures firm value as the present value of expected future cash flows, discounted for their timing and risk. Undiscounted cash flows or accounting profits ignore the time value of money and risk. **Exam cue:** shareholder wealth → present value of expected cash flows.","sourceAnswer":2,"auditStatus":"corrected-key","auditNote":"Original supplied answer retained in sourceAnswer; answer independently checked and corrected in this audit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"a170f46160218fc3baf491f04dc507273398abcf320e5991831f14a1d89b21b0","kind":"pyq"},{"id":"pyq-642","sourceNumber":642,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following rules stands true while preparing schedule of changes in working capital? 1. An increase in current assets increases working capital 2. An increase in current assets decreases working capital 3. An increase in current liabilities decreases working capital 4. An increase in current liabilities increases working capital Choose the most appropriate answer from the options given below.","options":["1 and 3 only","1 and 4 only","2 and 4 only","1, 2 and 3 only"],"answer":0,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why A is correct — 1 and 3 only:** Working capital = Current Assets − Current Liabilities. An increase in current assets increases working capital, while an increase in current liabilities decreases working capital. The opposite changes have the opposite effects. **Memory cue:** CA up → WC up; CL up → WC down.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"30717a570d31fb305eaaa94df8107ecf5f1406cadf9c4c0a2f082e77270fa18c","kind":"pyq"},{"id":"pyq-643","sourceNumber":643,"subject":"management-accounting","subjectName":"Management Accounting","question":"Match List I with List II: List I (a) Market risk (b) Financial risk (c) External business risk (d) Internal business risk List II (i) Associated with the efficiency with which a firm conducts its operations within the broader environment imposed upon it. (ii) Arises due to change in operating conditions caused by conditions thrust upon the firm which are beyond its control. (iii) Variations in price sparked off due to real, social, political and economic events. (iv) Associated with the capital structure of a firm. Choose the correct answer from the options given below.","options":["(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)","(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)","(a)-(iii), (b)-(i), (c)-(ii), (d)-(iv)","(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)"],"answer":1,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why B is correct:** Market risk arises from price changes driven by economic, social or political events (a–iii). Financial risk is linked to the firm’s capital structure (b–iv). External business risk comes from conditions beyond the firm’s control (c–ii), while internal business risk relates to the efficiency with which the firm operates within its environment (d–i). **Exam cue:** market = price events; financial = leverage; external = uncontrollable; internal = operations.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"4b3c6f1d115b517cf6fc001e637a5157df95c04e424ef8a59258abad1f7a95d7","kind":"pyq"},{"id":"pyq-644","sourceNumber":644,"subject":"management-accounting","subjectName":"Management Accounting","question":"The cash flow approach to assessing debt capacity involves the following steps: arrange these steps in a correct sequence: (1) Specify the tolerance limit on the probability of default. (2) Estimate the probability distribution of cash flows, taking into account the projected performance of the firm. (3) Calculate the fixed charges by way of interest payment and principal repayment associated with various levels of debt. (4) Estimate the debt capacity of the firm as the highest level of debt which is acceptable. Choose the correct answer from the options given below:","options":["4, 3, 1, 2","1, 2, 3, 4","2, 3, 4, 1","4, 1, 3, 2"],"answer":1,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why B is the supplied sequence — 1, 2, 3, 4:** Set the acceptable tolerance for default probability (1), estimate the probability distribution of future cash flows (2), calculate interest and principal charges at different debt levels (3), then identify the highest debt level that stays within the risk tolerance (4). This sequence sets the risk criterion before testing the cash-flow capacity. **Exam cue:** risk limit → cash-flow distribution → debt service → debt capacity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"fa8a0ee570443704291c2292c2bcfe51e6d1d1199b9b96b5c31bd649d0b9c219","kind":"pyq"},{"id":"pyq-645","sourceNumber":645,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following are three pillars of BASEL —II? a. Minimum Capital Requirements. b. Supervisory Review c. Leverage d. Market Discipline e. Capital Conservation Buffer. Choose the correct answer from the options given below:","options":["a, c, d only","a, d, e only","a, b, d only","b, c, e only"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — a, b and d:** Basel II rests on three pillars: minimum capital requirements (Pillar 1), supervisory review (Pillar 2) and market discipline/disclosure (Pillar 3). Leverage and the capital conservation buffer are associated with later Basel III developments, not the three pillars of Basel II. **Memory cue:** Basel II = capital, supervision, market discipline.","sourceAnswer":0,"auditStatus":"corrected-key","auditNote":"Original supplied answer retained in sourceAnswer; answer independently checked and corrected in this audit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"d55ae9ec48d545f9e894518d7dea88da7092a79758d687587ee1acf7a530707b","kind":"pyq"},{"id":"pyq-647","sourceNumber":647,"subject":"management-accounting","subjectName":"Management Accounting","question":"Rearrange the steps followed in evaluating an investment proposal using NPV method: a. Calculate the present value of cash flows . b. Identify an appropriate discount rate. c. Forecasting cash flows. d. Rank the projects as per NPV. e. Compute the net present value. Choose the correct answer from the options given below:","options":["b, e, a, d, c","a, b, c, d, e","c, b, a, e, d","d, a, c, b, e"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — c, b, a, e, d:** First forecast project cash flows (c), choose an appropriate discount rate (b), calculate the present value of each cash flow (a), compute NPV by subtracting the initial investment (e), and rank projects by NPV (d). **Memory cue:** forecast → discount rate → PV → NPV → rank.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"082c914b299e63efe8032b6105cfd2103b4c02b012580a73dbddc9e114b74480","kind":"pyq"},{"id":"pyq-648","sourceNumber":648,"subject":"management-accounting","subjectName":"Management Accounting","question":"From the following, select the right option with reference to the working capital:","options":["Higher net working capital leads to higher liquidity and higher profitability.","According to hedging approach, current assets should be financed from long-term sources.","There is an inverse relationship between the length of operating cycle of a firm and its working capital requirements","Trade-off plan, in general, is considered an appropriate financing strategy for working capital."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — Trade-off plan:** The trade-off approach balances liquidity and profitability by matching permanent working-capital needs with long-term funding and financing fluctuating needs with suitable short-term sources. Excessively high net working capital can lower profitability, and the hedging/matching approach does not generally finance all current assets from long-term sources. **Exam cue:** trade-off balances cost, risk, liquidity and profitability.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"d48a576977ce116874a805afc6e2f9ae33b57a64a5f9f68d810e35a0bfd9dc2a","kind":"pyq"},{"id":"pyq-649","sourceNumber":649,"subject":"management-accounting","subjectName":"Management Accounting","question":"A prudent financial policy suggested by Marris Hypothesis to maximize balanced growth of the firm is based on which of following financial ratios? (a) Return on investment ratio. (b) Debt equity ratio. (c) Return on capital employed ratio. (d) Liquidity ratio. (e) Retention ratio. Choose the most appropriate answer from the options given below:","options":["a, b and c only.","b, c and d only.","a, c and d only.","b, d and e only."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — b, d and e:** Marris’s balanced-growth hypothesis focuses on growth subject to managerial and financial constraints. Debt-equity, liquidity and retention ratios are relevant financial constraints/policies: leverage affects risk, liquidity affects the ability to meet obligations, and retention determines funds available for growth. **Exam cue:** balanced growth is constrained by finance and liquidity as well as growth ambitions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"66bad90341215989a820c184858d658246f1cf99c7f81aff76dc7711f4fcd8e5","kind":"pyq"},{"id":"pyq-650","sourceNumber":650,"subject":"management-accounting","subjectName":"Management Accounting","question":"Match List I with List II : List I (Type of Exposure): (a) Economic Exposure. (b) Translation Exposure. (c) Transaction Exposure. (d) Operating Exposure. List II (Description): (i) Potential changes in all future cash flows of a firm that result from unanticipated changes in exchange rates. (ii) It arises when items of financial statements that are stated in foreign currencies are restated in the home currency of an MNC. (iii) It arises when a firm’s contract obligations are exposed to unanticipated changes in exchange rate. (iv) When a firm’s real assets are exposed to unanticipated changes in exchange rates. Choose the correct answer from the options given below:","options":["a- iii, b- iv, c- ii, d- i","a- i, b- ii, c- iii, d- iv","a- iv, b- iii, c- ii, d- i","a- i, b- iv, c- iii, d- ii"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct:** Economic exposure concerns potential changes in future cash flows from unexpected exchange-rate movements (a–i). Translation exposure arises when foreign-currency financial statements are restated into the parent’s currency (b–ii). Transaction exposure concerns contractual foreign-currency receivables/payables (c–iii). Operating exposure concerns the effect of exchange rates on real assets/operating competitiveness and cash flows (d–iv). **Exam cue:** economic = future cash flows; translation = statements; transaction = contracts; operating = real operations/assets.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"9f310f895e757e563944d2413106d41a6c32e87c07eb9a0231e8111bd06198da","kind":"pyq"},{"id":"pyq-651","sourceNumber":651,"subject":"management-accounting","subjectName":"Management Accounting","question":"Arrange the following ratios in the ascending order of their significance in the prediction of industrial sickness (Altman, 1966): A. B. C. Working Capital Total Assets Retained Earnings Total Assets Earnings Before Interest and Taxes Total Assets Market Value of Equity D. Book Value of Total Debt Sales E. Total Assets Choose the correct answer from the options given below.","options":["D, E, A, B, C","C, E, B, D, A","B, D, C, A, E","E, B, D, C, A"],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why A is the supplied order — D, E, A, B, C:** Altman’s original Z-score uses ratios including working capital/total assets, retained earnings/total assets, EBIT/total assets, market value of equity/book value of total debt, and sales/total assets. This question asks for an order of significance, not the Z-score formula itself. The supplied order places the debt/equity market-value ratio and asset turnover ratio before the working-capital, retained-earnings and EBIT ratios. **Exam note:** the ranking is source-specific; remember the original model’s five ratios and weights separately.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"d43afad5601987ab17f545198070c75062523044dade8ad9f87a4b526283ff3f","kind":"pyq"},{"id":"pyq-652","sourceNumber":652,"subject":"management-accounting","subjectName":"Management Accounting","question":"As per which one of the following approaches, a firm finances a part of its permanent working capital with short term financing?","options":["Matching Approach","Conservating Approach","Aggressive Approach","Traditional Approach"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — Aggressive approach:** An aggressive working-capital financing policy uses short-term funds to finance not only temporary needs but also part of permanent working capital. It may lower financing cost but increases refinancing and liquidity risk. A matching approach aligns asset life with financing maturity, while a conservative approach relies more on long-term funding. **Exam cue:** short-term funding for permanent working capital → aggressive approach.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"090e5a82442d082b368fb856c98e09058fd316346bbf7cd403f877fc6b1f3535","kind":"pyq"},{"id":"pyq-653","sourceNumber":653,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which one of the following approaches of capital structure pleads that debt financing initially increases the value of the firm; however excess debt financing beyond a particular point reduced the value of the firm?","options":["Net Income Approach","Net Operating Income Approach","Traditional Approach","Modigliani-Miller Approach"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — Traditional approach:** The traditional capital-structure approach holds that moderate debt can reduce the overall cost of capital and increase firm value, but excessive leverage raises financial risk and the required returns of investors, eventually reducing value. **Memory cue:** debt helps up to an optimum point; beyond it, value falls.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"f4feb95b5ed146ffd6507669a7d52d1deb7ad188d63b50263ac2ec06cf311f13","kind":"pyq"},{"id":"pyq-655","sourceNumber":655,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following activities are included under investing activities in the Cash Flow Statement? a. Cash receipts from disposal of fixed assets (including intangible). b. Cash advances and loans made to third parties (other than advances and loans made by a financial enterprise). c. Cash receipts from repayment of advances and loans made to third parties (other than advances and loans of a financial enterprise). d. Cash repayments of amount borrowed. e. Cash payments to suppliers for goods and services. Choose the correct answer from the options given below: Codes","options":["a, b and c only","c, d and e only","c and d only","a, c and d only"],"answer":0,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct — a, b and c:** Cash proceeds from disposal of fixed/intangible assets are investing inflows; cash advances and loans made to third parties are investing outflows; and cash received when those advances/loans are repaid is an investing inflow. Repayment of borrowings is a financing activity, while payments to suppliers are operating activities. **Exam cue:** fixed assets and non-financial-enterprise loans → investing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"5cda7f676c40c5db78439edd9c4c4b9b6d8018dbfa78d9242b83d13a127fe9d8","kind":"pyq"},{"id":"pyq-656","sourceNumber":656,"subject":"management-accounting","subjectName":"Management Accounting","question":"The Internal Rate of Return (IRR) method offer which of the following advantages? A. It recognises the time value of money. B. It is consistent with the shareholders' profit-maximization objective also. C. It considers all cash flows occurring over the entire life of the project. D. It generally gives the same acceptance rule as the NPV method. E. It considers all positive NPV over the entire life of the project. Choose the correct answer from the options given below: Codes","options":["A, B and C only","B, C and E only","A, B, C and D only","A, D and E only"],"answer":2,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why C is correct — A, B, C and D:** IRR discounts cash flows and therefore recognises the time value of money; it considers cash flows over the project’s life; and for conventional independent projects it generally gives an acceptance decision consistent with NPV when compared with the cost of capital. It is also commonly presented as consistent with wealth maximisation, though NPV is usually more reliable for ranking mutually exclusive projects. **Exam trap:** IRR can conflict with NPV for projects of different scale/timing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"5f0d34c1d4efe2863af35561b3ce2ac5cd82c9d18d75690b673445381dbde2de","kind":"pyq"},{"id":"pyq-658","sourceNumber":658,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following factors determine the requirements of working capital of a firm? a. Nature of Business b. Technology and Manufacturing Policy c. Management Skills d. Credit Policy e. Market and Demand Conditions Choose the correct answer from the options given below: Codes","options":["a, b, c and d only","a, b, d, and e only","c, d and e only","a, b and e only"],"answer":1,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why B is correct — a, b, d and e:** Working-capital requirements are influenced by the nature of the business, production technology/manufacturing policy, credit terms and market demand. These factors affect inventory levels, production time, receivables, payables and the operating cycle. Management skill matters in controlling working capital, but the supplied source’s selected combination omits it. **Exam cue:** working capital = inventory + receivables − payables, influenced by business and credit cycle.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"6077736cdc7a2e405d6d5e0d36eb0be2ef14ece0b7accdcdf86ef7fc180bf709","kind":"pyq"},{"id":"pyq-659","sourceNumber":659,"subject":"management-accounting","subjectName":"Management Accounting","question":"In the context of banking sector. Spread is defined as a function of the following: a) Forex b) Net Interest income c) Rate Sensitive Assets d) Asset Ratio e) Leverage Ratio Choose the correct answer from the options given below:","options":["c and e only","a and c only","b and d only","b and e only"],"answer":2,"source":"UGC NET Commerce, Jun 2023","explanation":"**Why C is correct — b and d:** Bank spread is commonly understood as the difference between interest earned on assets and interest paid on liabilities, often analysed relative to earning assets or total assets. Net interest income is central to the measure, and the asset ratio is part of the source’s framing. Forex and leverage ratios are not the direct defining components in this question. **Exam cue:** banking spread → net interest income relative to assets/funding cost.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"8c2ddc506b160f09dd1d7d530ffa9ca8b11a13f11381550231610d6b8613ef7a","kind":"pyq"},{"id":"pyq-660","sourceNumber":660,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the followings are the approaches of determining the financing mix for working capital : A. Matching Approach B. Conservative Approach C. Operating Cycle Approach D. Aggressive Approach Choose the correct answer from the options given below","options":["B,C and D Only","A, Band D Only","A, Cand D Only","A, Band C Only"],"answer":1,"source":"UGC NET Commerce, Dec 2025","explanation":"**Why B is correct — A, B and D:** Matching, conservative and aggressive approaches are recognised methods for determining the financing mix for working capital. The operating-cycle approach helps estimate the amount/duration of working capital required but is not itself one of the standard financing-mix policies. **Exam distinction:** operating cycle estimates need; matching/conservative/aggressive decide financing mix.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"d098afa4c4dd7a7b5822f3f8ba23b9d056e61eda0cc8f92d7d6699e19204a416","kind":"pyq"},{"id":"pyq-661","sourceNumber":661,"subject":"management-accounting","subjectName":"Management Accounting","question":"An infinite series of equal cash flow occurring at regular time interval is known as","options":["An Annuity","An Annuity Due","Perpetuity","Future Value"],"answer":2,"source":"UGC NET Commerce, Dec 2025","explanation":"**Why C is correct — Perpetuity:** A perpetuity is an infinite stream of equal cash flows occurring at regular intervals. An annuity is a finite series of regular cash flows; an annuity due pays at the beginning of each period; future value is the accumulated value of cash flows at a future date. **Memory cue:** infinite equal payments → perpetuity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"9bd58b126833e9135b1191ece0222564545ed522cc3b57c0eeff657799d330ee","kind":"pyq"},{"id":"pyq-662","sourceNumber":662,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following ratio is also termed as leverage ratio?","options":["Debt equity ratio","Solvency ratio","Proprietary ratio","Interest coverage ratio"],"answer":0,"source":"SSC CGL AAO, 2017","explanation":"**Why A is correct — Debt-equity ratio:** The debt-equity ratio compares borrowed funds with owners’ equity and is a common leverage ratio. It indicates the extent to which the company is financed by debt relative to equity. Solvency ratio is a broader category; proprietary ratio measures owners’ funds relative to assets; interest coverage measures ability to pay interest. **Exam cue:** leverage → debt/equity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"a5d049e3126150ac2e5e5c54fc148cf8d727eeee5ca96dce19f06c024aa95cb0","kind":"pyq"},{"id":"pyq-663","sourceNumber":663,"subject":"management-accounting","subjectName":"Management Accounting","question":"Proceeds from sale of patent is classified under which activity in Cash Flow Statement?","options":["Investing","Operating","Financing","Cash"],"answer":0,"source":"SSC CGL AAO, 2017","explanation":"**Why A is correct — Investing activity:** Proceeds from selling a patent arise from disposal of an intangible long-term asset, so they are classified as investing cash flow. Operating activities cover the main revenue-producing operations; financing activities cover changes in equity and borrowings. **Exam cue:** purchase/sale of long-term assets → investing.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"7b47724183d740612eaa6ec5ba83ef1645b2960f91044b1aaea2a184ba3e76de","kind":"pyq"},{"id":"pyq-664","sourceNumber":664,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following statements is correct in the context of the payback period? I. It is expressed in terms of the number of years. II. Different industries or companies may have varying acceptable payback periods based on their risk tolerance and capital structure. II. It takes into account the time value of money. IV. It ignores profitability measures. V. It considers cash flows beyond the payback period.","options":["I, III and V only","I, II and V only","I, III and IV only","I, II and IV only"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct — I, II and IV:** Payback period is expressed in time, and acceptable payback limits vary by industry, risk tolerance and financing conditions. The simple payback method ignores the time value of money and ignores cash flows occurring after the payback point. Therefore statement III is false and statement V is false. **Exam cue:** simple payback = recovery time, not full profitability.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"c62c6985570176fb269132f2432fd1e7229163808c16d7b56ffd9245e1a9a67d","kind":"pyq"},{"id":"pyq-665","sourceNumber":665,"subject":"management-accounting","subjectName":"Management Accounting","question":"Cash payment for self-constructed property is to be classified as:","options":["Cash Flow from Financing Activities","Cash Flow from Investing Activities","Cash Flow from Operating Activities","Either B or C"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — Investing activities:** Cash payments to construct or acquire property, plant and equipment are investing cash outflows because they create or improve long-term assets. Financing activities relate to equity/debt; operating activities relate to ordinary business operations. **Exam cue:** self-constructed fixed asset → investing cash flow.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"95b6c830ca90d953a0aeef1b87e41b8b26475e0cb3575916eaa3f2f9d0ec7901","kind":"pyq"},{"id":"pyq-666","sourceNumber":666,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following statements is correct in the context of AS-19? I. This accounting standard comes into effect in respect of all assets leased on or after 1st April, 2001 and is mandatory. II. AS-19 does not apply to agreements that are contracts for services that do not transfer the right to use the assets from one contracting party to the other. III. From an accounting perspective, leases can be only of three types: Operating lease, Finance lease, and Leveraged lease. IV. An operating lease is classified as a dry lease if the lessor provides the know-how and related services for operating the asset and takes care of its insurance and maintenance. V. If The lease term is substantially less than the economic life of the asset, the lease is classified as a finance lease.","options":["I, II and IV only","I and II only","II, III, IV and V only","III and only"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — I and II only:** AS 19 applies to leases within its scope and excludes service contracts that do not transfer the right to use an asset. Traditional accounting classifies leases as operating or finance leases; leveraged lease is a financing structure, not a separate third basic lease classification. A dry lease does not mean the lessor supplies crew/maintenance/insurance; that description is closer to a wet lease. The finance-lease criterion in V is not correct as a blanket rule. **Exam cue:** AS 19 → operating vs finance; wet lease includes services.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"bd736c29ba563a175c85ced9009378f405dd8e99e140de37c097b6a2b02c382d","kind":"pyq"},{"id":"pyq-667","sourceNumber":667,"subject":"management-accounting","subjectName":"Management Accounting","question":"The degree of financial leverage may be defined as:","options":["percent change in sales/percent change in volume","percent change in EPS/percent change in net income","percent change in EPS/percent change in EBIT","percent change in EPS/percent change in sales"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is correct:** Degree of financial leverage measures the percentage change in earnings per share (EPS) relative to the percentage change in EBIT. It captures the effect of fixed financing costs, such as interest, on equity earnings. **Formula:** DFL = % change in EPS ÷ % change in EBIT.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"a6447608a439c039c1883b4b6ef392aca181f6f5271581775a93e74c76b14e1a","kind":"pyq"},{"id":"pyq-668","sourceNumber":668,"subject":"management-accounting","subjectName":"Management Accounting","question":"Which of the following best describes the Working Capital?","options":["Total Assets – Liabilities","Capital contributed by the owners","Current Assets – Current Liabilities","Cash + Inventory"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is correct — Current assets minus current liabilities:** Net working capital = Current Assets − Current Liabilities. It represents the short-term resources remaining after current obligations are covered. Cash plus inventory alone is incomplete because it ignores receivables and current liabilities. **Exam cue:** net working capital = CA − CL.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"a79e27b4f663b19ae0f980999e56792cd97d7f37b742c5ca8a7f10ed10a7a2a8","kind":"pyq"},{"id":"pyq-669","sourceNumber":669,"subject":"management-accounting","subjectName":"Management Accounting","question":"Match the following: I. Test of Liquidity A. ROI II. Test of Profitability B. Debtors turnover III. Test of Solvency C. Acid test ratio IV. Test of Activity D. Debt equity ratio","options":["I-A, II-B, III-C, IV-D","I-B, II-C, III-A, IV-D","I-C, II-A, III-D, IV-B","I-C, II-D, III-B, IV-A"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is correct:** Liquidity is tested by the acid-test/quick ratio (I–C); profitability by ROI (II–A); solvency by the debt-equity ratio (III–D); and activity/efficiency by debtors turnover (IV–B). **Memory cue:** liquidity = quick ratio; profitability = ROI; solvency = debt/equity; activity = turnover.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"f2ecb630b75bbe01e2dd3535545a50916d60dff3d9685fd2625ad7981aebb877","kind":"pyq"},{"id":"original-extra-051","sourceNumber":"EX-051","subject":"management-accounting","subjectName":"Management Accounting","question":"Management accounting is mainly intended to support:","options":["Only tax collection","Only bank reconciliation","Internal planning, control and decisions","Only external statutory filing"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"Management accounting supplies information for internal managerial decisions.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"742f9bb1e8c3e34c5a43c834cba0e40a7243ec5228f5a1c8460308e5c051cc34","kind":"mcq"},{"id":"original-extra-052","sourceNumber":"EX-052","subject":"management-accounting","subjectName":"Management Accounting","question":"A current ratio is calculated as:","options":["Current liabilities ÷ sales","Inventory ÷ capital","Net profit ÷ fixed assets","Current assets ÷ current liabilities"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"Current ratio measures short-term liquidity.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"56c9064c265079bd8dbd83aa94c10df977508a26d8eb2c237c0304f3b2b6d747","kind":"mcq"},{"id":"original-extra-053","sourceNumber":"EX-053","subject":"management-accounting","subjectName":"Management Accounting","question":"Quick assets usually exclude:","options":["Inventory and prepaid expenses","Cash and bank balances","Short-term receivables","Marketable securities"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"The quick ratio excludes less-liquid inventory and generally prepaid expenses.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"98e50c0a1f53986eb3d1cedd64be6cd7e074a8c4e5db1bc988d7cdf3391757c9","kind":"mcq"},{"id":"original-extra-054","sourceNumber":"EX-054","subject":"management-accounting","subjectName":"Management Accounting","question":"Return on capital employed commonly relates operating profit to:","options":["Cash sales only","Capital employed","Current liabilities alone","Gross purchases"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"ROCE measures operating return relative to capital employed; exact numerator conventions should be stated.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"6da1f06b87067cf27db3d504418761af0a101875707f715cba917722658894e6","kind":"mcq"},{"id":"original-extra-055","sourceNumber":"EX-055","subject":"management-accounting","subjectName":"Management Accounting","question":"A cash budget forecasts:","options":["Only annual profit","Only inventory quantities","Cash receipts and payments","Only non-cash depreciation"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"A cash budget estimates cash inflows, outflows and financing needs over a period.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"f141937b3a0ab3c201ac6e13fae6718e949b5c0daaad6ead787fa3fc51c0db18","kind":"mcq"},{"id":"original-extra-056","sourceNumber":"EX-056","subject":"management-accounting","subjectName":"Management Accounting","question":"Zero-based budgeting requires managers to:","options":["Increase every budget by last year's percentage","Budget only fixed costs","Take last year's figures without examining alternatives","Justify activities and expenditure from a zero base"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"ZBB evaluates activities from the ground up rather than automatically rolling forward prior budgets.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Zero-based budgeting requires managers to:","options":["Increase every budget by last year's percentage","Budget only fixed costs","Ignore alternatives","Justify activities and expenditure from a zero base"],"answer":3,"explanation":"ZBB evaluates activities from the ground up rather than automatically rolling forward prior budgets.","revision":"original","contentSignature":"7d35704f5503cc9ae3d622cf2d17623d436fb6d895107b613ac2838ee1e6c602"}],"contentSignature":"ec31f8f82260b84e248ed6c975530020f3ddedc2b7b0c929a5bec885642e4503","legacySubject":"management-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-057","sourceNumber":"EX-057","subject":"management-accounting","subjectName":"Management Accounting","question":"A standard cost is:","options":["A predetermined cost benchmark under stated conditions","Always the actual cost incurred","A historical figure of sales","A rate of tax laid down by law"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"Standard costs provide benchmarks for control and variance analysis.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A standard cost is:","options":["A predetermined cost benchmark under stated conditions","Always the actual cost paid","A historical sales figure","A tax rate"],"answer":0,"explanation":"Standard costs provide benchmarks for control and variance analysis.","revision":"original","contentSignature":"68fbfa9d5e0c24a77d8dc83c9705efed85714e46a71c5510e296575dd85991cb"}],"contentSignature":"4d368da53c656cfd06ac4427c624cef3400ac331a40e29e8605ca0a22e1735ce","legacySubject":"management-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-058","sourceNumber":"EX-058","subject":"management-accounting","subjectName":"Management Accounting","question":"A favourable sales volume variance under a contribution approach commonly indicates:","options":["No sales took place during the period","Actual volume generated more contribution than budgeted","The fixed costs ceased to exist","The actual selling price was necessarily lower than budgeted"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"Favourability depends on actual volume versus budget and the variance convention used.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A favourable sales volume variance under a contribution approach commonly indicates:","options":["No sales occurred","Actual volume generated more contribution than budgeted","Fixed costs disappeared","Actual selling price was necessarily lower"],"answer":1,"explanation":"Favourability depends on actual volume versus budget and the variance convention used.","revision":"original","contentSignature":"9bcc387c928124da931bc242de55f4ab96531070fc00da025e0783c4c061e8e3"}],"contentSignature":"515231bc5442b2338ddc97cfc1ee795165a2a7c6c45c2a209832348ea20f1eba","legacySubject":"management-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-059","sourceNumber":"EX-059","subject":"management-accounting","subjectName":"Management Accounting","question":"The break-even point is where:","options":["Fixed cost is zero","Sales are always maximum","Total revenue equals total cost","Contribution is zero in all cases"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"At break-even, profit is zero because total revenue equals total cost.","legacySubject":"management-accounting","sourceBank":"shared","contentSignature":"ae14eddd7c1f1d19ed40038a558c7263167a0dc80cdd02dc98fb1ee07df66229","kind":"mcq"},{"id":"original-extra-060","sourceNumber":"EX-060","subject":"management-accounting","subjectName":"Management Accounting","question":"A funds flow statement traditionally analyses changes in:","options":["The sales returns of the period alone","The share premium account alone","The minute-to-minute cash receipts of the business","Working capital between two balance-sheet dates"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"Funds flow analysis traditionally focuses on sources and applications of funds and working-capital changes.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A funds flow statement traditionally analyses changes in:","options":["Only sales returns","Only share premium","Only cash receipts every minute","Working capital between two balance-sheet dates"],"answer":3,"explanation":"Funds flow analysis traditionally focuses on sources and applications of funds and working-capital changes.","revision":"original","contentSignature":"a7bbc2e885cf98d2569bfd55c80b45a058719672c0ec33384a91ea5dfc5cb88a"}],"contentSignature":"a9204bca9fc650390039f93194b47678fb7d51ca748872af20dafac33b3ed246","legacySubject":"management-accounting","sourceBank":"shared","kind":"mcq"},{"id":"deep-management-MA001","sourceNumber":1,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Management accounting is best described as:","options":["A statutory system of recording the transactions of the business, maintained only to satisfy the requirements of the Companies Act","The application of accounting techniques (financial, cost and statistical) to provide information for PLANNING, CONTROL and DECISION- MAKING by management","The preparation of the annual financial statements of the business for the shareholders and the Registrar","The audit of the cost records of the business by the cost auditor appointed under the Companies Act - and management accounting is nothing more than this statutory audit of cost records, done once a year for the Registrar"],"answer":1,"explanation":"Management accounting serves internal users; it has no statutory format and uses both historical and future-oriented data.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA001","number":1,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Management accounting is best described as:","options":[{"key":"A","text":"A statutory system of recording the transactions of the business, maintained only to satisfy the requirements of the Companies Act"},{"key":"B","text":"The application of accounting techniques (financial, cost and statistical) to provide information for PLANNING, CONTROL and DECISION- MAKING by management"},{"key":"C","text":"The preparation of the annual financial statements of the business for the shareholders and the Registrar"},{"key":"D","text":"The audit of the cost records of the business by the cost auditor appointed under the Companies Act - and management accounting is nothing more than this statutory audit of cost records, done once a year for the Registrar"}],"answer":"B","explanation":"Management accounting serves internal users; it has no statutory format and uses both historical and future-oriented data.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Management accounting is best described as:","options":["A statutory system of recording transactions","The application of accounting techniques (financial, cost and statistical) to provide information for PLANNING, CONTROL and DECISION- MAKING by management","Preparation of annual financial statements","Audit of cost records"],"answer":1,"explanation":"Management accounting serves internal users; it has no statutory format and uses both historical and future-oriented data.","revision":"original","contentSignature":"5d9d9e655084ce2fb032153f44930d1580f0a467839953216b73b629696bc41e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA001","optionFormat":"letter"},"contentSignature":"035480d7c09384738e0ee449a032afbd5c112e4b7e926ee0e6a0637371a04833","kind":"mcq"},{"id":"deep-management-MA002","sourceNumber":2,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Management accounting information is primarily meant for:","options":["Income-tax authorities","INTERNAL management at all levels","Creditors","Shareholders"],"answer":1,"explanation":"Financial accounting serves external users; management accounting serves internal decision-makers.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA002","number":2,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Management accounting information is primarily meant for:","options":[{"key":"A","text":"Income-tax authorities"},{"key":"B","text":"INTERNAL management at all levels"},{"key":"C","text":"Creditors"},{"key":"D","text":"Shareholders"}],"answer":"B","explanation":"Financial accounting serves external users; management accounting serves internal decision-makers.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA002","optionFormat":"letter"},"contentSignature":"48362e73a4ee82e500c7aef418b34f91cd8880eba111c7ab7ddfef0572b34a0d","kind":"mcq"},{"id":"deep-management-MA003","sourceNumber":3,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which is TRUE of management accounting?","options":["It is OPTIONAL/FACULTATIVE - prepared as and when needed, using future-oriented and estimated data","It is COMPULSORY for all the companies registered under the Companies Act, 2013","It deals only with the past data of the business, and never with the future","It follows the GAAP strictly in every respect, just as financial accounting does"],"answer":0,"explanation":"No statute mandates management accounting; its reports are tailor-made, frequent and forward-looking.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA003","number":3,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which is TRUE of management accounting?","options":[{"key":"A","text":"It is OPTIONAL/FACULTATIVE - prepared as and when needed, using future-oriented and estimated data"},{"key":"B","text":"It is COMPULSORY for all the companies registered under the Companies Act, 2013"},{"key":"C","text":"It deals only with the past data of the business, and never with the future"},{"key":"D","text":"It follows the GAAP strictly in every respect, just as financial accounting does"}],"answer":"A","explanation":"No statute mandates management accounting; its reports are tailor-made, frequent and forward-looking.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is TRUE of management accounting?","options":["It is OPTIONAL/FACULTATIVE - prepared as and when needed, using future-oriented and estimated data","It is COMPULSORY for all companies","It deals only with past data","It follows GAAP strictly"],"answer":0,"explanation":"No statute mandates management accounting; its reports are tailor-made, frequent and forward-looking.","revision":"original","contentSignature":"c2b807467fa328f62e2db0274636be3dbb9b63d6cbe7cd1e8879ed93a23177c0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA003","optionFormat":"letter"},"contentSignature":"3f53b8446951b2dcc5a7c03e9af0b370922557eccc027550b4cb46ebf89398b2","kind":"mcq"},{"id":"deep-management-MA004","sourceNumber":4,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The MAIN tools and techniques of management accounting do NOT include:","options":["Double-entry bookkeeping","Marginal costing and capital budgeting","Budgetary control and standard costing","Ratio analysis, fund flow and cash flow analysis"],"answer":0,"explanation":"Double entry is the recording mechanism of financial accounting; MA borrows and analyses the resulting data.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA004","number":4,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The MAIN tools and techniques of management accounting do NOT include:","options":[{"key":"A","text":"Double-entry bookkeeping"},{"key":"B","text":"Marginal costing and capital budgeting"},{"key":"C","text":"Budgetary control and standard costing"},{"key":"D","text":"Ratio analysis, fund flow and cash flow analysis"}],"answer":"A","explanation":"Double entry is the recording mechanism of financial accounting; MA borrows and analyses the resulting data.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA004","optionFormat":"letter"},"contentSignature":"600189cf4ff814bf0ba8573b266a8a3b8a055b51d19effca816bedd400dcf821","kind":"mcq"},{"id":"deep-management-MA005","sourceNumber":5,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Management accounting is broader than cost accounting because it:","options":["Combines FINANCIAL accounting + COST accounting + statistical tools to serve managerial decisions","It deals only with the future costs of the business, and never with the past","It applies only to the service industries, and never to the manufacturing concerns","It ignores the cost data altogether, relying on the financial statements alone"],"answer":0,"explanation":"Cost accounting is a subset; management accounting additionally uses financial statements, budgets, ratios and statistics.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA005","number":5,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Management accounting is broader than cost accounting because it:","options":[{"key":"A","text":"Combines FINANCIAL accounting + COST accounting + statistical tools to serve managerial decisions"},{"key":"B","text":"It deals only with the future costs of the business, and never with the past"},{"key":"C","text":"It applies only to the service industries, and never to the manufacturing concerns"},{"key":"D","text":"It ignores the cost data altogether, relying on the financial statements alone"}],"answer":"A","explanation":"Cost accounting is a subset; management accounting additionally uses financial statements, budgets, ratios and statistics.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Management accounting is broader than cost accounting because it:","options":["Combines FINANCIAL accounting + COST accounting + statistical tools to serve managerial decisions","Deals only with future costs","Applies only to service industries","Ignores cost data"],"answer":0,"explanation":"Cost accounting is a subset; management accounting additionally uses financial statements, budgets, ratios and statistics.","revision":"original","contentSignature":"9df280b7f0c7a20b32771dddc77621688040bf68ed0e116c60404534ae679230"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA005","optionFormat":"letter"},"contentSignature":"9a38208999d81773a49e5f7026c5ca084cba4a372f0a68499950f34d602e895c","kind":"mcq"},{"id":"deep-management-MA006","sourceNumber":6,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which of the following is a CHARACTERISTIC of management accounting?","options":["The reports are prepared only once a year, at the close of the financial year","The reports are always audited by the statutory auditor before they are used","Reports may be at ANY interval, for ANY segment, in ANY format suited to the decision","It deals only with monetary and financial data drawn from the accounting records of the firm"],"answer":2,"explanation":"Flexibility of period, segment and format is the essence of MA; it also uses qualitative and non-monetary data.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA006","number":6,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which of the following is a CHARACTERISTIC of management accounting?","options":[{"key":"A","text":"The reports are prepared only once a year, at the close of the financial year"},{"key":"B","text":"The reports are always audited by the statutory auditor before they are used"},{"key":"C","text":"Reports may be at ANY interval, for ANY segment, in ANY format suited to the decision"},{"key":"D","text":"It deals only with monetary and financial data drawn from the accounting records of the firm"}],"answer":"C","explanation":"Flexibility of period, segment and format is the essence of MA; it also uses qualitative and non-monetary data.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is a CHARACTERISTIC of management accounting?","options":["Reports are prepared only once a year","Reports are always audited","Reports may be at ANY interval, for ANY segment, in ANY format suited to the decision","It is concerned only with monetary data"],"answer":2,"explanation":"Flexibility of period, segment and format is the essence of MA; it also uses qualitative and non-monetary data.","revision":"original","contentSignature":"252e69f84977c154579f52f9a360e0a331266e324077675d799255dccc687a99"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA006","optionFormat":"letter"},"contentSignature":"c5dbf4604b84d7a112e8e26f1b1b7ea7886c697ec69427cd094033c695a8793e","kind":"mcq"},{"id":"deep-management-MA007","sourceNumber":7,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The installation of a management accounting system is:","options":["Compulsory under the Income-tax Act, 1961, for every assessee carrying on a business","Compulsory under the Companies Act, 2013, for every company registered under it","Required by SEBI for every listed company, as a condition of the listing","OPTIONAL - it depends on the management own appreciation of its utility"],"answer":3,"explanation":"Unlike financial or (for specified industries) cost records, MA reporting has no legal mandate.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA007","number":7,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The installation of a management accounting system is:","options":[{"key":"A","text":"Compulsory under the Income-tax Act, 1961, for every assessee carrying on a business"},{"key":"B","text":"Compulsory under the Companies Act, 2013, for every company registered under it"},{"key":"C","text":"Required by SEBI for every listed company, as a condition of the listing"},{"key":"D","text":"OPTIONAL - it depends on the management own appreciation of its utility"}],"answer":"D","explanation":"Unlike financial or (for specified industries) cost records, MA reporting has no legal mandate.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The installation of a management accounting system is:","options":["Compulsory under the Income-tax Act","Compulsory under the Companies Act","Required by SEBI","OPTIONAL - it depends on the management own appreciation of its utility"],"answer":3,"explanation":"Unlike financial or (for specified industries) cost records, MA reporting has no legal mandate.","revision":"original","contentSignature":"49fb76ca8ccb63e62d26f9d62c7b54702fac0a48eec8ab2d3ab1fec4240f81f0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA007","optionFormat":"letter"},"contentSignature":"075f41b5471a2be7a67d24d8eb25d646f4e5890b932628fd3f40cdab3ea111a7","kind":"mcq"},{"id":"deep-management-MA008","sourceNumber":8,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The scope of management accounting includes all EXCEPT:","options":["Tax planning and inventory control","Financial accounting and analysis","Cost accounting and budgetary control","STATUTORY audit of accounts"],"answer":3,"explanation":"Audit is an independent attestation function; MA covers planning, control, decision analysis, reporting and tax planning.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA008","number":8,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The scope of management accounting includes all EXCEPT:","options":[{"key":"A","text":"Tax planning and inventory control"},{"key":"B","text":"Financial accounting and analysis"},{"key":"C","text":"Cost accounting and budgetary control"},{"key":"D","text":"STATUTORY audit of accounts"}],"answer":"D","explanation":"Audit is an independent attestation function; MA covers planning, control, decision analysis, reporting and tax planning.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA008","optionFormat":"letter"},"contentSignature":"aaf0f9f7f9b2e8cd70dbae195c3407f21c27851dde6ab0a7e75b0f93693434b6","kind":"mcq"},{"id":"deep-management-MA009","sourceNumber":9,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Management accounting reports are generally:","options":["Published in newspapers","CONFIDENTIAL internal documents, not published","Sent to shareholders","Filed with the Registrar of Companies"],"answer":1,"explanation":"MA reports are internal and confidential; external users have no right to them.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA009","number":9,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Management accounting reports are generally:","options":[{"key":"A","text":"Published in newspapers"},{"key":"B","text":"CONFIDENTIAL internal documents, not published"},{"key":"C","text":"Sent to shareholders"},{"key":"D","text":"Filed with the Registrar of Companies"}],"answer":"B","explanation":"MA reports are internal and confidential; external users have no right to them.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA009","optionFormat":"letter"},"contentSignature":"e8873d82864d2ce513f8df97ce7c3277c11585d69d6939713205f3f78991e612","kind":"mcq"},{"id":"deep-management-MA010","sourceNumber":10,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The chief limitation of management accounting is that it:","options":["It cannot use the future data of the business at all, being wholly confined to the past records of the concern","It is not recognised as a legitimate tool of management by the law","DEPENDS on the accuracy of financial and cost records and involves heavy cost and broad (not deep) coverage","It cannot show the segment data of the business at all, being wholly confined to the figures of the whole concern"],"answer":2,"explanation":"MA conclusions are only as good as the underlying financial/cost records; other limits: costly, broad-based, prone to personal bias, evolutionary stage.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA010","number":10,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The chief limitation of management accounting is that it:","options":[{"key":"A","text":"It cannot use the future data of the business at all, being wholly confined to the past records of the concern"},{"key":"B","text":"It is not recognised as a legitimate tool of management by the law"},{"key":"C","text":"DEPENDS on the accuracy of financial and cost records and involves heavy cost and broad (not deep) coverage"},{"key":"D","text":"It cannot show the segment data of the business at all, being wholly confined to the figures of the whole concern"}],"answer":"C","explanation":"MA conclusions are only as good as the underlying financial/cost records; other limits: costly, broad-based, prone to personal bias, evolutionary stage.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The chief limitation of management accounting is that it:","options":["Cannot use future data","Is illegal","DEPENDS on the accuracy of financial and cost records and involves heavy cost and broad (not deep) coverage","Cannot show segment data"],"answer":2,"explanation":"MA conclusions are only as good as the underlying financial/cost records; other limits: costly, broad-based, prone to personal bias, evolutionary stage.","revision":"original","contentSignature":"55a0156c166a1d8cdc5e939959f044c522e5e006f43d97ac8be80045861a66c3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA010","optionFormat":"letter"},"contentSignature":"99d88d3c4d44327e0b89b4a84b0613f132a170a20359ad4c4d03c32887df17fc","kind":"mcq"},{"id":"deep-management-MA011","sourceNumber":11,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The term \"management accounting\" was FIRST formally used (in its modern sense) by:","options":["The Anglo-American Council on Productivity team (1950) - popularising the use of accounting information for management","CIMA in the year 2000, at its London convention of the member bodies of the accountancy profession","The ICAI in the year 1949, at the time of its own establishment in India under the Act of Parliament","The SEC of the United States, in its regulations framed in the year 1934 after the crash"],"answer":0,"explanation":"The 1950 Anglo-American productivity team report popularised management accounting; the ICPAI/ICWAI and CIMA later institutionalised it.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA011","number":11,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The term \"management accounting\" was FIRST formally used (in its modern sense) by:","options":[{"key":"A","text":"The Anglo-American Council on Productivity team (1950) - popularising the use of accounting information for management"},{"key":"B","text":"CIMA in the year 2000, at its London convention of the member bodies of the accountancy profession"},{"key":"C","text":"The ICAI in the year 1949, at the time of its own establishment in India under the Act of Parliament"},{"key":"D","text":"The SEC of the United States, in its regulations framed in the year 1934 after the crash"}],"answer":"A","explanation":"The 1950 Anglo-American productivity team report popularised management accounting; the ICPAI/ICWAI and CIMA later institutionalised it.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The term \"management accounting\" was FIRST formally used (in its modern sense) by:","options":["The Anglo-American Council on Productivity team (1950) - popularising the use of accounting information for management","CIMA in 2000","The ICAI in 1949","The SEC"],"answer":0,"explanation":"The 1950 Anglo-American productivity team report popularised management accounting; the ICPAI/ICWAI and CIMA later institutionalised it.","revision":"original","contentSignature":"c4264b1b6ab58e9f03beb0ca93031949fd6ba72dd55e5f9926a80197321196fd"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA011","optionFormat":"letter"},"contentSignature":"e8f247821996a02b4f53bd5b2770cf29cc16bcad7e151b7216407a38044dd777","kind":"mcq"},{"id":"deep-management-MA012","sourceNumber":12,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which of the following is NOT an objective of management accounting?","options":["Coordinating and decision-making","Maintaining the statutory books of account","Controlling operations through budgets and standards","Planning and policy formulation"],"answer":1,"explanation":"Statutory record-keeping is financial accounting; MA objectives are planning, organising, coordinating, motivating, communicating and controlling.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA012","number":12,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which of the following is NOT an objective of management accounting?","options":[{"key":"A","text":"Coordinating and decision-making"},{"key":"B","text":"Maintaining the statutory books of account"},{"key":"C","text":"Controlling operations through budgets and standards"},{"key":"D","text":"Planning and policy formulation"}],"answer":"B","explanation":"Statutory record-keeping is financial accounting; MA objectives are planning, organising, coordinating, motivating, communicating and controlling.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA012","optionFormat":"letter"},"contentSignature":"7e7e21ea3388b2eb4757c03f27391ec71a0551b1568ef8da05582586d960bc75","kind":"mcq"},{"id":"deep-management-MA013","sourceNumber":13,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Management accounting is concerned with:","options":["Only the whole enterprise as a single unit, and never its segments at all","Only the external reporting of the enterprise, and never the internal needs","Only the factory floor of the enterprise, and never the office or the market","The enterprise AS A WHOLE AND ITS SEGMENTS - departments, products, territories"],"answer":3,"explanation":"Segment reporting (division, product line, region) is a hallmark of MA.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA013","number":13,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Management accounting is concerned with:","options":[{"key":"A","text":"Only the whole enterprise as a single unit, and never its segments at all"},{"key":"B","text":"Only the external reporting of the enterprise, and never the internal needs"},{"key":"C","text":"Only the factory floor of the enterprise, and never the office or the market"},{"key":"D","text":"The enterprise AS A WHOLE AND ITS SEGMENTS - departments, products, territories"}],"answer":"D","explanation":"Segment reporting (division, product line, region) is a hallmark of MA.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Management accounting is concerned with:","options":["Only the whole enterprise","Only external reporting","Only the factory floor","The enterprise AS A WHOLE AND ITS SEGMENTS - departments, products, territories"],"answer":3,"explanation":"Segment reporting (division, product line, region) is a hallmark of MA.","revision":"original","contentSignature":"d1f38a052655a12714b7c5dcdd7788990d7ffc10a163515296129a515884a595"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA013","optionFormat":"letter"},"contentSignature":"89ba2b7a6add58a4b45249672b47aab47e9195ec68db8913f634158514e2298f","kind":"mcq"},{"id":"deep-management-MA014","sourceNumber":14,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The PRIMARY emphasis of management accounting is on:","options":["The historical recording of the transactions of the business, day by day","FUTURE planning and decision-making (though it analyses past data)","The audit of the accounts of the business, as required by the statute","The tax compliance of the business, as required by the Income-tax Act"],"answer":1,"explanation":"MA is forward-looking: budgets, forecasts, project appraisal and what-if analysis dominate.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA014","number":14,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The PRIMARY emphasis of management accounting is on:","options":[{"key":"A","text":"The historical recording of the transactions of the business, day by day"},{"key":"B","text":"FUTURE planning and decision-making (though it analyses past data)"},{"key":"C","text":"The audit of the accounts of the business, as required by the statute"},{"key":"D","text":"The tax compliance of the business, as required by the Income-tax Act"}],"answer":"B","explanation":"MA is forward-looking: budgets, forecasts, project appraisal and what-if analysis dominate.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PRIMARY emphasis of management accounting is on:","options":["Historical recording","FUTURE planning and decision-making (though it analyses past data)","Audit","Tax compliance"],"answer":1,"explanation":"MA is forward-looking: budgets, forecasts, project appraisal and what-if analysis dominate.","revision":"original","contentSignature":"d288484df25c98ef9f2820b92b94db66f086fd87a26e0819467fcb228d3b68b4"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA014","optionFormat":"letter"},"contentSignature":"82cc34cd7787e298af201de7f392eefd3c81bdb36fb38a64e7481abecf29a188","kind":"mcq"},{"id":"deep-management-MA015","sourceNumber":15,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"A management accountant in India is professionally associated with:","options":["The ICSI - the Institute of Company Secretaries of India","The Institute of COST ACCOUNTANTS of India (ICMAI)","The RBI - the central bank of the country","The ICAI - the Institute of Chartered Accountants of India"],"answer":1,"explanation":"Cost and management accountants are regulated by the ICMAI (formerly ICWAI); the qualification is CMA.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA015","number":15,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"A management accountant in India is professionally associated with:","options":[{"key":"A","text":"The ICSI - the Institute of Company Secretaries of India"},{"key":"B","text":"The Institute of COST ACCOUNTANTS of India (ICMAI)"},{"key":"C","text":"The RBI - the central bank of the country"},{"key":"D","text":"The ICAI - the Institute of Chartered Accountants of India"}],"answer":"B","explanation":"Cost and management accountants are regulated by the ICMAI (formerly ICWAI); the qualification is CMA.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A management accountant in India is professionally associated with:","options":["ICSI","The Institute of COST ACCOUNTANTS of India (ICMAI)","RBI","ICAI"],"answer":1,"explanation":"Cost and management accountants are regulated by the ICMAI (formerly ICWAI); the qualification is CMA.","revision":"original","contentSignature":"fb83e63a18315162a6a55838eb6ef3ee0e999759c216e19464c65587161c0762"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA015","optionFormat":"letter"},"contentSignature":"eede507660721fb3c1d266ac660bb3e3f1759194550c77ab716e9998bd53f3f1","kind":"mcq"},{"id":"deep-management-MA016","sourceNumber":16,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which statement distinguishes management accounting from FINANCIAL accounting?","options":["The financial accounting has no rules at all, while the management accounting follows GAAP strictly","FA is mandatory and historical/external; MA is optional, analytical, internal and future-oriented","The management accounting uses only the cash basis of accounting, while the financial accounting uses the accrual","The management accounting reports to SEBI directly, while the financial accounting reports to the shareholders"],"answer":1,"explanation":"Financial accounting = stewardship + external reporting under GAAP/statute; management accounting = internal decision support.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA016","number":16,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which statement distinguishes management accounting from FINANCIAL accounting?","options":[{"key":"A","text":"The financial accounting has no rules at all, while the management accounting follows GAAP strictly"},{"key":"B","text":"FA is mandatory and historical/external; MA is optional, analytical, internal and future-oriented"},{"key":"C","text":"The management accounting uses only the cash basis of accounting, while the financial accounting uses the accrual"},{"key":"D","text":"The management accounting reports to SEBI directly, while the financial accounting reports to the shareholders"}],"answer":"B","explanation":"Financial accounting = stewardship + external reporting under GAAP/statute; management accounting = internal decision support.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which statement distinguishes management accounting from FINANCIAL accounting?","options":["FA has no rules","FA is mandatory and historical/external; MA is optional, analytical, internal and future-oriented","MA uses only cash basis","MA reports to SEBI"],"answer":1,"explanation":"Financial accounting = stewardship + external reporting under GAAP/statute; management accounting = internal decision support.","revision":"original","contentSignature":"5ffc47251ab2547f3b18e7c5792873cdef45990eb6b1b016fbb457bf91da0fde"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA016","optionFormat":"letter"},"contentSignature":"345b57636a85014c34a8243ed812f6f56d5d41fa5ab0523dc077e9a84555d606","kind":"mcq"},{"id":"deep-management-MA017","sourceNumber":17,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which statement distinguishes management accounting from COST accounting?","options":["The cost accounting covers the whole information system of the business, while the management accounting covers only a part","They are identical in every respect, being two names for the same discipline","Cost accounting RECORDS and analyses costs; management accounting ADDITIONALLY uses financial data and other tools for decisions","The cost accounting is external in its orientation, while the management accounting is internal"],"answer":2,"explanation":"Cost accounting feeds cost data into the wider MA system; MA uses cost + financial + statistical data.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA017","number":17,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which statement distinguishes management accounting from COST accounting?","options":[{"key":"A","text":"The cost accounting covers the whole information system of the business, while the management accounting covers only a part"},{"key":"B","text":"They are identical in every respect, being two names for the same discipline"},{"key":"C","text":"Cost accounting RECORDS and analyses costs; management accounting ADDITIONALLY uses financial data and other tools for decisions"},{"key":"D","text":"The cost accounting is external in its orientation, while the management accounting is internal"}],"answer":"C","explanation":"Cost accounting feeds cost data into the wider MA system; MA uses cost + financial + statistical data.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which statement distinguishes management accounting from COST accounting?","options":["Cost accounting covers the whole information system","They are identical","Cost accounting RECORDS and analyses costs; management accounting ADDITIONALLY uses financial data and other tools for decisions","Cost accounting is external"],"answer":2,"explanation":"Cost accounting feeds cost data into the wider MA system; MA uses cost + financial + statistical data.","revision":"original","contentSignature":"f0e08d593512b9c51ca47e3b83d5285a317b45dfe88aef1c1976aea9c99750b7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA017","optionFormat":"letter"},"contentSignature":"1f7a99aa736d469fd2f635d68d65318058f676e26bd1c5c35952fdd3ab29fe49","kind":"mcq"},{"id":"deep-management-MA018","sourceNumber":18,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Responsibility accounting, a part of management accounting, means:","options":["The government accounting of the departments, as practised by the CAG of India","Assigning costs/revenues to RESPONSIBILITY CENTRES headed by managers accountable for them","The accounting for the social responsibility of the business, as required by the Companies Act","The accounting only for the owners of the business, and for no one else at all"],"answer":1,"explanation":"Responsibility centres (cost, revenue, profit, investment centres) pin performance to the manager who controls it.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA018","number":18,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Responsibility accounting, a part of management accounting, means:","options":[{"key":"A","text":"The government accounting of the departments, as practised by the CAG of India"},{"key":"B","text":"Assigning costs/revenues to RESPONSIBILITY CENTRES headed by managers accountable for them"},{"key":"C","text":"The accounting for the social responsibility of the business, as required by the Companies Act"},{"key":"D","text":"The accounting only for the owners of the business, and for no one else at all"}],"answer":"B","explanation":"Responsibility centres (cost, revenue, profit, investment centres) pin performance to the manager who controls it.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Responsibility accounting, a part of management accounting, means:","options":["Government accounting","Assigning costs/revenues to RESPONSIBILITY CENTRES headed by managers accountable for them","Accounting for social responsibility","Accounting only for owners"],"answer":1,"explanation":"Responsibility centres (cost, revenue, profit, investment centres) pin performance to the manager who controls it.","revision":"original","contentSignature":"b80d7e47436e76a2e0394d7813e230d2f3eb0b39f2e6f51d447b6c10d5f4f44b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA018","optionFormat":"letter"},"contentSignature":"3167e98fb65b2685f0c56fd65d9a97ddf6db32c263d82bc71346228e500ec28b","kind":"mcq"},{"id":"deep-management-MA019","sourceNumber":19,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"The information supplied by management accounting should be:","options":["Only the audited figures, however late they may be available to the managers","Always rounded to lakhs","Always rounded to the lakhs, so that the managers are not confused by the detail","APPROXIMATE BUT TIMELY - relevance and speed matter more than exact precision"],"answer":3,"explanation":"MA accepts approximate figures prepared quickly; delayed precision has no decision value.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA019","number":19,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"The information supplied by management accounting should be:","options":[{"key":"A","text":"Only the audited figures, however late they may be available to the managers"},{"key":"B","text":"Always rounded to lakhs"},{"key":"C","text":"Always rounded to the lakhs, so that the managers are not confused by the detail"},{"key":"D","text":"APPROXIMATE BUT TIMELY - relevance and speed matter more than exact precision"}],"answer":"D","explanation":"MA accepts approximate figures prepared quickly; delayed precision has no decision value.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The information supplied by management accounting should be:","options":["Only audited","Always rounded to lakhs","Precise even if late","APPROXIMATE BUT TIMELY - relevance and speed matter more than exact precision"],"answer":3,"explanation":"MA accepts approximate figures prepared quickly; delayed precision has no decision value.","revision":"original","contentSignature":"086f40fe5f8f5c9554cb7331f983cc38d983379b6bdbd7b70fabab025714855f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA019","optionFormat":"letter"},"contentSignature":"7241726c1996dd05c6dbae66587ba6ddb7dae6337d8256dee244ddc109d1b5f5","kind":"mcq"},{"id":"deep-management-MA020","sourceNumber":20,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M0 · Management Accounting - Nature, Scope & Tools","question":"Which of the following pairs are BOTH techniques of management accounting?","options":["Trial balance and journal","Bank reconciliation and audit","Ratio analysis and cash flow analysis","Ledger posting and vouching"],"answer":2,"explanation":"Ratio analysis and fund/cash flow analysis are core MA analytical tools; the others are bookkeeping/audit processes.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA020","number":20,"module":"M0","moduleTitle":"Management Accounting - Nature, Scope & Tools","question":"Which of the following pairs are BOTH techniques of management accounting?","options":[{"key":"A","text":"Trial balance and journal"},{"key":"B","text":"Bank reconciliation and audit"},{"key":"C","text":"Ratio analysis and cash flow analysis"},{"key":"D","text":"Ledger posting and vouching"}],"answer":"C","explanation":"Ratio analysis and fund/cash flow analysis are core MA analytical tools; the others are bookkeeping/audit processes.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA020","optionFormat":"letter"},"contentSignature":"bf308ffed2dd6c3b85e8417cbf46018a74c6319673617da7151f4ef58c6d9a30","kind":"mcq"},{"id":"deep-management-MA021","sourceNumber":21,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Ratio analysis is a technique of:","options":["The preparation of the vouchers of the business, as the first step of the accounting work","Analysing and INTERPRETING financial statements by establishing mathematical relationships between related figures","The physical verification of the assets of the business, as the auditor does at the year end","The recording of the transactions of the business in the books of prime entry, day by day"],"answer":1,"explanation":"A ratio expresses one figure as a quotient/percentage/proportion of another; its value lies in comparison with standards, past periods or other firms.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA021","number":21,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Ratio analysis is a technique of:","options":[{"key":"A","text":"The preparation of the vouchers of the business, as the first step of the accounting work"},{"key":"B","text":"Analysing and INTERPRETING financial statements by establishing mathematical relationships between related figures"},{"key":"C","text":"The physical verification of the assets of the business, as the auditor does at the year end"},{"key":"D","text":"The recording of the transactions of the business in the books of prime entry, day by day"}],"answer":"B","explanation":"A ratio expresses one figure as a quotient/percentage/proportion of another; its value lies in comparison with standards, past periods or other firms.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Ratio analysis is a technique of:","options":["Preparing vouchers","Analysing and INTERPRETING financial statements by establishing mathematical relationships between related figures","Physical verification","Recording transactions"],"answer":1,"explanation":"A ratio expresses one figure as a quotient/percentage/proportion of another; its value lies in comparison with standards, past periods or other firms.","revision":"original","contentSignature":"89a6bb8e37217981882a5cbe18fd8f78e9e68a547c613ea672b788058bbd46f0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA021","optionFormat":"letter"},"contentSignature":"fa93f54bc98d36f03b299d60558785201b43938c489ad90492e1db688d3d21d6","kind":"mcq"},{"id":"deep-management-MA022","sourceNumber":22,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Ratios are broadly classified (traditional/functional classification) into:","options":["LIQUIDITY, SOLVENCY (leverage/capital structure), ACTIVITY (turnover) and PROFITABILITY ratios","Only the profitability ratios, since profit alone matters to every user of the statements","Only the liquidity ratios, since the payment of debts alone matters to every user","The primary and the secondary ratios only, under the traditional classification of ratios"],"answer":0,"explanation":"The functional classification groups ratios by the aspect they test: short-term liquidity, long-term solvency, efficiency of asset use, and profitability.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA022","number":22,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Ratios are broadly classified (traditional/functional classification) into:","options":[{"key":"A","text":"LIQUIDITY, SOLVENCY (leverage/capital structure), ACTIVITY (turnover) and PROFITABILITY ratios"},{"key":"B","text":"Only the profitability ratios, since profit alone matters to every user of the statements"},{"key":"C","text":"Only the liquidity ratios, since the payment of debts alone matters to every user"},{"key":"D","text":"The primary and the secondary ratios only, under the traditional classification of ratios"}],"answer":"A","explanation":"The functional classification groups ratios by the aspect they test: short-term liquidity, long-term solvency, efficiency of asset use, and profitability.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Ratios are broadly classified (traditional/functional classification) into:","options":["LIQUIDITY, SOLVENCY (leverage/capital structure), ACTIVITY (turnover) and PROFITABILITY ratios","Only profitability ratios","Only liquidity ratios","Primary and secondary only"],"answer":0,"explanation":"The functional classification groups ratios by the aspect they test: short-term liquidity, long-term solvency, efficiency of asset use, and profitability.","revision":"original","contentSignature":"9b0ce73ebde5daaf4db96b8f45dceee8a0d02acd118d13216e53e7138e13f3df"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA022","optionFormat":"letter"},"contentSignature":"04f523e12d8ac0bf2c3abc52d447aa194c667b13a3f690aa653e22cdc4b36012","kind":"mcq"},{"id":"deep-management-MA023","sourceNumber":23,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The CURRENT RATIO is computed as:","options":["Current liabilities / Current assets","CURRENT ASSETS / CURRENT LIABILITIES","Quick assets / Current liabilities","Debt / Equity"],"answer":1,"explanation":"Current ratio = current assets / current liabilities; the conventional yardstick is 2:1, though industry norms vary.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA023","number":23,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The CURRENT RATIO is computed as:","options":[{"key":"A","text":"Current liabilities / Current assets"},{"key":"B","text":"CURRENT ASSETS / CURRENT LIABILITIES"},{"key":"C","text":"Quick assets / Current liabilities"},{"key":"D","text":"Debt / Equity"}],"answer":"B","explanation":"Current ratio = current assets / current liabilities; the conventional yardstick is 2:1, though industry norms vary.","source":"Recall 2021","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA023","optionFormat":"letter"},"contentSignature":"3252eefc2c80f0a28fdc631bca784d10f05ff7d64821e2d288c446d37113bc6f","kind":"mcq"},{"id":"deep-management-MA024","sourceNumber":24,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"CURRENT ASSETS include all EXCEPT:","options":["Stock/inventory and debtors","PRELIMINARY EXPENSES not written off","Bills receivable and prepaid expenses","Cash, bank and short-term investments"],"answer":1,"explanation":"Fictitious/deferred assets (preliminary expenses, discount on issue of shares) are NOT current assets - they cannot be converted to cash.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA024","number":24,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"CURRENT ASSETS include all EXCEPT:","options":[{"key":"A","text":"Stock/inventory and debtors"},{"key":"B","text":"PRELIMINARY EXPENSES not written off"},{"key":"C","text":"Bills receivable and prepaid expenses"},{"key":"D","text":"Cash, bank and short-term investments"}],"answer":"B","explanation":"Fictitious/deferred assets (preliminary expenses, discount on issue of shares) are NOT current assets - they cannot be converted to cash.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA024","optionFormat":"letter"},"contentSignature":"e8ebe752d7bbfc533767b02288614dd151fe23ebd93e590d4f6c75aa6c9b444c","kind":"mcq"},{"id":"deep-management-MA025","sourceNumber":25,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"CURRENT LIABILITIES include:","options":["Outstanding expenses, sundry creditors, bills payable, bank overdraft and short-term loans","The general reserve of the company, built out of the profits of the earlier years","The share capital of the company, contributed by the shareholders of the company","The long-term loans of the company, repayable after the period of five years"],"answer":0,"explanation":"Current liabilities are obligations payable within a year (or the operating cycle), including provisions like provision for tax and proposed dividend.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA025","number":25,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"CURRENT LIABILITIES include:","options":[{"key":"A","text":"Outstanding expenses, sundry creditors, bills payable, bank overdraft and short-term loans"},{"key":"B","text":"The general reserve of the company, built out of the profits of the earlier years"},{"key":"C","text":"The share capital of the company, contributed by the shareholders of the company"},{"key":"D","text":"The long-term loans of the company, repayable after the period of five years"}],"answer":"A","explanation":"Current liabilities are obligations payable within a year (or the operating cycle), including provisions like provision for tax and proposed dividend.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CURRENT LIABILITIES include:","options":["Outstanding expenses, sundry creditors, bills payable, bank overdraft and short-term loans","General reserve","Share capital","Long-term loans"],"answer":0,"explanation":"Current liabilities are obligations payable within a year (or the operating cycle), including provisions like provision for tax and proposed dividend.","revision":"original","contentSignature":"cb772a1ac99e786d036aa34867e90013ec050a829473f023f620dee270cf90f1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA025","optionFormat":"letter"},"contentSignature":"619d0aab67ef8b3e147b9b0bb8f0982df2f0938a77283e427c54a3f24fe6fedd","kind":"mcq"},{"id":"deep-management-MA026","sourceNumber":26,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The IDEAL current ratio traditionally regarded as satisfactory is:","options":["2:1","1:1","3:1","5:1"],"answer":0,"explanation":"The 2:1 rule of thumb gives a safety margin on realisation of current assets; a very high ratio may indicate idle funds or poor working-capital management.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA026","number":26,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The IDEAL current ratio traditionally regarded as satisfactory is:","options":[{"key":"A","text":"2:1"},{"key":"B","text":"1:1"},{"key":"C","text":"3:1"},{"key":"D","text":"5:1"}],"answer":"A","explanation":"The 2:1 rule of thumb gives a safety margin on realisation of current assets; a very high ratio may indicate idle funds or poor working-capital management.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA026","optionFormat":"letter"},"contentSignature":"2951e9de17fcf01386cbf239d044632ea3cc7b24792488ff6cc8b0f63e3bdd9b","kind":"mcq"},{"id":"deep-management-MA027","sourceNumber":27,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The QUICK (acid-test/liquid) ratio is:","options":["The total debt of the company divided by the equity of the company, as the solvency test","The current assets of the company divided by the current liabilities, as the solvency test","The stock of the company divided by the debtors of the company, as the solvency test","QUICK ASSETS (current assets minus stock and prepaid expenses) / CURRENT LIABILITIES"],"answer":3,"explanation":"Quick ratio excludes inventory and prepaid expenses because they convert to cash slowly; the yardstick is 1:1.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA027","number":27,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The QUICK (acid-test/liquid) ratio is:","options":[{"key":"A","text":"The total debt of the company divided by the equity of the company, as the solvency test"},{"key":"B","text":"The current assets of the company divided by the current liabilities, as the solvency test"},{"key":"C","text":"The stock of the company divided by the debtors of the company, as the solvency test"},{"key":"D","text":"QUICK ASSETS (current assets minus stock and prepaid expenses) / CURRENT LIABILITIES"}],"answer":"D","explanation":"Quick ratio excludes inventory and prepaid expenses because they convert to cash slowly; the yardstick is 1:1.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The QUICK (acid-test/liquid) ratio is:","options":["Debt / Equity","Current assets / Current liabilities","Stock / Debtors","QUICK ASSETS (current assets minus stock and prepaid expenses) / CURRENT LIABILITIES"],"answer":3,"explanation":"Quick ratio excludes inventory and prepaid expenses because they convert to cash slowly; the yardstick is 1:1.","revision":"original","contentSignature":"f4bc2b7ce8323913dcf5403922487c1ca312b92abcc4af580f6e8a4ccb93e1fa"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA027","optionFormat":"letter"},"contentSignature":"0e6ab885c763732808e15cd2ed78a2a310161c69cf891c7df24679b9c9590824","kind":"mcq"},{"id":"deep-management-MA028","sourceNumber":28,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Quick liabilities EXCLUDE:","options":["The sundry creditors of the business - quick liabilities exclude every kind of creditor of the concern","The bills payable of the business - quick liabilities exclude every kind of acceptance of the concern","The outstanding expenses of the business - quick liabilities exclude every accrued charge of the concern","BANK OVERDRAFT - quick liabilities = current liabilities minus bank overdraft (it is treated as a semi-permanent source)"],"answer":3,"explanation":"The usual formula: quick ratio = quick assets / (current liabilities - bank overdraft). Bank overdraft is excluded from quick liabilities because it is a continuing source of finance.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA028","number":28,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Quick liabilities EXCLUDE:","options":[{"key":"A","text":"The sundry creditors of the business - quick liabilities exclude every kind of creditor of the concern"},{"key":"B","text":"The bills payable of the business - quick liabilities exclude every kind of acceptance of the concern"},{"key":"C","text":"The outstanding expenses of the business - quick liabilities exclude every accrued charge of the concern"},{"key":"D","text":"BANK OVERDRAFT - quick liabilities = current liabilities minus bank overdraft (it is treated as a semi-permanent source)"}],"answer":"D","explanation":"The usual formula: quick ratio = quick assets / (current liabilities - bank overdraft). Bank overdraft is excluded from quick liabilities because it is a continuing source of finance.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Quick liabilities EXCLUDE:","options":["Creditors","Bills payable","Outstanding expenses","BANK OVERDRAFT - quick liabilities = current liabilities minus bank overdraft (it is treated as a semi-permanent source)"],"answer":3,"explanation":"The usual formula: quick ratio = quick assets / (current liabilities - bank overdraft). Bank overdraft is excluded from quick liabilities because it is a continuing source of finance.","revision":"original","contentSignature":"c1006368cced1348e5f93045d8da45c98ce6e27a1516e1069273c4077ea917cc"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA028","optionFormat":"letter"},"contentSignature":"871e5298b4f189d97745689b1d87de0d7a033df7bb867fdef7603807abd81baa","kind":"mcq"},{"id":"deep-management-MA029","sourceNumber":29,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The ideal quick (acid-test) ratio is:","options":["2:1","1:1","3:1","0.5:1"],"answer":1,"explanation":"A 1:1 acid-test ratio means immediately realisable assets cover immediate liabilities fully.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA029","number":29,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The ideal quick (acid-test) ratio is:","options":[{"key":"A","text":"2:1"},{"key":"B","text":"1:1"},{"key":"C","text":"3:1"},{"key":"D","text":"0.5:1"}],"answer":"B","explanation":"A 1:1 acid-test ratio means immediately realisable assets cover immediate liabilities fully.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA029","optionFormat":"letter"},"contentSignature":"89e2ad8ad782dfb1cfb20f8d47346d8230500156eaf886a2d0e20019a6892b31","kind":"mcq"},{"id":"deep-management-MA030","sourceNumber":30,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"A firm has current assets of Rs.4,00,000 and current liabilities of Rs.2,00,000. Its current ratio is:","options":["1:1","2:1","4:1","0.5:1"],"answer":1,"explanation":"4,00,000 / 2,00,000 = 2:1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA030","number":30,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"A firm has current assets of Rs.4,00,000 and current liabilities of Rs.2,00,000. Its current ratio is:","options":[{"key":"A","text":"1:1"},{"key":"B","text":"2:1"},{"key":"C","text":"4:1"},{"key":"D","text":"0.5:1"}],"answer":"B","explanation":"4,00,000 / 2,00,000 = 2:1.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA030","optionFormat":"letter"},"contentSignature":"d18c925e62629cac39677805f5cd884f6108da5462208b5b279d608aabcdc691","kind":"mcq"},{"id":"deep-management-MA031","sourceNumber":31,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"A firm has current assets Rs.3,00,000 (including stock Rs.1,00,000 and prepaid expenses Rs.20,000) and current liabilities Rs.1,50,000 (including bank overdraft Rs.30,000). Its QUICK ratio is:","options":["1.67:1","1.5:1","2:1","1.2:1"],"answer":1,"explanation":"Quick assets = 3,00,000 - 1,00,000 - 20,000 = 1,80,000; quick liabilities = 1,50,000 - 30,000 = 1,20,000; ratio = 1.5:1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA031","number":31,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"A firm has current assets Rs.3,00,000 (including stock Rs.1,00,000 and prepaid expenses Rs.20,000) and current liabilities Rs.1,50,000 (including bank overdraft Rs.30,000). Its QUICK ratio is:","options":[{"key":"A","text":"1.67:1"},{"key":"B","text":"1.5:1"},{"key":"C","text":"2:1"},{"key":"D","text":"1.2:1"}],"answer":"B","explanation":"Quick assets = 3,00,000 - 1,00,000 - 20,000 = 1,80,000; quick liabilities = 1,50,000 - 30,000 = 1,20,000; ratio = 1.5:1.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA031","optionFormat":"letter"},"contentSignature":"27a2370868a18dc1bfb5fedf160696264be4e726eb69537e75f6fc9f245aa478","kind":"mcq"},{"id":"deep-management-MA032","sourceNumber":32,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"When the current ratio is 2:1 and there is an EQUAL increase in current assets and current liabilities, the ratio will:","options":["Become zero","Increase","Remain unchanged","DECREASE"],"answer":3,"explanation":"Adding equal amounts to both sides of a ratio greater than 1 pulls it down toward 1 (e.g. 2:1 plus 0.5/0.5 becomes 2.5:1.5 = 1.67:1).","source":"PYQ: UGC NET Commerce, 2020-Oct-E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA032","number":32,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"When the current ratio is 2:1 and there is an EQUAL increase in current assets and current liabilities, the ratio will:","options":[{"key":"A","text":"Become zero"},{"key":"B","text":"Increase"},{"key":"C","text":"Remain unchanged"},{"key":"D","text":"DECREASE"}],"answer":"D","explanation":"Adding equal amounts to both sides of a ratio greater than 1 pulls it down toward 1 (e.g. 2:1 plus 0.5/0.5 becomes 2.5:1.5 = 1.67:1).","source":"PYQ: UGC NET Commerce, 2020-Oct-E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA032","optionFormat":"letter"},"contentSignature":"fb2eb628e62c25c6007ea34b2dbdf7adca5de1b7269ea8d02b28eaf1c7174d5c","kind":"pyq"},{"id":"deep-management-MA033","sourceNumber":33,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Payment of a CURRENT LIABILITY in cash will:","options":["Reduce the working capital of the business, since the cash goes out of it","IMPROVE (increase) the current ratio when it is above 1","Decrease the current ratio of the business, when the ratio is already above one","Leave the current ratio of the business unchanged always, whatever the payment"],"answer":1,"explanation":"Equal reduction of CA and CL raises a ratio that is above 1 (e.g. CA 4, CL 2, paying 1 in cash leaves 3/1 = 3:1); total working capital stays unchanged.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA033","number":33,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Payment of a CURRENT LIABILITY in cash will:","options":[{"key":"A","text":"Reduce the working capital of the business, since the cash goes out of it"},{"key":"B","text":"IMPROVE (increase) the current ratio when it is above 1"},{"key":"C","text":"Decrease the current ratio of the business, when the ratio is already above one"},{"key":"D","text":"Leave the current ratio of the business unchanged always, whatever the payment"}],"answer":"B","explanation":"Equal reduction of CA and CL raises a ratio that is above 1 (e.g. CA 4, CL 2, paying 1 in cash leaves 3/1 = 3:1); total working capital stays unchanged.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Payment of a CURRENT LIABILITY in cash will:","options":["Reduce working capital","IMPROVE (increase) the current ratio when it is above 1","Decrease the current ratio (when above 1)","Leave it unchanged always"],"answer":1,"explanation":"Equal reduction of CA and CL raises a ratio that is above 1 (e.g. CA 4, CL 2, paying 1 in cash leaves 3/1 = 3:1); total working capital stays unchanged.","revision":"original","contentSignature":"71cbdb7d6d693b12d238e85e637a660a0db0357be19ea6f434cb14e44033ccff"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA033","optionFormat":"letter"},"contentSignature":"d472a19e205e23e4790b548001740a82b656f124f2c66ac83cb9689e48225f56","kind":"mcq"},{"id":"deep-management-MA034","sourceNumber":34,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Purchase of stock-in-trade on CREDIT will:","options":["Improve the quick ratio of the business at once, since the stock is a quick asset of the business itself","Decrease the working capital of the business at once, since the stock comes into the business on credit terms","INCREASE current assets and current liabilities EQUALLY - the current ratio FALLS if it was above 1; working capital stays UNCHANGED","Increase the working capital of the business at once, since the stock comes into the business itself at once"],"answer":2,"explanation":"Credit purchases add equal amounts to stock (CA) and creditors (CL): working capital unchanged, current ratio moves toward 1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA034","number":34,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Purchase of stock-in-trade on CREDIT will:","options":[{"key":"A","text":"Improve the quick ratio of the business at once, since the stock is a quick asset of the business itself"},{"key":"B","text":"Decrease the working capital of the business at once, since the stock comes into the business on credit terms"},{"key":"C","text":"INCREASE current assets and current liabilities EQUALLY - the current ratio FALLS if it was above 1; working capital stays UNCHANGED"},{"key":"D","text":"Increase the working capital of the business at once, since the stock comes into the business itself at once"}],"answer":"C","explanation":"Credit purchases add equal amounts to stock (CA) and creditors (CL): working capital unchanged, current ratio moves toward 1.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Purchase of stock-in-trade on CREDIT will:","options":["Improve the quick ratio","Decrease working capital","INCREASE current assets and current liabilities EQUALLY - the current ratio FALLS if it was above 1; working capital stays UNCHANGED","Increase working capital"],"answer":2,"explanation":"Credit purchases add equal amounts to stock (CA) and creditors (CL): working capital unchanged, current ratio moves toward 1.","revision":"original","contentSignature":"241048f0018257935752a899fb90f9456cb3e24ced9af9dcdacdec025fc297b3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA034","optionFormat":"letter"},"contentSignature":"ee67e39bffedd5e8cb20d6a4086db413ff5ae961a6dca6cb38d27eb72580e412","kind":"mcq"},{"id":"deep-management-MA035","sourceNumber":35,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The ABSOLUTE liquid (cash) ratio is:","options":["The debtors of the business divided by the sales of the year, as the liquidity test","The current assets of the business divided by the current liabilities, as the liquidity test","(Cash + bank + marketable securities) / Current liabilities","The cash of the business divided by the total assets of the business, as the liquidity test"],"answer":2,"explanation":"The cash ratio tests immediate solvency with cash and near-cash only; 0.5:1 is the commonly cited norm.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA035","number":35,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The ABSOLUTE liquid (cash) ratio is:","options":[{"key":"A","text":"The debtors of the business divided by the sales of the year, as the liquidity test"},{"key":"B","text":"The current assets of the business divided by the current liabilities, as the liquidity test"},{"key":"C","text":"(Cash + bank + marketable securities) / Current liabilities"},{"key":"D","text":"The cash of the business divided by the total assets of the business, as the liquidity test"}],"answer":"C","explanation":"The cash ratio tests immediate solvency with cash and near-cash only; 0.5:1 is the commonly cited norm.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The ABSOLUTE liquid (cash) ratio is:","options":["Debtors / Sales","Current assets / Current liabilities","(Cash + bank + marketable securities) / Current liabilities","Cash / Total assets"],"answer":2,"explanation":"The cash ratio tests immediate solvency with cash and near-cash only; 0.5:1 is the commonly cited norm.","revision":"original","contentSignature":"5208a315dedd573e57a92c7f14be6e483d2a8f70e037643490cb3cdfe5a05982"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA035","optionFormat":"letter"},"contentSignature":"732565b6f3c682dece99ec16b3112fb103e41212288004a0bfde6e4ab89ff197","kind":"mcq"},{"id":"deep-management-MA036","sourceNumber":36,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"DEBT-EQUITY ratio is computed as:","options":["The fixed assets of the company divided by the equity of the company","LONG-TERM DEBT / SHAREHOLDERS FUNDS (outsiders funds / own funds)","The equity of the company divided by the debt of the company","The total debt of the company divided by the current liabilities of the company"],"answer":1,"explanation":"Debt-equity = long-term external liabilities / shareholders funds; the conventional comfortable norm is 2:1 (varies by industry).","source":"PYQ: SSC CGL AAO, 2017 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA036","number":36,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"DEBT-EQUITY ratio is computed as:","options":[{"key":"A","text":"The fixed assets of the company divided by the equity of the company"},{"key":"B","text":"LONG-TERM DEBT / SHAREHOLDERS FUNDS (outsiders funds / own funds)"},{"key":"C","text":"The equity of the company divided by the debt of the company"},{"key":"D","text":"The total debt of the company divided by the current liabilities of the company"}],"answer":"B","explanation":"Debt-equity = long-term external liabilities / shareholders funds; the conventional comfortable norm is 2:1 (varies by industry).","source":"PYQ: SSC CGL AAO, 2017","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DEBT-EQUITY ratio is computed as:","options":["Fixed assets / Equity","LONG-TERM DEBT / SHAREHOLDERS FUNDS (outsiders funds / own funds)","Equity / Debt","Total debt / Current liabilities"],"answer":1,"explanation":"Debt-equity = long-term external liabilities / shareholders funds; the conventional comfortable norm is 2:1 (varies by industry).","revision":"original","contentSignature":"c9a201bf3d53578ef3736c4d7574058b087970e734816460a5109720b88f1102"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA036","optionFormat":"letter"},"contentSignature":"59e63baa04a867cf2bc686dd4824d575c1288066ff8579e303fa7ad9c26bb3b4","kind":"pyq"},{"id":"deep-management-MA037","sourceNumber":37,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Shareholders funds (proprietors funds/own funds) equal:","options":["The share capital of the company taken by itself alone, with nothing added to it","The fixed assets of the company, at their written-down value","Share capital + RESERVES AND SURPLUS - accumulated losses and fictitious assets","The total assets of the company, at their balance-sheet values"],"answer":2,"explanation":"Own funds = paid-up capital (equity + preference, as defined) plus free reserves minus accumulated losses, preliminary expenses and other fictitious assets.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA037","number":37,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Shareholders funds (proprietors funds/own funds) equal:","options":[{"key":"A","text":"The share capital of the company taken by itself alone, with nothing added to it"},{"key":"B","text":"The fixed assets of the company, at their written-down value"},{"key":"C","text":"Share capital + RESERVES AND SURPLUS - accumulated losses and fictitious assets"},{"key":"D","text":"The total assets of the company, at their balance-sheet values"}],"answer":"C","explanation":"Own funds = paid-up capital (equity + preference, as defined) plus free reserves minus accumulated losses, preliminary expenses and other fictitious assets.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Shareholders funds (proprietors funds/own funds) equal:","options":["Share capital only","Fixed assets","Share capital + RESERVES AND SURPLUS - accumulated losses and fictitious assets","Total assets"],"answer":2,"explanation":"Own funds = paid-up capital (equity + preference, as defined) plus free reserves minus accumulated losses, preliminary expenses and other fictitious assets.","revision":"original","contentSignature":"045d74307d2108e4a33704b3731cd121ad948e78b1380381aaed738cdce685c6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA037","optionFormat":"letter"},"contentSignature":"ad07d733c24434188176ba277a328bcff5e96260eb477516b51c9539914fac73","kind":"mcq"},{"id":"deep-management-MA038","sourceNumber":38,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The PROPRIETARY ratio is:","options":["Proprietors funds / TOTAL ASSETS","Debt / Equity","Current assets / Total assets","Net profit / Sales"],"answer":0,"explanation":"Proprietary ratio = shareholders funds / total assets; higher values indicate a stronger long-term financial position. A 0.5:1 or higher level is considered adequate.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA038","number":38,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The PROPRIETARY ratio is:","options":[{"key":"A","text":"Proprietors funds / TOTAL ASSETS"},{"key":"B","text":"Debt / Equity"},{"key":"C","text":"Current assets / Total assets"},{"key":"D","text":"Net profit / Sales"}],"answer":"A","explanation":"Proprietary ratio = shareholders funds / total assets; higher values indicate a stronger long-term financial position. A 0.5:1 or higher level is considered adequate.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA038","optionFormat":"letter"},"contentSignature":"01ccaa2c085811a256ab22ba8703ffe4f30ddc4ad70b0e9c3b9041198fa93e4e","kind":"mcq"},{"id":"deep-management-MA039","sourceNumber":39,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The SOLVENCY ratio (total liabilities to total assets) indicates:","options":["The profitability of the business, since the ratio compares the profit with the assets of the concern","The liquidity of the business, since the ratio compares the cash with the debts of the concern","The extent to which total assets are financed by OUTSIDERS liabilities - lower ratio means better long-term solvency","The activity of the business, since the ratio compares the sales with the assets of the concern"],"answer":2,"explanation":"Solvency ratio = total outside liabilities / total assets; it is the inverse view of the proprietary ratio.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA039","number":39,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The SOLVENCY ratio (total liabilities to total assets) indicates:","options":[{"key":"A","text":"The profitability of the business, since the ratio compares the profit with the assets of the concern"},{"key":"B","text":"The liquidity of the business, since the ratio compares the cash with the debts of the concern"},{"key":"C","text":"The extent to which total assets are financed by OUTSIDERS liabilities - lower ratio means better long-term solvency"},{"key":"D","text":"The activity of the business, since the ratio compares the sales with the assets of the concern"}],"answer":"C","explanation":"Solvency ratio = total outside liabilities / total assets; it is the inverse view of the proprietary ratio.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The SOLVENCY ratio (total liabilities to total assets) indicates:","options":["Profitability","Liquidity","The extent to which total assets are financed by OUTSIDERS liabilities - lower ratio means better long-term solvency","Activity"],"answer":2,"explanation":"Solvency ratio = total outside liabilities / total assets; it is the inverse view of the proprietary ratio.","revision":"original","contentSignature":"162f4df1b4e68e7b16435c28f3d2912efeb5193215810b03f052ea74d42ffbe6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA039","optionFormat":"letter"},"contentSignature":"67b1b57cb11f79a34f620b5f73d6156e37acd5e4b35cf5a17da935a3ba122a00","kind":"mcq"},{"id":"deep-management-MA040","sourceNumber":40,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Which of the following is also termed a LEVERAGE ratio?","options":["Current ratio","DEBT-EQUITY ratio","Gross profit ratio","Stock turnover ratio"],"answer":1,"explanation":"Capital-structure (leverage) ratios - debt-equity, proprietary, capital-gearing - measure the mix of debt and equity.","source":"PYQ: SSC CGL AAO, 2017 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA040","number":40,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Which of the following is also termed a LEVERAGE ratio?","options":[{"key":"A","text":"Current ratio"},{"key":"B","text":"DEBT-EQUITY ratio"},{"key":"C","text":"Gross profit ratio"},{"key":"D","text":"Stock turnover ratio"}],"answer":"B","explanation":"Capital-structure (leverage) ratios - debt-equity, proprietary, capital-gearing - measure the mix of debt and equity.","source":"PYQ: SSC CGL AAO, 2017","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA040","optionFormat":"letter"},"contentSignature":"e85917c8502512be9a5cd82cd67217e27cc2ba663ca489c51e46ebc5c747d873","kind":"pyq"},{"id":"deep-management-MA041","sourceNumber":41,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The CAPITAL GEARING ratio is:","options":["The sales of the year divided by the capital employed in the business","The debt of the company divided by the total assets of the company","The profit of the year divided by the equity of the company","(Equity share capital + free reserves) / FIXED-INTEREST/DIVIDEND bearing securities"],"answer":3,"explanation":"Capital gearing compares equity funds to fixed-return funds (preference capital + debt); a high ratio = low gearing (conservative), low ratio = high gearing (trading on equity).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA041","number":41,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The CAPITAL GEARING ratio is:","options":[{"key":"A","text":"The sales of the year divided by the capital employed in the business"},{"key":"B","text":"The debt of the company divided by the total assets of the company"},{"key":"C","text":"The profit of the year divided by the equity of the company"},{"key":"D","text":"(Equity share capital + free reserves) / FIXED-INTEREST/DIVIDEND bearing securities"}],"answer":"D","explanation":"Capital gearing compares equity funds to fixed-return funds (preference capital + debt); a high ratio = low gearing (conservative), low ratio = high gearing (trading on equity).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The CAPITAL GEARING ratio is:","options":["Sales / Capital employed","Debt / Total assets","Profit / Equity","(Equity share capital + free reserves) / FIXED-INTEREST/DIVIDEND bearing securities"],"answer":3,"explanation":"Capital gearing compares equity funds to fixed-return funds (preference capital + debt); a high ratio = low gearing (conservative), low ratio = high gearing (trading on equity).","revision":"original","contentSignature":"d188b204fef271265df4b5befeeeca9800dddf14c86b85922fa9a5ace8ec1b46"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA041","optionFormat":"letter"},"contentSignature":"7b72db73c529e82b8607e8acade385d5e08f130121ad7ac67c4669e335149e41","kind":"mcq"},{"id":"deep-management-MA042","sourceNumber":42,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"FIXED ASSETS ratio is:","options":["Fixed assets / Equity share capital only","Fixed assets / LONG-TERM FUNDS (capital employed)","Fixed assets / Sales","Fixed assets / Current assets"],"answer":1,"explanation":"Fixed assets / long-term funds shows whether fixed assets are financed by long-term money; ideally it should not exceed 1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA042","number":42,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"FIXED ASSETS ratio is:","options":[{"key":"A","text":"Fixed assets / Equity share capital only"},{"key":"B","text":"Fixed assets / LONG-TERM FUNDS (capital employed)"},{"key":"C","text":"Fixed assets / Sales"},{"key":"D","text":"Fixed assets / Current assets"}],"answer":"B","explanation":"Fixed assets / long-term funds shows whether fixed assets are financed by long-term money; ideally it should not exceed 1.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA042","optionFormat":"letter"},"contentSignature":"b4e845593d64fcdc00b713cef3d0a11894feed35196a4c21405f7978d4c5d362","kind":"mcq"},{"id":"deep-management-MA043","sourceNumber":43,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The INTEREST COVERAGE (debt service) ratio is:","options":["Sales / Interest","EBIT / Tax","Net profit / Interest","EBIT / FIXED INTEREST CHARGES"],"answer":3,"explanation":"Interest coverage = earnings before interest and tax / interest; it shows how many times earnings cover the interest burden (7x is a common comfort level).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA043","number":43,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The INTEREST COVERAGE (debt service) ratio is:","options":[{"key":"A","text":"Sales / Interest"},{"key":"B","text":"EBIT / Tax"},{"key":"C","text":"Net profit / Interest"},{"key":"D","text":"EBIT / FIXED INTEREST CHARGES"}],"answer":"D","explanation":"Interest coverage = earnings before interest and tax / interest; it shows how many times earnings cover the interest burden (7x is a common comfort level).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA043","optionFormat":"letter"},"contentSignature":"855873a9e193324f0ec3174259f43d5731e0e2450a168d3ad5aed546b11439ef","kind":"mcq"},{"id":"deep-management-MA044","sourceNumber":44,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"DIVIDEND coverage (preference) ratio is:","options":["NPAT / PREFERENCE DIVIDEND","Dividend / Profit","Equity dividend / NPAT","Dividend / Sales"],"answer":0,"explanation":"Preference dividend cover = net profit after tax / preference dividend; for equity dividend, NPAT minus preference dividend over equity dividend.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA044","number":44,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"DIVIDEND coverage (preference) ratio is:","options":[{"key":"A","text":"NPAT / PREFERENCE DIVIDEND"},{"key":"B","text":"Dividend / Profit"},{"key":"C","text":"Equity dividend / NPAT"},{"key":"D","text":"Dividend / Sales"}],"answer":"A","explanation":"Preference dividend cover = net profit after tax / preference dividend; for equity dividend, NPAT minus preference dividend over equity dividend.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA044","optionFormat":"letter"},"contentSignature":"2eaa248a70f6dd4ced80fed3d021db66208d52fc593aa6c0e06354d8f717136e","kind":"mcq"},{"id":"deep-management-MA045","sourceNumber":45,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The DEBT SERVICE COVERAGE ratio (DSCR) is:","options":["The cash of the business divided by the total debt of the business, as the coverage test","EBIT divided by the interest payable for the year, the principal instalments of the loans being ignored altogether","The sales of the year divided by the total debt of the business, as the coverage test","(Net profit after tax + depreciation + interest on long-term loans) / (interest + PRINCIPAL instalments due)"],"answer":3,"explanation":"DSCR measures the cash available to service both interest and principal; lenders look for 1.5-2x.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA045","number":45,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The DEBT SERVICE COVERAGE ratio (DSCR) is:","options":[{"key":"A","text":"The cash of the business divided by the total debt of the business, as the coverage test"},{"key":"B","text":"EBIT divided by the interest payable for the year, the principal instalments of the loans being ignored altogether"},{"key":"C","text":"The sales of the year divided by the total debt of the business, as the coverage test"},{"key":"D","text":"(Net profit after tax + depreciation + interest on long-term loans) / (interest + PRINCIPAL instalments due)"}],"answer":"D","explanation":"DSCR measures the cash available to service both interest and principal; lenders look for 1.5-2x.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DEBT SERVICE COVERAGE ratio (DSCR) is:","options":["Cash / Debt","EBIT / Interest","Sales / Debt","(Net profit after tax + depreciation + interest on long-term loans) / (interest + PRINCIPAL instalments due)"],"answer":3,"explanation":"DSCR measures the cash available to service both interest and principal; lenders look for 1.5-2x.","revision":"original","contentSignature":"6f8f304a7d0908c890ee777e3e14eba93a14dcccf2c32a0c50c31a3f72b73d1d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA045","optionFormat":"letter"},"contentSignature":"4d31644047cba53ad81b10010c80b4b559de4f22d360e23ef5dd222c6aab4f32","kind":"mcq"},{"id":"deep-management-MA046","sourceNumber":46,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Trading on EQUITY (financial leverage) is beneficial when:","options":["The equity of the company is nil, so that the whole capital is debt","The RATE OF RETURN ON CAPITAL EMPLOYED exceeds the rate of interest on debt","The interest rates rise in the market, so that the debt becomes dearer","The cost of the debt exceeds the return on the capital employed in the business"],"answer":1,"explanation":"When ROI > interest rate, the surplus on borrowed funds accrues to equity shareholders, magnifying their return.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA046","number":46,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Trading on EQUITY (financial leverage) is beneficial when:","options":[{"key":"A","text":"The equity of the company is nil, so that the whole capital is debt"},{"key":"B","text":"The RATE OF RETURN ON CAPITAL EMPLOYED exceeds the rate of interest on debt"},{"key":"C","text":"The interest rates rise in the market, so that the debt becomes dearer"},{"key":"D","text":"The cost of the debt exceeds the return on the capital employed in the business"}],"answer":"B","explanation":"When ROI > interest rate, the surplus on borrowed funds accrues to equity shareholders, magnifying their return.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Trading on EQUITY (financial leverage) is beneficial when:","options":["Equity is nil","The RATE OF RETURN ON CAPITAL EMPLOYED exceeds the rate of interest on debt","Interest rates rise","Cost of debt exceeds the return on capital employed"],"answer":1,"explanation":"When ROI > interest rate, the surplus on borrowed funds accrues to equity shareholders, magnifying their return.","revision":"original","contentSignature":"706d2415963fb7a7bed73cc164b7a0fbe9fd51837f9235cf77d93208928eb691"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA046","optionFormat":"letter"},"contentSignature":"3e4dd8e84bf0e753874bd123b6e12d3214cd58549471ec49f13b037077d8a982","kind":"mcq"},{"id":"deep-management-MA047","sourceNumber":47,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"A high debt-equity ratio indicates:","options":["A risky capital structure - higher fixed interest burden and lower cushion for lenders","A low gearing of the capital structure, with a small burden of the fixed interest","A low risk to the lenders, with a large cushion of the own funds for them","A high liquidity of the business, with a large holding of the quick assets"],"answer":0,"explanation":"High leverage magnifies both gains and losses and raises financial risk; lenders prefer a lower ratio.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA047","number":47,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"A high debt-equity ratio indicates:","options":[{"key":"A","text":"A risky capital structure - higher fixed interest burden and lower cushion for lenders"},{"key":"B","text":"A low gearing of the capital structure, with a small burden of the fixed interest"},{"key":"C","text":"A low risk to the lenders, with a large cushion of the own funds for them"},{"key":"D","text":"A high liquidity of the business, with a large holding of the quick assets"}],"answer":"A","explanation":"High leverage magnifies both gains and losses and raises financial risk; lenders prefer a lower ratio.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A high debt-equity ratio indicates:","options":["A risky capital structure - higher fixed interest burden and lower cushion for lenders","Low gearing","Low risk to lenders","High liquidity"],"answer":0,"explanation":"High leverage magnifies both gains and losses and raises financial risk; lenders prefer a lower ratio.","revision":"original","contentSignature":"1893c8147da66acfb2d77ef6218c2fa6cdc82cb4050c330026b257444cf11157"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA047","optionFormat":"letter"},"contentSignature":"4ba498193a62b85e2496572522f364589e9171d56bc48cd5ff82bcbf461d3bec","kind":"mcq"},{"id":"deep-management-MA048","sourceNumber":48,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Which group of ratios is primarily of interest to SHORT-TERM creditors?","options":["The profitability ratios, since the creditors lend only to the profitable concerns","LIQUIDITY ratios (current, quick, cash)","The return on the equity, since the creditors lend only to the high-return concerns","The capital gearing of the company, since the creditors lend only to the low-geared concerns"],"answer":1,"explanation":"Short-term lenders and suppliers judge repayment ability through liquidity ratios and the working-capital position.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA048","number":48,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Which group of ratios is primarily of interest to SHORT-TERM creditors?","options":[{"key":"A","text":"The profitability ratios, since the creditors lend only to the profitable concerns"},{"key":"B","text":"LIQUIDITY ratios (current, quick, cash)"},{"key":"C","text":"The return on the equity, since the creditors lend only to the high-return concerns"},{"key":"D","text":"The capital gearing of the company, since the creditors lend only to the low-geared concerns"}],"answer":"B","explanation":"Short-term lenders and suppliers judge repayment ability through liquidity ratios and the working-capital position.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which group of ratios is primarily of interest to SHORT-TERM creditors?","options":["Profitability ratios","LIQUIDITY ratios (current, quick, cash)","Return on equity","Capital gearing"],"answer":1,"explanation":"Short-term lenders and suppliers judge repayment ability through liquidity ratios and the working-capital position.","revision":"original","contentSignature":"2ea4a7d79b456a50c3ad4c39349eec21a509f2f612024fe967f60de311a7e8f4"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA048","optionFormat":"letter"},"contentSignature":"aa8ceb6c6149921bc84696f481e1f323202c03a600201f44cd77ca2ce117712c","kind":"mcq"},{"id":"deep-management-MA049","sourceNumber":49,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Which group of ratios is primarily of interest to LONG-TERM lenders (debenture holders, term lenders)?","options":["The operating ratio, since the lenders lend only to the low-cost concerns","The liquidity ratios, since the lenders look only to the payment of the current debts","The turnover ratios, since the lenders look only to the speed of the cycle","SOLVENCY/leverage ratios plus interest and debt-service coverage"],"answer":3,"explanation":"Long-term lenders focus on capital structure, asset cover and debt-servicing capacity.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA049","number":49,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Which group of ratios is primarily of interest to LONG-TERM lenders (debenture holders, term lenders)?","options":[{"key":"A","text":"The operating ratio, since the lenders lend only to the low-cost concerns"},{"key":"B","text":"The liquidity ratios, since the lenders look only to the payment of the current debts"},{"key":"C","text":"The turnover ratios, since the lenders look only to the speed of the cycle"},{"key":"D","text":"SOLVENCY/leverage ratios plus interest and debt-service coverage"}],"answer":"D","explanation":"Long-term lenders focus on capital structure, asset cover and debt-servicing capacity.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which group of ratios is primarily of interest to LONG-TERM lenders (debenture holders, term lenders)?","options":["Operating ratio","Liquidity ratios","Turnover ratios","SOLVENCY/leverage ratios plus interest and debt-service coverage"],"answer":3,"explanation":"Long-term lenders focus on capital structure, asset cover and debt-servicing capacity.","revision":"original","contentSignature":"e54e300f6a2516d69d92214ad18aab7f09a5d3f74d834d0ec708cb54d48fa90f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA049","optionFormat":"letter"},"contentSignature":"48b0b929ba0b48b7b117e1e5f3bf3558208a21e6d2347ea733a325cb64b654f3","kind":"mcq"},{"id":"deep-management-MA050","sourceNumber":50,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The basic LIMITATION of ratio analysis does NOT include:","options":["Ratios are based on historical data and ignore price-level changes","Different firms use different accounting policies, hurting comparability","Ratios are affected by window dressing","Ratios give ABSOLUTE answers that need no interpretation"],"answer":3,"explanation":"Ratios are only indicators needing interpretation against standards, trends and industry - they never speak absolutely.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA050","number":50,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The basic LIMITATION of ratio analysis does NOT include:","options":[{"key":"A","text":"Ratios are based on historical data and ignore price-level changes"},{"key":"B","text":"Different firms use different accounting policies, hurting comparability"},{"key":"C","text":"Ratios are affected by window dressing"},{"key":"D","text":"Ratios give ABSOLUTE answers that need no interpretation"}],"answer":"D","explanation":"Ratios are only indicators needing interpretation against standards, trends and industry - they never speak absolutely.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA050","optionFormat":"letter"},"contentSignature":"d64b3c16214c26b1c9a5e18a867e8320d16588effa75f78dbe639a11e71b1b90","kind":"mcq"},{"id":"deep-management-MA051","sourceNumber":51,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"A current ratio that is TOO HIGH (say 6:1) usually indicates:","options":["IDLE funds, over-stocking or poor collection - inefficient working-capital use","An excellent management of the working capital of the business, and nothing wrong at all","A high profitability of the business, since the ratio rises with the profit","A certain bankruptcy of the business, since the ratio can never be too high"],"answer":0,"explanation":"Excessive liquidity signals unutilised resources; ratios must be judged against the industry norm, not merely maximised.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA051","number":51,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"A current ratio that is TOO HIGH (say 6:1) usually indicates:","options":[{"key":"A","text":"IDLE funds, over-stocking or poor collection - inefficient working-capital use"},{"key":"B","text":"An excellent management of the working capital of the business, and nothing wrong at all"},{"key":"C","text":"A high profitability of the business, since the ratio rises with the profit"},{"key":"D","text":"A certain bankruptcy of the business, since the ratio can never be too high"}],"answer":"A","explanation":"Excessive liquidity signals unutilised resources; ratios must be judged against the industry norm, not merely maximised.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A current ratio that is TOO HIGH (say 6:1) usually indicates:","options":["IDLE funds, over-stocking or poor collection - inefficient working-capital use","Excellent management","High profitability","Certain bankruptcy"],"answer":0,"explanation":"Excessive liquidity signals unutilised resources; ratios must be judged against the industry norm, not merely maximised.","revision":"original","contentSignature":"a3fa8abdfd46245926cc2449090312afd73c43207c3d9f55b969e2f97c278212"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA051","optionFormat":"letter"},"contentSignature":"4bcd2835cdbe0ad4a23adbe948ae397114b20a05251be8007ee1fbda432eb5a3","kind":"mcq"},{"id":"deep-management-MA052","sourceNumber":52,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Window dressing in financial statements:","options":["DISTORTS ratios (e.g. paying creditors just before the balance sheet date to inflate the current ratio)","Improves the reliability of the ratios computed from the statements, for every user of them","Is illegal under the law but harmless to every user of the financial statements","Affects only the profit of the year, and never the ratios of the business at all"],"answer":0,"explanation":"Cosmetic period-end adjustments can flatter liquidity and other ratios; analysts should use averages and audit-adjusted data.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA052","number":52,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Window dressing in financial statements:","options":[{"key":"A","text":"DISTORTS ratios (e.g. paying creditors just before the balance sheet date to inflate the current ratio)"},{"key":"B","text":"Improves the reliability of the ratios computed from the statements, for every user of them"},{"key":"C","text":"Is illegal under the law but harmless to every user of the financial statements"},{"key":"D","text":"Affects only the profit of the year, and never the ratios of the business at all"}],"answer":"A","explanation":"Cosmetic period-end adjustments can flatter liquidity and other ratios; analysts should use averages and audit-adjusted data.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Window dressing in financial statements:","options":["DISTORTS ratios (e.g. paying creditors just before the balance sheet date to inflate the current ratio)","Improves the reliability of ratios","Is illegal but harmless","Affects only profit"],"answer":0,"explanation":"Cosmetic period-end adjustments can flatter liquidity and other ratios; analysts should use averages and audit-adjusted data.","revision":"original","contentSignature":"aa1141aaac06b559fa81a8a993c03a51986929b7bcf13ebf2af72469a2be56cd"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA052","optionFormat":"letter"},"contentSignature":"85bbb0ce9d9c078545127dbae78c1909c05c101f0f51c4cd053f6caf1cb1e16e","kind":"mcq"},{"id":"deep-management-MA053","sourceNumber":53,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Which of the following is NOT a use of ratio analysis?","options":["Trend analysis and forecasting","Locating areas of weakness for corrective action","Inter-firm and intra-firm comparison","REPLACING the need for financial statements"],"answer":3,"explanation":"Ratios depend on the statements; they summarise and interpret but never substitute for them.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA053","number":53,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Which of the following is NOT a use of ratio analysis?","options":[{"key":"A","text":"Trend analysis and forecasting"},{"key":"B","text":"Locating areas of weakness for corrective action"},{"key":"C","text":"Inter-firm and intra-firm comparison"},{"key":"D","text":"REPLACING the need for financial statements"}],"answer":"D","explanation":"Ratios depend on the statements; they summarise and interpret but never substitute for them.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA053","optionFormat":"letter"},"contentSignature":"ce9298326d74abfa633a5ce24f4697d1b1e73c16b16ec9dadbf366d962156b62","kind":"mcq"},{"id":"deep-management-MA054","sourceNumber":54,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The \"rule of thumb\" standard ratios commonly cited are: current ratio ________, quick ratio ________, debt-equity ________:","options":["2:1; 1:1; 2:1","2:1; 1:1; 1:2","3:1; 2:1; 1:1","1:1; 2:1; 1:1"],"answer":0,"explanation":"Conventional yardsticks: current 2:1, quick 1:1, debt-equity 2:1 (for manufacturing; lower for infrastructure etc.).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA054","number":54,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The \"rule of thumb\" standard ratios commonly cited are: current ratio ________, quick ratio ________, debt-equity ________:","options":[{"key":"A","text":"2:1; 1:1; 2:1"},{"key":"B","text":"2:1; 1:1; 1:2"},{"key":"C","text":"3:1; 2:1; 1:1"},{"key":"D","text":"1:1; 2:1; 1:1"}],"answer":"A","explanation":"Conventional yardsticks: current 2:1, quick 1:1, debt-equity 2:1 (for manufacturing; lower for infrastructure etc.).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA054","optionFormat":"letter"},"contentSignature":"87fb23b0c29a86cfa6086c8a8d5f5fda61ccff1209ecb23375f3e0ad213bbfc5","kind":"mcq"},{"id":"deep-management-MA055","sourceNumber":55,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"The debt-equity ratio of a company with equity share capital Rs.5,00,000, reserves Rs.3,00,000, 10% debentures Rs.4,00,000 and long- term loans Rs.4,00,000 is:","options":["2:1","1:2","0.5:1","1:1"],"answer":3,"explanation":"Debt = 4,00,000 + 4,00,000 = 8,00,000; equity = 5,00,000 + 3,00,000 = 8,00,000; ratio = 1:1.","source":"Recall 2018 (numerical pattern) · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA055","number":55,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"The debt-equity ratio of a company with equity share capital Rs.5,00,000, reserves Rs.3,00,000, 10% debentures Rs.4,00,000 and long- term loans Rs.4,00,000 is:","options":[{"key":"A","text":"2:1"},{"key":"B","text":"1:2"},{"key":"C","text":"0.5:1"},{"key":"D","text":"1:1"}],"answer":"D","explanation":"Debt = 4,00,000 + 4,00,000 = 8,00,000; equity = 5,00,000 + 3,00,000 = 8,00,000; ratio = 1:1.","source":"Recall 2018 (numerical pattern)","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA055","optionFormat":"letter"},"contentSignature":"580c2ff1c4e20409722c8c55eddc84c9012b532a8bbe3e516582c861d66719d3","kind":"mcq"},{"id":"deep-management-MA056","sourceNumber":56,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"Contingent liabilities appearing as a footnote are:","options":["Generally EXCLUDED from ratio computations but noted by the analyst","Added to the debt of the company in every ratio computation, as a matter of prudence","Added to the current liabilities of the company in every ratio computation","Ignored in the analysis altogether, since they are not recorded in the books"],"answer":0,"explanation":"Contingent liabilities are not recorded liabilities; analysts factor them qualitatively when assessing solvency.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA056","number":56,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"Contingent liabilities appearing as a footnote are:","options":[{"key":"A","text":"Generally EXCLUDED from ratio computations but noted by the analyst"},{"key":"B","text":"Added to the debt of the company in every ratio computation, as a matter of prudence"},{"key":"C","text":"Added to the current liabilities of the company in every ratio computation"},{"key":"D","text":"Ignored in the analysis altogether, since they are not recorded in the books"}],"answer":"A","explanation":"Contingent liabilities are not recorded liabilities; analysts factor them qualitatively when assessing solvency.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Contingent liabilities appearing as a footnote are:","options":["Generally EXCLUDED from ratio computations but noted by the analyst","Added to debt","Added to current liabilities","Ignored in analysis"],"answer":0,"explanation":"Contingent liabilities are not recorded liabilities; analysts factor them qualitatively when assessing solvency.","revision":"original","contentSignature":"cc7bd6c96ee9ed9db18992464fe48eeaac59aa50b2c702e57d3bb2241ec8fa2c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA056","optionFormat":"letter"},"contentSignature":"ffb32988887b5cc71acfffe5c6906eb07e0b18428f8bfb9c8b53d319c25f35fe","kind":"mcq"},{"id":"deep-management-MA057","sourceNumber":57,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M1 · Ratio Analysis I - Liquidity & Solvency","question":"For computing ratios, \"operating profit\" means:","options":["PROFIT BEFORE non-operating income/expenses, interest and tax (EBIT adjusted for non-operating items)","The sales of the year less the cash expenses of the year, ignoring all non-cash items like depreciation and amortisation","The net profit of the year after the tax, as shown in the statement of profit and loss","The gross profit of the year only, before any expense of the business is deducted at all"],"answer":0,"explanation":"Operating profit excludes non-operating items (interest/dividend received, profit on asset sales) and is the base for the operating ratio and interest coverage.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA057","number":57,"module":"M1","moduleTitle":"Ratio Analysis I - Liquidity & Solvency","question":"For computing ratios, \"operating profit\" means:","options":[{"key":"A","text":"PROFIT BEFORE non-operating income/expenses, interest and tax (EBIT adjusted for non-operating items)"},{"key":"B","text":"The sales of the year less the cash expenses of the year, ignoring all non-cash items like depreciation and amortisation"},{"key":"C","text":"The net profit of the year after the tax, as shown in the statement of profit and loss"},{"key":"D","text":"The gross profit of the year only, before any expense of the business is deducted at all"}],"answer":"A","explanation":"Operating profit excludes non-operating items (interest/dividend received, profit on asset sales) and is the base for the operating ratio and interest coverage.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For computing ratios, \"operating profit\" means:","options":["PROFIT BEFORE non-operating income/expenses, interest and tax (EBIT adjusted for non-operating items)","Sales minus cash expenses","Net profit after tax","Gross profit only"],"answer":0,"explanation":"Operating profit excludes non-operating items (interest/dividend received, profit on asset sales) and is the base for the operating ratio and interest coverage.","revision":"original","contentSignature":"a0d497aff7360dc95090827bdd2dd40f95412012c9dba229b9188dbbe3c0fe3f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA057","optionFormat":"letter"},"contentSignature":"8c162ae83ca72ab2d64760e8d855d5f487d79d88864a96be9ce2a465b7ace596","kind":"mcq"},{"id":"deep-management-MA058","sourceNumber":58,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Activity (turnover/efficiency) ratios measure:","options":["How EFFICIENTLY the firm uses its assets - speed of conversion into sales/cash","The solvency of the firm - its ability to meet the long-term obligations as they fall due","The capital structure of the firm - the mix of the debt and the equity in its finances","The profit margin of the firm - the rate of profit earned on the sales of the year"],"answer":0,"explanation":"Turnover ratios link sales or cost of goods sold to assets/receivables/inventory/payables, measured as times or days.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA058","number":58,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Activity (turnover/efficiency) ratios measure:","options":[{"key":"A","text":"How EFFICIENTLY the firm uses its assets - speed of conversion into sales/cash"},{"key":"B","text":"The solvency of the firm - its ability to meet the long-term obligations as they fall due"},{"key":"C","text":"The capital structure of the firm - the mix of the debt and the equity in its finances"},{"key":"D","text":"The profit margin of the firm - the rate of profit earned on the sales of the year"}],"answer":"A","explanation":"Turnover ratios link sales or cost of goods sold to assets/receivables/inventory/payables, measured as times or days.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Activity (turnover/efficiency) ratios measure:","options":["How EFFICIENTLY the firm uses its assets - speed of conversion into sales/cash","Solvency","Capital structure","The profit margin"],"answer":0,"explanation":"Turnover ratios link sales or cost of goods sold to assets/receivables/inventory/payables, measured as times or days.","revision":"original","contentSignature":"9992e39fa19abf25726d76fc4a6ad6914cebbe4f44a6f7dfff6f76dd7f6394b0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA058","optionFormat":"letter"},"contentSignature":"caf544739e199dfab53ea54b8ad59052350f4b49c873ee13514ca3a0ef05e3db","kind":"mcq"},{"id":"deep-management-MA059","sourceNumber":59,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"INVENTORY (stock) TURNOVER ratio is:","options":["The stock of the business divided by the sales of the year","The purchases of the year divided by the stock held","COST OF GOODS SOLD / AVERAGE INVENTORY","The sales of the year divided by the closing stock held"],"answer":2,"explanation":"Stock turnover = COGS / average stock; a high ratio indicates brisk selling and low carrying cost, but may also signal under-stocking.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA059","number":59,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"INVENTORY (stock) TURNOVER ratio is:","options":[{"key":"A","text":"The stock of the business divided by the sales of the year"},{"key":"B","text":"The purchases of the year divided by the stock held"},{"key":"C","text":"COST OF GOODS SOLD / AVERAGE INVENTORY"},{"key":"D","text":"The sales of the year divided by the closing stock held"}],"answer":"C","explanation":"Stock turnover = COGS / average stock; a high ratio indicates brisk selling and low carrying cost, but may also signal under-stocking.","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"INVENTORY (stock) TURNOVER ratio is:","options":["Stock / Sales","Purchases / Stock","COST OF GOODS SOLD / AVERAGE INVENTORY","Sales / Closing stock"],"answer":2,"explanation":"Stock turnover = COGS / average stock; a high ratio indicates brisk selling and low carrying cost, but may also signal under-stocking.","revision":"original","contentSignature":"0bbc29bff9d9e15a6d98814f20838e7442311e6d2f095b1c42f3962e17f20bfe"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA059","optionFormat":"letter"},"contentSignature":"2dbf01025d2d28ab54c3807943d862f0d02489c40b74d67498550e85d2cd8138","kind":"mcq"},{"id":"deep-management-MA060","sourceNumber":60,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has COGS Rs.6,00,000, opening stock Rs.1,00,000, closing stock Rs.1,40,000. Inventory turnover is:","options":["5 times","6 times","4.3 times","4 times"],"answer":0,"explanation":"Average stock = (1,00,000 + 1,40,000)/2 = 1,20,000; 6,00,000/1,20,000 = 5 times.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA060","number":60,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has COGS Rs.6,00,000, opening stock Rs.1,00,000, closing stock Rs.1,40,000. Inventory turnover is:","options":[{"key":"A","text":"5 times"},{"key":"B","text":"6 times"},{"key":"C","text":"4.3 times"},{"key":"D","text":"4 times"}],"answer":"A","explanation":"Average stock = (1,00,000 + 1,40,000)/2 = 1,20,000; 6,00,000/1,20,000 = 5 times.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA060","optionFormat":"letter"},"contentSignature":"7c2fb9a3341608b4989a7f79ac983a49ac071d183581b0a30f47817e9922dbfc","kind":"mcq"},{"id":"deep-management-MA061","sourceNumber":61,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The inventory turnover PERIOD (days) is:","options":["Debtors / Sales x 365","Stock / Sales x 365","365 x Purchases","365 / INVENTORY TURNOVER RATIO"],"answer":3,"explanation":"Inventory holding period = 365 (or 360) divided by the inventory turnover ratio; fewer days = faster moving stock.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA061","number":61,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The inventory turnover PERIOD (days) is:","options":[{"key":"A","text":"Debtors / Sales x 365"},{"key":"B","text":"Stock / Sales x 365"},{"key":"C","text":"365 x Purchases"},{"key":"D","text":"365 / INVENTORY TURNOVER RATIO"}],"answer":"D","explanation":"Inventory holding period = 365 (or 360) divided by the inventory turnover ratio; fewer days = faster moving stock.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA061","optionFormat":"letter"},"contentSignature":"22b23c4572879ac12dc1b9a5204591122b633571654fc8ceeb9148b47dcbe347","kind":"mcq"},{"id":"deep-management-MA062","sourceNumber":62,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DEBTORS (receivables) TURNOVER ratio is:","options":["The cash sales of the year divided by the debtors of the business","The purchases of the year divided by the creditors of the business","CREDIT SALES / AVERAGE DEBTORS (incl. bills receivable)","The debtors of the business divided by the sales of the year"],"answer":2,"explanation":"Debtors turnover = net credit sales / average trade receivables; it measures collection efficiency.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA062","number":62,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DEBTORS (receivables) TURNOVER ratio is:","options":[{"key":"A","text":"The cash sales of the year divided by the debtors of the business"},{"key":"B","text":"The purchases of the year divided by the creditors of the business"},{"key":"C","text":"CREDIT SALES / AVERAGE DEBTORS (incl. bills receivable)"},{"key":"D","text":"The debtors of the business divided by the sales of the year"}],"answer":"C","explanation":"Debtors turnover = net credit sales / average trade receivables; it measures collection efficiency.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DEBTORS (receivables) TURNOVER ratio is:","options":["Cash sales / Debtors","Purchases / Creditors","CREDIT SALES / AVERAGE DEBTORS (incl. bills receivable)","Debtors / Sales"],"answer":2,"explanation":"Debtors turnover = net credit sales / average trade receivables; it measures collection efficiency.","revision":"original","contentSignature":"4f6b8190a7c197e39b75dbd927cbf06d917f7ec0ddacd40f547af34ab633c7c3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA062","optionFormat":"letter"},"contentSignature":"f389a5193afdab3846b3220675fcb755801889ad79547c43eaefca0dd01eb2b0","kind":"mcq"},{"id":"deep-management-MA063","sourceNumber":63,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The AVERAGE COLLECTION PERIOD (debtors velocity) is:","options":["Sales / 365","Debtors x Sales","365 / DEBTORS TURNOVER","365 / Creditors turnover"],"answer":2,"explanation":"Collection period = 365 / debtors turnover (or average receivables / credit sales x 365); compare with the credit terms allowed.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA063","number":63,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The AVERAGE COLLECTION PERIOD (debtors velocity) is:","options":[{"key":"A","text":"Sales / 365"},{"key":"B","text":"Debtors x Sales"},{"key":"C","text":"365 / DEBTORS TURNOVER"},{"key":"D","text":"365 / Creditors turnover"}],"answer":"C","explanation":"Collection period = 365 / debtors turnover (or average receivables / credit sales x 365); compare with the credit terms allowed.","source":"Recall 2021","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA063","optionFormat":"letter"},"contentSignature":"d5efb1960e8285b5bbe9e5b0aa74c421764518ffed895d2a909c7608d59b3715","kind":"mcq"},{"id":"deep-management-MA064","sourceNumber":64,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has credit sales of Rs.12,00,000 and average debtors of Rs.1,00,000. The average collection period (365 days) is about:","options":["45 days","60 days","12 days","30 days"],"answer":3,"explanation":"Debtors turnover = 12,00,000/1,00,000 = 12; collection period = 365/12 = about 30 days.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA064","number":64,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has credit sales of Rs.12,00,000 and average debtors of Rs.1,00,000. The average collection period (365 days) is about:","options":[{"key":"A","text":"45 days"},{"key":"B","text":"60 days"},{"key":"C","text":"12 days"},{"key":"D","text":"30 days"}],"answer":"D","explanation":"Debtors turnover = 12,00,000/1,00,000 = 12; collection period = 365/12 = about 30 days.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA064","optionFormat":"letter"},"contentSignature":"8f0dd969d5fdb17ccb76a94e5284d04c4f553df1e144b99ddfd3a2a771b79868","kind":"mcq"},{"id":"deep-management-MA065","sourceNumber":65,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"CREDITORS (payables) TURNOVER ratio is:","options":["The creditors of the business divided by the purchases of the year","The cost of goods sold divided by the creditors of the business","The sales of the year divided by the creditors of the business","CREDIT PURCHASES / AVERAGE CREDITORS (incl. bills payable)"],"answer":3,"explanation":"Payables turnover and the corresponding payment period measure how slowly/quickly the firm pays suppliers.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA065","number":65,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"CREDITORS (payables) TURNOVER ratio is:","options":[{"key":"A","text":"The creditors of the business divided by the purchases of the year"},{"key":"B","text":"The cost of goods sold divided by the creditors of the business"},{"key":"C","text":"The sales of the year divided by the creditors of the business"},{"key":"D","text":"CREDIT PURCHASES / AVERAGE CREDITORS (incl. bills payable)"}],"answer":"D","explanation":"Payables turnover and the corresponding payment period measure how slowly/quickly the firm pays suppliers.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CREDITORS (payables) TURNOVER ratio is:","options":["Creditors / Purchases","COGS / Creditors","Sales / Creditors","CREDIT PURCHASES / AVERAGE CREDITORS (incl. bills payable)"],"answer":3,"explanation":"Payables turnover and the corresponding payment period measure how slowly/quickly the firm pays suppliers.","revision":"original","contentSignature":"2e8d2aa47f9b49c1b748627f4780ec4ff4751b7fea994627f16c5e15f4749404"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA065","optionFormat":"letter"},"contentSignature":"70f6533fb8483f28fd682672ef1739ae75b0191d96fa76c835c73ecdfef497b9","kind":"mcq"},{"id":"deep-management-MA066","sourceNumber":66,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"WORKING CAPITAL TURNOVER ratio is:","options":["Sales / Fixed assets","Sales (or COGS) / WORKING CAPITAL","Working capital / Sales","Current assets / Sales"],"answer":1,"explanation":"Working capital turnover = net sales / working capital (CA - CL); it shows how actively the working capital revolves.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA066","number":66,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"WORKING CAPITAL TURNOVER ratio is:","options":[{"key":"A","text":"Sales / Fixed assets"},{"key":"B","text":"Sales (or COGS) / WORKING CAPITAL"},{"key":"C","text":"Working capital / Sales"},{"key":"D","text":"Current assets / Sales"}],"answer":"B","explanation":"Working capital turnover = net sales / working capital (CA - CL); it shows how actively the working capital revolves.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA066","optionFormat":"letter"},"contentSignature":"3035ea30358712cd2c1574ef5cf240a576e7836f679c599dfa891f40f8beb496","kind":"mcq"},{"id":"deep-management-MA067","sourceNumber":67,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"FIXED ASSETS TURNOVER ratio is:","options":["Sales / NET FIXED ASSETS (at WDV)","The fixed assets of the business divided by the sales of the year","The cost of goods sold divided by the fixed assets of the business","The sales of the year divided by the gross block of the business"],"answer":0,"explanation":"Fixed-assets turnover = net sales / net fixed assets; a low ratio signals over-capitalisation or idle capacity.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA067","number":67,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"FIXED ASSETS TURNOVER ratio is:","options":[{"key":"A","text":"Sales / NET FIXED ASSETS (at WDV)"},{"key":"B","text":"The fixed assets of the business divided by the sales of the year"},{"key":"C","text":"The cost of goods sold divided by the fixed assets of the business"},{"key":"D","text":"The sales of the year divided by the gross block of the business"}],"answer":"A","explanation":"Fixed-assets turnover = net sales / net fixed assets; a low ratio signals over-capitalisation or idle capacity.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"FIXED ASSETS TURNOVER ratio is:","options":["Sales / NET FIXED ASSETS (at WDV)","Fixed assets / Sales","COGS / Fixed assets","Sales / Gross block"],"answer":0,"explanation":"Fixed-assets turnover = net sales / net fixed assets; a low ratio signals over-capitalisation or idle capacity.","revision":"original","contentSignature":"4379ff488272fb340358a730f0f7f87fb5bc768b20d2c59c5f847201e6c1e531"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA067","optionFormat":"letter"},"contentSignature":"87fa3fc474b5aff811a95c353fe44b3992f17a38f70136343e54677771f0032e","kind":"mcq"},{"id":"deep-management-MA068","sourceNumber":68,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"TOTAL ASSETS TURNOVER ratio is:","options":["The profit of the year divided by the total assets of the business","The total assets of the business divided by the sales of the year","The sales of the year divided by the equity of the company","Sales / TOTAL ASSETS (or capital employed)"],"answer":3,"explanation":"Total assets turnover shows sales generated per rupee of assets; it is a component of the DuPont ROI decomposition.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA068","number":68,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"TOTAL ASSETS TURNOVER ratio is:","options":[{"key":"A","text":"The profit of the year divided by the total assets of the business"},{"key":"B","text":"The total assets of the business divided by the sales of the year"},{"key":"C","text":"The sales of the year divided by the equity of the company"},{"key":"D","text":"Sales / TOTAL ASSETS (or capital employed)"}],"answer":"D","explanation":"Total assets turnover shows sales generated per rupee of assets; it is a component of the DuPont ROI decomposition.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TOTAL ASSETS TURNOVER ratio is:","options":["Profit / Assets","Assets / Sales","Sales / Equity","Sales / TOTAL ASSETS (or capital employed)"],"answer":3,"explanation":"Total assets turnover shows sales generated per rupee of assets; it is a component of the DuPont ROI decomposition.","revision":"original","contentSignature":"0e5131a30bccb8ff8059532519188723e02d274d6b89575128eb7a783a1d8592"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA068","optionFormat":"letter"},"contentSignature":"ef79bc4dfa139782d6aa6f5136082effac8234109c441923ac48ca0d1b24c9f8","kind":"mcq"},{"id":"deep-management-MA069","sourceNumber":69,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"GROSS PROFIT ratio is:","options":["Net profit / Sales x 100","COGS / Sales x 100","GROSS PROFIT / NET SALES x 100","Gross profit / COGS"],"answer":2,"explanation":"GP ratio = (sales - COGS)/net sales x 100.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA069","number":69,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"GROSS PROFIT ratio is:","options":[{"key":"A","text":"Net profit / Sales x 100"},{"key":"B","text":"COGS / Sales x 100"},{"key":"C","text":"GROSS PROFIT / NET SALES x 100"},{"key":"D","text":"Gross profit / COGS"}],"answer":"C","explanation":"GP ratio = (sales - COGS)/net sales x 100.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA069","optionFormat":"letter"},"contentSignature":"a16fc70221bf389e18f81aa1ccce3db9cad31c15eb90cdd0c18ec45eb7e2a887","kind":"mcq"},{"id":"deep-management-MA070","sourceNumber":70,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"NET PROFIT ratio is:","options":["The profit before tax divided by the capital of the business","NET PROFIT (after tax) / NET SALES x 100","The net profit of the year divided by the capital of the business","The gross profit of the year divided by the sales of the year"],"answer":1,"explanation":"NP ratio = net profit after tax / net sales x 100 (some texts use profit before tax); it shows overall profitability per sales rupee.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA070","number":70,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"NET PROFIT ratio is:","options":[{"key":"A","text":"The profit before tax divided by the capital of the business"},{"key":"B","text":"NET PROFIT (after tax) / NET SALES x 100"},{"key":"C","text":"The net profit of the year divided by the capital of the business"},{"key":"D","text":"The gross profit of the year divided by the sales of the year"}],"answer":"B","explanation":"NP ratio = net profit after tax / net sales x 100 (some texts use profit before tax); it shows overall profitability per sales rupee.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"NET PROFIT ratio is:","options":["PBT / Capital","NET PROFIT (after tax) / NET SALES x 100","Net profit / Capital","Gross profit / Sales"],"answer":1,"explanation":"NP ratio = net profit after tax / net sales x 100 (some texts use profit before tax); it shows overall profitability per sales rupee.","revision":"original","contentSignature":"81bd99624941426b34c9c6f6e25ef987a97f76f032b12f13e4607ef25483622c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA070","optionFormat":"letter"},"contentSignature":"42aefd8aec13354115c5b42f7d05cda2b33837b09c9e9c85a695e1725dafd473","kind":"mcq"},{"id":"deep-management-MA071","sourceNumber":71,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The OPERATING ratio is:","options":["The sales of the year divided by the operating cost of the business","(COST OF GOODS SOLD + OPERATING EXPENSES) / NET SALES x 100","The operating profit of the year divided by the sales of the year","The fixed cost of the year divided by the sales of the year"],"answer":1,"explanation":"Operating ratio + operating PROFIT ratio = 100%; a lower operating ratio indicates better operating efficiency.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA071","number":71,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The OPERATING ratio is:","options":[{"key":"A","text":"The sales of the year divided by the operating cost of the business"},{"key":"B","text":"(COST OF GOODS SOLD + OPERATING EXPENSES) / NET SALES x 100"},{"key":"C","text":"The operating profit of the year divided by the sales of the year"},{"key":"D","text":"The fixed cost of the year divided by the sales of the year"}],"answer":"B","explanation":"Operating ratio + operating PROFIT ratio = 100%; a lower operating ratio indicates better operating efficiency.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The OPERATING ratio is:","options":["Sales / Operating cost","(COST OF GOODS SOLD + OPERATING EXPENSES) / NET SALES x 100","Operating profit / Sales","Fixed cost / Sales"],"answer":1,"explanation":"Operating ratio + operating PROFIT ratio = 100%; a lower operating ratio indicates better operating efficiency.","revision":"original","contentSignature":"1e106d06deeb7d3d903c54ef2f7aeae5da688d2d5359d0f58b83cdd59b0003b7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA071","optionFormat":"letter"},"contentSignature":"7000dfa718af07e4e0c6bbd42f4b8737d2fec3755dd7b1004fb0deee7eaff64d","kind":"mcq"},{"id":"deep-management-MA072","sourceNumber":72,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"If the operating ratio is 75%, the operating PROFIT ratio is:","options":["75%","Cannot say","25%","33%"],"answer":2,"explanation":"Operating profit ratio = 100 - operating ratio = 100 - 75 = 25%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA072","number":72,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"If the operating ratio is 75%, the operating PROFIT ratio is:","options":[{"key":"A","text":"75%"},{"key":"B","text":"Cannot say"},{"key":"C","text":"25%"},{"key":"D","text":"33%"}],"answer":"C","explanation":"Operating profit ratio = 100 - operating ratio = 100 - 75 = 25%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA072","optionFormat":"letter"},"contentSignature":"7ae23810aa1c73460bf4b76df9d999d771fbdfbc42edc1fe6b5632a17c09ed27","kind":"mcq"},{"id":"deep-management-MA073","sourceNumber":73,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The EXPENSE ratio for a specific expense is:","options":["That expense divided by the cost of goods sold, times 100","That expense divided by the profit of the year, times 100","The sales of the year divided by that expense, times 100","That expense / NET SALES x 100"],"answer":3,"explanation":"Individual expense ratios (administrative, selling, financial) express each expense as a percentage of net sales.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA073","number":73,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The EXPENSE ratio for a specific expense is:","options":[{"key":"A","text":"That expense divided by the cost of goods sold, times 100"},{"key":"B","text":"That expense divided by the profit of the year, times 100"},{"key":"C","text":"The sales of the year divided by that expense, times 100"},{"key":"D","text":"That expense / NET SALES x 100"}],"answer":"D","explanation":"Individual expense ratios (administrative, selling, financial) express each expense as a percentage of net sales.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The EXPENSE ratio for a specific expense is:","options":["Expense / COGS","Expense / Profit","Sales / Expense","That expense / NET SALES x 100"],"answer":3,"explanation":"Individual expense ratios (administrative, selling, financial) express each expense as a percentage of net sales.","revision":"original","contentSignature":"a5f7737408c7b1177368ac90cdb40e45dbb4bdbf40e840b89c070f71d917d4ec"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA073","optionFormat":"letter"},"contentSignature":"2e8538f6ca99116b44958333b521f20d0ac978de63e33a92ce9b483087796af6","kind":"mcq"},{"id":"deep-management-MA074","sourceNumber":74,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON CAPITAL EMPLOYED (ROCE/ROI) is:","options":["The equity of the company divided by the total assets of the company","The EBIT of the year divided by the equity of the company","The net profit of the year divided by the sales of the year","EBIT (or profit before interest and tax) / CAPITAL EMPLOYED x 100"],"answer":3,"explanation":"ROCE = profit before interest and tax / capital employed x 100; capital employed = equity + long-term debt (or total assets - current liabilities).","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA074","number":74,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON CAPITAL EMPLOYED (ROCE/ROI) is:","options":[{"key":"A","text":"The equity of the company divided by the total assets of the company"},{"key":"B","text":"The EBIT of the year divided by the equity of the company"},{"key":"C","text":"The net profit of the year divided by the sales of the year"},{"key":"D","text":"EBIT (or profit before interest and tax) / CAPITAL EMPLOYED x 100"}],"answer":"D","explanation":"ROCE = profit before interest and tax / capital employed x 100; capital employed = equity + long-term debt (or total assets - current liabilities).","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RETURN ON CAPITAL EMPLOYED (ROCE/ROI) is:","options":["Equity / Assets","EBIT / Equity","Net profit / Sales","EBIT (or profit before interest and tax) / CAPITAL EMPLOYED x 100"],"answer":3,"explanation":"ROCE = profit before interest and tax / capital employed x 100; capital employed = equity + long-term debt (or total assets - current liabilities).","revision":"original","contentSignature":"52f70f1c7263e27a2b8405a7cf0c3b6eb7527aba08180cd4ca08e845fb0e0e44"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA074","optionFormat":"letter"},"contentSignature":"a98e1f393a60d872cec4d96785284e8684fcce418244c06cea945e86ec740171","kind":"mcq"},{"id":"deep-management-MA075","sourceNumber":75,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Capital employed can be computed as:","options":["Shareholders funds + LONG-TERM DEBT = fixed assets + working capital (liabilities-side or assets-side approach)","The share capital of the company taken by itself","The total assets of the company, at their balance-sheet values as on the date of the accounts","The equity capital plus the reserves of the company, and no borrowings or long-term debt of any kind from any source"],"answer":0,"explanation":"Both approaches converge: own funds + borrowed long-term funds = net fixed assets + working capital (+ investments).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA075","number":75,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Capital employed can be computed as:","options":[{"key":"A","text":"Shareholders funds + LONG-TERM DEBT = fixed assets + working capital (liabilities-side or assets-side approach)"},{"key":"B","text":"The share capital of the company taken by itself"},{"key":"C","text":"The total assets of the company, at their balance-sheet values as on the date of the accounts"},{"key":"D","text":"The equity capital plus the reserves of the company, and no borrowings or long-term debt of any kind from any source"}],"answer":"A","explanation":"Both approaches converge: own funds + borrowed long-term funds = net fixed assets + working capital (+ investments).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital employed can be computed as:","options":["Shareholders funds + LONG-TERM DEBT = fixed assets + working capital (liabilities-side or assets-side approach)","Share capital only","Total assets","Equity + Reserves only"],"answer":0,"explanation":"Both approaches converge: own funds + borrowed long-term funds = net fixed assets + working capital (+ investments).","revision":"original","contentSignature":"8691c3301b68661b1e91cae41595e78c5dc67aa49a72c08ed773e60892ac14bf"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA075","optionFormat":"letter"},"contentSignature":"f9df5df23119034c6230b2fa0b334baf9c2551b2f79aa3aa74d5096147f4e130","kind":"mcq"},{"id":"deep-management-MA076","sourceNumber":76,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON EQUITY (ROE) is:","options":["The net profit after tax divided by the total assets of the company, times 100","The EBIT of the year divided by the equity of the company, times 100","(NPAT - preference dividend) / EQUITY SHAREHOLDERS FUNDS x 100","The sales of the year divided by the equity of the company, times 100"],"answer":2,"explanation":"ROE measures the return on ordinary shareholders funds; preference dividend is deducted because it is a prior charge.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA076","number":76,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON EQUITY (ROE) is:","options":[{"key":"A","text":"The net profit after tax divided by the total assets of the company, times 100"},{"key":"B","text":"The EBIT of the year divided by the equity of the company, times 100"},{"key":"C","text":"(NPAT - preference dividend) / EQUITY SHAREHOLDERS FUNDS x 100"},{"key":"D","text":"The sales of the year divided by the equity of the company, times 100"}],"answer":"C","explanation":"ROE measures the return on ordinary shareholders funds; preference dividend is deducted because it is a prior charge.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RETURN ON EQUITY (ROE) is:","options":["NPAT / Total assets","EBIT / Equity","(NPAT - preference dividend) / EQUITY SHAREHOLDERS FUNDS x 100","Sales / Equity"],"answer":2,"explanation":"ROE measures the return on ordinary shareholders funds; preference dividend is deducted because it is a prior charge.","revision":"original","contentSignature":"29999c8ac591101aa5a7700b4887a7776822ae056374e879cc7fb438205f65de"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA076","optionFormat":"letter"},"contentSignature":"9943466cf747f7584b088989ae1095090db47624fbe39dfde52528660c69be84","kind":"mcq"},{"id":"deep-management-MA077","sourceNumber":77,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON TOTAL ASSETS (ROA) is:","options":["The equity of the company divided by the total assets of the company, times 100","The EBIT of the year divided by the equity of the company, times 100","The sales of the year divided by the total assets of the company, times 100","Net profit (after tax) / TOTAL ASSETS x 100 (or EBIT / average total assets)"],"answer":3,"explanation":"ROA shows how productively the asset base generates profit, independent of financing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA077","number":77,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"RETURN ON TOTAL ASSETS (ROA) is:","options":[{"key":"A","text":"The equity of the company divided by the total assets of the company, times 100"},{"key":"B","text":"The EBIT of the year divided by the equity of the company, times 100"},{"key":"C","text":"The sales of the year divided by the total assets of the company, times 100"},{"key":"D","text":"Net profit (after tax) / TOTAL ASSETS x 100 (or EBIT / average total assets)"}],"answer":"D","explanation":"ROA shows how productively the asset base generates profit, independent of financing.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RETURN ON TOTAL ASSETS (ROA) is:","options":["Equity / Assets","EBIT / Equity","Sales / Assets","Net profit (after tax) / TOTAL ASSETS x 100 (or EBIT / average total assets)"],"answer":3,"explanation":"ROA shows how productively the asset base generates profit, independent of financing.","revision":"original","contentSignature":"6d24af1d6391d83608166913eaeb3aafdc5d08712fa4b45e7d9ecae1080e0afa"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA077","optionFormat":"letter"},"contentSignature":"0868932002d1351648572b0f3ac8a90af1c49b667dfd13c6fe452b625de77dd6","kind":"mcq"},{"id":"deep-management-MA078","sourceNumber":78,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"EARNINGS PER SHARE (EPS) is:","options":["The net profit of the year divided by the number of the preference shares","(NPAT - preference dividend) / NUMBER OF EQUITY SHARES","The EBIT of the year divided by the number of the equity shares","The dividend of the year divided by the number of the equity shares"],"answer":1,"explanation":"EPS = net profit after tax and preference dividend divided by the number of equity shares (AS-20 uses weighted average shares).","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA078","number":78,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"EARNINGS PER SHARE (EPS) is:","options":[{"key":"A","text":"The net profit of the year divided by the number of the preference shares"},{"key":"B","text":"(NPAT - preference dividend) / NUMBER OF EQUITY SHARES"},{"key":"C","text":"The EBIT of the year divided by the number of the equity shares"},{"key":"D","text":"The dividend of the year divided by the number of the equity shares"}],"answer":"B","explanation":"EPS = net profit after tax and preference dividend divided by the number of equity shares (AS-20 uses weighted average shares).","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"EARNINGS PER SHARE (EPS) is:","options":["Net profit / Preference shares","(NPAT - preference dividend) / NUMBER OF EQUITY SHARES","EBIT / Shares","Dividend / Shares"],"answer":1,"explanation":"EPS = net profit after tax and preference dividend divided by the number of equity shares (AS-20 uses weighted average shares).","revision":"original","contentSignature":"2a0eaa936dbb64821e9fd7e2716eacf4403897a422b37092aad751c182909af5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA078","optionFormat":"letter"},"contentSignature":"94b5436c9466793aa66e1d7985d5976d1fbdd8031ea3458d3f41121116d86e78","kind":"mcq"},{"id":"deep-management-MA079","sourceNumber":79,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A company earns NPAT Rs.82,000 (no preference capital) with 10,000 equity shares. EPS is:","options":["Rs.82","Rs.0.82","Rs.8.20","Rs.16.40"],"answer":2,"explanation":"82,000 / 10,000 = Rs.8.20 per share.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA079","number":79,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A company earns NPAT Rs.82,000 (no preference capital) with 10,000 equity shares. EPS is:","options":[{"key":"A","text":"Rs.82"},{"key":"B","text":"Rs.0.82"},{"key":"C","text":"Rs.8.20"},{"key":"D","text":"Rs.16.40"}],"answer":"C","explanation":"82,000 / 10,000 = Rs.8.20 per share.","source":"Recall 2018","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA079","optionFormat":"letter"},"contentSignature":"e84a76d9860f504405a733c7312034adf8711d709c2a6b06b53cd2b92646d231","kind":"mcq"},{"id":"deep-management-MA080","sourceNumber":80,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The PRICE-EARNINGS (P/E) ratio is:","options":["Dividend / Price","Book value / Price","EPS / Market price","MARKET PRICE per share / EPS"],"answer":3,"explanation":"P/E = MPS/EPS; it shows what the market pays for one rupee of current earnings - a valuation and confidence indicator.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA080","number":80,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The PRICE-EARNINGS (P/E) ratio is:","options":[{"key":"A","text":"Dividend / Price"},{"key":"B","text":"Book value / Price"},{"key":"C","text":"EPS / Market price"},{"key":"D","text":"MARKET PRICE per share / EPS"}],"answer":"D","explanation":"P/E = MPS/EPS; it shows what the market pays for one rupee of current earnings - a valuation and confidence indicator.","source":"Recall 2018","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA080","optionFormat":"letter"},"contentSignature":"fef180e1ff113486e65d1d2cc8f7321151f3322ade8d24cb4b7e5c7a68d742d3","kind":"mcq"},{"id":"deep-management-MA081","sourceNumber":81,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A company has EPS of Rs.8.20 and a P/E ratio of 8. Its market price per share is:","options":["Rs.8.20","Rs.1.025","Rs.65.60","Rs.16.40"],"answer":2,"explanation":"MPS = EPS x P/E = 8.20 x 8 = Rs.65.60.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA081","number":81,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A company has EPS of Rs.8.20 and a P/E ratio of 8. Its market price per share is:","options":[{"key":"A","text":"Rs.8.20"},{"key":"B","text":"Rs.1.025"},{"key":"C","text":"Rs.65.60"},{"key":"D","text":"Rs.16.40"}],"answer":"C","explanation":"MPS = EPS x P/E = 8.20 x 8 = Rs.65.60.","source":"Recall 2018","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA081","optionFormat":"letter"},"contentSignature":"b220cedb9b43b10c5b350d1bc1a4eb336415f667b8970d86b7683a73f2eb860c","kind":"mcq"},{"id":"deep-management-MA082","sourceNumber":82,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DIVIDEND YIELD ratio is:","options":["The dividend of the year divided by the profit of the year, times 100","The dividend per share divided by the face value of the share, times 100","DIVIDEND PER SHARE / MARKET PRICE per share x 100","The dividend per share divided by the book value of the share, times 100"],"answer":2,"explanation":"Dividend yield = DPS/MPS; the related dividend payout ratio = DPS/EPS and retention = 1 - payout.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA082","number":82,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DIVIDEND YIELD ratio is:","options":[{"key":"A","text":"The dividend of the year divided by the profit of the year, times 100"},{"key":"B","text":"The dividend per share divided by the face value of the share, times 100"},{"key":"C","text":"DIVIDEND PER SHARE / MARKET PRICE per share x 100"},{"key":"D","text":"The dividend per share divided by the book value of the share, times 100"}],"answer":"C","explanation":"Dividend yield = DPS/MPS; the related dividend payout ratio = DPS/EPS and retention = 1 - payout.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DIVIDEND YIELD ratio is:","options":["Dividend / Profit","DPS / Face value","DIVIDEND PER SHARE / MARKET PRICE per share x 100","DPS / Book value"],"answer":2,"explanation":"Dividend yield = DPS/MPS; the related dividend payout ratio = DPS/EPS and retention = 1 - payout.","revision":"original","contentSignature":"0073ca548ab2dead0c53c959812148bb500b46f88bd003a8fb41ab6c99b7bed2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA082","optionFormat":"letter"},"contentSignature":"a067d6e7f46958259cd2d36389da0a001a4a75e1b58442bc037f0abdeead07d7","kind":"mcq"},{"id":"deep-management-MA083","sourceNumber":83,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DIVIDEND PAYOUT ratio is:","options":["DPS / MPS","DPS / EPS x 100","EPS / DPS","Dividend / Capital"],"answer":1,"explanation":"Payout + retention ratio = 1; growth firms typically retain more (low payout).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA083","number":83,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"DIVIDEND PAYOUT ratio is:","options":[{"key":"A","text":"DPS / MPS"},{"key":"B","text":"DPS / EPS x 100"},{"key":"C","text":"EPS / DPS"},{"key":"D","text":"Dividend / Capital"}],"answer":"B","explanation":"Payout + retention ratio = 1; growth firms typically retain more (low payout).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA083","optionFormat":"letter"},"contentSignature":"b89b342636c575a0d3983bb09391eb8fbb2b76f981172a2c75572bc29e626aeb","kind":"mcq"},{"id":"deep-management-MA084","sourceNumber":84,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"BOOK VALUE per share is:","options":["The capital of the company divided by the number of the shares","The profit of the year divided by the number of the shares","The assets of the company divided by the number of the shares","Equity shareholders funds / NUMBER OF EQUITY SHARES"],"answer":3,"explanation":"Book value = (equity capital + reserves - fictitious assets) / number of equity shares; compare with market value.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA084","number":84,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"BOOK VALUE per share is:","options":[{"key":"A","text":"The capital of the company divided by the number of the shares"},{"key":"B","text":"The profit of the year divided by the number of the shares"},{"key":"C","text":"The assets of the company divided by the number of the shares"},{"key":"D","text":"Equity shareholders funds / NUMBER OF EQUITY SHARES"}],"answer":"D","explanation":"Book value = (equity capital + reserves - fictitious assets) / number of equity shares; compare with market value.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"BOOK VALUE per share is:","options":["Capital / Shares","Profit / Shares","Assets / Shares","Equity shareholders funds / NUMBER OF EQUITY SHARES"],"answer":3,"explanation":"Book value = (equity capital + reserves - fictitious assets) / number of equity shares; compare with market value.","revision":"original","contentSignature":"ffdfe2337114ff7f6911c60c620b8cf86132e6600e0250f53f0a853b6be0ec80"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA084","optionFormat":"letter"},"contentSignature":"b6e9943594ac4fbeacfabb818bfcd7b11e78111e4e66677937585d8686d98d3d","kind":"mcq"},{"id":"deep-management-MA085","sourceNumber":85,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The DuPont analysis decomposes RETURN ON INVESTMENT into:","options":["Net profit ratio x CAPITAL TURNOVER ratio (ROI = NP/Sales x Sales/Capital employed)","The EPS of the year multiplied by the P/E ratio of the company, as computed","The current ratio multiplied by the quick ratio of the company, as computed","The GP ratio multiplied by the stock turnover of the company, as computed"],"answer":0,"explanation":"DuPont: ROI = profit margin x asset turnover; it shows whether returns come from margins or asset efficiency.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA085","number":85,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The DuPont analysis decomposes RETURN ON INVESTMENT into:","options":[{"key":"A","text":"Net profit ratio x CAPITAL TURNOVER ratio (ROI = NP/Sales x Sales/Capital employed)"},{"key":"B","text":"The EPS of the year multiplied by the P/E ratio of the company, as computed"},{"key":"C","text":"The current ratio multiplied by the quick ratio of the company, as computed"},{"key":"D","text":"The GP ratio multiplied by the stock turnover of the company, as computed"}],"answer":"A","explanation":"DuPont: ROI = profit margin x asset turnover; it shows whether returns come from margins or asset efficiency.","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DuPont analysis decomposes RETURN ON INVESTMENT into:","options":["Net profit ratio x CAPITAL TURNOVER ratio (ROI = NP/Sales x Sales/Capital employed)","EPS x P/E","Current ratio x Quick ratio","GP ratio x Stock turnover"],"answer":0,"explanation":"DuPont: ROI = profit margin x asset turnover; it shows whether returns come from margins or asset efficiency.","revision":"original","contentSignature":"206e0d08c394b9299945e979902c272491296e7eb0e6256637088f3593f7fbfe"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA085","optionFormat":"letter"},"contentSignature":"d7b589f999631ffd9274189605c27dbc32946b9ceada76ebec2aea6ec0f4028d","kind":"mcq"},{"id":"deep-management-MA086","sourceNumber":86,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has a net profit ratio of 5% and a capital turnover ratio of 3 times. Its ROI (DuPont) is:","options":["15%","2%","8%","1.67%"],"answer":0,"explanation":"ROI = 5% x 3 = 15%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA086","number":86,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"A firm has a net profit ratio of 5% and a capital turnover ratio of 3 times. Its ROI (DuPont) is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"2%"},{"key":"C","text":"8%"},{"key":"D","text":"1.67%"}],"answer":"A","explanation":"ROI = 5% x 3 = 15%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA086","optionFormat":"letter"},"contentSignature":"5a583b595c51353d6d8b9347af121d2baab0e1800c6014ae0a4c79c05870cd2e","kind":"mcq"},{"id":"deep-management-MA087","sourceNumber":87,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"EARNINGS YIELD is the reciprocal of:","options":["P/E ratio (EPS / MPS x 100)","The dividend yield ratio of the company, as computed","The current ratio of the company, as computed","The payout ratio of the company, as computed"],"answer":0,"explanation":"Earnings yield = EPS/MPS = 1/(P/E); it is used to compare equity returns with bond yields.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA087","number":87,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"EARNINGS YIELD is the reciprocal of:","options":[{"key":"A","text":"P/E ratio (EPS / MPS x 100)"},{"key":"B","text":"The dividend yield ratio of the company, as computed"},{"key":"C","text":"The current ratio of the company, as computed"},{"key":"D","text":"The payout ratio of the company, as computed"}],"answer":"A","explanation":"Earnings yield = EPS/MPS = 1/(P/E); it is used to compare equity returns with bond yields.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"EARNINGS YIELD is the reciprocal of:","options":["P/E ratio (EPS / MPS x 100)","Dividend yield","Current ratio","Payout"],"answer":0,"explanation":"Earnings yield = EPS/MPS = 1/(P/E); it is used to compare equity returns with bond yields.","revision":"original","contentSignature":"d0816b0fd3e736f2a47965f37747a59fb5fd8facc6297e2e0480720e71e31e8c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA087","optionFormat":"letter"},"contentSignature":"67f2a6fce9dbebf7e1f5ecb28a2a6ede2bd7a03e531ef034b793a88324981189","kind":"mcq"},{"id":"deep-management-MA088","sourceNumber":88,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Preference share capital is treated as DEBT (not owners funds) when computing:","options":["The quick ratio of the company, where the preference capital is treated as debt always","The GP ratio of the company, where the preference capital is treated as debt always","The proprietary ratio in all cases, where the preference capital is treated as debt always","CAPITAL GEARING ratio (preference capital goes with fixed-return funds) and (in one convention) debt-equity"],"answer":3,"explanation":"For capital gearing, preference capital is clubbed with fixed-return bearing funds; for debt-equity, treatment varies - the question convention should be followed.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA088","number":88,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Preference share capital is treated as DEBT (not owners funds) when computing:","options":[{"key":"A","text":"The quick ratio of the company, where the preference capital is treated as debt always"},{"key":"B","text":"The GP ratio of the company, where the preference capital is treated as debt always"},{"key":"C","text":"The proprietary ratio in all cases, where the preference capital is treated as debt always"},{"key":"D","text":"CAPITAL GEARING ratio (preference capital goes with fixed-return funds) and (in one convention) debt-equity"}],"answer":"D","explanation":"For capital gearing, preference capital is clubbed with fixed-return bearing funds; for debt-equity, treatment varies - the question convention should be followed.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Preference share capital is treated as DEBT (not owners funds) when computing:","options":["Quick ratio","GP ratio","Proprietary ratio in all cases","CAPITAL GEARING ratio (preference capital goes with fixed-return funds) and (in one convention) debt-equity"],"answer":3,"explanation":"For capital gearing, preference capital is clubbed with fixed-return bearing funds; for debt-equity, treatment varies - the question convention should be followed.","revision":"original","contentSignature":"f1da63a681a92bda4fd99a60109acca9db70c7d72a35beaf97d78f25ff3b7e2e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA088","optionFormat":"letter"},"contentSignature":"33922c66d3e62b73407f4a696253ccacaf1635e2ca2a7ecea81b920e691e7c36","kind":"mcq"},{"id":"deep-management-MA089","sourceNumber":89,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Which of the following increases RETURN ON EQUITY without any change in total assets or profit?","options":["The issue of the new equity shares at par to the public","The creation of the revaluation reserve by the company","Replacement of equity by CHEAPER DEBT (trading on equity)","The issue of the bonus shares to the existing shareholders"],"answer":2,"explanation":"Substituting lower-cost debt for equity concentrates the same profit on a smaller equity base, raising ROE when ROI exceeds the interest rate.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA089","number":89,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Which of the following increases RETURN ON EQUITY without any change in total assets or profit?","options":[{"key":"A","text":"The issue of the new equity shares at par to the public"},{"key":"B","text":"The creation of the revaluation reserve by the company"},{"key":"C","text":"Replacement of equity by CHEAPER DEBT (trading on equity)"},{"key":"D","text":"The issue of the bonus shares to the existing shareholders"}],"answer":"C","explanation":"Substituting lower-cost debt for equity concentrates the same profit on a smaller equity base, raising ROE when ROI exceeds the interest rate.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following increases RETURN ON EQUITY without any change in total assets or profit?","options":["Issue of new equity at par","Revaluation reserve","Replacement of equity by CHEAPER DEBT (trading on equity)","Issue of bonus shares"],"answer":2,"explanation":"Substituting lower-cost debt for equity concentrates the same profit on a smaller equity base, raising ROE when ROI exceeds the interest rate.","revision":"original","contentSignature":"f3f7d116d93c64aa1decefb10aceaafd9c926c76dfbbd899e7f81621d059ff7f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA089","optionFormat":"letter"},"contentSignature":"d839c3d5dbdbf33872c3a90646f1ee7aa6ca1a8c6e2cf3545aab61e7fcb3f5b7","kind":"mcq"},{"id":"deep-management-MA090","sourceNumber":90,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The \"acid test\" of a company with quick assets Rs.90,000 and quick liabilities Rs.60,000 is:","options":["0.67:1","2:1","1.5:1","1:1"],"answer":2,"explanation":"90,000/60,000 = 1.5:1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA090","number":90,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"The \"acid test\" of a company with quick assets Rs.90,000 and quick liabilities Rs.60,000 is:","options":[{"key":"A","text":"0.67:1"},{"key":"B","text":"2:1"},{"key":"C","text":"1.5:1"},{"key":"D","text":"1:1"}],"answer":"C","explanation":"90,000/60,000 = 1.5:1.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA090","optionFormat":"letter"},"contentSignature":"2cb8a6588867ed005748e4c344a64aa3e79445cd64deed55e3360c6eccf81b2b","kind":"mcq"},{"id":"deep-management-MA091","sourceNumber":91,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"If gross profit ratio is 20% on sales of Rs.10,00,000 and indirect expenses are Rs.1,20,000, the net profit is:","options":["Rs.2,00,000","Rs.3,20,000","Rs.80,000","Rs.1,20,000"],"answer":2,"explanation":"GP = 20% of 10,00,000 = 2,00,000; NP = 2,00,000 - 1,20,000 = Rs.80,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA091","number":91,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"If gross profit ratio is 20% on sales of Rs.10,00,000 and indirect expenses are Rs.1,20,000, the net profit is:","options":[{"key":"A","text":"Rs.2,00,000"},{"key":"B","text":"Rs.3,20,000"},{"key":"C","text":"Rs.80,000"},{"key":"D","text":"Rs.1,20,000"}],"answer":"C","explanation":"GP = 20% of 10,00,000 = 2,00,000; NP = 2,00,000 - 1,20,000 = Rs.80,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA091","optionFormat":"letter"},"contentSignature":"c748c34cd2f99f55f2bba606c3dad40eaa877efeab6400338c0d27d64639569b","kind":"mcq"},{"id":"deep-management-MA092","sourceNumber":92,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M2 · Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Stock velocity of 73 days (365-day year) means an inventory turnover of:","options":["6 times","3 times","4 times","5 times"],"answer":3,"explanation":"365/73 = 5 times.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA092","number":92,"module":"M2","moduleTitle":"Ratio Analysis II - Activity, Profitability, DuPont & Market Ratios","question":"Stock velocity of 73 days (365-day year) means an inventory turnover of:","options":[{"key":"A","text":"6 times"},{"key":"B","text":"3 times"},{"key":"C","text":"4 times"},{"key":"D","text":"5 times"}],"answer":"D","explanation":"365/73 = 5 times.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA092","optionFormat":"letter"},"contentSignature":"d5f86aaf1723e6083d584e2cc12cad527cc5603a742df184450095fb83ac6760","kind":"mcq"},{"id":"deep-management-MA093","sourceNumber":93,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"A FUND FLOW statement analyses:","options":["The MOVEMENT OF WORKING CAPITAL (funds) between two balance-sheet dates - sources and applications of funds","Only the cash of the business - the movement of the cash balance between the two dates","The share prices of the company - the movement of the market price between the two dates","Only the bank balance of the business - its movement between the two balance-sheet dates"],"answer":0,"explanation":"Fund = working capital (current assets minus current liabilities); the statement explains its increase or decrease over the period.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA093","number":93,"module":"M3","moduleTitle":"Fund Flow Statement","question":"A FUND FLOW statement analyses:","options":[{"key":"A","text":"The MOVEMENT OF WORKING CAPITAL (funds) between two balance-sheet dates - sources and applications of funds"},{"key":"B","text":"Only the cash of the business - the movement of the cash balance between the two dates"},{"key":"C","text":"The share prices of the company - the movement of the market price between the two dates"},{"key":"D","text":"Only the bank balance of the business - its movement between the two balance-sheet dates"}],"answer":"A","explanation":"Fund = working capital (current assets minus current liabilities); the statement explains its increase or decrease over the period.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A FUND FLOW statement analyses:","options":["The MOVEMENT OF WORKING CAPITAL (funds) between two balance-sheet dates - sources and applications of funds","Only cash","Share prices","Bank balance only"],"answer":0,"explanation":"Fund = working capital (current assets minus current liabilities); the statement explains its increase or decrease over the period.","revision":"original","contentSignature":"49198da8cf9fcac4187e5ce018ccd09b108af870156b3acb3a742ed3b88ee5bd"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA093","optionFormat":"letter"},"contentSignature":"2d1e27ca29cfd536b6dc69ca04ae54a05a8226b80288917d8eb3089e0293ab97","kind":"mcq"},{"id":"deep-management-MA094","sourceNumber":94,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"In fund flow analysis, \"fund\" means:","options":["The share capital of the company, as subscribed by the shareholders","The fixed assets of the company, at their written-down value","Only the cash of the business, in hand and at the bank","WORKING CAPITAL (current assets minus current liabilities)"],"answer":3,"explanation":"The traditional meaning of funds in a funds-flow statement is net working capital.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA094","number":94,"module":"M3","moduleTitle":"Fund Flow Statement","question":"In fund flow analysis, \"fund\" means:","options":[{"key":"A","text":"The share capital of the company, as subscribed by the shareholders"},{"key":"B","text":"The fixed assets of the company, at their written-down value"},{"key":"C","text":"Only the cash of the business, in hand and at the bank"},{"key":"D","text":"WORKING CAPITAL (current assets minus current liabilities)"}],"answer":"D","explanation":"The traditional meaning of funds in a funds-flow statement is net working capital.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In fund flow analysis, \"fund\" means:","options":["Share capital","Fixed assets","Cash only","WORKING CAPITAL (current assets minus current liabilities)"],"answer":3,"explanation":"The traditional meaning of funds in a funds-flow statement is net working capital.","revision":"original","contentSignature":"f73fe921ac85fe47e9c4c0b006ee3c70660901f62aa2944715b8ac37f22f4c27"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA094","optionFormat":"letter"},"contentSignature":"7ae227f29461ee4520817e21ab63bfb6ea2d4b5c50c304e8e8485f1ed2cffd16","kind":"mcq"},{"id":"deep-management-MA095","sourceNumber":95,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Which of the following is a SOURCE of funds?","options":["The payment of the dividend to the shareholders of the company, year by year","The redemption of the debentures of the company, at their due dates","PURCHASE of fixed assets/investments, redemption of debentures/preference shares, repayment of long-term loans, payment of dividends and taxes - every one of these being a source of funds","FUNDS FROM OPERATIONS (net profit adjusted for non-fund items), issue of shares/debentures, long-term borrowings, sale of fixed assets/investments"],"answer":3,"explanation":"Sources add to working capital: operations, fresh long-term capital and disposal of non-current assets.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA095","number":95,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Which of the following is a SOURCE of funds?","options":[{"key":"A","text":"The payment of the dividend to the shareholders of the company, year by year"},{"key":"B","text":"The redemption of the debentures of the company, at their due dates"},{"key":"C","text":"PURCHASE of fixed assets/investments, redemption of debentures/preference shares, repayment of long-term loans, payment of dividends and taxes - every one of these being a source of funds"},{"key":"D","text":"FUNDS FROM OPERATIONS (net profit adjusted for non-fund items), issue of shares/debentures, long-term borrowings, sale of fixed assets/investments"}],"answer":"D","explanation":"Sources add to working capital: operations, fresh long-term capital and disposal of non-current assets.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is a SOURCE of funds?","options":["Payment of dividend","Redemption of debentures","Purchase of fixed assets","FUNDS FROM OPERATIONS (net profit adjusted for non-fund items), issue of shares/debentures, long-term borrowings, sale of fixed assets/investments"],"answer":3,"explanation":"Sources add to working capital: operations, fresh long-term capital and disposal of non-current assets.","revision":"original","contentSignature":"add29d4bc7c27422eb444ff5965c1bd95c446b9d87c595e4f28a25bbb70ad131"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA095","optionFormat":"letter"},"contentSignature":"a79eab63954a8d5e8f5481a4ba07bf73907bb7b20fe3eaa0fb97a2e43caa01d2","kind":"mcq"},{"id":"deep-management-MA096","sourceNumber":96,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Which of the following is an APPLICATION (use) of funds?","options":["The sale of the machinery of the business, at its book value or above","The funds from the operations of the business, computed in the usual way","PURCHASE of fixed assets/investments, redemption of debentures/preference shares, repayment of long-term loans, payment of dividends and taxes","ISSUE of shares and debentures, long-term borrowings, sale of fixed assets and investments, and the funds from operations - every one of these being an application of the funds of the business"],"answer":2,"explanation":"Applications consume working capital: acquiring non-current assets or retiring long-term funds and distributing profits.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA096","number":96,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Which of the following is an APPLICATION (use) of funds?","options":[{"key":"A","text":"The sale of the machinery of the business, at its book value or above"},{"key":"B","text":"The funds from the operations of the business, computed in the usual way"},{"key":"C","text":"PURCHASE of fixed assets/investments, redemption of debentures/preference shares, repayment of long-term loans, payment of dividends and taxes"},{"key":"D","text":"ISSUE of shares and debentures, long-term borrowings, sale of fixed assets and investments, and the funds from operations - every one of these being an application of the funds of the business"}],"answer":"C","explanation":"Applications consume working capital: acquiring non-current assets or retiring long-term funds and distributing profits.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is an APPLICATION (use) of funds?","options":["Sale of machinery","Funds from operations","PURCHASE of fixed assets/investments, redemption of debentures/preference shares, repayment of long-term loans, payment of dividends and taxes","Issue of shares"],"answer":2,"explanation":"Applications consume working capital: acquiring non-current assets or retiring long-term funds and distributing profits.","revision":"original","contentSignature":"6f2bb9058ad1b498ed39e8c777b65abf0d941bab884e4a06cb56c3613a5b959f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA096","optionFormat":"letter"},"contentSignature":"0081cee6d1631aa53fdc668f7d85e7b2ed089af47745c93c5ecf2d7a394285be","kind":"mcq"},{"id":"deep-management-MA097","sourceNumber":97,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"A transaction between two CURRENT items (e.g. goods purchased on credit) results in:","options":["An increase in the funds of the business, as a source of the funds","NO flow of funds - both items belong to the current (working capital) category","A source of the funds of the business, as working capital rises","An application of the funds of the business, as working capital falls"],"answer":1,"explanation":"Fund flow arises only when a transaction crosses the current/non-current boundary; current-current and non-current-non-current transactions create no flow.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA097","number":97,"module":"M3","moduleTitle":"Fund Flow Statement","question":"A transaction between two CURRENT items (e.g. goods purchased on credit) results in:","options":[{"key":"A","text":"An increase in the funds of the business, as a source of the funds"},{"key":"B","text":"NO flow of funds - both items belong to the current (working capital) category"},{"key":"C","text":"A source of the funds of the business, as working capital rises"},{"key":"D","text":"An application of the funds of the business, as working capital falls"}],"answer":"B","explanation":"Fund flow arises only when a transaction crosses the current/non-current boundary; current-current and non-current-non-current transactions create no flow.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A transaction between two CURRENT items (e.g. goods purchased on credit) results in:","options":["Increase in funds","NO flow of funds - both items belong to the current (working capital) category","Source of funds","Application of funds"],"answer":1,"explanation":"Fund flow arises only when a transaction crosses the current/non-current boundary; current-current and non-current-non-current transactions create no flow.","revision":"original","contentSignature":"7f03a622eff5268c7ef538bc7cca93825c44f01755c073ae2a2158133ed7164e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA097","optionFormat":"letter"},"contentSignature":"70e906688b2b639adcdaeb97322aec61639564546a7147af1a2b4d80da2aa4b4","kind":"mcq"},{"id":"deep-management-MA098","sourceNumber":98,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"A transaction between two NON-CURRENT items (e.g. issue of shares for machinery) results in:","options":["An application of the funds of the business concerned","A source of the funds of the business","NO flow of funds - both are non-current items","A cash inflow into the business"],"answer":2,"explanation":"Shares issued to acquire machinery cross no working-capital boundary; there is no fund flow (though it is a significant non-fund transaction).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA098","number":98,"module":"M3","moduleTitle":"Fund Flow Statement","question":"A transaction between two NON-CURRENT items (e.g. issue of shares for machinery) results in:","options":[{"key":"A","text":"An application of the funds of the business concerned"},{"key":"B","text":"A source of the funds of the business"},{"key":"C","text":"NO flow of funds - both are non-current items"},{"key":"D","text":"A cash inflow into the business"}],"answer":"C","explanation":"Shares issued to acquire machinery cross no working-capital boundary; there is no fund flow (though it is a significant non-fund transaction).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A transaction between two NON-CURRENT items (e.g. issue of shares for machinery) results in:","options":["Application of funds","Source of funds","NO flow of funds - both are non-current items","Cash inflow"],"answer":2,"explanation":"Shares issued to acquire machinery cross no working-capital boundary; there is no fund flow (though it is a significant non-fund transaction).","revision":"original","contentSignature":"65dc6cbcf1850db5894ff7831ae8beedb83dddfa47ea71ff205278dccb091cf6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA098","optionFormat":"letter"},"contentSignature":"89c4c8c2ca575e9ba2d6000c32df4252799bfb8e661192bc588e69276abd5a6b","kind":"mcq"},{"id":"deep-management-MA099","sourceNumber":99,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"A transaction between a CURRENT and a NON-CURRENT item results in:","options":["Always a source of the funds of the business, whatever the direction","Always an application of the funds of the business, whatever the direction","A FLOW of funds - source if working capital increases, application if it decreases","No movement of the funds of the business takes place between the two items in the books"],"answer":2,"explanation":"Only cross-category transactions move working capital: e.g. sale of a fixed asset for cash (source), purchase of machinery for cash (application).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA099","number":99,"module":"M3","moduleTitle":"Fund Flow Statement","question":"A transaction between a CURRENT and a NON-CURRENT item results in:","options":[{"key":"A","text":"Always a source of the funds of the business, whatever the direction"},{"key":"B","text":"Always an application of the funds of the business, whatever the direction"},{"key":"C","text":"A FLOW of funds - source if working capital increases, application if it decreases"},{"key":"D","text":"No movement of the funds of the business takes place between the two items in the books"}],"answer":"C","explanation":"Only cross-category transactions move working capital: e.g. sale of a fixed asset for cash (source), purchase of machinery for cash (application).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A transaction between a CURRENT and a NON-CURRENT item results in:","options":["Always a source","Always an application","A FLOW of funds - source if working capital increases, application if it decreases","No flow"],"answer":2,"explanation":"Only cross-category transactions move working capital: e.g. sale of a fixed asset for cash (source), purchase of machinery for cash (application).","revision":"original","contentSignature":"61d0732f06623a8cb675a38d39a438b46ae6b8e2e99e1e1ca6c8d144590594ed"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA099","optionFormat":"letter"},"contentSignature":"53f87d565a2c0addccd4b040abc5eed9c6a0f10c0073a464da80e3cfaae6e953","kind":"mcq"},{"id":"deep-management-MA100","sourceNumber":100,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"FUNDS FROM OPERATIONS is computed by:","options":["The EBIT of the year less the tax payable for the year","NET PROFIT + non-cash/non-operating DEBITS (depreciation, goodwill written off, loss on sale of assets, transfer to reserves) - non- operating CREDITS (profit on sale, dividend received)","The depreciation of the year added to the sales of the year","The cash sales of the year less the cash purchases of the year"],"answer":1,"explanation":"FFO starts from P&L profit and reverses all items that do not affect working capital or are non-operating.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA100","number":100,"module":"M3","moduleTitle":"Fund Flow Statement","question":"FUNDS FROM OPERATIONS is computed by:","options":[{"key":"A","text":"The EBIT of the year less the tax payable for the year"},{"key":"B","text":"NET PROFIT + non-cash/non-operating DEBITS (depreciation, goodwill written off, loss on sale of assets, transfer to reserves) - non- operating CREDITS (profit on sale, dividend received)"},{"key":"C","text":"The depreciation of the year added to the sales of the year"},{"key":"D","text":"The cash sales of the year less the cash purchases of the year"}],"answer":"B","explanation":"FFO starts from P&L profit and reverses all items that do not affect working capital or are non-operating.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"FUNDS FROM OPERATIONS is computed by:","options":["EBIT - tax","NET PROFIT + non-cash/non-operating DEBITS (depreciation, goodwill written off, loss on sale of assets, transfer to reserves) - non- operating CREDITS (profit on sale, dividend received)","Adding depreciation to sales","Cash sales - cash purchases"],"answer":1,"explanation":"FFO starts from P&L profit and reverses all items that do not affect working capital or are non-operating.","revision":"original","contentSignature":"960f4c2319fe97839c5fe55ac6419bcc88f4019f181f6f183bc906bb6a49af82"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA100","optionFormat":"letter"},"contentSignature":"7dd6b781ef1185e75c9edcd542e5229f5cb343c0098c723b92ff82e991451d3f","kind":"mcq"},{"id":"deep-management-MA101","sourceNumber":101,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Depreciation charged on fixed assets is:","options":["Ignored everywhere in the fund flow analysis, as a mere book entry","An application of the funds of the business, since the assets fall in value","A source of the funds of the business, since the charge raises the funds","ADDED BACK to profit while computing funds from operations (a non-fund charge)"],"answer":3,"explanation":"Depreciation reduces profit without any outflow of working capital, so it is added back to find FFO.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA101","number":101,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Depreciation charged on fixed assets is:","options":[{"key":"A","text":"Ignored everywhere in the fund flow analysis, as a mere book entry"},{"key":"B","text":"An application of the funds of the business, since the assets fall in value"},{"key":"C","text":"A source of the funds of the business, since the charge raises the funds"},{"key":"D","text":"ADDED BACK to profit while computing funds from operations (a non-fund charge)"}],"answer":"D","explanation":"Depreciation reduces profit without any outflow of working capital, so it is added back to find FFO.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation charged on fixed assets is:","options":["Ignored everywhere","An application of funds","A source of funds","ADDED BACK to profit while computing funds from operations (a non-fund charge)"],"answer":3,"explanation":"Depreciation reduces profit without any outflow of working capital, so it is added back to find FFO.","revision":"original","contentSignature":"6c8e5a1bdd49abf46e75af5b556a0b749173cd6d10ee3c4278c4a4e91ff9ed02"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA101","optionFormat":"letter"},"contentSignature":"660c48563c9123a50bb4e295a3ead1cf7ed29866efe733d98f56c1bbb335acec","kind":"mcq"},{"id":"deep-management-MA102","sourceNumber":102,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Goodwill WRITTEN OFF is:","options":["An application of the funds of the business, since the assets fall in value","ADDED BACK to profit in FFO computation (non-fund item)","A cash outflow of the business, since the goodwill is paid away","A source of the funds of the business, since the charge raises the funds"],"answer":1,"explanation":"Writing off intangibles is a book entry with no working-capital effect; it is added back.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA102","number":102,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Goodwill WRITTEN OFF is:","options":[{"key":"A","text":"An application of the funds of the business, since the assets fall in value"},{"key":"B","text":"ADDED BACK to profit in FFO computation (non-fund item)"},{"key":"C","text":"A cash outflow of the business, since the goodwill is paid away"},{"key":"D","text":"A source of the funds of the business, since the charge raises the funds"}],"answer":"B","explanation":"Writing off intangibles is a book entry with no working-capital effect; it is added back.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Goodwill WRITTEN OFF is:","options":["An application of funds","ADDED BACK to profit in FFO computation (non-fund item)","A cash outflow","A source of funds"],"answer":1,"explanation":"Writing off intangibles is a book entry with no working-capital effect; it is added back.","revision":"original","contentSignature":"0725081ea613189477f65c9288e28afbd475d17d1d709c4041e91da89fe3ab9a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA102","optionFormat":"letter"},"contentSignature":"cf22ba2cec9de2fba69c9803776e848a119b48d627ca8fd773817b41d5961cbe","kind":"mcq"},{"id":"deep-management-MA103","sourceNumber":103,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Profit on sale of a FIXED ASSET is:","options":["Treated as the depreciation of the year, and handled exactly like it in the computation","Added to the profit in the FFO computation, as a non-fund credit of the year","An application of the funds of the business, shown on the uses side of the statement","SUBTRACTED from profit in FFO computation; the full sale PROCEEDS are shown separately as a source"],"answer":3,"explanation":"Only the total proceeds are a source; the profit element inside them is non-operating and is removed from FFO.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA103","number":103,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Profit on sale of a FIXED ASSET is:","options":[{"key":"A","text":"Treated as the depreciation of the year, and handled exactly like it in the computation"},{"key":"B","text":"Added to the profit in the FFO computation, as a non-fund credit of the year"},{"key":"C","text":"An application of the funds of the business, shown on the uses side of the statement"},{"key":"D","text":"SUBTRACTED from profit in FFO computation; the full sale PROCEEDS are shown separately as a source"}],"answer":"D","explanation":"Only the total proceeds are a source; the profit element inside them is non-operating and is removed from FFO.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Profit on sale of a FIXED ASSET is:","options":["Treated as depreciation","Added to FFO","An application","SUBTRACTED from profit in FFO computation; the full sale PROCEEDS are shown separately as a source"],"answer":3,"explanation":"Only the total proceeds are a source; the profit element inside them is non-operating and is removed from FFO.","revision":"original","contentSignature":"99472a90866929ed51d92a5e1b4515db147d0086d283d93a124e81150709e3f6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA103","optionFormat":"letter"},"contentSignature":"d721f587799dc5786a2d5d3fda9f8616e140b9cc659caa04815bb6ace41df6e1","kind":"mcq"},{"id":"deep-management-MA104","sourceNumber":104,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"LOSS on sale of a fixed asset is:","options":["An application of the funds of the business, shown on the uses side","Ignored altogether in the fund flow analysis, as a mere book entry","Subtracted from the profit in the FFO computation, as a non-fund debit","Added back in FFO; the sale proceeds appear as a source"],"answer":3,"explanation":"The book loss is non-operating (added back); the actual proceeds are a source of funds.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA104","number":104,"module":"M3","moduleTitle":"Fund Flow Statement","question":"LOSS on sale of a fixed asset is:","options":[{"key":"A","text":"An application of the funds of the business, shown on the uses side"},{"key":"B","text":"Ignored altogether in the fund flow analysis, as a mere book entry"},{"key":"C","text":"Subtracted from the profit in the FFO computation, as a non-fund debit"},{"key":"D","text":"Added back in FFO; the sale proceeds appear as a source"}],"answer":"D","explanation":"The book loss is non-operating (added back); the actual proceeds are a source of funds.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"LOSS on sale of a fixed asset is:","options":["An application of funds","Ignored","Subtracted in FFO","Added back in FFO; the sale proceeds appear as a source"],"answer":3,"explanation":"The book loss is non-operating (added back); the actual proceeds are a source of funds.","revision":"original","contentSignature":"c8ad04fe336acabd60250e95e75d1ba0381b140bbd45cd179b50e4910966729a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA104","optionFormat":"letter"},"contentSignature":"8b544120f138481f237a885ac8274b73b46c07cf60aff2d669e84fcc04bb765e","kind":"mcq"},{"id":"deep-management-MA105","sourceNumber":105,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"The SCHEDULE OF CHANGES IN WORKING CAPITAL shows:","options":["The cash flows of the business between the two dates","The movement in the reserves between the two dates","The increase/decrease in EACH current asset and current liability and the net change in working capital between two dates","The sources from which funds came between the two dates"],"answer":2,"explanation":"An increase in current assets increases working capital; an increase in current liabilities decreases it; the schedule nets these out.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA105","number":105,"module":"M3","moduleTitle":"Fund Flow Statement","question":"The SCHEDULE OF CHANGES IN WORKING CAPITAL shows:","options":[{"key":"A","text":"The cash flows of the business between the two dates"},{"key":"B","text":"The movement in the reserves between the two dates"},{"key":"C","text":"The increase/decrease in EACH current asset and current liability and the net change in working capital between two dates"},{"key":"D","text":"The sources from which funds came between the two dates"}],"answer":"C","explanation":"An increase in current assets increases working capital; an increase in current liabilities decreases it; the schedule nets these out.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The SCHEDULE OF CHANGES IN WORKING CAPITAL shows:","options":["Cash flow","Reserves movement","The increase/decrease in EACH current asset and current liability and the net change in working capital between two dates","Sources of funds"],"answer":2,"explanation":"An increase in current assets increases working capital; an increase in current liabilities decreases it; the schedule nets these out.","revision":"original","contentSignature":"2ba5be339102dd33706330a67bfc5235b6f071edff82c7bef81045982a6a31da"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA105","optionFormat":"letter"},"contentSignature":"f5f09da868b5f42402dcdd339fd776478495b833190e98186a29b16cea71c340","kind":"mcq"},{"id":"deep-management-MA106","sourceNumber":106,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"While preparing the schedule of changes in working capital:","options":["Both increases raise the working capital of the business, whether of current assets or of current liabilities in the period","Both increases lower the working capital of the business","The current liabilities never affect the working capital of the business at all, whatever","An increase in current assets increases working capital; an increase in current liabilities DECREASES it"],"answer":3,"explanation":"WC = CA - CL: rising CA raises WC, rising CL lowers it - the first rule of the schedule.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA106","number":106,"module":"M3","moduleTitle":"Fund Flow Statement","question":"While preparing the schedule of changes in working capital:","options":[{"key":"A","text":"Both increases raise the working capital of the business, whether of current assets or of current liabilities in the period"},{"key":"B","text":"Both increases lower the working capital of the business"},{"key":"C","text":"The current liabilities never affect the working capital of the business at all, whatever"},{"key":"D","text":"An increase in current assets increases working capital; an increase in current liabilities DECREASES it"}],"answer":"D","explanation":"WC = CA - CL: rising CA raises WC, rising CL lowers it - the first rule of the schedule.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"While preparing the schedule of changes in working capital:","options":["Both increase it","Both decrease it","Current liabilities never affect it","An increase in current assets increases working capital; an increase in current liabilities DECREASES it"],"answer":3,"explanation":"WC = CA - CL: rising CA raises WC, rising CL lowers it - the first rule of the schedule.","revision":"original","contentSignature":"ad25c6da5f20fa839c05dc0f589f447f819c2448b6e0ec48890d54d7c45ccada"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA106","optionFormat":"letter"},"contentSignature":"d8e6355e29f6159a515d3ad3a9a88bf9607d81cae302c48535c98aa3fd03b42a","kind":"pyq"},{"id":"deep-management-MA107","sourceNumber":107,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Provision for taxation and proposed dividend, in fund flow analysis, are usually treated as:","options":["Current liabilities in the schedule of changes in working capital prepared for the year","Ignored altogether in the fund flow analysis, as mere book entries","NON-CURRENT items - tax PAID and dividend PAID are shown as APPLICATIONS of funds","Sources of the funds of the business, shown on the sources side of the statement"],"answer":2,"explanation":"Under the preferred treatment they are kept out of the current schedule; additions are adjusted in FFO and payments shown as applications.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA107","number":107,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Provision for taxation and proposed dividend, in fund flow analysis, are usually treated as:","options":[{"key":"A","text":"Current liabilities in the schedule of changes in working capital prepared for the year"},{"key":"B","text":"Ignored altogether in the fund flow analysis, as mere book entries"},{"key":"C","text":"NON-CURRENT items - tax PAID and dividend PAID are shown as APPLICATIONS of funds"},{"key":"D","text":"Sources of the funds of the business, shown on the sources side of the statement"}],"answer":"C","explanation":"Under the preferred treatment they are kept out of the current schedule; additions are adjusted in FFO and payments shown as applications.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Provision for taxation and proposed dividend, in fund flow analysis, are usually treated as:","options":["Current liabilities in the schedule","Ignore them","NON-CURRENT items - tax PAID and dividend PAID are shown as APPLICATIONS of funds","Sources"],"answer":2,"explanation":"Under the preferred treatment they are kept out of the current schedule; additions are adjusted in FFO and payments shown as applications.","revision":"original","contentSignature":"dd3a6a752f1268621c34928a7e7f58bc4dd04182909a3300240cf9e64eaa6f48"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA107","optionFormat":"letter"},"contentSignature":"6d60c5d0e61c141401f62b7de0dd33f556f08a4efcd6707e350c0ad1561ff5e7","kind":"mcq"},{"id":"deep-management-MA108","sourceNumber":108,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"A fund flow statement is:","options":["An audited statement, certified by the statutory auditor of the company every year without fail","NOT mandatory - a supplementary analytical statement (the Companies Act requires the CASH flow statement instead)","A legal requirement under the Companies Act, 2013, for every company registered under that Act","A part of the balance sheet of the company, presented along with it every year to the Registrar"],"answer":1,"explanation":"Only cash flow statements (AS-3) are prescribed; the fund flow statement is an internal/voluntary analysis.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA108","number":108,"module":"M3","moduleTitle":"Fund Flow Statement","question":"A fund flow statement is:","options":[{"key":"A","text":"An audited statement, certified by the statutory auditor of the company every year without fail"},{"key":"B","text":"NOT mandatory - a supplementary analytical statement (the Companies Act requires the CASH flow statement instead)"},{"key":"C","text":"A legal requirement under the Companies Act, 2013, for every company registered under that Act"},{"key":"D","text":"A part of the balance sheet of the company, presented along with it every year to the Registrar"}],"answer":"B","explanation":"Only cash flow statements (AS-3) are prescribed; the fund flow statement is an internal/voluntary analysis.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A fund flow statement is:","options":["An audited statement","NOT mandatory - a supplementary analytical statement (the Companies Act requires the CASH flow statement instead)","A legal requirement under the Companies Act","Part of the balance sheet"],"answer":1,"explanation":"Only cash flow statements (AS-3) are prescribed; the fund flow statement is an internal/voluntary analysis.","revision":"original","contentSignature":"db21d8dcd3ca2f43811e297fc64362a27939586b2dc44f30e233e3c0b41c32fe"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA108","optionFormat":"letter"},"contentSignature":"44195f61f4d011a0de206dcc68ef8d9033917c88017314c7ce738c4a48296ee3","kind":"mcq"},{"id":"deep-management-MA109","sourceNumber":109,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"The net result of a fund flow statement (sources vs applications) equals:","options":["The increase or decrease in WORKING CAPITAL shown by the schedule of changes","The net profit of the year, as shown in the statement of profit and loss","The reserves of the company, as shown in the balance sheet","The cash balance of the business, as shown in the balance sheet"],"answer":0,"explanation":"Sources minus applications must reconcile with the net working-capital change from the schedule - the statement is self-balancing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA109","number":109,"module":"M3","moduleTitle":"Fund Flow Statement","question":"The net result of a fund flow statement (sources vs applications) equals:","options":[{"key":"A","text":"The increase or decrease in WORKING CAPITAL shown by the schedule of changes"},{"key":"B","text":"The net profit of the year, as shown in the statement of profit and loss"},{"key":"C","text":"The reserves of the company, as shown in the balance sheet"},{"key":"D","text":"The cash balance of the business, as shown in the balance sheet"}],"answer":"A","explanation":"Sources minus applications must reconcile with the net working-capital change from the schedule - the statement is self-balancing.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The net result of a fund flow statement (sources vs applications) equals:","options":["The increase or decrease in WORKING CAPITAL shown by the schedule of changes","Net profit","Reserves","Cash balance"],"answer":0,"explanation":"Sources minus applications must reconcile with the net working-capital change from the schedule - the statement is self-balancing.","revision":"original","contentSignature":"c0fc13e6f86cf995b2bfc6dc25a4287dd6fbe4617519b2efb2548be76f632054"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA109","optionFormat":"letter"},"contentSignature":"3c2c82882211e40487a50348eb4f952c544cd3d97c9730de0e4b542c20a5a48d","kind":"mcq"},{"id":"deep-management-MA110","sourceNumber":110,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Provision for depreciation on machinery increases during the year by Rs.50,000 while machinery is sold with accumulated depreciation Rs.20,000. Depreciation charged for the year is:","options":["Rs.50,000","Rs.70,000","Rs.30,000","Rs.20,000"],"answer":1,"explanation":"Closing provision = opening + charge for year - provision on asset sold: charge = 50,000 (net rise) + 20,000 (removed) = Rs.70,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA110","number":110,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Provision for depreciation on machinery increases during the year by Rs.50,000 while machinery is sold with accumulated depreciation Rs.20,000. Depreciation charged for the year is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.70,000"},{"key":"C","text":"Rs.30,000"},{"key":"D","text":"Rs.20,000"}],"answer":"B","explanation":"Closing provision = opening + charge for year - provision on asset sold: charge = 50,000 (net rise) + 20,000 (removed) = Rs.70,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA110","optionFormat":"letter"},"contentSignature":"f9452c51ad3c29d5ae764c9776890bae0591e5b5c384fa437e67bcb52f9f2002","kind":"mcq"},{"id":"deep-management-MA111","sourceNumber":111,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Dividend RECEIVED on investments is:","options":["A non-operating income SUBTRACTED from FFO (it is shown, if significant, separately as inflow or netted)","An application of the funds of the business","Added to the profit in the FFO computation, as an operating income of the year of receipt","A part of the operating income of the business and so it is included in the funds from operations of the year"],"answer":0,"explanation":"Investment income is non-operating for a non-investment business and is excluded from FFO.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA111","number":111,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Dividend RECEIVED on investments is:","options":[{"key":"A","text":"A non-operating income SUBTRACTED from FFO (it is shown, if significant, separately as inflow or netted)"},{"key":"B","text":"An application of the funds of the business"},{"key":"C","text":"Added to the profit in the FFO computation, as an operating income of the year of receipt"},{"key":"D","text":"A part of the operating income of the business and so it is included in the funds from operations of the year"}],"answer":"A","explanation":"Investment income is non-operating for a non-investment business and is excluded from FFO.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Dividend RECEIVED on investments is:","options":["A non-operating income SUBTRACTED from FFO (it is shown, if significant, separately as inflow or netted)","Always an application","Added to FFO","Part of operations"],"answer":0,"explanation":"Investment income is non-operating for a non-investment business and is excluded from FFO.","revision":"original","contentSignature":"2f469065a9f2363cd5bbb8d4d359834532a85e27bb4764e7fb7fbf592ed5895d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA111","optionFormat":"letter"},"contentSignature":"b119d2364d664d4609609b6e702a21072c020b8af6ddd464f834c576a9189efc","kind":"mcq"},{"id":"deep-management-MA112","sourceNumber":112,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Fund flow statement is also known as the statement of:","options":["SOURCES AND APPLICATIONS OF FUNDS / statement of changes in financial position","The retained earnings of the company, year after year, as the other name","The cash receipts and payments of the business, during the year, as the other name","The profit appropriation of the company, during the year, as the other name"],"answer":0,"explanation":"Its classic title is \"Statement of Sources and Application of Funds\" or \"Statement of Changes in Financial Position (working capital basis)\".","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA112","number":112,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Fund flow statement is also known as the statement of:","options":[{"key":"A","text":"SOURCES AND APPLICATIONS OF FUNDS / statement of changes in financial position"},{"key":"B","text":"The retained earnings of the company, year after year, as the other name"},{"key":"C","text":"The cash receipts and payments of the business, during the year, as the other name"},{"key":"D","text":"The profit appropriation of the company, during the year, as the other name"}],"answer":"A","explanation":"Its classic title is \"Statement of Sources and Application of Funds\" or \"Statement of Changes in Financial Position (working capital basis)\".","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Fund flow statement is also known as the statement of:","options":["SOURCES AND APPLICATIONS OF FUNDS / statement of changes in financial position","Retained earnings","Cash receipts and payments","Profit appropriation"],"answer":0,"explanation":"Its classic title is \"Statement of Sources and Application of Funds\" or \"Statement of Changes in Financial Position (working capital basis)\".","revision":"original","contentSignature":"0cf4f0e2c28a6dbc2047c89a5579c27272b6cac9bb7b15d538f47b634438de50"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA112","optionFormat":"letter"},"contentSignature":"eb6b6a0578c581e556e2a9d916ed9d9fbbef03738a033fe97aa46b71b86ce5e0","kind":"mcq"},{"id":"deep-management-MA113","sourceNumber":113,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Transfer to GENERAL RESERVE out of profits is:","options":["Ignored altogether in the fund flow analysis, as a mere book entry of the year","An application of the funds of the business, shown on the uses side of the statement","A source of the funds of the business, shown on the sources side of the statement","ADDED BACK to current-year profit in the FFO computation (an appropriation, not a fund use)"],"answer":3,"explanation":"Transfers to reserves merely move profit within equity; no working capital leaves the business.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA113","number":113,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Transfer to GENERAL RESERVE out of profits is:","options":[{"key":"A","text":"Ignored altogether in the fund flow analysis, as a mere book entry of the year"},{"key":"B","text":"An application of the funds of the business, shown on the uses side of the statement"},{"key":"C","text":"A source of the funds of the business, shown on the sources side of the statement"},{"key":"D","text":"ADDED BACK to current-year profit in the FFO computation (an appropriation, not a fund use)"}],"answer":"D","explanation":"Transfers to reserves merely move profit within equity; no working capital leaves the business.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Transfer to GENERAL RESERVE out of profits is:","options":["Ignored","An application of funds","A source of funds","ADDED BACK to current-year profit in the FFO computation (an appropriation, not a fund use)"],"answer":3,"explanation":"Transfers to reserves merely move profit within equity; no working capital leaves the business.","revision":"original","contentSignature":"a1a784e34e8018c118f77a892040e630fecfdd755d81520771292cba621317b0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA113","optionFormat":"letter"},"contentSignature":"1ded23cc7a85cac53db5fb387c37e690184004e77b89471b4fd6fa3137b95b2a","kind":"mcq"},{"id":"deep-management-MA114","sourceNumber":114,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Issue of BONUS shares is:","options":["A NON-FUND transaction - a capitalisation of reserves with no working-capital effect","A source of the funds of the business, shown on the sources side of the statement","An application of the funds of the business, shown on the uses side of the statement","A cash inflow of the business, shown in the schedule of the changes"],"answer":0,"explanation":"Bonus issue converts reserves into share capital; no fund flow arises.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA114","number":114,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Issue of BONUS shares is:","options":[{"key":"A","text":"A NON-FUND transaction - a capitalisation of reserves with no working-capital effect"},{"key":"B","text":"A source of the funds of the business, shown on the sources side of the statement"},{"key":"C","text":"An application of the funds of the business, shown on the uses side of the statement"},{"key":"D","text":"A cash inflow of the business, shown in the schedule of the changes"}],"answer":"A","explanation":"Bonus issue converts reserves into share capital; no fund flow arises.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Issue of BONUS shares is:","options":["A NON-FUND transaction - a capitalisation of reserves with no working-capital effect","A source of funds","An application of funds","A cash inflow"],"answer":0,"explanation":"Bonus issue converts reserves into share capital; no fund flow arises.","revision":"original","contentSignature":"b0b373a7e5e9786796b1a9f8359435128520ea763ba3bb977d608ab5b2db755c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA114","optionFormat":"letter"},"contentSignature":"e8bbb86ec99dc97826f9e3c3966e12a6924156d5903603dabf71d36c72ecc2b3","kind":"mcq"},{"id":"deep-management-MA115","sourceNumber":115,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"Purchase of machinery by ISSUE OF EQUITY SHARES is:","options":["A source of the funds of the business, since the shares are issued","An application of the funds of the business, since the machinery is bought","A NON-FUND transaction (both items non-current) - disclosed, if at all, separately","A fund inflow of the business, since the machinery comes in"],"answer":2,"explanation":"No working capital moves; it is excluded from the fund flow statement.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA115","number":115,"module":"M3","moduleTitle":"Fund Flow Statement","question":"Purchase of machinery by ISSUE OF EQUITY SHARES is:","options":[{"key":"A","text":"A source of the funds of the business, since the shares are issued"},{"key":"B","text":"An application of the funds of the business, since the machinery is bought"},{"key":"C","text":"A NON-FUND transaction (both items non-current) - disclosed, if at all, separately"},{"key":"D","text":"A fund inflow of the business, since the machinery comes in"}],"answer":"C","explanation":"No working capital moves; it is excluded from the fund flow statement.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Purchase of machinery by ISSUE OF EQUITY SHARES is:","options":["A source","An application","A NON-FUND transaction (both items non-current) - disclosed, if at all, separately","A fund inflow"],"answer":2,"explanation":"No working capital moves; it is excluded from the fund flow statement.","revision":"original","contentSignature":"d424112dd056e8dccda6cfad6680b921d7aed7a9cc57a384f69457ad53d8bbd1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA115","optionFormat":"letter"},"contentSignature":"f2ebb7cbeb351410d21057dd9b0c8389310321c08c78a8a1ccdcabd48958d934","kind":"mcq"},{"id":"deep-management-MA116","sourceNumber":116,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M3 · Fund Flow Statement","question":"The excess of applications over sources of funds indicates:","options":["Higher cash always","Higher profit","Increase in working capital","DECREASE in working capital"],"answer":3,"explanation":"When uses exceed sources, working capital falls - and the schedule will show the same net decrease.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA116","number":116,"module":"M3","moduleTitle":"Fund Flow Statement","question":"The excess of applications over sources of funds indicates:","options":[{"key":"A","text":"Higher cash always"},{"key":"B","text":"Higher profit"},{"key":"C","text":"Increase in working capital"},{"key":"D","text":"DECREASE in working capital"}],"answer":"D","explanation":"When uses exceed sources, working capital falls - and the schedule will show the same net decrease.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA116","optionFormat":"letter"},"contentSignature":"953dff42db3bc7160aeeec53521eea927b013624251c0e3025d3076232d9b565","kind":"mcq"},{"id":"deep-management-MA117","sourceNumber":117,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"A CASH FLOW statement (AS-3) classifies cash flows into:","options":["The fixed and the variable flows of the cash of the business","OPERATING, INVESTING and FINANCING activities","The capital and the revenue flows of the cash of the business","The sources and the applications of the funds of the business"],"answer":1,"explanation":"AS-3 mandates the three-way classification so users can see cash generated by operations, invested in assets, and raised/repaid through financing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA117","number":117,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"A CASH FLOW statement (AS-3) classifies cash flows into:","options":[{"key":"A","text":"The fixed and the variable flows of the cash of the business"},{"key":"B","text":"OPERATING, INVESTING and FINANCING activities"},{"key":"C","text":"The capital and the revenue flows of the cash of the business"},{"key":"D","text":"The sources and the applications of the funds of the business"}],"answer":"B","explanation":"AS-3 mandates the three-way classification so users can see cash generated by operations, invested in assets, and raised/repaid through financing.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A CASH FLOW statement (AS-3) classifies cash flows into:","options":["Fixed and variable","OPERATING, INVESTING and FINANCING activities","Capital and revenue","Sources and applications"],"answer":1,"explanation":"AS-3 mandates the three-way classification so users can see cash generated by operations, invested in assets, and raised/repaid through financing.","revision":"original","contentSignature":"343803d0862848ffc289900f9047d7895486b3bcc2b85ef5279a88cc1cadfe6b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA117","optionFormat":"letter"},"contentSignature":"b45bb9b00701daba8a3bd32ab8fea5f78cd1726e6aabf08ac65494d7933d57ff","kind":"mcq"},{"id":"deep-management-MA118","sourceNumber":118,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The \"cash and cash equivalents\" of AS-3 include:","options":["The debtors of the business, as the most liquid of its assets","The long-term investments of the business, as the safest of its assets","CASH IN HAND and demand deposits + SHORT-TERM highly liquid investments (maturity up to 3 months) readily convertible into known amounts of cash with insignificant risk of value change","ALL the bank balances of the business including the fixed deposits for five years, the entire debtors of the business as the most liquid of its assets, and the long-term investments of the business as the safest of its assets - every one of these being a cash equivalent under AS-3"],"answer":2,"explanation":"Cash equivalents are short-term (<=3 months from acquisition), highly liquid investments like T-bills and money-market instruments; bank overdrafts repayable on demand are treated as part of cash management.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA118","number":118,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The \"cash and cash equivalents\" of AS-3 include:","options":[{"key":"A","text":"The debtors of the business, as the most liquid of its assets"},{"key":"B","text":"The long-term investments of the business, as the safest of its assets"},{"key":"C","text":"CASH IN HAND and demand deposits + SHORT-TERM highly liquid investments (maturity up to 3 months) readily convertible into known amounts of cash with insignificant risk of value change"},{"key":"D","text":"ALL the bank balances of the business including the fixed deposits for five years, the entire debtors of the business as the most liquid of its assets, and the long-term investments of the business as the safest of its assets - every one of these being a cash equivalent under AS-3"}],"answer":"C","explanation":"Cash equivalents are short-term (<=3 months from acquisition), highly liquid investments like T-bills and money-market instruments; bank overdrafts repayable on demand are treated as part of cash management.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The \"cash and cash equivalents\" of AS-3 include:","options":["Debtors","Long-term investments","CASH IN HAND and demand deposits + SHORT-TERM highly liquid investments (maturity up to 3 months) readily convertible into known amounts of cash with insignificant risk of value change","All bank balances including fixed deposits for 5 years"],"answer":2,"explanation":"Cash equivalents are short-term (<=3 months from acquisition), highly liquid investments like T-bills and money-market instruments; bank overdrafts repayable on demand are treated as part of cash management.","revision":"original","contentSignature":"e10604ca7f805995bdff505d88a9e9da06c421e951a227c4d3d337c42bf73331"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA118","optionFormat":"letter"},"contentSignature":"ad7c61171b5725b429aece02149e0cef3d7a57452ede79dd26b3fbe57402a71c","kind":"mcq"},{"id":"deep-management-MA119","sourceNumber":119,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Which is an OPERATING activity?","options":["The purchase of the machinery for the factory of the business, for cash, during the year under review","The purchase of the investments by the business, for cash, during the year under review","PAYMENT for the purchase of a machine, the purchase of the investments, the repayment of a bank loan, the proceeds from the issue of shares and debentures, and the payment of dividends - every one of these being an operating activity of the business under AS-3","Cash receipts from sale of goods and rendering of services; payments to suppliers and employees; income tax paid (unless specifically identified with investing/financing)"],"answer":3,"explanation":"Operating activities are the principal revenue-producing activities of the enterprise.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA119","number":119,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Which is an OPERATING activity?","options":[{"key":"A","text":"The purchase of the machinery for the factory of the business, for cash, during the year under review"},{"key":"B","text":"The purchase of the investments by the business, for cash, during the year under review"},{"key":"C","text":"PAYMENT for the purchase of a machine, the purchase of the investments, the repayment of a bank loan, the proceeds from the issue of shares and debentures, and the payment of dividends - every one of these being an operating activity of the business under AS-3"},{"key":"D","text":"Cash receipts from sale of goods and rendering of services; payments to suppliers and employees; income tax paid (unless specifically identified with investing/financing)"}],"answer":"D","explanation":"Operating activities are the principal revenue-producing activities of the enterprise.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is an OPERATING activity?","options":["Purchase of machinery","Purchase of investments","Issue of shares","Cash receipts from sale of goods and rendering of services; payments to suppliers and employees; income tax paid (unless specifically identified with investing/financing)"],"answer":3,"explanation":"Operating activities are the principal revenue-producing activities of the enterprise.","revision":"original","contentSignature":"c61c43a0b6b5c99562e3246f1110b2b453c869f04a182750dd724042aed3925f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA119","optionFormat":"letter"},"contentSignature":"573e071a085ec4720d7bb60935bc9a1187643761f038db5f24b1857bcf61a878","kind":"mcq"},{"id":"deep-management-MA120","sourceNumber":120,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Which of the following is NOT an operating activity?","options":["PAYMENT FOR PURCHASE OF A MACHINE (an INVESTING activity)","The payment of the rent of the premises of the business, for the year","The payment of the wages of the workers of the business, for the year","The cash received from the customers of the business, during the year"],"answer":0,"explanation":"Acquisition of fixed assets is an investing activity; the recall question hinges exactly on this classification.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA120","number":120,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Which of the following is NOT an operating activity?","options":[{"key":"A","text":"PAYMENT FOR PURCHASE OF A MACHINE (an INVESTING activity)"},{"key":"B","text":"The payment of the rent of the premises of the business, for the year"},{"key":"C","text":"The payment of the wages of the workers of the business, for the year"},{"key":"D","text":"The cash received from the customers of the business, during the year"}],"answer":"A","explanation":"Acquisition of fixed assets is an investing activity; the recall question hinges exactly on this classification.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is NOT an operating activity?","options":["PAYMENT FOR PURCHASE OF A MACHINE (an INVESTING activity)","Payment of rent","Payment of wages","Cash received from customers"],"answer":0,"explanation":"Acquisition of fixed assets is an investing activity; the recall question hinges exactly on this classification.","revision":"original","contentSignature":"b1ba5bf0004f4a9b8d05bc56bee84d2226026d2ff1bcefb8a0d3c8e2736dc2d6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA120","optionFormat":"letter"},"contentSignature":"fdb4fe6a7a67d9907e87f4e2a7fd225512f64c6eb25dbc9513700ad0092985c9","kind":"mcq"},{"id":"deep-management-MA121","sourceNumber":121,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"INCOME TAX paid is generally classified under:","options":["Excluded from the statement altogether, since the tax is not a business flow","The financing activities of the business, since the tax is a cost of the capital","The investing activities of the business, since the tax is a cost of the assets","OPERATING activities - unless specifically identifiable with investing or financing activities"],"answer":3,"explanation":"AS-3 defaults tax cash flows to operating; only taxes specifically attributable to investing/financing transactions follow those heads.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA121","number":121,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"INCOME TAX paid is generally classified under:","options":[{"key":"A","text":"Excluded from the statement altogether, since the tax is not a business flow"},{"key":"B","text":"The financing activities of the business, since the tax is a cost of the capital"},{"key":"C","text":"The investing activities of the business, since the tax is a cost of the assets"},{"key":"D","text":"OPERATING activities - unless specifically identifiable with investing or financing activities"}],"answer":"D","explanation":"AS-3 defaults tax cash flows to operating; only taxes specifically attributable to investing/financing transactions follow those heads.","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"INCOME TAX paid is generally classified under:","options":["Excluded from the statement","Financing activities","Investing activities","OPERATING activities - unless specifically identifiable with investing or financing activities"],"answer":3,"explanation":"AS-3 defaults tax cash flows to operating; only taxes specifically attributable to investing/financing transactions follow those heads.","revision":"original","contentSignature":"b7d8d218466d259ebca1118cb4b58805308475bb75b23d03b8867c50639537d3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA121","optionFormat":"letter"},"contentSignature":"119532349d6d38264b6ca17d6733d3b6be21af63d95b710f9bdf4d64e155a1d1","kind":"mcq"},{"id":"deep-management-MA122","sourceNumber":122,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Proceeds from the SALE OF A PATENT are classified as:","options":["Operating activity","Financing activity","INVESTING activity","Cash equivalent"],"answer":2,"explanation":"Disposal of intangible/fixed assets generates investing inflows.","source":"PYQ: SSC CGL AAO, 2017 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA122","number":122,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Proceeds from the SALE OF A PATENT are classified as:","options":[{"key":"A","text":"Operating activity"},{"key":"B","text":"Financing activity"},{"key":"C","text":"INVESTING activity"},{"key":"D","text":"Cash equivalent"}],"answer":"C","explanation":"Disposal of intangible/fixed assets generates investing inflows.","source":"PYQ: SSC CGL AAO, 2017","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA122","optionFormat":"letter"},"contentSignature":"7930f40490e7c37517ff6f02fe61ab42c6f070d23f410e8febe3101fd4273697","kind":"pyq"},{"id":"deep-management-MA123","sourceNumber":123,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Cash payment for a SELF-CONSTRUCTED property is classified as:","options":["Either operating or financing","Financing activity","INVESTING activity","Operating activity"],"answer":2,"explanation":"Payments to acquire or construct fixed assets are investing outflows.","source":"PYQ: JAIIB AFM, 2023 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA123","number":123,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Cash payment for a SELF-CONSTRUCTED property is classified as:","options":[{"key":"A","text":"Either operating or financing"},{"key":"B","text":"Financing activity"},{"key":"C","text":"INVESTING activity"},{"key":"D","text":"Operating activity"}],"answer":"C","explanation":"Payments to acquire or construct fixed assets are investing outflows.","source":"PYQ: JAIIB AFM, 2023","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA123","optionFormat":"letter"},"contentSignature":"d8f3b671ec06b6a30ed8d35479109e7e9134b87a1e7d24fe4b0d8e25c8cf7859","kind":"pyq"},{"id":"deep-management-MA124","sourceNumber":124,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Which is a FINANCING activity?","options":["The purchase of the stock of the business, for cash or on credit","The payment of the wages of the workers of the business, for the year","PROCEEDS from the sale of the goods of the business, the cash received from the customers, the payments to the suppliers and the employees, and the income tax paid - every one of these being a financing activity of the business under AS-3","Repayment of a bank LOAN (principal), proceeds from issue of shares and debentures, payment of dividends and interest on borrowings (for non-financial enterprises, as per AS-3 options)"],"answer":3,"explanation":"Financing activities change the size and composition of owners capital and borrowings.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA124","number":124,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Which is a FINANCING activity?","options":[{"key":"A","text":"The purchase of the stock of the business, for cash or on credit"},{"key":"B","text":"The payment of the wages of the workers of the business, for the year"},{"key":"C","text":"PROCEEDS from the sale of the goods of the business, the cash received from the customers, the payments to the suppliers and the employees, and the income tax paid - every one of these being a financing activity of the business under AS-3"},{"key":"D","text":"Repayment of a bank LOAN (principal), proceeds from issue of shares and debentures, payment of dividends and interest on borrowings (for non-financial enterprises, as per AS-3 options)"}],"answer":"D","explanation":"Financing activities change the size and composition of owners capital and borrowings.","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is a FINANCING activity?","options":["Purchase of stock","Payment of wages","Sale of goods","Repayment of a bank LOAN (principal), proceeds from issue of shares and debentures, payment of dividends and interest on borrowings (for non-financial enterprises, as per AS-3 options)"],"answer":3,"explanation":"Financing activities change the size and composition of owners capital and borrowings.","revision":"original","contentSignature":"ac9bb276738414b21afcf1402f1753a7895081bfc2fde079a1076dad13a3bdf5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA124","optionFormat":"letter"},"contentSignature":"e389d4cec189fb4ec83c054c81449f71cca8741a8629eed34a34b09ac99ff3b0","kind":"mcq"},{"id":"deep-management-MA125","sourceNumber":125,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"For a NON-FINANCIAL enterprise under AS-3, INTEREST PAID is shown as:","options":["FINANCING activity","Excluded","Operating","Investing"],"answer":0,"explanation":"AS-3 allows interest paid as financing for non-financial enterprises; interest and dividends RECEIVED are investing; dividend PAID is financing. (For financial enterprises, interest paid and received are operating.)","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA125","number":125,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"For a NON-FINANCIAL enterprise under AS-3, INTEREST PAID is shown as:","options":[{"key":"A","text":"FINANCING activity"},{"key":"B","text":"Excluded"},{"key":"C","text":"Operating"},{"key":"D","text":"Investing"}],"answer":"A","explanation":"AS-3 allows interest paid as financing for non-financial enterprises; interest and dividends RECEIVED are investing; dividend PAID is financing. (For financial enterprises, interest paid and received are operating.)","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA125","optionFormat":"letter"},"contentSignature":"1f4f26b58c8db21aca91bc2fbc651ecfdb6cee7fbcaca28243276bdb6d21bdbc","kind":"mcq"},{"id":"deep-management-MA126","sourceNumber":126,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"DIVIDEND PAID by a company is classified as:","options":["An operating activity of the business, since the dividend is an appropriation","FINANCING activity (it is a cost of obtaining financial resources)","An investing activity of the business, since the dividend relates to the shares","Not a cash flow at all, since the dividend is a mere appropriation of profit"],"answer":1,"explanation":"Dividend paid is a financing outflow; AS-3 requires it to be disclosed separately.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA126","number":126,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"DIVIDEND PAID by a company is classified as:","options":[{"key":"A","text":"An operating activity of the business, since the dividend is an appropriation"},{"key":"B","text":"FINANCING activity (it is a cost of obtaining financial resources)"},{"key":"C","text":"An investing activity of the business, since the dividend relates to the shares"},{"key":"D","text":"Not a cash flow at all, since the dividend is a mere appropriation of profit"}],"answer":"B","explanation":"Dividend paid is a financing outflow; AS-3 requires it to be disclosed separately.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DIVIDEND PAID by a company is classified as:","options":["Operating activity","FINANCING activity (it is a cost of obtaining financial resources)","Investing activity","Not a cash flow"],"answer":1,"explanation":"Dividend paid is a financing outflow; AS-3 requires it to be disclosed separately.","revision":"original","contentSignature":"7cdc0cbe679339f1d0ea386ae17de84211c3d005939f04e620fa206e132949cc"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA126","optionFormat":"letter"},"contentSignature":"1434ec2018d409ce6064a5f4e0118962ab4305d0973902d11f37f37f47efeb25","kind":"mcq"},{"id":"deep-management-MA127","sourceNumber":127,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"INTEREST and DIVIDENDS RECEIVED (non-financial enterprise) are:","options":["Financing","INVESTING activities","Ignored","Operating"],"answer":1,"explanation":"Returns on investments are investing inflows for non-financial enterprises.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA127","number":127,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"INTEREST and DIVIDENDS RECEIVED (non-financial enterprise) are:","options":[{"key":"A","text":"Financing"},{"key":"B","text":"INVESTING activities"},{"key":"C","text":"Ignored"},{"key":"D","text":"Operating"}],"answer":"B","explanation":"Returns on investments are investing inflows for non-financial enterprises.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA127","optionFormat":"letter"},"contentSignature":"68343405ae931865e4b0ee2b763955479e7c15c56d30aa8152723389ff2a874d","kind":"mcq"},{"id":"deep-management-MA128","sourceNumber":128,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The DIRECT method of reporting operating cash flows shows:","options":["Only the net profit of the year, adjusted for nothing at all, as the single figure shown in it","MAJOR CLASSES of gross cash receipts and gross cash payments (cash from customers, cash paid to suppliers/employees etc.)","The profit adjusted only for the non-cash items","Only the changes in the balance sheet figures between the dates, with no direct listing of the receipts and the payments made"],"answer":1,"explanation":"AS-3 encourages the direct method (gross receipts/payments); the indirect method starts from profit before tax and adjusts.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA128","number":128,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The DIRECT method of reporting operating cash flows shows:","options":[{"key":"A","text":"Only the net profit of the year, adjusted for nothing at all, as the single figure shown in it"},{"key":"B","text":"MAJOR CLASSES of gross cash receipts and gross cash payments (cash from customers, cash paid to suppliers/employees etc.)"},{"key":"C","text":"The profit adjusted only for the non-cash items"},{"key":"D","text":"Only the changes in the balance sheet figures between the dates, with no direct listing of the receipts and the payments made"}],"answer":"B","explanation":"AS-3 encourages the direct method (gross receipts/payments); the indirect method starts from profit before tax and adjusts.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DIRECT method of reporting operating cash flows shows:","options":["Only net profit","MAJOR CLASSES of gross cash receipts and gross cash payments (cash from customers, cash paid to suppliers/employees etc.)","Profit adjusted for non-cash items","Only changes in balance sheet"],"answer":1,"explanation":"AS-3 encourages the direct method (gross receipts/payments); the indirect method starts from profit before tax and adjusts.","revision":"original","contentSignature":"ea1aadb30ee0339aeaa8bb26b17dcd08c36b4d3f7cf8287a477f8ff16d6722cf"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA128","optionFormat":"letter"},"contentSignature":"f7a0e3149866c981bc274863b493a83d1f1f58752bb2b20bf81c69b1a81cf721","kind":"mcq"},{"id":"deep-management-MA129","sourceNumber":129,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The INDIRECT method of computing cash flow from operations starts with:","options":["The cash sales of the year, as the starting figure of the computation","The dividend paid during the year, as the starting figure of the computation","PROFIT BEFORE TAX and extraordinary items - adjusted for non-cash items (depreciation), non-operating items (interest), and changes in working capital","GROSS SALES of the year - adjusted for the cash sales, the credit sales, the returns inward, the trade discount allowed, the bad debts written off and the sales tax collected, every adjustment being made to arrive at the operating cash flow"],"answer":2,"explanation":"Indirect method: PBT + depreciation +/- non-operating items +/- working-capital changes = cash from operations before tax.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA129","number":129,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The INDIRECT method of computing cash flow from operations starts with:","options":[{"key":"A","text":"The cash sales of the year, as the starting figure of the computation"},{"key":"B","text":"The dividend paid during the year, as the starting figure of the computation"},{"key":"C","text":"PROFIT BEFORE TAX and extraordinary items - adjusted for non-cash items (depreciation), non-operating items (interest), and changes in working capital"},{"key":"D","text":"GROSS SALES of the year - adjusted for the cash sales, the credit sales, the returns inward, the trade discount allowed, the bad debts written off and the sales tax collected, every adjustment being made to arrive at the operating cash flow"}],"answer":"C","explanation":"Indirect method: PBT + depreciation +/- non-operating items +/- working-capital changes = cash from operations before tax.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The INDIRECT method of computing cash flow from operations starts with:","options":["Cash sales","Dividend paid","PROFIT BEFORE TAX and extraordinary items - adjusted for non-cash items (depreciation), non-operating items (interest), and changes in working capital","Gross profit"],"answer":2,"explanation":"Indirect method: PBT + depreciation +/- non-operating items +/- working-capital changes = cash from operations before tax.","revision":"original","contentSignature":"c4ff7b4883f6685bbb233eec5633982e64e771a5cab87462514f9fff6bd9c36f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA129","optionFormat":"letter"},"contentSignature":"f02d94b86c65f1af11f8c63b12ab0b32802ee5460098d0aca5db7810009c7869","kind":"mcq"},{"id":"deep-management-MA130","sourceNumber":130,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"While computing operating cash flow (indirect method), an INCREASE in current assets is:","options":["Ignored altogether in the computation, as a mere book figure","SUBTRACTED (an increase in debtors/stock means cash is tied up)","Added to the financing activities of the business, as an inflow","Added to the profit of the year, as an inflow of the cash"],"answer":1,"explanation":"Increase in current assets = outflow; decrease = inflow. For current liabilities it is the reverse.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA130","number":130,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"While computing operating cash flow (indirect method), an INCREASE in current assets is:","options":[{"key":"A","text":"Ignored altogether in the computation, as a mere book figure"},{"key":"B","text":"SUBTRACTED (an increase in debtors/stock means cash is tied up)"},{"key":"C","text":"Added to the financing activities of the business, as an inflow"},{"key":"D","text":"Added to the profit of the year, as an inflow of the cash"}],"answer":"B","explanation":"Increase in current assets = outflow; decrease = inflow. For current liabilities it is the reverse.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"While computing operating cash flow (indirect method), an INCREASE in current assets is:","options":["Ignored","SUBTRACTED (an increase in debtors/stock means cash is tied up)","Added to financing","Added to profit"],"answer":1,"explanation":"Increase in current assets = outflow; decrease = inflow. For current liabilities it is the reverse.","revision":"original","contentSignature":"3351a809e87d72765dae314184b3c3007ececc4b4487662382ac68472c88f702"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA130","optionFormat":"letter"},"contentSignature":"aab3858cf7115302f436547ca7f789430ee03ac8aae55b0f36d325e07421988b","kind":"mcq"},{"id":"deep-management-MA131","sourceNumber":131,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"An INCREASE in current liabilities in the indirect method is:","options":["An investing inflow of the business, shown on the investing side","Ignored altogether in the computation, as a mere book figure","ADDED to profit (higher creditors mean less cash paid out)","Subtracted from the profit of the year, as an outflow of the cash"],"answer":2,"explanation":"Increase in current liabilities = cash conserved = added; decrease = subtracted.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA131","number":131,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"An INCREASE in current liabilities in the indirect method is:","options":[{"key":"A","text":"An investing inflow of the business, shown on the investing side"},{"key":"B","text":"Ignored altogether in the computation, as a mere book figure"},{"key":"C","text":"ADDED to profit (higher creditors mean less cash paid out)"},{"key":"D","text":"Subtracted from the profit of the year, as an outflow of the cash"}],"answer":"C","explanation":"Increase in current liabilities = cash conserved = added; decrease = subtracted.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An INCREASE in current liabilities in the indirect method is:","options":["An investing inflow","Ignored","ADDED to profit (higher creditors mean less cash paid out)","Subtracted"],"answer":2,"explanation":"Increase in current liabilities = cash conserved = added; decrease = subtracted.","revision":"original","contentSignature":"0d7b58406437e556647005b1191a8617368687d3b3f056c4a9b3d3ea4deea461"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA131","optionFormat":"letter"},"contentSignature":"2c5db0fa0f238f790ad8f2eb7f0472a96e7ea4d4476d09c1d5e2e63e3c771ab1","kind":"mcq"},{"id":"deep-management-MA132","sourceNumber":132,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Depreciation on machinery is dealt with in the indirect method by:","options":["Subtracting it from the profit of the year, as an expense","ADDING it back to profit (a non-cash expense)","Ignoring it altogether in the computation, as a book entry","Showing it as a financing activity of the business, as an outflow"],"answer":1,"explanation":"Depreciation, amortisation and provisions are non-cash charges added back to profit.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA132","number":132,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Depreciation on machinery is dealt with in the indirect method by:","options":[{"key":"A","text":"Subtracting it from the profit of the year, as an expense"},{"key":"B","text":"ADDING it back to profit (a non-cash expense)"},{"key":"C","text":"Ignoring it altogether in the computation, as a book entry"},{"key":"D","text":"Showing it as a financing activity of the business, as an outflow"}],"answer":"B","explanation":"Depreciation, amortisation and provisions are non-cash charges added back to profit.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation on machinery is dealt with in the indirect method by:","options":["Subtracting it","ADDING it back to profit (a non-cash expense)","Ignoring it","Showing it as financing"],"answer":1,"explanation":"Depreciation, amortisation and provisions are non-cash charges added back to profit.","revision":"original","contentSignature":"6a508f6868d40384b22b575613352754142ead2308043a0b3df59e9a12de56a8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA132","optionFormat":"letter"},"contentSignature":"1254cbc3ee6e0260b8b617076a71e771acf87f65f367aa463b04af319e281f44","kind":"mcq"},{"id":"deep-management-MA133","sourceNumber":133,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The purchase of a MACHINE by issuing DEBENTURES is:","options":["A financing inflow of the business, since the debentures are issued","An operating outflow of the business, since the machine is bought","A NON-CASH transaction - EXCLUDED from the cash flow statement","An investing outflow of the business, since the machine is bought"],"answer":2,"explanation":"Transactions not involving cash or cash equivalents are excluded from the cash flow statement (disclosed elsewhere).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA133","number":133,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The purchase of a MACHINE by issuing DEBENTURES is:","options":[{"key":"A","text":"A financing inflow of the business, since the debentures are issued"},{"key":"B","text":"An operating outflow of the business, since the machine is bought"},{"key":"C","text":"A NON-CASH transaction - EXCLUDED from the cash flow statement"},{"key":"D","text":"An investing outflow of the business, since the machine is bought"}],"answer":"C","explanation":"Transactions not involving cash or cash equivalents are excluded from the cash flow statement (disclosed elsewhere).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The purchase of a MACHINE by issuing DEBENTURES is:","options":["A financing inflow","An operating outflow","A NON-CASH transaction - EXCLUDED from the cash flow statement","An investing outflow"],"answer":2,"explanation":"Transactions not involving cash or cash equivalents are excluded from the cash flow statement (disclosed elsewhere).","revision":"original","contentSignature":"c5092e18c6a7348a0269c72fc60016964579f630733e684fa5cf032ee50bc93a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA133","optionFormat":"letter"},"contentSignature":"e8a0232edc9b73aa01d1b84fe6e93c0be7279089d242ab6c28cb1d66056055e5","kind":"mcq"},{"id":"deep-management-MA134","sourceNumber":134,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"A company reports profit before tax Rs.5,00,000, depreciation Rs.80,000, interest paid Rs.40,000 (financing), increase in debtors Rs.30,000, decrease in creditors Rs.20,000. Cash flow from OPERATIONS (before tax) is:","options":["Rs.6,50,000","Rs.5,30,000","Rs.4,70,000","Rs.5,70,000"],"answer":3,"explanation":"5,00,000 + 80,000 + 40,000 (interest added back, as it is financing) - 30,000 - 20,000 = Rs.5,70,000. Check: 5,00,000 + 1,20,000 = 6,20,000; minus 50,000 = 5,70,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA134","number":134,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"A company reports profit before tax Rs.5,00,000, depreciation Rs.80,000, interest paid Rs.40,000 (financing), increase in debtors Rs.30,000, decrease in creditors Rs.20,000. Cash flow from OPERATIONS (before tax) is:","options":[{"key":"A","text":"Rs.6,50,000"},{"key":"B","text":"Rs.5,30,000"},{"key":"C","text":"Rs.4,70,000"},{"key":"D","text":"Rs.5,70,000"}],"answer":"D","explanation":"5,00,000 + 80,000 + 40,000 (interest added back, as it is financing) - 30,000 - 20,000 = Rs.5,70,000. Check: 5,00,000 + 1,20,000 = 6,20,000; minus 50,000 = 5,70,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA134","optionFormat":"letter"},"contentSignature":"e8f6766a89999b8472ed4640df50d4df77d1511b1af06f49b78e4910f02414e6","kind":"mcq"},{"id":"deep-management-MA135","sourceNumber":135,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"In the above question (tax paid Rs.1,00,000), NET cash from operating activities is:","options":["Rs.4,70,000","Rs.5,30,000","Rs.5,70,000","Rs.6,20,000"],"answer":0,"explanation":"5,70,000 - 1,00,000 = Rs.4,70,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA135","number":135,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"In the above question (tax paid Rs.1,00,000), NET cash from operating activities is:","options":[{"key":"A","text":"Rs.4,70,000"},{"key":"B","text":"Rs.5,30,000"},{"key":"C","text":"Rs.5,70,000"},{"key":"D","text":"Rs.6,20,000"}],"answer":"A","explanation":"5,70,000 - 1,00,000 = Rs.4,70,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA135","optionFormat":"letter"},"contentSignature":"69e9ddeec5c745155dda88dfaf0e14d1362494627583e19ac469c7eebe40908d","kind":"mcq"},{"id":"deep-management-MA136","sourceNumber":136,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Cash flow from INVESTING activities includes:","options":["The payment of the interest on the loans of the business, year by year, as an investing flow always","PURCHASE and sale of fixed assets, investments, intangibles; interest and dividends received; loans advanced and recovered","The issue of the shares of the company to the public, for cash, as an investing flow always","The payment of the dividend to the shareholders of the company, year by year, as an investing flow"],"answer":1,"explanation":"Investing covers acquisition/disposal of long-term assets and non-cash-equivalent investments.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA136","number":136,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Cash flow from INVESTING activities includes:","options":[{"key":"A","text":"The payment of the interest on the loans of the business, year by year, as an investing flow always"},{"key":"B","text":"PURCHASE and sale of fixed assets, investments, intangibles; interest and dividends received; loans advanced and recovered"},{"key":"C","text":"The issue of the shares of the company to the public, for cash, as an investing flow always"},{"key":"D","text":"The payment of the dividend to the shareholders of the company, year by year, as an investing flow"}],"answer":"B","explanation":"Investing covers acquisition/disposal of long-term assets and non-cash-equivalent investments.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cash flow from INVESTING activities includes:","options":["Payment of interest on loans","PURCHASE and sale of fixed assets, investments, intangibles; interest and dividends received; loans advanced and recovered","Issue of shares","Payment of dividend"],"answer":1,"explanation":"Investing covers acquisition/disposal of long-term assets and non-cash-equivalent investments.","revision":"original","contentSignature":"cb82eae753b3ae4499cc464ef9eb3361882b6a3066df540bfdfe780d5dc4ff7d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA136","optionFormat":"letter"},"contentSignature":"7ceb0fb044578af4d7fbcf88e51cb70899f1241439068ea12cd66dd580eaa5a7","kind":"mcq"},{"id":"deep-management-MA137","sourceNumber":137,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Cash flow from FINANCING activities includes:","options":["The sale of the patents of the business, for cash, during the year, as a financing flow always","PROCEEDS from issue of shares/debentures, long-term borrowings, their repayment, interest and dividends paid","The tax paid by the business during the year, in cash, as a financing flow always","The purchase of the goodwill of another business, for cash, as a financing flow always"],"answer":1,"explanation":"Financing covers raising and servicing of capital - equity and debt.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA137","number":137,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Cash flow from FINANCING activities includes:","options":[{"key":"A","text":"The sale of the patents of the business, for cash, during the year, as a financing flow always"},{"key":"B","text":"PROCEEDS from issue of shares/debentures, long-term borrowings, their repayment, interest and dividends paid"},{"key":"C","text":"The tax paid by the business during the year, in cash, as a financing flow always"},{"key":"D","text":"The purchase of the goodwill of another business, for cash, as a financing flow always"}],"answer":"B","explanation":"Financing covers raising and servicing of capital - equity and debt.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cash flow from FINANCING activities includes:","options":["Sale of patents","PROCEEDS from issue of shares/debentures, long-term borrowings, their repayment, interest and dividends paid","Tax paid","Purchase of goodwill"],"answer":1,"explanation":"Financing covers raising and servicing of capital - equity and debt.","revision":"original","contentSignature":"0a4a92206c0e960ae22aff640401d3ae0f0b1b1f450b2f8222a986d65de6c5b5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA137","optionFormat":"letter"},"contentSignature":"e585433bd9659d5cf3b27a3cb0de73780e87814d772e83aa1a82c4d4125b3993","kind":"mcq"},{"id":"deep-management-MA138","sourceNumber":138,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"AS-3 (Cash Flow Statements) is applicable/mandatory to:","options":["Only the banks of the country, and no other enterprise at all, whatever the size or the listing","Level I enterprises (listed/turnover above Rs.50 crore/borrowings above Rs.10 crore etc.); others are encouraged - companies must give it under the Companies Act via AS rules","Only the enterprises whose turnover is below one crore and whose borrowings are below one lakh - the smallest of the small - while every listed company and every large enterprise is wholly exempt from AS-3, whatever its size, its listing or its borrowings","Only the government companies of the country, and no other enterprise at all, whatever the size"],"answer":1,"explanation":"AS-3 is mandatory for Level-I enterprises; for companies, the cash flow statement is part of financial statements where AS-3 applies.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA138","number":138,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"AS-3 (Cash Flow Statements) is applicable/mandatory to:","options":[{"key":"A","text":"Only the banks of the country, and no other enterprise at all, whatever the size or the listing"},{"key":"B","text":"Level I enterprises (listed/turnover above Rs.50 crore/borrowings above Rs.10 crore etc.); others are encouraged - companies must give it under the Companies Act via AS rules"},{"key":"C","text":"Only the enterprises whose turnover is below one crore and whose borrowings are below one lakh - the smallest of the small - while every listed company and every large enterprise is wholly exempt from AS-3, whatever its size, its listing or its borrowings"},{"key":"D","text":"Only the government companies of the country, and no other enterprise at all, whatever the size"}],"answer":"B","explanation":"AS-3 is mandatory for Level-I enterprises; for companies, the cash flow statement is part of financial statements where AS-3 applies.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"AS-3 (Cash Flow Statements) is applicable/mandatory to:","options":["Only banks","Level I enterprises (listed/turnover above Rs.50 crore/borrowings above Rs.10 crore etc.); others are encouraged - companies must give it under the Companies Act via AS rules","All enterprises without exception","Only government companies"],"answer":1,"explanation":"AS-3 is mandatory for Level-I enterprises; for companies, the cash flow statement is part of financial statements where AS-3 applies.","revision":"original","contentSignature":"66df3731a5dc3b96edf0c9bd891c29c6c606d98d92471f881b411ee8d166e112"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA138","optionFormat":"letter"},"contentSignature":"ca08f2b6e9e2834a1ebd180985bba649a02ef8508f892ad087ea7bcd394ca183","kind":"mcq"},{"id":"deep-management-MA139","sourceNumber":139,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"A BANK (financial enterprise) reports interest received and paid under:","options":["Investing","Cash equivalents","Financing","OPERATING activities"],"answer":3,"explanation":"For financial enterprises, interest and dividends relating to their main business are operating cash flows.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA139","number":139,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"A BANK (financial enterprise) reports interest received and paid under:","options":[{"key":"A","text":"Investing"},{"key":"B","text":"Cash equivalents"},{"key":"C","text":"Financing"},{"key":"D","text":"OPERATING activities"}],"answer":"D","explanation":"For financial enterprises, interest and dividends relating to their main business are operating cash flows.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA139","optionFormat":"letter"},"contentSignature":"1f38e7915d477fc8adcde2366fd8908d60f8a82fa1cb008ac7192853d55e2de2","kind":"mcq"},{"id":"deep-management-MA140","sourceNumber":140,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The net increase in cash and cash equivalents shown by the cash flow statement equals:","options":["The funds from the operations of the business, computed in the usual way","The difference between the OPENING and CLOSING balances of cash and cash equivalents","The change in the working capital of the business between the two dates","The net profit of the business for the year, after all adjustments"],"answer":1,"explanation":"The three activity totals net to the movement in cash and equivalents, reconciling with the balance-sheet figures.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA140","number":140,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The net increase in cash and cash equivalents shown by the cash flow statement equals:","options":[{"key":"A","text":"The funds from the operations of the business, computed in the usual way"},{"key":"B","text":"The difference between the OPENING and CLOSING balances of cash and cash equivalents"},{"key":"C","text":"The change in the working capital of the business between the two dates"},{"key":"D","text":"The net profit of the business for the year, after all adjustments"}],"answer":"B","explanation":"The three activity totals net to the movement in cash and equivalents, reconciling with the balance-sheet figures.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The net increase in cash and cash equivalents shown by the cash flow statement equals:","options":["Funds from operations","The difference between the OPENING and CLOSING balances of cash and cash equivalents","Change in working capital","Net profit"],"answer":1,"explanation":"The three activity totals net to the movement in cash and equivalents, reconciling with the balance-sheet figures.","revision":"original","contentSignature":"5619cc3111389b186918c9f665c6cc6a7b6f94b53f3eaa7b3b5f8ab960a7d769"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA140","optionFormat":"letter"},"contentSignature":"5eed85e69a48a68779d55f981c07f52c158d6fba2939a23aec19e5ed3868cdfd","kind":"mcq"},{"id":"deep-management-MA141","sourceNumber":141,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Foreign currency cash flows are recorded at:","options":["The forward exchange rate fixed under the contract, even where the actual conversion takes place at a different spot rate on the date of the flow","The exchange rate on the DATE of the cash flow (or an average approximating it); unrealised exchange differences are NOT cash flows","The closing rate of the exchange always, whatever the date of the cash flow itself may be in the year","The historical rate of the exchange, at the date of the original transaction of the business itself always"],"answer":1,"explanation":"AS-3/AS-11: use transaction-date rates; unrealised gains/losses from retranslation are not cash flows.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA141","number":141,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Foreign currency cash flows are recorded at:","options":[{"key":"A","text":"The forward exchange rate fixed under the contract, even where the actual conversion takes place at a different spot rate on the date of the flow"},{"key":"B","text":"The exchange rate on the DATE of the cash flow (or an average approximating it); unrealised exchange differences are NOT cash flows"},{"key":"C","text":"The closing rate of the exchange always, whatever the date of the cash flow itself may be in the year"},{"key":"D","text":"The historical rate of the exchange, at the date of the original transaction of the business itself always"}],"answer":"B","explanation":"AS-3/AS-11: use transaction-date rates; unrealised gains/losses from retranslation are not cash flows.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Foreign currency cash flows are recorded at:","options":["Forward rate","The exchange rate on the DATE of the cash flow (or an average approximating it); unrealised exchange differences are NOT cash flows","Closing rate always","Historical rate"],"answer":1,"explanation":"AS-3/AS-11: use transaction-date rates; unrealised gains/losses from retranslation are not cash flows.","revision":"original","contentSignature":"2bd0eee7c223c3984859d347ba8e51a4c4eb05ef443b9a7bebcd54f3ee01f8f1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA141","optionFormat":"letter"},"contentSignature":"e42ef3419c5e278dcff4c09599b71115f2b5ba5f2ff1c807aeee08b75c6344f8","kind":"mcq"},{"id":"deep-management-MA142","sourceNumber":142,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Cash flows from FUTURES, forwards, options and swaps are generally classified as:","options":["OPERATING, unless they hedge identifiable investing or financing positions (then they follow the hedged item)","Investing always, whatever the position hedged by the contract of the business itself","Excluded from the statement altogether, as a derivative flow of the business itself","Financing always, whatever the position hedged by the contract of the business itself"],"answer":0,"explanation":"Hedging instrument cash flows are classified the same way as the cash flows of the position being hedged.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA142","number":142,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Cash flows from FUTURES, forwards, options and swaps are generally classified as:","options":[{"key":"A","text":"OPERATING, unless they hedge identifiable investing or financing positions (then they follow the hedged item)"},{"key":"B","text":"Investing always, whatever the position hedged by the contract of the business itself"},{"key":"C","text":"Excluded from the statement altogether, as a derivative flow of the business itself"},{"key":"D","text":"Financing always, whatever the position hedged by the contract of the business itself"}],"answer":"A","explanation":"Hedging instrument cash flows are classified the same way as the cash flows of the position being hedged.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cash flows from FUTURES, forwards, options and swaps are generally classified as:","options":["OPERATING, unless they hedge identifiable investing or financing positions (then they follow the hedged item)","Investing always","Excluded","Financing"],"answer":0,"explanation":"Hedging instrument cash flows are classified the same way as the cash flows of the position being hedged.","revision":"original","contentSignature":"f1bf76f9087aedaf558a24440cb33016519d03273d1364b37cff5ebfef8a0449"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA142","optionFormat":"letter"},"contentSignature":"53d762e5cc63288dd127ca48754fdfdc0466244ebf012e2880d50d282c888897","kind":"mcq"},{"id":"deep-management-MA143","sourceNumber":143,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Which of the following is a non-cash INVESTING AND FINANCING transaction excluded from the cash flow statement?","options":["The interest paid on the borrowings of the business, during the year","The sale of the machinery of the business, for cash, during the year","Conversion of DEBENTURES into EQUITY SHARES","The dividend received on the investments of the business, during the year"],"answer":2,"explanation":"Conversion of debt into equity moves no cash; such significant non-cash transactions are disclosed outside the statement.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA143","number":143,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Which of the following is a non-cash INVESTING AND FINANCING transaction excluded from the cash flow statement?","options":[{"key":"A","text":"The interest paid on the borrowings of the business, during the year"},{"key":"B","text":"The sale of the machinery of the business, for cash, during the year"},{"key":"C","text":"Conversion of DEBENTURES into EQUITY SHARES"},{"key":"D","text":"The dividend received on the investments of the business, during the year"}],"answer":"C","explanation":"Conversion of debt into equity moves no cash; such significant non-cash transactions are disclosed outside the statement.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is a non-cash INVESTING AND FINANCING transaction excluded from the cash flow statement?","options":["Interest paid","Sale of machinery for cash","Conversion of DEBENTURES into EQUITY SHARES","Dividend received"],"answer":2,"explanation":"Conversion of debt into equity moves no cash; such significant non-cash transactions are disclosed outside the statement.","revision":"original","contentSignature":"3ee24c05b15a92ddf7a4cd9096212004d24308d740d268e1b15a6dbe6836fa35"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA143","optionFormat":"letter"},"contentSignature":"ee65fc3869057fe2a5dcab19905a42c561310b175211d7427c6d17444f962f16","kind":"mcq"},{"id":"deep-management-MA144","sourceNumber":144,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"An OVERDRAFT repayable on demand, forming an integral part of cash management, is:","options":["INCLUDED as a component of cash and cash equivalents (negative component)","An investing item of the business, shown on the investing side","Ignored altogether in the statement, as a mere book figure","A financing inflow of the business, shown on the financing side"],"answer":0,"explanation":"Bank overdrafts of this type reduce cash equivalents rather than appearing as financing flows.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA144","number":144,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"An OVERDRAFT repayable on demand, forming an integral part of cash management, is:","options":[{"key":"A","text":"INCLUDED as a component of cash and cash equivalents (negative component)"},{"key":"B","text":"An investing item of the business, shown on the investing side"},{"key":"C","text":"Ignored altogether in the statement, as a mere book figure"},{"key":"D","text":"A financing inflow of the business, shown on the financing side"}],"answer":"A","explanation":"Bank overdrafts of this type reduce cash equivalents rather than appearing as financing flows.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An OVERDRAFT repayable on demand, forming an integral part of cash management, is:","options":["INCLUDED as a component of cash and cash equivalents (negative component)","An investing item","Ignored","A financing inflow"],"answer":0,"explanation":"Bank overdrafts of this type reduce cash equivalents rather than appearing as financing flows.","revision":"original","contentSignature":"30ac2f22db755ae348b8aed0a8840280e4116d9ab8e527dbfb88b398696a93e3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA144","optionFormat":"letter"},"contentSignature":"25c2902b51e3ff167e275e8c7ce1023d9f782d733175c2dd3edadb77d1225015","kind":"mcq"},{"id":"deep-management-MA145","sourceNumber":145,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"The primary DIFFERENCE between a fund flow statement and a cash flow statement is:","options":["FUND flow explains changes in WORKING CAPITAL; CASH flow explains changes in CASH AND CASH EQUIVALENTS only","No difference at all - the two statements are the same in every respect whatever","The cash flow statement is optional, while the fund flow statement is mandatory for all","The fund flow statement is audited, while the cash flow statement is never audited"],"answer":0,"explanation":"Cash flow is narrower (cash basis, three activities) and is the statutorily prescribed one; fund flow works on the working-capital concept.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA145","number":145,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"The primary DIFFERENCE between a fund flow statement and a cash flow statement is:","options":[{"key":"A","text":"FUND flow explains changes in WORKING CAPITAL; CASH flow explains changes in CASH AND CASH EQUIVALENTS only"},{"key":"B","text":"No difference at all - the two statements are the same in every respect whatever"},{"key":"C","text":"The cash flow statement is optional, while the fund flow statement is mandatory for all"},{"key":"D","text":"The fund flow statement is audited, while the cash flow statement is never audited"}],"answer":"A","explanation":"Cash flow is narrower (cash basis, three activities) and is the statutorily prescribed one; fund flow works on the working-capital concept.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The primary DIFFERENCE between a fund flow statement and a cash flow statement is:","options":["FUND flow explains changes in WORKING CAPITAL; CASH flow explains changes in CASH AND CASH EQUIVALENTS only","No difference","Cash flow is optional","Fund flow is audited"],"answer":0,"explanation":"Cash flow is narrower (cash basis, three activities) and is the statutorily prescribed one; fund flow works on the working-capital concept.","revision":"original","contentSignature":"87632802ebf04c0dd70fcfca2d22274e15a0fd79e36c80f248809a130adcfdb1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA145","optionFormat":"letter"},"contentSignature":"4aec762d0aabcb5387aa0012a722d10ab9e8aab95c606456d0e0196a4a90f1b6","kind":"mcq"},{"id":"deep-management-MA146","sourceNumber":146,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"While preparing a cash flow statement, an increase in the provision for doubtful debts (treated as a non-cash appropriation) is:","options":["Subtracted from the profit in the operating activities, as an expense","A financing item of the business, shown on the financing side","Added back to profit in operating activities","An investing item of the business, shown on the investing side"],"answer":2,"explanation":"Being a non-cash charge, the increase is added back (under the alternative treatment it may be deducted from debtors as a current-liability-style adjustment).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA146","number":146,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"While preparing a cash flow statement, an increase in the provision for doubtful debts (treated as a non-cash appropriation) is:","options":[{"key":"A","text":"Subtracted from the profit in the operating activities, as an expense"},{"key":"B","text":"A financing item of the business, shown on the financing side"},{"key":"C","text":"Added back to profit in operating activities"},{"key":"D","text":"An investing item of the business, shown on the investing side"}],"answer":"C","explanation":"Being a non-cash charge, the increase is added back (under the alternative treatment it may be deducted from debtors as a current-liability-style adjustment).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"While preparing a cash flow statement, an increase in the provision for doubtful debts (treated as a non-cash appropriation) is:","options":["Subtracted from profit","A financing item","Added back to profit in operating activities","An investing item"],"answer":2,"explanation":"Being a non-cash charge, the increase is added back (under the alternative treatment it may be deducted from debtors as a current-liability-style adjustment).","revision":"original","contentSignature":"1a4996c9765c028ce584145976bc0f07f926c07f14b064c895625f4020fb8577"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA146","optionFormat":"letter"},"contentSignature":"bb407020fe324ccdc54eb514a1d9961f5136533be77cb5e955e64d94ed06d786","kind":"mcq"},{"id":"deep-management-MA147","sourceNumber":147,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M4 · Cash Flow Statement (AS-3)","question":"Cash GENERATED from operations is best described as:","options":["The net profit shown in the profit and loss statement of the year, with no adjustment for the non-cash items or the working capital changes","The sales of the year less the purchases of the year","Operating profit BEFORE working-capital changes, adjusted for the working-capital changes - i.e. cash actually produced by operations","The EBITDA of the year only, before any working-capital adjustment at all is made in the year itself"],"answer":2,"explanation":"It is the intermediate figure in the indirect method after adjusting profit for non-cash/non-operating items and working-capital movements, before deducting tax.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA147","number":147,"module":"M4","moduleTitle":"Cash Flow Statement (AS-3)","question":"Cash GENERATED from operations is best described as:","options":[{"key":"A","text":"The net profit shown in the profit and loss statement of the year, with no adjustment for the non-cash items or the working capital changes"},{"key":"B","text":"The sales of the year less the purchases of the year"},{"key":"C","text":"Operating profit BEFORE working-capital changes, adjusted for the working-capital changes - i.e. cash actually produced by operations"},{"key":"D","text":"The EBITDA of the year only, before any working-capital adjustment at all is made in the year itself"}],"answer":"C","explanation":"It is the intermediate figure in the indirect method after adjusting profit for non-cash/non-operating items and working-capital movements, before deducting tax.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cash GENERATED from operations is best described as:","options":["Net profit","Sales minus purchases","Operating profit BEFORE working-capital changes, adjusted for the working-capital changes - i.e. cash actually produced by operations","EBITDA only"],"answer":2,"explanation":"It is the intermediate figure in the indirect method after adjusting profit for non-cash/non-operating items and working-capital movements, before deducting tax.","revision":"original","contentSignature":"2487dd296a17e642b8a4188af14403d7491549cb7ea5b472837791fbf4ee68b4"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA147","optionFormat":"letter"},"contentSignature":"faf0d6b9778b07b263a101f9c23310afd71b29b3d8f80307cd386311ae3c67e6","kind":"mcq"},{"id":"deep-management-MA148","sourceNumber":148,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Capital budgeting is the process of:","options":["Evaluating and selecting LONG-TERM INVESTMENT proposals whose returns flow over several years","The preparation of the annual budgets of the business, year after year, as a routine","The valuation of the goodwill of the business, from time to time, as required","The estimation of the daily cash requirements of the business, day after day"],"answer":0,"explanation":"Capital budgeting commits funds to long-lived assets; decisions are hard to reverse and shape the firm future.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA148","number":148,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Capital budgeting is the process of:","options":[{"key":"A","text":"Evaluating and selecting LONG-TERM INVESTMENT proposals whose returns flow over several years"},{"key":"B","text":"The preparation of the annual budgets of the business, year after year, as a routine"},{"key":"C","text":"The valuation of the goodwill of the business, from time to time, as required"},{"key":"D","text":"The estimation of the daily cash requirements of the business, day after day"}],"answer":"A","explanation":"Capital budgeting commits funds to long-lived assets; decisions are hard to reverse and shape the firm future.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital budgeting is the process of:","options":["Evaluating and selecting LONG-TERM INVESTMENT proposals whose returns flow over several years","Preparing annual budgets","Valuing goodwill","Estimating daily cash"],"answer":0,"explanation":"Capital budgeting commits funds to long-lived assets; decisions are hard to reverse and shape the firm future.","revision":"original","contentSignature":"39164d3f0a1fa4968f56dec3fa9873bbd2cc3f238f67dac5a2c2f3cf102b85e5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA148","optionFormat":"letter"},"contentSignature":"1f1f2e606a0bb8cf553c8831691e67cacc52cd9956d0a8ed682ce906a9d3ef78","kind":"mcq"},{"id":"deep-management-MA149","sourceNumber":149,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Capital budgeting decisions are important because they involve:","options":["Only the revenue expenses of the year, which are small and recurring in nature","The daily operations of the business, which are routine and repetitive in nature","LARGE, LONG-TERM, largely IRREVERSIBLE commitments that determine profitability and risk for years","Only the small sums of money, which are easily reversible at the will of the management"],"answer":2,"explanation":"Size, longevity, irreversibility, risk and their effect on profitability make these the most critical financial decisions.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA149","number":149,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Capital budgeting decisions are important because they involve:","options":[{"key":"A","text":"Only the revenue expenses of the year, which are small and recurring in nature"},{"key":"B","text":"The daily operations of the business, which are routine and repetitive in nature"},{"key":"C","text":"LARGE, LONG-TERM, largely IRREVERSIBLE commitments that determine profitability and risk for years"},{"key":"D","text":"Only the small sums of money, which are easily reversible at the will of the management"}],"answer":"C","explanation":"Size, longevity, irreversibility, risk and their effect on profitability make these the most critical financial decisions.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital budgeting decisions are important because they involve:","options":["Only revenue expenses","Daily operations","LARGE, LONG-TERM, largely IRREVERSIBLE commitments that determine profitability and risk for years","Small sums"],"answer":2,"explanation":"Size, longevity, irreversibility, risk and their effect on profitability make these the most critical financial decisions.","revision":"original","contentSignature":"1e1168f7b6de2e5344c24f5cc55cb4fcb38632e8471bb832b48d4faa4f4011e0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA149","optionFormat":"letter"},"contentSignature":"a3008cd92004ad4ca579c70a81b05a5ca52ba485e0f53af1b2d1c74e8b0c5c0b","kind":"mcq"},{"id":"deep-management-MA150","sourceNumber":150,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Which of the following is a NON-DISCOUNTING (traditional) technique of capital budgeting?","options":["The IRR of the project, as the traditional measure","PAYBACK PERIOD and Accounting (Average) Rate of Return","The NPV of the project, as the traditional measure","The profitability index of the project, as the traditional measure"],"answer":1,"explanation":"Payback and ARR ignore the time value of money; NPV, IRR and PI are discounted-cash-flow techniques.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA150","number":150,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Which of the following is a NON-DISCOUNTING (traditional) technique of capital budgeting?","options":[{"key":"A","text":"The IRR of the project, as the traditional measure"},{"key":"B","text":"PAYBACK PERIOD and Accounting (Average) Rate of Return"},{"key":"C","text":"The NPV of the project, as the traditional measure"},{"key":"D","text":"The profitability index of the project, as the traditional measure"}],"answer":"B","explanation":"Payback and ARR ignore the time value of money; NPV, IRR and PI are discounted-cash-flow techniques.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following is a NON-DISCOUNTING (traditional) technique of capital budgeting?","options":["IRR","PAYBACK PERIOD and Accounting (Average) Rate of Return","NPV","Profitability index"],"answer":1,"explanation":"Payback and ARR ignore the time value of money; NPV, IRR and PI are discounted-cash-flow techniques.","revision":"original","contentSignature":"f03431b0340f062313a3a177bd415591047077809047f4ed0c3f28042efbc877"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA150","optionFormat":"letter"},"contentSignature":"1a6ff9e7b188a6f5f5d8d263fcb5945f3f804b2eb784989a36e6397b7430054f","kind":"mcq"},{"id":"deep-management-MA151","sourceNumber":151,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The PAYBACK PERIOD is:","options":["The life of the asset in years, as estimated by the management","The depreciation period of the asset, as fixed by the statute","The tenure of the loan taken for the asset, as fixed by the lender","The TIME REQUIRED TO RECOVER the initial cash outlay from the annual cash inflows"],"answer":3,"explanation":"Payback = initial investment / annual cash inflow (for even inflows); shorter is better.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA151","number":151,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The PAYBACK PERIOD is:","options":[{"key":"A","text":"The life of the asset in years, as estimated by the management"},{"key":"B","text":"The depreciation period of the asset, as fixed by the statute"},{"key":"C","text":"The tenure of the loan taken for the asset, as fixed by the lender"},{"key":"D","text":"The TIME REQUIRED TO RECOVER the initial cash outlay from the annual cash inflows"}],"answer":"D","explanation":"Payback = initial investment / annual cash inflow (for even inflows); shorter is better.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PAYBACK PERIOD is:","options":["The life of the asset","The depreciation period","The loan tenure","The TIME REQUIRED TO RECOVER the initial cash outlay from the annual cash inflows"],"answer":3,"explanation":"Payback = initial investment / annual cash inflow (for even inflows); shorter is better.","revision":"original","contentSignature":"9bcc93b7030b8ac57f08de8f6254273210e2b01ac0c9bcf7c649e79edd1046f1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA151","optionFormat":"letter"},"contentSignature":"533fec70b119b573562496de323374d8f1c494115803792501e8706dfd2a42be","kind":"mcq"},{"id":"deep-management-MA152","sourceNumber":152,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"A machine costs Rs.5,00,000 and generates even annual cash inflows of Rs.1,00,000. Its payback period is:","options":["4 years","6 years","10 years","5 years"],"answer":3,"explanation":"5,00,000 / 1,00,000 = 5 years.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA152","number":152,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"A machine costs Rs.5,00,000 and generates even annual cash inflows of Rs.1,00,000. Its payback period is:","options":[{"key":"A","text":"4 years"},{"key":"B","text":"6 years"},{"key":"C","text":"10 years"},{"key":"D","text":"5 years"}],"answer":"D","explanation":"5,00,000 / 1,00,000 = 5 years.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA152","optionFormat":"letter"},"contentSignature":"26f6101551f7a683e69c1e7369b6d2a82b6882be4ffc2b8323cfde2b637ad13b","kind":"mcq"},{"id":"deep-management-MA153","sourceNumber":153,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"For UNEVEN cash inflows, the payback period is found by:","options":["Using the IRR of the project, with the usual tables of the present value","CUMULATING the annual inflows until they equal the outlay (interpolation for the part-year)","Dividing the cost of the project by the average inflow of the years of its life","Using the ARR of the project, with the usual formula of the average profit"],"answer":1,"explanation":"Cumulative inflows: payback = completed years + (unrecovered amount / inflow of the next year).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA153","number":153,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"For UNEVEN cash inflows, the payback period is found by:","options":[{"key":"A","text":"Using the IRR of the project, with the usual tables of the present value"},{"key":"B","text":"CUMULATING the annual inflows until they equal the outlay (interpolation for the part-year)"},{"key":"C","text":"Dividing the cost of the project by the average inflow of the years of its life"},{"key":"D","text":"Using the ARR of the project, with the usual formula of the average profit"}],"answer":"B","explanation":"Cumulative inflows: payback = completed years + (unrecovered amount / inflow of the next year).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"For UNEVEN cash inflows, the payback period is found by:","options":["Using IRR","CUMULATING the annual inflows until they equal the outlay (interpolation for the part-year)","Dividing cost by average inflow","Using ARR"],"answer":1,"explanation":"Cumulative inflows: payback = completed years + (unrecovered amount / inflow of the next year).","revision":"original","contentSignature":"a8502ca2136dd40ca9aa04ebfca61916e59ce7d11d44dcfd1b89ce7bb6244401"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA153","optionFormat":"letter"},"contentSignature":"dbd8fa954a85688239742f5c722061b99eca25c8c8601efb246ccba9a254592d","kind":"mcq"},{"id":"deep-management-MA154","sourceNumber":154,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"A project costs Rs.2,00,000 with inflows: Y1 Rs.80,000, Y2 Rs.60,000, Y3 Rs.50,000, Y4 Rs.40,000. Payback period is:","options":["2.9 years","4 years","3 years","3.25 years"],"answer":3,"explanation":"Cumulative: 80,000 (Y1), 1,40,000 (Y2), 1,90,000 (Y3). Unrecovered after Y3 = 10,000; Y4 inflow 40,000, so 10,000/40,000 = 0.25. Payback = 3.25 years.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA154","number":154,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"A project costs Rs.2,00,000 with inflows: Y1 Rs.80,000, Y2 Rs.60,000, Y3 Rs.50,000, Y4 Rs.40,000. Payback period is:","options":[{"key":"A","text":"2.9 years"},{"key":"B","text":"4 years"},{"key":"C","text":"3 years"},{"key":"D","text":"3.25 years"}],"answer":"D","explanation":"Cumulative: 80,000 (Y1), 1,40,000 (Y2), 1,90,000 (Y3). Unrecovered after Y3 = 10,000; Y4 inflow 40,000, so 10,000/40,000 = 0.25. Payback = 3.25 years.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA154","optionFormat":"letter"},"contentSignature":"e45f6c467b52a51a5ee277b2d78ee7c6c06f11907f4849d2f03c4f74fc76660b","kind":"mcq"},{"id":"deep-management-MA155","sourceNumber":155,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The MAIN merit of the payback method is:","options":["It maximises the wealth of the shareholders by choosing the most profitable project out of all the proposals every time","It considers the time value of the money, in every computation of the payback","It considers the total profitability of the project, over its whole life of years","Its SIMPLICITY and its stress on LIQUIDITY/early recovery - suited to risky, fast-obsolescing investments"],"answer":3,"explanation":"Payback is easy to compute and favours quick-recovery projects; that is why overleveraged or risk-averse firms use it.","source":"PYQ: UGC NET Commerce, 2020-Oct-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA155","number":155,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The MAIN merit of the payback method is:","options":[{"key":"A","text":"It maximises the wealth of the shareholders by choosing the most profitable project out of all the proposals every time"},{"key":"B","text":"It considers the time value of the money, in every computation of the payback"},{"key":"C","text":"It considers the total profitability of the project, over its whole life of years"},{"key":"D","text":"Its SIMPLICITY and its stress on LIQUIDITY/early recovery - suited to risky, fast-obsolescing investments"}],"answer":"D","explanation":"Payback is easy to compute and favours quick-recovery projects; that is why overleveraged or risk-averse firms use it.","source":"PYQ: UGC NET Commerce, 2020-Oct-M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MAIN merit of the payback method is:","options":["It maximises wealth","It considers time value","It considers total profitability","Its SIMPLICITY and its stress on LIQUIDITY/early recovery - suited to risky, fast-obsolescing investments"],"answer":3,"explanation":"Payback is easy to compute and favours quick-recovery projects; that is why overleveraged or risk-averse firms use it.","revision":"original","contentSignature":"1064235251f2823c709a6c4bad021398ed7d1bc395a202f51175b20895a2865e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA155","optionFormat":"letter"},"contentSignature":"d75f1755d9b12074b92bc2a2cb211e0482a76a67ce74192a5461f60f3bfe72fa","kind":"pyq"},{"id":"deep-management-MA156","sourceNumber":156,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The DEMERITS of the payback method include:","options":["It uses the discounted flows of the project, in every computation of the period","It requires a cut-off rate of return, fixed by the management of the company","It IGNORES the time value of money AND cash flows AFTER the payback period (total profitability)","It is too complex for the ordinary manager to apply in the practice of the business"],"answer":2,"explanation":"Payback ignores both discounting and post-payback returns - a project with high later inflows may be wrongly rejected.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA156","number":156,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The DEMERITS of the payback method include:","options":[{"key":"A","text":"It uses the discounted flows of the project, in every computation of the period"},{"key":"B","text":"It requires a cut-off rate of return, fixed by the management of the company"},{"key":"C","text":"It IGNORES the time value of money AND cash flows AFTER the payback period (total profitability)"},{"key":"D","text":"It is too complex for the ordinary manager to apply in the practice of the business"}],"answer":"C","explanation":"Payback ignores both discounting and post-payback returns - a project with high later inflows may be wrongly rejected.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DEMERITS of the payback method include:","options":["It uses discounted flows","It requires a cut-off rate","It IGNORES the time value of money AND cash flows AFTER the payback period (total profitability)","It is too complex"],"answer":2,"explanation":"Payback ignores both discounting and post-payback returns - a project with high later inflows may be wrongly rejected.","revision":"original","contentSignature":"5e5b8c8daf3a2a49d996f031fcd4c13d72b13583c7f6e0e96b93d5b3a06f89b3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA156","optionFormat":"letter"},"contentSignature":"036397f04ccaedc05073c5f2b32f1fce2a4c6eab3e1966dc8537b3a455ff9627","kind":"mcq"},{"id":"deep-management-MA157","sourceNumber":157,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"POST-PAYBACK profitability is:","options":["The total investment made in the project, at the start","The profit/cash inflows earned AFTER the initial investment has been recovered","The profit earned within the payback period itself, and nothing beyond it at all","The scrap value of the asset, at the end of its life"],"answer":1,"explanation":"Post-payback profitability = total inflows - initial outlay (the surplus earned beyond recovery).","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA157","number":157,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"POST-PAYBACK profitability is:","options":[{"key":"A","text":"The total investment made in the project, at the start"},{"key":"B","text":"The profit/cash inflows earned AFTER the initial investment has been recovered"},{"key":"C","text":"The profit earned within the payback period itself, and nothing beyond it at all"},{"key":"D","text":"The scrap value of the asset, at the end of its life"}],"answer":"B","explanation":"Post-payback profitability = total inflows - initial outlay (the surplus earned beyond recovery).","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"POST-PAYBACK profitability is:","options":["Total investment","The profit/cash inflows earned AFTER the initial investment has been recovered","Profit during payback","Scrap value"],"answer":1,"explanation":"Post-payback profitability = total inflows - initial outlay (the surplus earned beyond recovery).","revision":"original","contentSignature":"5136fde91e74813c848f5cf1bd211abaf24c9eddd37584933ed6991e0abeb0f5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA157","optionFormat":"letter"},"contentSignature":"c1bfdfb17a9e7d8d53b2b7277e9ab0ee1f43c445cf715be4d5b1815edb714c7c","kind":"mcq"},{"id":"deep-management-MA158","sourceNumber":158,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The DISCOUNTED payback period improves on simple payback by:","options":["Ignoring the scrap value of the asset, at the end of its life","Using the book profit of the project, instead of the cash flows","Discounting the cash inflows BEFORE computing the recovery period","Ignoring the time value of the money, in every computation"],"answer":2,"explanation":"Discounted payback applies the time value of money to inflows but still ignores flows beyond recovery.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA158","number":158,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The DISCOUNTED payback period improves on simple payback by:","options":[{"key":"A","text":"Ignoring the scrap value of the asset, at the end of its life"},{"key":"B","text":"Using the book profit of the project, instead of the cash flows"},{"key":"C","text":"Discounting the cash inflows BEFORE computing the recovery period"},{"key":"D","text":"Ignoring the time value of the money, in every computation"}],"answer":"C","explanation":"Discounted payback applies the time value of money to inflows but still ignores flows beyond recovery.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DISCOUNTED payback period improves on simple payback by:","options":["Ignoring scrap value","Using book profit","Discounting the cash inflows BEFORE computing the recovery period","Ignoring time value"],"answer":2,"explanation":"Discounted payback applies the time value of money to inflows but still ignores flows beyond recovery.","revision":"original","contentSignature":"addbf98b74b3ff8c0d7acf0882b4f4cf5b907789a0542677924aa196455b96c3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA158","optionFormat":"letter"},"contentSignature":"00f959f3661d41827d628253b1a5630ab7adf4870f7a9856e0d5676a8bc51f9d","kind":"mcq"},{"id":"deep-management-MA159","sourceNumber":159,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The ACCOUNTING (Average) RATE OF RETURN (ARR) is:","options":["The investment of the project divided by the profit of the year, times 100","AVERAGE ANNUAL PROFIT (after depreciation and tax) / AVERAGE (or initial) INVESTMENT x 100","The NPV of the project divided by the investment of the project, times 100","The annual cash inflow divided by the investment of the project, times 100"],"answer":1,"explanation":"ARR is a profit-based, non-discounted measure; projects are accepted if ARR exceeds the target rate.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA159","number":159,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The ACCOUNTING (Average) RATE OF RETURN (ARR) is:","options":[{"key":"A","text":"The investment of the project divided by the profit of the year, times 100"},{"key":"B","text":"AVERAGE ANNUAL PROFIT (after depreciation and tax) / AVERAGE (or initial) INVESTMENT x 100"},{"key":"C","text":"The NPV of the project divided by the investment of the project, times 100"},{"key":"D","text":"The annual cash inflow divided by the investment of the project, times 100"}],"answer":"B","explanation":"ARR is a profit-based, non-discounted measure; projects are accepted if ARR exceeds the target rate.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The ACCOUNTING (Average) RATE OF RETURN (ARR) is:","options":["Investment / Profit","AVERAGE ANNUAL PROFIT (after depreciation and tax) / AVERAGE (or initial) INVESTMENT x 100","NPV / Investment","Annual cash inflow / Investment"],"answer":1,"explanation":"ARR is a profit-based, non-discounted measure; projects are accepted if ARR exceeds the target rate.","revision":"original","contentSignature":"465d99a83a67da564668f9ee7d0df5f5d887722cca611f7cd8c529a3b2d2686d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA159","optionFormat":"letter"},"contentSignature":"26028e856f412069fd4f55dcd4d44d2ea258948bc8b7f038bf356480cc40e9c8","kind":"mcq"},{"id":"deep-management-MA160","sourceNumber":160,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"A project needs an investment of Rs.5,00,000 (no scrap value) and yields average annual accounting profit of Rs.60,000. ARR on AVERAGE investment is:","options":["12%","6%","10%","24%"],"answer":3,"explanation":"Average investment = (5,00,000 + 0)/2 = 2,50,000; ARR = 60,000/2,50,000 = 24% (on initial investment it is 12%).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA160","number":160,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"A project needs an investment of Rs.5,00,000 (no scrap value) and yields average annual accounting profit of Rs.60,000. ARR on AVERAGE investment is:","options":[{"key":"A","text":"12%"},{"key":"B","text":"6%"},{"key":"C","text":"10%"},{"key":"D","text":"24%"}],"answer":"D","explanation":"Average investment = (5,00,000 + 0)/2 = 2,50,000; ARR = 60,000/2,50,000 = 24% (on initial investment it is 12%).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA160","optionFormat":"letter"},"contentSignature":"8bfe91da80586916e957debc1702631148407c2d27387489fd826acfbcfa45e7","kind":"mcq"},{"id":"deep-management-MA161","sourceNumber":161,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"In capital budgeting, the relevant cash flows are:","options":["The gross margins of the project, year by year, before any expense of the business at all","The accounting profits of the project, year by year, as per the books of the business itself","The sales figures of the project, year by year, as per the estimates of the management alone","INCREMENTAL after-tax CASH flows (profit after tax + depreciation), ignoring sunk costs and allocated overheads"],"answer":3,"explanation":"Decisions use incremental cash flows; depreciation is added back (non-cash) though its tax shield matters; sunk costs are irrelevant.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA161","number":161,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"In capital budgeting, the relevant cash flows are:","options":[{"key":"A","text":"The gross margins of the project, year by year, before any expense of the business at all"},{"key":"B","text":"The accounting profits of the project, year by year, as per the books of the business itself"},{"key":"C","text":"The sales figures of the project, year by year, as per the estimates of the management alone"},{"key":"D","text":"INCREMENTAL after-tax CASH flows (profit after tax + depreciation), ignoring sunk costs and allocated overheads"}],"answer":"D","explanation":"Decisions use incremental cash flows; depreciation is added back (non-cash) though its tax shield matters; sunk costs are irrelevant.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In capital budgeting, the relevant cash flows are:","options":["Gross margins","Accounting profits","Sales figures","INCREMENTAL after-tax CASH flows (profit after tax + depreciation), ignoring sunk costs and allocated overheads"],"answer":3,"explanation":"Decisions use incremental cash flows; depreciation is added back (non-cash) though its tax shield matters; sunk costs are irrelevant.","revision":"original","contentSignature":"691991d28c3b8c5a21878d5d1ce47a4767d99c25e54a71dbb916a0bcdd552ba8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA161","optionFormat":"letter"},"contentSignature":"3b9853efb9d8172d47c0010559fd30f0a4ec998ad2d25fec6ea3cfe52b12a9ad","kind":"mcq"},{"id":"deep-management-MA162","sourceNumber":162,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Depreciation enters capital budgeting cash-flow computation because:","options":["It is a cash cost of the year, paid out in money every year by the business itself","It has no bearing on the decision at all, being a fixed charge of the year always","It is a NON-CASH expense that SAVES TAX - cash inflow = PAT + depreciation (or EBIT(1-t) + depreciation)","It increases the cash of the business, being an inflow of the year of its own charge"],"answer":2,"explanation":"Depreciation itself is not a cash flow, but it shields taxable profit; the standard conversion adds it back to PAT.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA162","number":162,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Depreciation enters capital budgeting cash-flow computation because:","options":[{"key":"A","text":"It is a cash cost of the year, paid out in money every year by the business itself"},{"key":"B","text":"It has no bearing on the decision at all, being a fixed charge of the year always"},{"key":"C","text":"It is a NON-CASH expense that SAVES TAX - cash inflow = PAT + depreciation (or EBIT(1-t) + depreciation)"},{"key":"D","text":"It increases the cash of the business, being an inflow of the year of its own charge"}],"answer":"C","explanation":"Depreciation itself is not a cash flow, but it shields taxable profit; the standard conversion adds it back to PAT.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation enters capital budgeting cash-flow computation because:","options":["It is a cash cost","It is irrelevant","It is a NON-CASH expense that SAVES TAX - cash inflow = PAT + depreciation (or EBIT(1-t) + depreciation)","It increases cash"],"answer":2,"explanation":"Depreciation itself is not a cash flow, but it shields taxable profit; the standard conversion adds it back to PAT.","revision":"original","contentSignature":"ef6bbfae4d114fab1d58710d7e73d4f7227a9e85751268b43eb43b5e4568629b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA162","optionFormat":"letter"},"contentSignature":"0798005bbbd9334f98ccee84dcc7b57e1a241e873900b6fe5261275c6327088a","kind":"mcq"},{"id":"deep-management-MA163","sourceNumber":163,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"A SUNK cost in capital budgeting is:","options":["A cost ALREADY INCURRED that cannot be recovered - IRRELEVANT to the accept/reject decision","A working-capital need of the project, recurring every year of its useful life","The salvage value of the asset, at the end of its own useful life","A future cost of the project, yet to be incurred by the business itself"],"answer":0,"explanation":"Only future incremental flows matter; sunk costs (e.g. research already done) do not change with the decision.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA163","number":163,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"A SUNK cost in capital budgeting is:","options":[{"key":"A","text":"A cost ALREADY INCURRED that cannot be recovered - IRRELEVANT to the accept/reject decision"},{"key":"B","text":"A working-capital need of the project, recurring every year of its useful life"},{"key":"C","text":"The salvage value of the asset, at the end of its own useful life"},{"key":"D","text":"A future cost of the project, yet to be incurred by the business itself"}],"answer":"A","explanation":"Only future incremental flows matter; sunk costs (e.g. research already done) do not change with the decision.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A SUNK cost in capital budgeting is:","options":["A cost ALREADY INCURRED that cannot be recovered - IRRELEVANT to the accept/reject decision","A working-capital need","The salvage value","A future cost"],"answer":0,"explanation":"Only future incremental flows matter; sunk costs (e.g. research already done) do not change with the decision.","revision":"original","contentSignature":"03dd04c4de2c81abdc91860a504043545ca7440d557ac890bd8311aea8b46bc6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA163","optionFormat":"letter"},"contentSignature":"75f17d2fd69aa2531bb76b0e108cbd22ca88616a46ccb74e3caf347f2b55ca23","kind":"mcq"},{"id":"deep-management-MA164","sourceNumber":164,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The initial investment in a project includes:","options":["Only the cost of installing the asset","Cost of the asset + installation + working capital margin, net of any sale proceeds of the replaced asset","Only the equity-financed portion of the cost of the asset","Only the purchase price of the asset itself"],"answer":1,"explanation":"The outlay is the full incremental commitment: asset cost, erection/installation, additional working capital, less realisations from the old asset.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA164","number":164,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The initial investment in a project includes:","options":[{"key":"A","text":"Only the cost of installing the asset"},{"key":"B","text":"Cost of the asset + installation + working capital margin, net of any sale proceeds of the replaced asset"},{"key":"C","text":"Only the equity-financed portion of the cost of the asset"},{"key":"D","text":"Only the purchase price of the asset itself"}],"answer":"B","explanation":"The outlay is the full incremental commitment: asset cost, erection/installation, additional working capital, less realisations from the old asset.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The initial investment in a project includes:","options":["Only installation","Cost of the asset + installation + working capital margin, net of any sale proceeds of the replaced asset","Only equity portion","Only the asset price"],"answer":1,"explanation":"The outlay is the full incremental commitment: asset cost, erection/installation, additional working capital, less realisations from the old asset.","revision":"original","contentSignature":"692b4564c30d9de58c7f6c9b6775613bc4088636dbd38bc29de5857d7437fa54"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA164","optionFormat":"letter"},"contentSignature":"2fd5c9cdbc3827b4a751a678767bf43ab23c2a17c5274d7b738e92e29a5e34dc","kind":"mcq"},{"id":"deep-management-MA165","sourceNumber":165,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Terminal cash flows of a project include:","options":["SALVAGE value (net of tax) and RECOVERY of working capital at the end of the project life","The interest paid on the borrowings of the project, at the end of its life","The initial cost of the asset, recovered at the end of the life","The annual depreciation of the asset, at the end of the life of the project"],"answer":0,"explanation":"The final year adds scrap/salvage proceeds and release of working capital to the operating inflow.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA165","number":165,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Terminal cash flows of a project include:","options":[{"key":"A","text":"SALVAGE value (net of tax) and RECOVERY of working capital at the end of the project life"},{"key":"B","text":"The interest paid on the borrowings of the project, at the end of its life"},{"key":"C","text":"The initial cost of the asset, recovered at the end of the life"},{"key":"D","text":"The annual depreciation of the asset, at the end of the life of the project"}],"answer":"A","explanation":"The final year adds scrap/salvage proceeds and release of working capital to the operating inflow.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Terminal cash flows of a project include:","options":["SALVAGE value (net of tax) and RECOVERY of working capital at the end of the project life","Interest","Initial cost","Annual depreciation"],"answer":0,"explanation":"The final year adds scrap/salvage proceeds and release of working capital to the operating inflow.","revision":"original","contentSignature":"6df97a8d6689628f093e9a74c79d2d02039957f7e512bb69a9d209f293e694c2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA165","optionFormat":"letter"},"contentSignature":"74202d16ee39f6460ee3930212c46250110f8acafe28e2477cd763189f780d2a","kind":"mcq"},{"id":"deep-management-MA166","sourceNumber":166,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The accept rule under the payback method is:","options":["Accept the project if its payback equals its ARR","ACCEPT if the payback period is LESS than the maximum acceptable period set by management","Accept every project whatever its payback period","Accept the project if its payback exceeds the life of the asset in the appraisal made by it"],"answer":1,"explanation":"Compare the computed payback with the predetermined cut-off; among mutually exclusive projects, the shortest payback wins.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA166","number":166,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The accept rule under the payback method is:","options":[{"key":"A","text":"Accept the project if its payback equals its ARR"},{"key":"B","text":"ACCEPT if the payback period is LESS than the maximum acceptable period set by management"},{"key":"C","text":"Accept every project whatever its payback period"},{"key":"D","text":"Accept the project if its payback exceeds the life of the asset in the appraisal made by it"}],"answer":"B","explanation":"Compare the computed payback with the predetermined cut-off; among mutually exclusive projects, the shortest payback wins.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The accept rule under the payback method is:","options":["Accept if payback = ARR","ACCEPT if the payback period is LESS than the maximum acceptable period set by management","Accept all","Accept if payback exceeds life"],"answer":1,"explanation":"Compare the computed payback with the predetermined cut-off; among mutually exclusive projects, the shortest payback wins.","revision":"original","contentSignature":"6fa988bf1224c81d854bdacec25cdef55a040a50f95c55c6462a3b6c6e3b4c11"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA166","optionFormat":"letter"},"contentSignature":"026e97b7db0e147ebb847f578641062251bc868882a8f6a89eae48ded4b9f92b","kind":"mcq"},{"id":"deep-management-MA167","sourceNumber":167,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The accept rule under ARR is:","options":["ARR equal to zero","ARR equal to the IRR of the project under evaluation by it","ARR below the cost of capital","ARR ABOVE the minimum/target rate fixed by management"],"answer":3,"explanation":"Projects meeting the target accounting return are accepted; mutually exclusive choices pick the highest ARR.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA167","number":167,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The accept rule under ARR is:","options":[{"key":"A","text":"ARR equal to zero"},{"key":"B","text":"ARR equal to the IRR of the project under evaluation by it"},{"key":"C","text":"ARR below the cost of capital"},{"key":"D","text":"ARR ABOVE the minimum/target rate fixed by management"}],"answer":"D","explanation":"Projects meeting the target accounting return are accepted; mutually exclusive choices pick the highest ARR.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The accept rule under ARR is:","options":["ARR = 0","ARR = IRR","ARR below cost of capital","ARR ABOVE the minimum/target rate fixed by management"],"answer":3,"explanation":"Projects meeting the target accounting return are accepted; mutually exclusive choices pick the highest ARR.","revision":"original","contentSignature":"377c02f718ab12f71d93b22b5dd849a80db5858804c8310f038279132652a92f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA167","optionFormat":"letter"},"contentSignature":"61bc0557f07336d94e1dcd6963dde0536c9810aadf9209bebf7814af34287336","kind":"mcq"},{"id":"deep-management-MA168","sourceNumber":168,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"In MUTUALLY EXCLUSIVE projects, choosing one project:","options":["Doubles the returns expected from the chosen project over the whole of its life","AUTOMATICALLY REJECTS the alternatives (they compete for the same purpose)","Leaves the other alternatives wholly unaffected","Permits the other alternatives to be chosen as well"],"answer":1,"explanation":"Mutually exclusive projects serve the same need; independent projects can all be accepted if they clear the hurdle.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA168","number":168,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"In MUTUALLY EXCLUSIVE projects, choosing one project:","options":[{"key":"A","text":"Doubles the returns expected from the chosen project over the whole of its life"},{"key":"B","text":"AUTOMATICALLY REJECTS the alternatives (they compete for the same purpose)"},{"key":"C","text":"Leaves the other alternatives wholly unaffected"},{"key":"D","text":"Permits the other alternatives to be chosen as well"}],"answer":"B","explanation":"Mutually exclusive projects serve the same need; independent projects can all be accepted if they clear the hurdle.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In MUTUALLY EXCLUSIVE projects, choosing one project:","options":["Doubles returns","AUTOMATICALLY REJECTS the alternatives (they compete for the same purpose)","Has no effect","Allows choosing others too"],"answer":1,"explanation":"Mutually exclusive projects serve the same need; independent projects can all be accepted if they clear the hurdle.","revision":"original","contentSignature":"88e8bf4a1a897717a4c64878fef061e39ffb0e39568bf169bed332efab2e6991"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA168","optionFormat":"letter"},"contentSignature":"cb181a14206c566d10737606270df5bf7362839471e074c48e1b3fbcd4fc3b13","kind":"mcq"},{"id":"deep-management-MA169","sourceNumber":169,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Capital RATIONING exists when:","options":["The payback of every project is short, so that the funds of the firm suffice for all of them at once, whatever the size","The firm has MORE acceptable projects than it can finance with the available capital - projects must be ranked and combined within the budget","The IRR of every project is negative, so that none of them can be taken up at all by the firm ever, whatever","The funds of the firm are unlimited, so that every acceptable project can be taken up at once by it, whatever"],"answer":1,"explanation":"Under capital rationing, select the combination of projects that maximises total NPV within the budget constraint.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA169","number":169,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Capital RATIONING exists when:","options":[{"key":"A","text":"The payback of every project is short, so that the funds of the firm suffice for all of them at once, whatever the size"},{"key":"B","text":"The firm has MORE acceptable projects than it can finance with the available capital - projects must be ranked and combined within the budget"},{"key":"C","text":"The IRR of every project is negative, so that none of them can be taken up at all by the firm ever, whatever"},{"key":"D","text":"The funds of the firm are unlimited, so that every acceptable project can be taken up at once by it, whatever"}],"answer":"B","explanation":"Under capital rationing, select the combination of projects that maximises total NPV within the budget constraint.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Capital RATIONING exists when:","options":["Payback is short","The firm has MORE acceptable projects than it can finance with the available capital - projects must be ranked and combined within the budget","IRR is negative","Funds are unlimited"],"answer":1,"explanation":"Under capital rationing, select the combination of projects that maximises total NPV within the budget constraint.","revision":"original","contentSignature":"7e87fc35cf1fe99a00b333eaa064507fea84fcb42f6f7776337f6c2867265a02"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA169","optionFormat":"letter"},"contentSignature":"fafc0467b44f53a577c7ea07ca91d988b7045c3099f80a5f86c7c54504d94496","kind":"mcq"},{"id":"deep-management-MA170","sourceNumber":170,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Risk analysis in capital budgeting does NOT use:","options":["Sensitivity analysis","Scenario/simulation analysis","CERTAINTY of cash flows assumption","Standard deviation and coefficient of variation"],"answer":2,"explanation":"Risk techniques (sensitivity, SD/CV, risk-adjusted rate, certainty equivalents, decision trees, simulation) exist precisely because flows are uncertain.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA170","number":170,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Risk analysis in capital budgeting does NOT use:","options":[{"key":"A","text":"Sensitivity analysis"},{"key":"B","text":"Scenario/simulation analysis"},{"key":"C","text":"CERTAINTY of cash flows assumption"},{"key":"D","text":"Standard deviation and coefficient of variation"}],"answer":"C","explanation":"Risk techniques (sensitivity, SD/CV, risk-adjusted rate, certainty equivalents, decision trees, simulation) exist precisely because flows are uncertain.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA170","optionFormat":"letter"},"contentSignature":"3f56dcbc86c64e141119bdcc33f08f4f644e5797dca5090b1a56f70e10c924bf","kind":"mcq"},{"id":"deep-management-MA171","sourceNumber":171,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"The RISK-ADJUSTED DISCOUNT RATE approach handles risk by:","options":["Adding a RISK PREMIUM to the risk-free rate for discounting project flows","Ignoring the risk of the project altogether, in the computation","Reducing the cash flows of the project to zero, in the computation","Using the payback of the project, as the only measure of the risk"],"answer":0,"explanation":"Riskier projects are discounted at higher rates; the certainty-equivalent approach instead scales down the flows themselves.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA171","number":171,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"The RISK-ADJUSTED DISCOUNT RATE approach handles risk by:","options":[{"key":"A","text":"Adding a RISK PREMIUM to the risk-free rate for discounting project flows"},{"key":"B","text":"Ignoring the risk of the project altogether, in the computation"},{"key":"C","text":"Reducing the cash flows of the project to zero, in the computation"},{"key":"D","text":"Using the payback of the project, as the only measure of the risk"}],"answer":"A","explanation":"Riskier projects are discounted at higher rates; the certainty-equivalent approach instead scales down the flows themselves.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The RISK-ADJUSTED DISCOUNT RATE approach handles risk by:","options":["Adding a RISK PREMIUM to the risk-free rate for discounting project flows","Ignoring risk","Reducing cash flows to zero","Using the payback"],"answer":0,"explanation":"Riskier projects are discounted at higher rates; the certainty-equivalent approach instead scales down the flows themselves.","revision":"original","contentSignature":"1da73d5aa3e4e09ea589ae24b00127f3a3cf5b939910d3c5d82a50feca72c436"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA171","optionFormat":"letter"},"contentSignature":"1db9d8b7af969eb931ed6c7deacd50f68fa179be40d93255c514052703967baf","kind":"mcq"},{"id":"deep-management-MA172","sourceNumber":172,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M5 · Capital Budgeting I - Payback & ARR","question":"Social and governmental projects are often evaluated using:","options":["COST-BENEFIT ANALYSIS (including social costs and benefits)","The ARR of the project, as the usual measure","The book value of the assets, as the usual measure","The payback of the project only, as the usual measure"],"answer":0,"explanation":"Public investment appraisal uses social cost-benefit analysis; commercial appraisal uses the DCF techniques.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA172","number":172,"module":"M5","moduleTitle":"Capital Budgeting I - Payback & ARR","question":"Social and governmental projects are often evaluated using:","options":[{"key":"A","text":"COST-BENEFIT ANALYSIS (including social costs and benefits)"},{"key":"B","text":"The ARR of the project, as the usual measure"},{"key":"C","text":"The book value of the assets, as the usual measure"},{"key":"D","text":"The payback of the project only, as the usual measure"}],"answer":"A","explanation":"Public investment appraisal uses social cost-benefit analysis; commercial appraisal uses the DCF techniques.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Social and governmental projects are often evaluated using:","options":["COST-BENEFIT ANALYSIS (including social costs and benefits)","ARR","Book value","Payback only"],"answer":0,"explanation":"Public investment appraisal uses social cost-benefit analysis; commercial appraisal uses the DCF techniques.","revision":"original","contentSignature":"fd3f3a771c6569848c78e3aeeb9390d2ed6e00d350781a2a9e6e3adce44db308"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA172","optionFormat":"letter"},"contentSignature":"cdf5030f604c4e22dee28786ddacecb16063ebcf783afe6c90df6049a5e7ea6b","kind":"mcq"},{"id":"deep-management-MA173","sourceNumber":173,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The time value of money means:","options":["Money to be received in future is worth more than money in hand today for the firm","The money loses its value only due to the inflation, and for no other reason","The value of the money never changes at all, whatever the time","A rupee TODAY is worth MORE than a rupee tomorrow because of its earning potential"],"answer":3,"explanation":"Money can earn interest; receiving earlier allows reinvestment. Discounting (present value) and compounding (future value) are opposite processes.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA173","number":173,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The time value of money means:","options":[{"key":"A","text":"Money to be received in future is worth more than money in hand today for the firm"},{"key":"B","text":"The money loses its value only due to the inflation, and for no other reason"},{"key":"C","text":"The value of the money never changes at all, whatever the time"},{"key":"D","text":"A rupee TODAY is worth MORE than a rupee tomorrow because of its earning potential"}],"answer":"D","explanation":"Money can earn interest; receiving earlier allows reinvestment. Discounting (present value) and compounding (future value) are opposite processes.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The time value of money means:","options":["Future money is worth more","Money loses value only due to inflation","Money value never changes","A rupee TODAY is worth MORE than a rupee tomorrow because of its earning potential"],"answer":3,"explanation":"Money can earn interest; receiving earlier allows reinvestment. Discounting (present value) and compounding (future value) are opposite processes.","revision":"original","contentSignature":"4fdab6bf0587482bc414044de77c59c4edafa43c9f0a16fbca64da3c2c1d9383"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA173","optionFormat":"letter"},"contentSignature":"90636b9c7184f9022ed7796070827974187fbde3261d1ad0cd96f044e0b115cb","kind":"mcq"},{"id":"deep-management-MA174","sourceNumber":174,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"DISCOUNTING is the process of finding the ________ of future cash flows; COMPOUNDING finds the ________:","options":["Annuity; perpetuity","PRESENT VALUE; FUTURE VALUE","Future value; present value","IRR; NPV"],"answer":1,"explanation":"Discounting converts future flows to today value at the required rate; compounding carries present sums forward.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA174","number":174,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"DISCOUNTING is the process of finding the ________ of future cash flows; COMPOUNDING finds the ________:","options":[{"key":"A","text":"Annuity; perpetuity"},{"key":"B","text":"PRESENT VALUE; FUTURE VALUE"},{"key":"C","text":"Future value; present value"},{"key":"D","text":"IRR; NPV"}],"answer":"B","explanation":"Discounting converts future flows to today value at the required rate; compounding carries present sums forward.","source":"Recall 2021","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA174","optionFormat":"letter"},"contentSignature":"09933e8aee0bf48099f1c9b8636ffe8f8cea96139a0babd681224f926f871bf1","kind":"mcq"},{"id":"deep-management-MA175","sourceNumber":175,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"An infinite series of EQUAL cash flows occurring at regular intervals is called:","options":["A PERPETUITY","An annuity due","An annuity","Future value"],"answer":0,"explanation":"A perpetuity is an endless level stream (PV = annual amount / rate); an annuity is a level stream for a FIXED number of periods.","source":"PYQ: UGC NET Commerce, 2025- Dec · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA175","number":175,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"An infinite series of EQUAL cash flows occurring at regular intervals is called:","options":[{"key":"A","text":"A PERPETUITY"},{"key":"B","text":"An annuity due"},{"key":"C","text":"An annuity"},{"key":"D","text":"Future value"}],"answer":"A","explanation":"A perpetuity is an endless level stream (PV = annual amount / rate); an annuity is a level stream for a FIXED number of periods.","source":"PYQ: UGC NET Commerce, 2025- Dec","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA175","optionFormat":"letter"},"contentSignature":"f70effa655147fa6e7c31d30f860428eb5be9ce28cb70ee6b53521debfabc41a","kind":"pyq"},{"id":"deep-management-MA176","sourceNumber":176,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The present value of a perpetuity of Rs.10,000 per year at 10% is:","options":["Rs.10,00,000","Rs.1,00,000","Rs.1,10,000","Rs.10,000"],"answer":1,"explanation":"PV of perpetuity = 10,000 / 0.10 = Rs.1,00,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA176","number":176,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The present value of a perpetuity of Rs.10,000 per year at 10% is:","options":[{"key":"A","text":"Rs.10,00,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.1,10,000"},{"key":"D","text":"Rs.10,000"}],"answer":"B","explanation":"PV of perpetuity = 10,000 / 0.10 = Rs.1,00,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA176","optionFormat":"letter"},"contentSignature":"854b3b0577ef6bc90578ce98e17f3965321ea733a0d16658b0ee6a0750199425","kind":"mcq"},{"id":"deep-management-MA177","sourceNumber":177,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"An ANNUITY DUE differs from an ordinary annuity in that payments occur:","options":["Irregularly","At the END of each period","Only once","At the BEGINNING of each period"],"answer":3,"explanation":"Annuity-due payments fall at period starts (like rent/lease in advance), making each payment discount one period less.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA177","number":177,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"An ANNUITY DUE differs from an ordinary annuity in that payments occur:","options":[{"key":"A","text":"Irregularly"},{"key":"B","text":"At the END of each period"},{"key":"C","text":"Only once"},{"key":"D","text":"At the BEGINNING of each period"}],"answer":"D","explanation":"Annuity-due payments fall at period starts (like rent/lease in advance), making each payment discount one period less.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA177","optionFormat":"letter"},"contentSignature":"fd17106e36035c544575014a3379c6a495631464a09a5e9828cba9f0cd9a20b8","kind":"mcq"},{"id":"deep-management-MA178","sourceNumber":178,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"NET PRESENT VALUE (NPV) is:","options":["The PRESENT VALUE of future cash inflows MINUS the present value of cash outflows (initial investment)","The total inflows of the project minus the total outflows, without any discounting at all","The IRR of the project minus the cost of the capital of the firm, as computed","The profit of the year less the tax of the year, computed after charging all expenses of every kind, cash or otherwise"],"answer":0,"explanation":"NPV discounts all flows at the cost of capital; it measures the net addition to wealth in absolute rupees.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA178","number":178,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"NET PRESENT VALUE (NPV) is:","options":[{"key":"A","text":"The PRESENT VALUE of future cash inflows MINUS the present value of cash outflows (initial investment)"},{"key":"B","text":"The total inflows of the project minus the total outflows, without any discounting at all"},{"key":"C","text":"The IRR of the project minus the cost of the capital of the firm, as computed"},{"key":"D","text":"The profit of the year less the tax of the year, computed after charging all expenses of every kind, cash or otherwise"}],"answer":"A","explanation":"NPV discounts all flows at the cost of capital; it measures the net addition to wealth in absolute rupees.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"NET PRESENT VALUE (NPV) is:","options":["The PRESENT VALUE of future cash inflows MINUS the present value of cash outflows (initial investment)","Total inflows - total outflows","IRR - cost of capital","Profit - tax"],"answer":0,"explanation":"NPV discounts all flows at the cost of capital; it measures the net addition to wealth in absolute rupees.","revision":"original","contentSignature":"90dfd4f6b482f31baba4cc461514b4729a02eebb79f28b08928a16fd77eb6681"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA178","optionFormat":"letter"},"contentSignature":"22a67ada4639f6a60ce1fef4f07a66bedc525adfb79a0504b21af5f2963db0f4","kind":"mcq"},{"id":"deep-management-MA179","sourceNumber":179,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The ACCEPT rule under NPV is:","options":["Accept the project if its NPV is negative","Accept every project whatever its NPV","Accept if NPV is POSITIVE (> 0); reject if negative; indifferent at zero","Accept the project only if its NPV is exactly zero at the appraisal stage"],"answer":2,"explanation":"A positive NPV means the project earns more than the required rate and adds to shareholder wealth.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA179","number":179,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The ACCEPT rule under NPV is:","options":[{"key":"A","text":"Accept the project if its NPV is negative"},{"key":"B","text":"Accept every project whatever its NPV"},{"key":"C","text":"Accept if NPV is POSITIVE (> 0); reject if negative; indifferent at zero"},{"key":"D","text":"Accept the project only if its NPV is exactly zero at the appraisal stage"}],"answer":"C","explanation":"A positive NPV means the project earns more than the required rate and adds to shareholder wealth.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The ACCEPT rule under NPV is:","options":["Accept if NPV is negative","Accept all","Accept if NPV is POSITIVE (> 0); reject if negative; indifferent at zero","Accept if NPV is zero"],"answer":2,"explanation":"A positive NPV means the project earns more than the required rate and adds to shareholder wealth.","revision":"original","contentSignature":"34a05bc66d0eee5c50b2470885c70c5f0bdb39293da9ede4ebbc9c2d29577282"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA179","optionFormat":"letter"},"contentSignature":"9d2614ab72e8c296d10d1f6a73845ab0da824f7125190a42017a7955dcaa28e8","kind":"mcq"},{"id":"deep-management-MA180","sourceNumber":180,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"If the NPV of a project is ZERO, it means:","options":["The IRR of the project works out to zero","The project earns EXACTLY the required rate of return (the discount rate) - it recovers the investment plus the required return","The project runs at a loss throughout its life","The project yields no cash inflows at all"],"answer":1,"explanation":"Zero NPV = inflows discounted at the required rate exactly cover the outlay; the firm is indifferent.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA180","number":180,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"If the NPV of a project is ZERO, it means:","options":[{"key":"A","text":"The IRR of the project works out to zero"},{"key":"B","text":"The project earns EXACTLY the required rate of return (the discount rate) - it recovers the investment plus the required return"},{"key":"C","text":"The project runs at a loss throughout its life"},{"key":"D","text":"The project yields no cash inflows at all"}],"answer":"B","explanation":"Zero NPV = inflows discounted at the required rate exactly cover the outlay; the firm is indifferent.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the NPV of a project is ZERO, it means:","options":["IRR is zero","The project earns EXACTLY the required rate of return (the discount rate) - it recovers the investment plus the required return","The project makes a loss","No cash inflows"],"answer":1,"explanation":"Zero NPV = inflows discounted at the required rate exactly cover the outlay; the firm is indifferent.","revision":"original","contentSignature":"9f47c284700fc9846a5fa0fc664c9097f0de0aa3c77c926da2591f40a1a10fa7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA180","optionFormat":"letter"},"contentSignature":"76755ae21447493a0b58d23b74fd42c137f75e72ba986e2069b19ef3914a33c7","kind":"mcq"},{"id":"deep-management-MA181","sourceNumber":181,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The INTERNAL RATE OF RETURN (IRR) is the discount rate at which:","options":["The ARR of the project equals the cost of the capital, at that rate","NPV EQUALS ZERO (PV of inflows = PV of outflows)","The payback of the project is the shortest possible, at that rate","The NPV of the project is the maximum possible, at that rate"],"answer":1,"explanation":"IRR is the break-even discount rate; it is found by trial and error/interpolation between two rates with opposite-sign NPVs.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA181","number":181,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The INTERNAL RATE OF RETURN (IRR) is the discount rate at which:","options":[{"key":"A","text":"The ARR of the project equals the cost of the capital, at that rate"},{"key":"B","text":"NPV EQUALS ZERO (PV of inflows = PV of outflows)"},{"key":"C","text":"The payback of the project is the shortest possible, at that rate"},{"key":"D","text":"The NPV of the project is the maximum possible, at that rate"}],"answer":"B","explanation":"IRR is the break-even discount rate; it is found by trial and error/interpolation between two rates with opposite-sign NPVs.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The INTERNAL RATE OF RETURN (IRR) is the discount rate at which:","options":["ARR equals cost of capital","NPV EQUALS ZERO (PV of inflows = PV of outflows)","Payback is shortest","NPV is maximum"],"answer":1,"explanation":"IRR is the break-even discount rate; it is found by trial and error/interpolation between two rates with opposite-sign NPVs.","revision":"original","contentSignature":"71fd741c4c7d57d5bdec788de1419a9ba4a92248486558869ecce8e374574043"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA181","optionFormat":"letter"},"contentSignature":"6970a98484f45edab86a958a2aa17d55ae934f479d338dcbab33be84577c5389","kind":"mcq"},{"id":"deep-management-MA182","sourceNumber":182,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The ACCEPT rule under IRR is:","options":["IRR of the project is negative","IRR of the project is zero","IRR of the project is below the cost of capital of the firm","IRR GREATER THAN the cost of capital (hurdle rate)"],"answer":3,"explanation":"Accept when IRR exceeds the required rate; for mutually exclusive projects, pick the highest IRR (subject to the NPV conflict caveat).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA182","number":182,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The ACCEPT rule under IRR is:","options":[{"key":"A","text":"IRR of the project is negative"},{"key":"B","text":"IRR of the project is zero"},{"key":"C","text":"IRR of the project is below the cost of capital of the firm"},{"key":"D","text":"IRR GREATER THAN the cost of capital (hurdle rate)"}],"answer":"D","explanation":"Accept when IRR exceeds the required rate; for mutually exclusive projects, pick the highest IRR (subject to the NPV conflict caveat).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The ACCEPT rule under IRR is:","options":["IRR negative","IRR = 0","IRR below the cost of capital","IRR GREATER THAN the cost of capital (hurdle rate)"],"answer":3,"explanation":"Accept when IRR exceeds the required rate; for mutually exclusive projects, pick the highest IRR (subject to the NPV conflict caveat).","revision":"original","contentSignature":"772b9f52cb117ec2844abbda6487f33ef9b20cae2716ec8eecec72d7a2b7a09d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA182","optionFormat":"letter"},"contentSignature":"244809438620999af79fc67139ab660a0a2f172e4661ffde9e188f828498ab04","kind":"mcq"},{"id":"deep-management-MA183","sourceNumber":183,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A project costs Rs.1,00,000 and yields a single inflow of Rs.1,21,000 after 2 years. Its IRR is:","options":["11%","20%","10%","21%"],"answer":2,"explanation":"1,00,000 x (1+r)^2 = 1,21,000 gives (1+r)^2 = 1.21, so 1+r = 1.1 and r = 10%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA183","number":183,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A project costs Rs.1,00,000 and yields a single inflow of Rs.1,21,000 after 2 years. Its IRR is:","options":[{"key":"A","text":"11%"},{"key":"B","text":"20%"},{"key":"C","text":"10%"},{"key":"D","text":"21%"}],"answer":"C","explanation":"1,00,000 x (1+r)^2 = 1,21,000 gives (1+r)^2 = 1.21, so 1+r = 1.1 and r = 10%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA183","optionFormat":"letter"},"contentSignature":"08ac41b19e731e9d1e41672d343bb2612315b3b199d2c2efde2bdce9f8912ff4","kind":"mcq"},{"id":"deep-management-MA184","sourceNumber":184,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The PROFITABILITY INDEX (PI / benefit-cost ratio) is:","options":["The IRR of the project divided by the cost of the capital of the firm","The NPV of the project divided by the investment of the project","The profit of the year divided by the sales of the year","PV OF CASH INFLOWS / PV OF CASH OUTFLOWS (initial investment)"],"answer":3,"explanation":"PI = PV inflows / PV outflows = 1 + (NPV/outlay); accept if PI > 1. It is a relative measure, ideal for capital rationing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA184","number":184,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The PROFITABILITY INDEX (PI / benefit-cost ratio) is:","options":[{"key":"A","text":"The IRR of the project divided by the cost of the capital of the firm"},{"key":"B","text":"The NPV of the project divided by the investment of the project"},{"key":"C","text":"The profit of the year divided by the sales of the year"},{"key":"D","text":"PV OF CASH INFLOWS / PV OF CASH OUTFLOWS (initial investment)"}],"answer":"D","explanation":"PI = PV inflows / PV outflows = 1 + (NPV/outlay); accept if PI > 1. It is a relative measure, ideal for capital rationing.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PROFITABILITY INDEX (PI / benefit-cost ratio) is:","options":["IRR / Cost of capital","NPV / Investment","Profit / Sales","PV OF CASH INFLOWS / PV OF CASH OUTFLOWS (initial investment)"],"answer":3,"explanation":"PI = PV inflows / PV outflows = 1 + (NPV/outlay); accept if PI > 1. It is a relative measure, ideal for capital rationing.","revision":"original","contentSignature":"9b0e1306e050608c86aa8f9828d383909f234c3ff770719a6df63ac39c785ac2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA184","optionFormat":"letter"},"contentSignature":"d0fde61e1a75fd89496ba3ed9689e0ce1d5adde0c89834b843986cbf514eebde","kind":"mcq"},{"id":"deep-management-MA185","sourceNumber":185,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A project has PV of inflows Rs.3,60,000 and initial investment Rs.3,00,000. Its PI and NPV are:","options":["PI 1.2; NPV Rs.60,000","PI 0.83; NPV Rs.60,000","PI 0.2; NPV Rs.60,000","PI 1.2; NPV Rs.30,000"],"answer":0,"explanation":"PI = 3,60,000/3,00,000 = 1.2; NPV = 3,60,000 - 3,00,000 = Rs.60,000. Accept on both counts.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA185","number":185,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A project has PV of inflows Rs.3,60,000 and initial investment Rs.3,00,000. Its PI and NPV are:","options":[{"key":"A","text":"PI 1.2; NPV Rs.60,000"},{"key":"B","text":"PI 0.83; NPV Rs.60,000"},{"key":"C","text":"PI 0.2; NPV Rs.60,000"},{"key":"D","text":"PI 1.2; NPV Rs.30,000"}],"answer":"A","explanation":"PI = 3,60,000/3,00,000 = 1.2; NPV = 3,60,000 - 3,00,000 = Rs.60,000. Accept on both counts.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA185","optionFormat":"letter"},"contentSignature":"3163ee6b687f5ef16e84732aa7acc1894ba5fce1ef8f11c0f9e25471af15f083","kind":"mcq"},{"id":"deep-management-MA186","sourceNumber":186,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"NPV and IRR methods may yield CONFLICTING rankings because of:","options":["Identical cash flows year by year in the two projects","Both of them ignore the time value of the money, in every computation of the conflict whatever it may be at all","The rates of tax applicable to the firm over the years, which change the discount rate and hence push the two methods in opposite directions each time","DIFFERENCES IN PROJECT SIZE (investment disparity) or in the TIMING/PATTERN of cash flows (and unconventional flows causing multiple IRRs)"],"answer":3,"explanation":"Scale and timing differences make the relative (IRR) and absolute (NPV) measures disagree; unconventional flows can give multiple IRRs.","source":"PYQ: UGC NET Commerce, 2020-Oct-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA186","number":186,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"NPV and IRR methods may yield CONFLICTING rankings because of:","options":[{"key":"A","text":"Identical cash flows year by year in the two projects"},{"key":"B","text":"Both of them ignore the time value of the money, in every computation of the conflict whatever it may be at all"},{"key":"C","text":"The rates of tax applicable to the firm over the years, which change the discount rate and hence push the two methods in opposite directions each time"},{"key":"D","text":"DIFFERENCES IN PROJECT SIZE (investment disparity) or in the TIMING/PATTERN of cash flows (and unconventional flows causing multiple IRRs)"}],"answer":"D","explanation":"Scale and timing differences make the relative (IRR) and absolute (NPV) measures disagree; unconventional flows can give multiple IRRs.","source":"PYQ: UGC NET Commerce, 2020-Oct-M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"NPV and IRR methods may yield CONFLICTING rankings because of:","options":["Same cash flows","Both ignore time value","Tax rates","DIFFERENCES IN PROJECT SIZE (investment disparity) or in the TIMING/PATTERN of cash flows (and unconventional flows causing multiple IRRs)"],"answer":3,"explanation":"Scale and timing differences make the relative (IRR) and absolute (NPV) measures disagree; unconventional flows can give multiple IRRs.","revision":"original","contentSignature":"0777d5238e5abb6a084affafaf94908dff4dccea7a45fa08bf1de1b1bd817547"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA186","optionFormat":"letter"},"contentSignature":"acb118f3d949edcb2663601acc0ab3b6b9279d1fca657f24ac061117ebde0d6a","kind":"pyq"},{"id":"deep-management-MA187","sourceNumber":187,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"When NPV and IRR conflict for MUTUALLY EXCLUSIVE projects, the decision should follow:","options":["The payback of the projects, as the better measure of the wealth of the shareholders","The ARR of the projects, as the better measure of the wealth of the shareholders","NPV - because it assumes reinvestment at the COST OF CAPITAL and measures absolute wealth addition","The IRR of the projects, as the better measure of the wealth of the shareholders"],"answer":2,"explanation":"The NPV reinvestment assumption (at cost of capital) is more realistic than the IRR assumption (at IRR itself), so NPV governs.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA187","number":187,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"When NPV and IRR conflict for MUTUALLY EXCLUSIVE projects, the decision should follow:","options":[{"key":"A","text":"The payback of the projects, as the better measure of the wealth of the shareholders"},{"key":"B","text":"The ARR of the projects, as the better measure of the wealth of the shareholders"},{"key":"C","text":"NPV - because it assumes reinvestment at the COST OF CAPITAL and measures absolute wealth addition"},{"key":"D","text":"The IRR of the projects, as the better measure of the wealth of the shareholders"}],"answer":"C","explanation":"The NPV reinvestment assumption (at cost of capital) is more realistic than the IRR assumption (at IRR itself), so NPV governs.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"When NPV and IRR conflict for MUTUALLY EXCLUSIVE projects, the decision should follow:","options":["Payback","ARR","NPV - because it assumes reinvestment at the COST OF CAPITAL and measures absolute wealth addition","IRR"],"answer":2,"explanation":"The NPV reinvestment assumption (at cost of capital) is more realistic than the IRR assumption (at IRR itself), so NPV governs.","revision":"original","contentSignature":"79df124987110f68f52ea80391e9a258cf21fb4d078411e8d555bc4c7c8ab9ef"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA187","optionFormat":"letter"},"contentSignature":"4d4c7fa0c2281ef68087130546b7a2fe2aecf7173a548cac40db0643a115b797","kind":"mcq"},{"id":"deep-management-MA188","sourceNumber":188,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The discount rate used in NPV is normally:","options":["The prime lending rate of the banks","The firm COST OF CAPITAL / required rate of return","The bank rate fixed by the RBI","The IRR of the project under evaluation by the firm"],"answer":1,"explanation":"The cost of capital (or a risk-adjusted required rate) is the opportunity-cost benchmark for discounting.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA188","number":188,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The discount rate used in NPV is normally:","options":[{"key":"A","text":"The prime lending rate of the banks"},{"key":"B","text":"The firm COST OF CAPITAL / required rate of return"},{"key":"C","text":"The bank rate fixed by the RBI"},{"key":"D","text":"The IRR of the project under evaluation by the firm"}],"answer":"B","explanation":"The cost of capital (or a risk-adjusted required rate) is the opportunity-cost benchmark for discounting.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The discount rate used in NPV is normally:","options":["The prime lending rate","The firm COST OF CAPITAL / required rate of return","The bank rate","The IRR"],"answer":1,"explanation":"The cost of capital (or a risk-adjusted required rate) is the opportunity-cost benchmark for discounting.","revision":"original","contentSignature":"8e3b079db093d4f08327b8776ee6872aabf5c340b5fa572b6555781013c25e64"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA188","optionFormat":"letter"},"contentSignature":"09481db9c500b8d2bbd125cabcdf039c460b97a273df31a2a2a6453162fafd5d","kind":"mcq"},{"id":"deep-management-MA189","sourceNumber":189,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The steps in evaluating a proposal by NPV, in correct order, are:","options":["Compute the NPV, discount the flows, decide, and identify the rate, in that order","Calculate the ARR, the NPV, the IRR and the PI, in that order","Decide first, then discount, compute, and identify the rate, in that order","Identify discount rate, calculate PV of cash flows, compute NPV, decide (accept if positive)"],"answer":3,"explanation":"First forecast the flows and select the discount (cut-off) rate, then discount inflows, subtract the outlay, and apply the accept rule.","source":"PYQ: UGC NET Commerce, 2022- Oct-14M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA189","number":189,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The steps in evaluating a proposal by NPV, in correct order, are:","options":[{"key":"A","text":"Compute the NPV, discount the flows, decide, and identify the rate, in that order"},{"key":"B","text":"Calculate the ARR, the NPV, the IRR and the PI, in that order"},{"key":"C","text":"Decide first, then discount, compute, and identify the rate, in that order"},{"key":"D","text":"Identify discount rate, calculate PV of cash flows, compute NPV, decide (accept if positive)"}],"answer":"D","explanation":"First forecast the flows and select the discount (cut-off) rate, then discount inflows, subtract the outlay, and apply the accept rule.","source":"PYQ: UGC NET Commerce, 2022- Oct-14M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The steps in evaluating a proposal by NPV, in correct order, are:","options":["Compute NPV, discount, decide, identify rate","Calculate ARR, NPV, IRR, PI","Decide, discount, compute, identify","Identify discount rate, calculate PV of cash flows, compute NPV, decide (accept if positive)"],"answer":3,"explanation":"First forecast the flows and select the discount (cut-off) rate, then discount inflows, subtract the outlay, and apply the accept rule.","revision":"original","contentSignature":"0e7c0ca176ac9be8343aaca24c175847ea2eaf51871951e9d48c09b478ed4662"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA189","optionFormat":"letter"},"contentSignature":"40b6b66d208c3fb7b2bbab5c73100056c801cbf8fcccaa75efbd319eedab0ac7","kind":"pyq"},{"id":"deep-management-MA190","sourceNumber":190,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The MERITS of NPV include all EXCEPT:","options":["It is consistent with WEALTH MAXIMISATION","It is EASY to compute and needs no discount rate","It considers ALL cash flows over the project life","It recognises the time value of money"],"answer":1,"explanation":"NPV needs a predetermined discount rate and is harder to explain than payback; its theoretical superiority is otherwise unmatched.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA190","number":190,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The MERITS of NPV include all EXCEPT:","options":[{"key":"A","text":"It is consistent with WEALTH MAXIMISATION"},{"key":"B","text":"It is EASY to compute and needs no discount rate"},{"key":"C","text":"It considers ALL cash flows over the project life"},{"key":"D","text":"It recognises the time value of money"}],"answer":"B","explanation":"NPV needs a predetermined discount rate and is harder to explain than payback; its theoretical superiority is otherwise unmatched.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA190","optionFormat":"letter"},"contentSignature":"ad4a5e4cefc4ae58e5f61053b905fb33ee18995f0f866ae9bf201b33784da22a","kind":"mcq"},{"id":"deep-management-MA191","sourceNumber":191,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A limitation of IRR is:","options":["It ignores the time value of the money, in every computation of the rate whatever","It ignores the later flows of the project, after the payback period is over at last","It ignores the risk of the project, in every computation of the rate whatever","It can produce MULTIPLE rates for unconventional cash flows and assumes reinvestment AT THE IRR"],"answer":3,"explanation":"Non-conventional flow patterns (alternating signs) may yield multiple IRRs; the reinvestment-at-IRR assumption is unrealistic.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA191","number":191,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A limitation of IRR is:","options":[{"key":"A","text":"It ignores the time value of the money, in every computation of the rate whatever"},{"key":"B","text":"It ignores the later flows of the project, after the payback period is over at last"},{"key":"C","text":"It ignores the risk of the project, in every computation of the rate whatever"},{"key":"D","text":"It can produce MULTIPLE rates for unconventional cash flows and assumes reinvestment AT THE IRR"}],"answer":"D","explanation":"Non-conventional flow patterns (alternating signs) may yield multiple IRRs; the reinvestment-at-IRR assumption is unrealistic.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A limitation of IRR is:","options":["It ignores time value","It ignores later flows","It ignores risk","It can produce MULTIPLE rates for unconventional cash flows and assumes reinvestment AT THE IRR"],"answer":3,"explanation":"Non-conventional flow patterns (alternating signs) may yield multiple IRRs; the reinvestment-at-IRR assumption is unrealistic.","revision":"original","contentSignature":"f31cbb9d9a589eb6ddd47296800750d9e98dd8df7aa53b8e73e346acc0fa7614"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA191","optionFormat":"letter"},"contentSignature":"5e9e80bab73ff94caf6892176ccf03060e8d40f41b0865448652e3fcdf5a74ea","kind":"mcq"},{"id":"deep-management-MA192","sourceNumber":192,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The MODIFIED IRR (MIRR) improves on IRR by:","options":["Assuming reinvestment at the COST OF CAPITAL and compounding inflows to the terminal year","Ignoring the time value of the money, in every computation of the modified rate","Leaving out the discount rate from the computation of the terminal value of the project entirely","Using the book profits of the project, instead of the cash flows of the project"],"answer":0,"explanation":"MIRR compounds positive flows at the finance/reinvestment rate to the end, then finds the single rate equating them to the PV of outflows - one unique answer.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA192","number":192,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The MODIFIED IRR (MIRR) improves on IRR by:","options":[{"key":"A","text":"Assuming reinvestment at the COST OF CAPITAL and compounding inflows to the terminal year"},{"key":"B","text":"Ignoring the time value of the money, in every computation of the modified rate"},{"key":"C","text":"Leaving out the discount rate from the computation of the terminal value of the project entirely"},{"key":"D","text":"Using the book profits of the project, instead of the cash flows of the project"}],"answer":"A","explanation":"MIRR compounds positive flows at the finance/reinvestment rate to the end, then finds the single rate equating them to the PV of outflows - one unique answer.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MODIFIED IRR (MIRR) improves on IRR by:","options":["Assuming reinvestment at the COST OF CAPITAL and compounding inflows to the terminal year","Ignoring time value","Removing the discount rate","Using book profits"],"answer":0,"explanation":"MIRR compounds positive flows at the finance/reinvestment rate to the end, then finds the single rate equating them to the PV of outflows - one unique answer.","revision":"original","contentSignature":"0ea1715564c755af454f4fa2b34cd16fe07ddb63a08ab691f6b2874f0ee84889"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA192","optionFormat":"letter"},"contentSignature":"68bac53c1ba1776c97c250c3b8a44ec582e188e131390eab061d6ecd9dab6859","kind":"mcq"},{"id":"deep-management-MA193","sourceNumber":193,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The value of a firm under the WEALTH MAXIMISATION objective is measured by:","options":["The PRESENT VALUE OF ALL EXPECTED FUTURE CASH FLOWS (benefits) discounted at an appropriate rate","The share capital of the firm, as subscribed by the shareholders of the company","The total assets of the firm, at their balance-sheet values as on the date","The book profit of the firm, as per its accounts of the year under review"],"answer":0,"explanation":"Wealth maximisation discounts the entire expected benefit stream; it is the theoretically correct goal of financial management.","source":"PYQ: UGC NET Commerce, 2021-Nov- 25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA193","number":193,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The value of a firm under the WEALTH MAXIMISATION objective is measured by:","options":[{"key":"A","text":"The PRESENT VALUE OF ALL EXPECTED FUTURE CASH FLOWS (benefits) discounted at an appropriate rate"},{"key":"B","text":"The share capital of the firm, as subscribed by the shareholders of the company"},{"key":"C","text":"The total assets of the firm, at their balance-sheet values as on the date"},{"key":"D","text":"The book profit of the firm, as per its accounts of the year under review"}],"answer":"A","explanation":"Wealth maximisation discounts the entire expected benefit stream; it is the theoretically correct goal of financial management.","source":"PYQ: UGC NET Commerce, 2021-Nov- 25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The value of a firm under the WEALTH MAXIMISATION objective is measured by:","options":["The PRESENT VALUE OF ALL EXPECTED FUTURE CASH FLOWS (benefits) discounted at an appropriate rate","Share capital","Total assets","Book profit"],"answer":0,"explanation":"Wealth maximisation discounts the entire expected benefit stream; it is the theoretically correct goal of financial management.","revision":"original","contentSignature":"d52a89c57e2b565835c4b7e75994f1b117ae8207571608ee04e588639ce54660"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA193","optionFormat":"letter"},"contentSignature":"278357828e0afc4fbfb0c91fc42f6f70ce6b608e3761142b3bed09425f4135df","kind":"pyq"},{"id":"deep-management-MA194","sourceNumber":194,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"PROFIT MAXIMISATION is criticised as a goal because it:","options":["IGNORES timing (time value), risk, quality of benefits and is VAGUE about which profit (short/long run, before/after tax)","It adds directly to the wealth of the shareholders","It takes full account of the risks of the business","It is too precise about the profit to be pursued"],"answer":0,"explanation":"Profit maximisation is ambiguous, ignores time value and risk, and can invite short-sighted decisions; wealth maximisation answers all three.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA194","number":194,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"PROFIT MAXIMISATION is criticised as a goal because it:","options":[{"key":"A","text":"IGNORES timing (time value), risk, quality of benefits and is VAGUE about which profit (short/long run, before/after tax)"},{"key":"B","text":"It adds directly to the wealth of the shareholders"},{"key":"C","text":"It takes full account of the risks of the business"},{"key":"D","text":"It is too precise about the profit to be pursued"}],"answer":"A","explanation":"Profit maximisation is ambiguous, ignores time value and risk, and can invite short-sighted decisions; wealth maximisation answers all three.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"PROFIT MAXIMISATION is criticised as a goal because it:","options":["IGNORES timing (time value), risk, quality of benefits and is VAGUE about which profit (short/long run, before/after tax)","Maximises wealth","Considers risk","Is too precise"],"answer":0,"explanation":"Profit maximisation is ambiguous, ignores time value and risk, and can invite short-sighted decisions; wealth maximisation answers all three.","revision":"original","contentSignature":"78d4b45968a01766e1c1201e4f58720cd00d12cf45a17f390689d56eb9b910e8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA194","optionFormat":"letter"},"contentSignature":"428fe0fc457f460de909f64dda4037e39a63e69727130053c6d6f0f5bc57e961","kind":"mcq"},{"id":"deep-management-MA195","sourceNumber":195,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The DESIRABILITY (profitability) index is particularly useful under:","options":["The perfect markets, where the funds are always available","CAPITAL RATIONING - it ranks projects by NPV PER RUPEE invested","The single projects, where no choice arises at all","The unlimited funds, where every project can be taken"],"answer":1,"explanation":"PI ranking selects the bundle with the highest total NPV within a fixed budget.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA195","number":195,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The DESIRABILITY (profitability) index is particularly useful under:","options":[{"key":"A","text":"The perfect markets, where the funds are always available"},{"key":"B","text":"CAPITAL RATIONING - it ranks projects by NPV PER RUPEE invested"},{"key":"C","text":"The single projects, where no choice arises at all"},{"key":"D","text":"The unlimited funds, where every project can be taken"}],"answer":"B","explanation":"PI ranking selects the bundle with the highest total NPV within a fixed budget.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DESIRABILITY (profitability) index is particularly useful under:","options":["Perfect markets","CAPITAL RATIONING - it ranks projects by NPV PER RUPEE invested","Single projects","Unlimited funds"],"answer":1,"explanation":"PI ranking selects the bundle with the highest total NPV within a fixed budget.","revision":"original","contentSignature":"29991c86d91c76fceeb48b9cdf7cfb9fbdcbea048537267a5dc3486ab467a0dd"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA195","optionFormat":"letter"},"contentSignature":"323860597e398245d78e5db3d7126cf56a04212b4b24fe9e38a97d756c9f8017","kind":"mcq"},{"id":"deep-management-MA196","sourceNumber":196,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A machine costs Rs.2,00,000; cash inflows for 4 years are Rs.80,000 p.a. At a 10% discount factor (annuity 4 years = 3.170), the NPV is:","options":["Rs.1,20,000","Rs.2,53,600","Rs.53,600","Rs.-53,600"],"answer":2,"explanation":"PV of inflows = 80,000 x 3.170 = 2,53,600; NPV = 2,53,600 - 2,00,000 = Rs.53,600 (positive - accept).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA196","number":196,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"A machine costs Rs.2,00,000; cash inflows for 4 years are Rs.80,000 p.a. At a 10% discount factor (annuity 4 years = 3.170), the NPV is:","options":[{"key":"A","text":"Rs.1,20,000"},{"key":"B","text":"Rs.2,53,600"},{"key":"C","text":"Rs.53,600"},{"key":"D","text":"Rs.-53,600"}],"answer":"C","explanation":"PV of inflows = 80,000 x 3.170 = 2,53,600; NPV = 2,53,600 - 2,00,000 = Rs.53,600 (positive - accept).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA196","optionFormat":"letter"},"contentSignature":"93c6aa196a440003d7ef3641653e6d8486841085d3d6c4c4e3aaf4326212f5e0","kind":"mcq"},{"id":"deep-management-MA197","sourceNumber":197,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The PV factor (at 10%) for Rs.1 receivable after 1 year is 0.909 and after 2 years 0.826. The PV of Rs.1,00,000 receivable at the end of year 2 is:","options":["Rs.1,00,000","Rs.90,900","Rs.82,600","Rs.1,21,000"],"answer":2,"explanation":"1,00,000 x 0.826 = Rs.82,600.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA197","number":197,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"The PV factor (at 10%) for Rs.1 receivable after 1 year is 0.909 and after 2 years 0.826. The PV of Rs.1,00,000 receivable at the end of year 2 is:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"Rs.90,900"},{"key":"C","text":"Rs.82,600"},{"key":"D","text":"Rs.1,21,000"}],"answer":"C","explanation":"1,00,000 x 0.826 = Rs.82,600.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA197","optionFormat":"letter"},"contentSignature":"13d521846773068ffd4b4f26c70278d97eb7acc60a8a288a600b6f370d79a54e","kind":"mcq"},{"id":"deep-management-MA198","sourceNumber":198,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"If the discount rate INCREASES, the NPV of a conventional project will:","options":["Stay constant, whatever the change in the discount rate","Become infinite, as the discount rate increases","Increase, as the discount rate increases","DECREASE (later flows shrink more in present value)"],"answer":3,"explanation":"Higher discounting shrinks PV of inflows; at the IRR the NPV hits zero, beyond it NPV turns negative.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA198","number":198,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"If the discount rate INCREASES, the NPV of a conventional project will:","options":[{"key":"A","text":"Stay constant, whatever the change in the discount rate"},{"key":"B","text":"Become infinite, as the discount rate increases"},{"key":"C","text":"Increase, as the discount rate increases"},{"key":"D","text":"DECREASE (later flows shrink more in present value)"}],"answer":"D","explanation":"Higher discounting shrinks PV of inflows; at the IRR the NPV hits zero, beyond it NPV turns negative.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the discount rate INCREASES, the NPV of a conventional project will:","options":["Stay constant","Become infinite","Increase","DECREASE (later flows shrink more in present value)"],"answer":3,"explanation":"Higher discounting shrinks PV of inflows; at the IRR the NPV hits zero, beyond it NPV turns negative.","revision":"original","contentSignature":"8468b9b2eb6361fe0b361ebfe89c0e215d1b728570dd0df007697706942d59da"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA198","optionFormat":"letter"},"contentSignature":"a3bf5bc40f8491ba5bd97b93d42c001c60f8c23494ea2009cb4b1d7bceff19f8","kind":"mcq"},{"id":"deep-management-MA199","sourceNumber":199,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"Which DCF technique gives the answer as a RATE (percentage)?","options":["Payback","IRR","PI","NPV"],"answer":1,"explanation":"IRR is expressed as a percentage rate; NPV is an absolute amount and PI a ratio.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA199","number":199,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"Which DCF technique gives the answer as a RATE (percentage)?","options":[{"key":"A","text":"Payback"},{"key":"B","text":"IRR"},{"key":"C","text":"PI"},{"key":"D","text":"NPV"}],"answer":"B","explanation":"IRR is expressed as a percentage rate; NPV is an absolute amount and PI a ratio.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA199","optionFormat":"letter"},"contentSignature":"478616d8652e8d209d7131e8c033e1dbc59bed2c85d4d7227f9b28467a9d89e2","kind":"mcq"},{"id":"deep-management-MA200","sourceNumber":200,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"SIMULATION in capital budgeting is used to:","options":["Compute the payback of the project, in the usual way of the evaluation of it","Avoid the computation altogether, by a simple guess of the management of it","Fix the discount rate of the project, once for all its years of life","Model the PROBABILITY DISTRIBUTION of NPV/IRR by repeatedly sampling uncertain variables"],"answer":3,"explanation":"Monte Carlo simulation assigns distributions to key variables and generates the distribution of outcomes - a richer risk picture than sensitivity alone.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA200","number":200,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"SIMULATION in capital budgeting is used to:","options":[{"key":"A","text":"Compute the payback of the project, in the usual way of the evaluation of it"},{"key":"B","text":"Avoid the computation altogether, by a simple guess of the management of it"},{"key":"C","text":"Fix the discount rate of the project, once for all its years of life"},{"key":"D","text":"Model the PROBABILITY DISTRIBUTION of NPV/IRR by repeatedly sampling uncertain variables"}],"answer":"D","explanation":"Monte Carlo simulation assigns distributions to key variables and generates the distribution of outcomes - a richer risk picture than sensitivity alone.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"SIMULATION in capital budgeting is used to:","options":["Compute payback","Avoid computation","Fix the discount rate","Model the PROBABILITY DISTRIBUTION of NPV/IRR by repeatedly sampling uncertain variables"],"answer":3,"explanation":"Monte Carlo simulation assigns distributions to key variables and generates the distribution of outcomes - a richer risk picture than sensitivity alone.","revision":"original","contentSignature":"499fd6f241ed3eaf6328132e1add09a1d4bbcdd8852276752d20a5a7aa1c2bf7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA200","optionFormat":"letter"},"contentSignature":"66e2be92bd2a6dfa18ad55674a45fd22e17b9b74db134801bdd79e68f053f258","kind":"mcq"},{"id":"deep-management-MA201","sourceNumber":201,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M6 · Capital Budgeting II - Time Value, NPV, IRR & PI","question":"CERTAINTY EQUIVALENT approach adjusts:","options":["The discount rate, multiplied by a certainty coefficient","The payback period, multiplied by a certainty coefficient","The CASH FLOWS - uncertain flows are multiplied by certainty-equivalent coefficients, then discounted at the RISK-FREE rate","The tax rates, multiplied by a certainty coefficient"],"answer":2,"explanation":"Certainty equivalents convert risky flows into their sure equivalents, discounted at the risk-free rate - the risk adjustment sits in the numerator.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA201","number":201,"module":"M6","moduleTitle":"Capital Budgeting II - Time Value, NPV, IRR & PI","question":"CERTAINTY EQUIVALENT approach adjusts:","options":[{"key":"A","text":"The discount rate, multiplied by a certainty coefficient"},{"key":"B","text":"The payback period, multiplied by a certainty coefficient"},{"key":"C","text":"The CASH FLOWS - uncertain flows are multiplied by certainty-equivalent coefficients, then discounted at the RISK-FREE rate"},{"key":"D","text":"The tax rates, multiplied by a certainty coefficient"}],"answer":"C","explanation":"Certainty equivalents convert risky flows into their sure equivalents, discounted at the risk-free rate - the risk adjustment sits in the numerator.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CERTAINTY EQUIVALENT approach adjusts:","options":["The discount rate","The payback","The CASH FLOWS - uncertain flows are multiplied by certainty-equivalent coefficients, then discounted at the RISK-FREE rate","Tax rates"],"answer":2,"explanation":"Certainty equivalents convert risky flows into their sure equivalents, discounted at the risk-free rate - the risk adjustment sits in the numerator.","revision":"original","contentSignature":"0e05923fd31c57d4a12ee40e486f0b5bed9f11b4d3d25c0faee7bf865225e404"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA201","optionFormat":"letter"},"contentSignature":"f9d5030cf627dcef5fe8f00f80d8e4e39d73f43485b55e80077e2f332b19ae3a","kind":"mcq"},{"id":"deep-management-MA202","sourceNumber":202,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"Cost of capital is:","options":["The coupon rate on the debt of the firm, as fixed in the debenture trust deed at the time of the issue of the debentures","The bank rate of the RBI, as announced by the central bank from time to time in its credit policy statements","The MINIMUM RATE OF RETURN a firm must earn on its investments to keep the market value of its shares unchanged (the opportunity cost of funds)","The dividend rate of the firm, as declared by the board of directors at the annual general meeting of the year"],"answer":2,"explanation":"Cost of capital is the cut-off/hurdle rate for investment decisions and the discount rate in NPV.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA202","number":202,"module":"M7","moduleTitle":"Cost of Capital","question":"Cost of capital is:","options":[{"key":"A","text":"The coupon rate on the debt of the firm, as fixed in the debenture trust deed at the time of the issue of the debentures"},{"key":"B","text":"The bank rate of the RBI, as announced by the central bank from time to time in its credit policy statements"},{"key":"C","text":"The MINIMUM RATE OF RETURN a firm must earn on its investments to keep the market value of its shares unchanged (the opportunity cost of funds)"},{"key":"D","text":"The dividend rate of the firm, as declared by the board of directors at the annual general meeting of the year"}],"answer":"C","explanation":"Cost of capital is the cut-off/hurdle rate for investment decisions and the discount rate in NPV.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Cost of capital is:","options":["The coupon rate on debt","The bank rate","The MINIMUM RATE OF RETURN a firm must earn on its investments to keep the market value of its shares unchanged (the opportunity cost of funds)","The dividend rate"],"answer":2,"explanation":"Cost of capital is the cut-off/hurdle rate for investment decisions and the discount rate in NPV.","revision":"original","contentSignature":"c0d75a55c3008a18a53b6b3b134535fe897aa2928d6a11919be4fc78c5d9f5a2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA202","optionFormat":"letter"},"contentSignature":"418fe0210e78978cb2db87597a788449c574d3166e088ae231d6da9e7951fae1","kind":"mcq"},{"id":"deep-management-MA203","sourceNumber":203,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of capital is used in financial management mainly for:","options":["ACCEPT-REJECT decisions in capital budgeting (discount/hurdle rate) and designing the optimal capital structure","The audit of the accounts of the firm, as required by the statute for every company registered under the Act","The preparation of the budgets of the firm, year after year, as a routine exercise of the management","The filing of the tax returns of the firm, year after year, as required by the Income-tax Act"],"answer":0,"explanation":"It links investment and financing decisions: projects must clear it, and the mix of funds should minimise it.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA203","number":203,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of capital is used in financial management mainly for:","options":[{"key":"A","text":"ACCEPT-REJECT decisions in capital budgeting (discount/hurdle rate) and designing the optimal capital structure"},{"key":"B","text":"The audit of the accounts of the firm, as required by the statute for every company registered under the Act"},{"key":"C","text":"The preparation of the budgets of the firm, year after year, as a routine exercise of the management"},{"key":"D","text":"The filing of the tax returns of the firm, year after year, as required by the Income-tax Act"}],"answer":"A","explanation":"It links investment and financing decisions: projects must clear it, and the mix of funds should minimise it.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of capital is used in financial management mainly for:","options":["ACCEPT-REJECT decisions in capital budgeting (discount/hurdle rate) and designing the optimal capital structure","Audit","Preparing budgets","Tax filing"],"answer":0,"explanation":"It links investment and financing decisions: projects must clear it, and the mix of funds should minimise it.","revision":"original","contentSignature":"28213ba5c3d5a3f09cb7c588af65bd417bcefe561bae36a05bd8d3cd5c894a2d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA203","optionFormat":"letter"},"contentSignature":"8c23e1b617e00ddf3bba90628e20baa1c2d01c5ccf10149f105dfd2e8284e9c0","kind":"mcq"},{"id":"deep-management-MA204","sourceNumber":204,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of DEBT (Kd) is computed on a(n) ________ basis:","options":["The accrual basis only, whatever the tax position of the firm","The pre-tax basis, since the interest is paid before the tax","AFTER-TAX basis: Kd = I(1 - t)/NP because interest is TAX-DEDUCTIBLE","The gross basis, without any adjustment for the tax at all"],"answer":2,"explanation":"Interest tax shield: effective cost = interest x (1 - tax rate) divided by net proceeds of the debenture.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA204","number":204,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of DEBT (Kd) is computed on a(n) ________ basis:","options":[{"key":"A","text":"The accrual basis only, whatever the tax position of the firm"},{"key":"B","text":"The pre-tax basis, since the interest is paid before the tax"},{"key":"C","text":"AFTER-TAX basis: Kd = I(1 - t)/NP because interest is TAX-DEDUCTIBLE"},{"key":"D","text":"The gross basis, without any adjustment for the tax at all"}],"answer":"C","explanation":"Interest tax shield: effective cost = interest x (1 - tax rate) divided by net proceeds of the debenture.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of DEBT (Kd) is computed on a(n) ________ basis:","options":["Accrual only","Pre-tax","AFTER-TAX basis: Kd = I(1 - t)/NP because interest is TAX-DEDUCTIBLE","Gross basis"],"answer":2,"explanation":"Interest tax shield: effective cost = interest x (1 - tax rate) divided by net proceeds of the debenture.","revision":"original","contentSignature":"db7275cbeb49edeb924cee71a0fb0dcf423a11754463d573a370d367ab1ae402"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA204","optionFormat":"letter"},"contentSignature":"cf556a288dad0514b41429aefa4fef6e282a022fc040aac0abb8a5e2d7609c2a","kind":"mcq"},{"id":"deep-management-MA205","sourceNumber":205,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A company issues 10% debentures of Rs.100 at par; tax rate 30%. The after-tax cost of debt is:","options":["3%","7%","10%","13%"],"answer":1,"explanation":"Kd = 10 x (1 - 0.30) = 7%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA205","number":205,"module":"M7","moduleTitle":"Cost of Capital","question":"A company issues 10% debentures of Rs.100 at par; tax rate 30%. The after-tax cost of debt is:","options":[{"key":"A","text":"3%"},{"key":"B","text":"7%"},{"key":"C","text":"10%"},{"key":"D","text":"13%"}],"answer":"B","explanation":"Kd = 10 x (1 - 0.30) = 7%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA205","optionFormat":"letter"},"contentSignature":"12ab5cfbd373a92aaf395be2f3452dc68d114fc720bc21116a754b640413de0c","kind":"mcq"},{"id":"deep-management-MA206","sourceNumber":206,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A 12% debenture of Rs.100 is issued at a PREMIUM of 10% (net proceeds Rs.110); tax 40%. Approximate cost of debt is:","options":["6.86%","6.55%","7.2%","12%"],"answer":1,"explanation":"Kd = 12 x (1 - 0.40)/110 = 7.2/110 = 6.545%, about 6.55%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA206","number":206,"module":"M7","moduleTitle":"Cost of Capital","question":"A 12% debenture of Rs.100 is issued at a PREMIUM of 10% (net proceeds Rs.110); tax 40%. Approximate cost of debt is:","options":[{"key":"A","text":"6.86%"},{"key":"B","text":"6.55%"},{"key":"C","text":"7.2%"},{"key":"D","text":"12%"}],"answer":"B","explanation":"Kd = 12 x (1 - 0.40)/110 = 7.2/110 = 6.545%, about 6.55%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA206","optionFormat":"letter"},"contentSignature":"c66f5658e185f79dfb4fd00554f988ea55e945f82746c12f44544bd03337ffa0","kind":"mcq"},{"id":"deep-management-MA207","sourceNumber":207,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of PREFERENCE capital (Kp) is:","options":["The interest of the year divided by the net proceeds of the issue of the debentures, as computed","The preference dividend multiplied by (1 minus the tax rate), divided by the net proceeds of the issue","The preference dividend divided by the face value of the shares, with full tax adjustment for the dividend paid","PREFERENCE DIVIDEND / NET PROCEEDS - NO tax adjustment, since preference dividend is NOT a deductible expense"],"answer":3,"explanation":"Preference dividend is an appropriation, not a charge; hence no (1-t) factor.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA207","number":207,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of PREFERENCE capital (Kp) is:","options":[{"key":"A","text":"The interest of the year divided by the net proceeds of the issue of the debentures, as computed"},{"key":"B","text":"The preference dividend multiplied by (1 minus the tax rate), divided by the net proceeds of the issue"},{"key":"C","text":"The preference dividend divided by the face value of the shares, with full tax adjustment for the dividend paid"},{"key":"D","text":"PREFERENCE DIVIDEND / NET PROCEEDS - NO tax adjustment, since preference dividend is NOT a deductible expense"}],"answer":"D","explanation":"Preference dividend is an appropriation, not a charge; hence no (1-t) factor.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of PREFERENCE capital (Kp) is:","options":["Interest / NP","Preference dividend x (1-t) / NP","Dividend / Face value only","PREFERENCE DIVIDEND / NET PROCEEDS - NO tax adjustment, since preference dividend is NOT a deductible expense"],"answer":3,"explanation":"Preference dividend is an appropriation, not a charge; hence no (1-t) factor.","revision":"original","contentSignature":"14a62c81efd0bd3d62d367fe823c1d09b9f4126fabee6ed0617c4fb201cbbfa2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA207","optionFormat":"letter"},"contentSignature":"f405d93c2649c641aa59ea4e52250b900f1f9c7ca500517e4af6d6a44c544c3a","kind":"mcq"},{"id":"deep-management-MA208","sourceNumber":208,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A company issues 8% preference shares of Rs.100 at par. Cost of preference capital is:","options":["5.6%","4%","11.2%","8%"],"answer":3,"explanation":"Kp = 8/100 = 8% (no tax adjustment).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA208","number":208,"module":"M7","moduleTitle":"Cost of Capital","question":"A company issues 8% preference shares of Rs.100 at par. Cost of preference capital is:","options":[{"key":"A","text":"5.6%"},{"key":"B","text":"4%"},{"key":"C","text":"11.2%"},{"key":"D","text":"8%"}],"answer":"D","explanation":"Kp = 8/100 = 8% (no tax adjustment).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA208","optionFormat":"letter"},"contentSignature":"51024b96436ed6c665c89d261768d54e5db97643b9d1d8ea86e0cd09dda79d04","kind":"mcq"},{"id":"deep-management-MA209","sourceNumber":209,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of EQUITY share capital (Ke) under the DIVIDEND PRICE approach is:","options":["The dividend of the year divided by the face value of the share","Dividend per share / MARKET PRICE per share (Ke = D/P0)","The EPS of the year divided by the market price of the share","Dividend per share divided by the book value per share"],"answer":1,"explanation":"Ke = D1/P0 under constant dividend; with constant growth g, the Gordon form is Ke = D1/P0 + g.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA209","number":209,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of EQUITY share capital (Ke) under the DIVIDEND PRICE approach is:","options":[{"key":"A","text":"The dividend of the year divided by the face value of the share"},{"key":"B","text":"Dividend per share / MARKET PRICE per share (Ke = D/P0)"},{"key":"C","text":"The EPS of the year divided by the market price of the share"},{"key":"D","text":"Dividend per share divided by the book value per share"}],"answer":"B","explanation":"Ke = D1/P0 under constant dividend; with constant growth g, the Gordon form is Ke = D1/P0 + g.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of EQUITY share capital (Ke) under the DIVIDEND PRICE approach is:","options":["Dividend / Face value","Dividend per share / MARKET PRICE per share (Ke = D/P0)","EPS / MP","DPS / MP"],"answer":1,"explanation":"Ke = D1/P0 under constant dividend; with constant growth g, the Gordon form is Ke = D1/P0 + g.","revision":"original","contentSignature":"41af50eae0fa5d007856c71edeb2d1efea128d7e9198af04cc8087fbd64ee45b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA209","optionFormat":"letter"},"contentSignature":"157affa5cd7ee8e3c908d4b8f0bd5ed2e6dd30ac057b3379a4bc69600852638f","kind":"mcq"},{"id":"deep-management-MA210","sourceNumber":210,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"Under the DIVIDEND PRICE PLUS GROWTH (Gordon) model, Ke =","options":["D1/P0 + G (dividend yield plus the constant growth rate)","The dividend multiplied by (1 minus the tax rate), divided by the price","The dividend divided by the price, with no growth at all","The EPS divided by the price, plus the growth rate of the firm"],"answer":0,"explanation":"The constant-growth model adds the expected perpetual dividend growth rate to the forward dividend yield.","source":"Recall 2018 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA210","number":210,"module":"M7","moduleTitle":"Cost of Capital","question":"Under the DIVIDEND PRICE PLUS GROWTH (Gordon) model, Ke =","options":[{"key":"A","text":"D1/P0 + G (dividend yield plus the constant growth rate)"},{"key":"B","text":"The dividend multiplied by (1 minus the tax rate), divided by the price"},{"key":"C","text":"The dividend divided by the price, with no growth at all"},{"key":"D","text":"The EPS divided by the price, plus the growth rate of the firm"}],"answer":"A","explanation":"The constant-growth model adds the expected perpetual dividend growth rate to the forward dividend yield.","source":"Recall 2018","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the DIVIDEND PRICE PLUS GROWTH (Gordon) model, Ke =","options":["D1/P0 + G (dividend yield plus the constant growth rate)","D(1-t)/P","D/P","EPS/P + g"],"answer":0,"explanation":"The constant-growth model adds the expected perpetual dividend growth rate to the forward dividend yield.","revision":"original","contentSignature":"a9932f4091fbd069a5c102f8be486717de05cc43c9430ec73e7c5aef89ccb5e0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA210","optionFormat":"letter"},"contentSignature":"2eb4217e3a3a14a0d2a25c127551fa3c425bace4199463892dbecb07692c7363","kind":"mcq"},{"id":"deep-management-MA211","sourceNumber":211,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A share sells at Rs.50; expected dividend next year Rs.5, growing at 6% forever. Ke is:","options":["10%","4%","6%","16%"],"answer":3,"explanation":"Ke = 5/50 + 0.06 = 0.10 + 0.06 = 16%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA211","number":211,"module":"M7","moduleTitle":"Cost of Capital","question":"A share sells at Rs.50; expected dividend next year Rs.5, growing at 6% forever. Ke is:","options":[{"key":"A","text":"10%"},{"key":"B","text":"4%"},{"key":"C","text":"6%"},{"key":"D","text":"16%"}],"answer":"D","explanation":"Ke = 5/50 + 0.06 = 0.10 + 0.06 = 16%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA211","optionFormat":"letter"},"contentSignature":"9a40ea6b5142bca54e6ae4eadce463df93e8627278a7c584b7ced2c79ec1c671","kind":"mcq"},{"id":"deep-management-MA212","sourceNumber":212,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The EARNINGS-PRICE approach estimates Ke as:","options":["Market price per share divided by the EPS","Book value per share divided by the market price of the share in the stock market","EPS / MARKET PRICE (appropriate when earnings are fully distributed or stable)","Dividend per share divided by the market price"],"answer":2,"explanation":"Ke = EPS/P0; it approximates the capitalisation rate of a no-growth, full-payout firm.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA212","number":212,"module":"M7","moduleTitle":"Cost of Capital","question":"The EARNINGS-PRICE approach estimates Ke as:","options":[{"key":"A","text":"Market price per share divided by the EPS"},{"key":"B","text":"Book value per share divided by the market price of the share in the stock market"},{"key":"C","text":"EPS / MARKET PRICE (appropriate when earnings are fully distributed or stable)"},{"key":"D","text":"Dividend per share divided by the market price"}],"answer":"C","explanation":"Ke = EPS/P0; it approximates the capitalisation rate of a no-growth, full-payout firm.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The EARNINGS-PRICE approach estimates Ke as:","options":["MP / EPS","BV / MP","EPS / MARKET PRICE (appropriate when earnings are fully distributed or stable)","D/P"],"answer":2,"explanation":"Ke = EPS/P0; it approximates the capitalisation rate of a no-growth, full-payout firm.","revision":"original","contentSignature":"b5cb2b7e7dc66fa4625568168da4d723e421ce8fbc9a1a058de113c741a679b8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA212","optionFormat":"letter"},"contentSignature":"c0e0adf395770551bab4898a690ca500376f04aa3cbc8801f60f9449ecab092e","kind":"mcq"},{"id":"deep-management-MA213","sourceNumber":213,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of RETAINED EARNINGS (Kr) is:","options":["EQUAL to the cost of equity (opportunity cost of dividends forgone), sometimes adjusted for personal tax and flotation saved","Zero always - the retained earnings are free funds of the firm, with no cost at all attached to them whatever","Half of the cost of the equity capital","Equal to the cost of the debt of the firm, since retained earnings carry the same safety and the same claim as the borrowings do"],"answer":0,"explanation":"Retained earnings carry an opportunity cost equal to what shareholders could earn outside (Ke); no flotation cost is incurred.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA213","number":213,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of RETAINED EARNINGS (Kr) is:","options":[{"key":"A","text":"EQUAL to the cost of equity (opportunity cost of dividends forgone), sometimes adjusted for personal tax and flotation saved"},{"key":"B","text":"Zero always - the retained earnings are free funds of the firm, with no cost at all attached to them whatever"},{"key":"C","text":"Half of the cost of the equity capital"},{"key":"D","text":"Equal to the cost of the debt of the firm, since retained earnings carry the same safety and the same claim as the borrowings do"}],"answer":"A","explanation":"Retained earnings carry an opportunity cost equal to what shareholders could earn outside (Ke); no flotation cost is incurred.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of RETAINED EARNINGS (Kr) is:","options":["EQUAL to the cost of equity (opportunity cost of dividends forgone), sometimes adjusted for personal tax and flotation saved","Zero - retained earnings are free","Half of Ke","The cost of debt"],"answer":0,"explanation":"Retained earnings carry an opportunity cost equal to what shareholders could earn outside (Ke); no flotation cost is incurred.","revision":"original","contentSignature":"b150c9842c066c92ce4cbb50b0a1e3bc7ad474403dcb40b01b3892f40ec7eafd"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA213","optionFormat":"letter"},"contentSignature":"ecedeeebeb3fcab1d55967e667fb9382a1901b5a5f4281ed62ff961a56d80f7f","kind":"mcq"},{"id":"deep-management-MA214","sourceNumber":214,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"FLOTATION costs on a NEW equity issue:","options":["Are ignored in computing the cost of the new equity raised by the company in the issue","INCREASE the effective cost - Ke = D1 / P0(1 - f) + g, because net proceeds fall","Reduce the Ke of the firm, since the issue becomes cheaper","Reduce the cost of the debt of the firm, since the issue becomes cheaper"],"answer":1,"explanation":"Flotation cost reduces net proceeds, raising the cost of new equity above that of retained earnings.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA214","number":214,"module":"M7","moduleTitle":"Cost of Capital","question":"FLOTATION costs on a NEW equity issue:","options":[{"key":"A","text":"Are ignored in computing the cost of the new equity raised by the company in the issue"},{"key":"B","text":"INCREASE the effective cost - Ke = D1 / P0(1 - f) + g, because net proceeds fall"},{"key":"C","text":"Reduce the Ke of the firm, since the issue becomes cheaper"},{"key":"D","text":"Reduce the cost of the debt of the firm, since the issue becomes cheaper"}],"answer":"B","explanation":"Flotation cost reduces net proceeds, raising the cost of new equity above that of retained earnings.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"FLOTATION costs on a NEW equity issue:","options":["Are ignored","INCREASE the effective cost - Ke = D1 / P0(1 - f) + g, because net proceeds fall","Reduce Ke","Reduce debt cost"],"answer":1,"explanation":"Flotation cost reduces net proceeds, raising the cost of new equity above that of retained earnings.","revision":"original","contentSignature":"2788ee5d2c0ad86f9cdb0663a0dc0766ae68f62ec636cd168158864f44dcc29c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA214","optionFormat":"letter"},"contentSignature":"f591426ebe545af15ea378c723d924c98510509f6c3a7bdca32310f3be0d21cb","kind":"mcq"},{"id":"deep-management-MA215","sourceNumber":215,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The WEIGHTED AVERAGE COST OF CAPITAL (WACC / Ko) is:","options":["The Ke of the firm always, whatever the structure of the capital of the firm may be in the year","The highest of the component costs in the structure, taken as the single rate the firm must pay for all of its funds","The simple average of the component costs, without any weights at all attached to the components","The SUM OF COMPONENT COSTS WEIGHTED BY their PROPORTIONS in the capital structure (book or market value weights)"],"answer":3,"explanation":"Ko = sum of (weight x after-tax cost) for debt, preference, equity and retained earnings.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA215","number":215,"module":"M7","moduleTitle":"Cost of Capital","question":"The WEIGHTED AVERAGE COST OF CAPITAL (WACC / Ko) is:","options":[{"key":"A","text":"The Ke of the firm always, whatever the structure of the capital of the firm may be in the year"},{"key":"B","text":"The highest of the component costs in the structure, taken as the single rate the firm must pay for all of its funds"},{"key":"C","text":"The simple average of the component costs, without any weights at all attached to the components"},{"key":"D","text":"The SUM OF COMPONENT COSTS WEIGHTED BY their PROPORTIONS in the capital structure (book or market value weights)"}],"answer":"D","explanation":"Ko = sum of (weight x after-tax cost) for debt, preference, equity and retained earnings.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The WEIGHTED AVERAGE COST OF CAPITAL (WACC / Ko) is:","options":["Ke always","The highest component cost","The simple average of component costs","The SUM OF COMPONENT COSTS WEIGHTED BY their PROPORTIONS in the capital structure (book or market value weights)"],"answer":3,"explanation":"Ko = sum of (weight x after-tax cost) for debt, preference, equity and retained earnings.","revision":"original","contentSignature":"c7110864304ca63b4288d35d8c0e32e37ba852d8781bff3c1f6422db897d103e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA215","optionFormat":"letter"},"contentSignature":"aa5e28baf61e01ba63222dd10e985c662242791195c568a444e25760eb34779c","kind":"mcq"},{"id":"deep-management-MA216","sourceNumber":216,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A firm has equity (Rs.6,00,000, Ke 16%) and debt (Rs.4,00,000, after-tax Kd 8%). WACC is:","options":["12.8%","14%","12%","11.2%"],"answer":0,"explanation":"Ko = 0.6 x 16 + 0.4 x 8 = 9.6 + 3.2 = 12.8%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA216","number":216,"module":"M7","moduleTitle":"Cost of Capital","question":"A firm has equity (Rs.6,00,000, Ke 16%) and debt (Rs.4,00,000, after-tax Kd 8%). WACC is:","options":[{"key":"A","text":"12.8%"},{"key":"B","text":"14%"},{"key":"C","text":"12%"},{"key":"D","text":"11.2%"}],"answer":"A","explanation":"Ko = 0.6 x 16 + 0.4 x 8 = 9.6 + 3.2 = 12.8%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA216","optionFormat":"letter"},"contentSignature":"468b5073b05627b67975b9ee0a953ffafe7b2eb7ca64ed8ad3a187d130780ee9","kind":"mcq"},{"id":"deep-management-MA217","sourceNumber":217,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"MARKET VALUE weights are preferred to book value weights in WACC because:","options":["They reflect the CURRENT economic proportions in which investors value the firm","They are constant over the years, unlike the book values of the securities of the firm","They are easier to compute than the book values of the securities of the firm","Book value weights are not permitted by law for this purpose"],"answer":0,"explanation":"Market values track the true opportunity costs; book weights can be badly outdated (though stable and always available).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA217","number":217,"module":"M7","moduleTitle":"Cost of Capital","question":"MARKET VALUE weights are preferred to book value weights in WACC because:","options":[{"key":"A","text":"They reflect the CURRENT economic proportions in which investors value the firm"},{"key":"B","text":"They are constant over the years, unlike the book values of the securities of the firm"},{"key":"C","text":"They are easier to compute than the book values of the securities of the firm"},{"key":"D","text":"Book value weights are not permitted by law for this purpose"}],"answer":"A","explanation":"Market values track the true opportunity costs; book weights can be badly outdated (though stable and always available).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"MARKET VALUE weights are preferred to book value weights in WACC because:","options":["They reflect the CURRENT economic proportions in which investors value the firm","They are constant","They are easier","Book values are illegal"],"answer":0,"explanation":"Market values track the true opportunity costs; book weights can be badly outdated (though stable and always available).","revision":"original","contentSignature":"bedab69da1adf9a33135f542edafeb9a25dccb508511fa9a83f483f94d03f140"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA217","optionFormat":"letter"},"contentSignature":"cf5b382e44227f24ef049987d4778f0f100cfe9b7988de5c7818f19966ea6466","kind":"mcq"},{"id":"deep-management-MA218","sourceNumber":218,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The MARGINAL cost of capital is:","options":["The cost of the debt portion of the firm's total capital raised","The cost of the ADDITIONAL (next) rupee of new capital raised","The historical cost of the capital of the firm, as recorded","The average of all the past capital raised by the firm"],"answer":1,"explanation":"Marginal cost matters for new investment decisions; it may jump at break points where retained earnings are exhausted.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA218","number":218,"module":"M7","moduleTitle":"Cost of Capital","question":"The MARGINAL cost of capital is:","options":[{"key":"A","text":"The cost of the debt portion of the firm's total capital raised"},{"key":"B","text":"The cost of the ADDITIONAL (next) rupee of new capital raised"},{"key":"C","text":"The historical cost of the capital of the firm, as recorded"},{"key":"D","text":"The average of all the past capital raised by the firm"}],"answer":"B","explanation":"Marginal cost matters for new investment decisions; it may jump at break points where retained earnings are exhausted.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MARGINAL cost of capital is:","options":["The cost of debt only","The cost of the ADDITIONAL (next) rupee of new capital raised","The historical cost","The average of all past capital"],"answer":1,"explanation":"Marginal cost matters for new investment decisions; it may jump at break points where retained earnings are exhausted.","revision":"original","contentSignature":"7d26a5b623b5aff40dbebef8a4f11531bb145152d9611c5a3e363d1a05773557"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA218","optionFormat":"letter"},"contentSignature":"afa5d4091ec469745f578472f0e94ac627c734a7d824f1471d0348d8fc62b43f","kind":"mcq"},{"id":"deep-management-MA219","sourceNumber":219,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A firm keeps its debt-equity at 40:60 and has Rs.3,00,000 of retained earnings (Ke 14%) before needing new equity (Ke 16%). The BREAK POINT for the equity component is:","options":["Rs.5,00,000","Rs.7,50,000","Rs.3,00,000","Rs.1,80,000"],"answer":0,"explanation":"Break point = retained earnings / equity weight = 3,00,000 / 0.60 = Rs.5,00,000 of total new financing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA219","number":219,"module":"M7","moduleTitle":"Cost of Capital","question":"A firm keeps its debt-equity at 40:60 and has Rs.3,00,000 of retained earnings (Ke 14%) before needing new equity (Ke 16%). The BREAK POINT for the equity component is:","options":[{"key":"A","text":"Rs.5,00,000"},{"key":"B","text":"Rs.7,50,000"},{"key":"C","text":"Rs.3,00,000"},{"key":"D","text":"Rs.1,80,000"}],"answer":"A","explanation":"Break point = retained earnings / equity weight = 3,00,000 / 0.60 = Rs.5,00,000 of total new financing.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA219","optionFormat":"letter"},"contentSignature":"4fedeaf0850c2e1f773323d02d25e9977ad688bc50460d935bba10655e9edc03","kind":"mcq"},{"id":"deep-management-MA220","sourceNumber":220,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"The cost of capital for an ALL-EQUITY firm is:","options":["Kp only","Kd only","Zero always, since the equity has no cost at all","Ke only (WACC = cost of equity)"],"answer":3,"explanation":"With no debt or preference, the weighted average reduces to the cost of equity.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA220","number":220,"module":"M7","moduleTitle":"Cost of Capital","question":"The cost of capital for an ALL-EQUITY firm is:","options":[{"key":"A","text":"Kp only"},{"key":"B","text":"Kd only"},{"key":"C","text":"Zero always, since the equity has no cost at all"},{"key":"D","text":"Ke only (WACC = cost of equity)"}],"answer":"D","explanation":"With no debt or preference, the weighted average reduces to the cost of equity.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The cost of capital for an ALL-EQUITY firm is:","options":["Kp","Kd","Zero","Ke only (WACC = cost of equity)"],"answer":3,"explanation":"With no debt or preference, the weighted average reduces to the cost of equity.","revision":"original","contentSignature":"86f0243ae179e84a0180bfa1c1728a07d836e1116cb1a614fb7b51e6e7a4b6c7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA220","optionFormat":"letter"},"contentSignature":"b1d3fabb4a985e8d5de3f96c9db573636d8352c91394713a8fac24dc8a72f1c1","kind":"mcq"},{"id":"deep-management-MA221","sourceNumber":221,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"Explicit cost of capital refers to:","options":["Zero cost always, since the explicit sources of the capital are free to the firm","The rate the firm must PAY on the specific source (e.g. interest rate on debt)","The implied cost of the source, as computed by the analyst of the firm","The opportunity cost of the source, as computed by the analyst of the firm"],"answer":1,"explanation":"Explicit cost is the contractual rate; implicit (opportunity) cost attaches to sources like retained earnings.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA221","number":221,"module":"M7","moduleTitle":"Cost of Capital","question":"Explicit cost of capital refers to:","options":[{"key":"A","text":"Zero cost always, since the explicit sources of the capital are free to the firm"},{"key":"B","text":"The rate the firm must PAY on the specific source (e.g. interest rate on debt)"},{"key":"C","text":"The implied cost of the source, as computed by the analyst of the firm"},{"key":"D","text":"The opportunity cost of the source, as computed by the analyst of the firm"}],"answer":"B","explanation":"Explicit cost is the contractual rate; implicit (opportunity) cost attaches to sources like retained earnings.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Explicit cost of capital refers to:","options":["Zero cost","The rate the firm must PAY on the specific source (e.g. interest rate on debt)","Implied cost","Opportunity cost"],"answer":1,"explanation":"Explicit cost is the contractual rate; implicit (opportunity) cost attaches to sources like retained earnings.","revision":"original","contentSignature":"5d8b8d1d14d276cf5215766202f1a6f0bc3bc869550ee6a4a4067ed9ff58df70"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA221","optionFormat":"letter"},"contentSignature":"d3139cfa4d62c97532d3f1adc4bc608f7b837d4059f38e713bd562f44ab388ff","kind":"mcq"},{"id":"deep-management-MA222","sourceNumber":222,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"Redeemable debentures cost formula (approximation) is:","options":["Interest for the year divided by the redeemable value","Dividend for the year divided by the price of the share","Kd = [I(1-t) + (RV - NP)/n] / [(RV + NP)/2], where RV = redeemable value, NP = net proceeds","Interest multiplied by (1 - tax rate), divided by the net proceeds of the debenture issue made"],"answer":2,"explanation":"For redeemable debt, the amortisation of the redemption premium/discount over the life is added to the after-tax interest.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA222","number":222,"module":"M7","moduleTitle":"Cost of Capital","question":"Redeemable debentures cost formula (approximation) is:","options":[{"key":"A","text":"Interest for the year divided by the redeemable value"},{"key":"B","text":"Dividend for the year divided by the price of the share"},{"key":"C","text":"Kd = [I(1-t) + (RV - NP)/n] / [(RV + NP)/2], where RV = redeemable value, NP = net proceeds"},{"key":"D","text":"Interest multiplied by (1 - tax rate), divided by the net proceeds of the debenture issue made"}],"answer":"C","explanation":"For redeemable debt, the amortisation of the redemption premium/discount over the life is added to the after-tax interest.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Redeemable debentures cost formula (approximation) is:","options":["I/RV","D/P0","Kd = [I(1-t) + (RV - NP)/n] / [(RV + NP)/2], where RV = redeemable value, NP = net proceeds","I(1-t)/NP"],"answer":2,"explanation":"For redeemable debt, the amortisation of the redemption premium/discount over the life is added to the after-tax interest.","revision":"original","contentSignature":"7658c9075609331b3f78617d1f211639770566c08eaedadc39433713cce0e3ba"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA222","optionFormat":"letter"},"contentSignature":"39fdd605df3fb2d1faad36ef85e5c63755cf0c90bc790823d7f537180dd032aa","kind":"mcq"},{"id":"deep-management-MA223","sourceNumber":223,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"CAPM estimates the cost of equity as:","options":["EPS divided by the market price of the share","Dividend divided by the price, plus the growth rate of dividends expected in future","Rf + beta x (Rm - Rf) - risk-free rate plus beta times the market risk premium","Cost of debt plus the rate of tax"],"answer":2,"explanation":"CAPM prices systematic risk only: Ke = Rf + beta(Rm - Rf).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA223","number":223,"module":"M7","moduleTitle":"Cost of Capital","question":"CAPM estimates the cost of equity as:","options":[{"key":"A","text":"EPS divided by the market price of the share"},{"key":"B","text":"Dividend divided by the price, plus the growth rate of dividends expected in future"},{"key":"C","text":"Rf + beta x (Rm - Rf) - risk-free rate plus beta times the market risk premium"},{"key":"D","text":"Cost of debt plus the rate of tax"}],"answer":"C","explanation":"CAPM prices systematic risk only: Ke = Rf + beta(Rm - Rf).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CAPM estimates the cost of equity as:","options":["EPS/P","D/P + g","Rf + beta x (Rm - Rf) - risk-free rate plus beta times the market risk premium","Kd + t"],"answer":2,"explanation":"CAPM prices systematic risk only: Ke = Rf + beta(Rm - Rf).","revision":"original","contentSignature":"82d95ad64a6fd29ea9f0a703c45672410fca5d57d764804f8657b241426fbcb2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA223","optionFormat":"letter"},"contentSignature":"b2261ff0ef05c385f9b9c20d2316af618f209d7d73a039c54c3f74ce67bfa90d","kind":"mcq"},{"id":"deep-management-MA224","sourceNumber":224,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"A share has beta 1.4, risk-free rate 7%, expected market return 15%. Ke (CAPM) is:","options":["21%","18.2%","11.2%","15%"],"answer":1,"explanation":"Ke = 7 + 1.4 x (15 - 7) = 7 + 11.2 = 18.2%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA224","number":224,"module":"M7","moduleTitle":"Cost of Capital","question":"A share has beta 1.4, risk-free rate 7%, expected market return 15%. Ke (CAPM) is:","options":[{"key":"A","text":"21%"},{"key":"B","text":"18.2%"},{"key":"C","text":"11.2%"},{"key":"D","text":"15%"}],"answer":"B","explanation":"Ke = 7 + 1.4 x (15 - 7) = 7 + 11.2 = 18.2%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA224","optionFormat":"letter"},"contentSignature":"a3b3e57dbf658127a7fe15a67204edceb424d8269a80508f67bf97af041e679e","kind":"mcq"},{"id":"deep-management-MA225","sourceNumber":225,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"Beta measures:","options":["The unsystematic risk of the security, specific to the firm and its own affairs","The liquidity of the security, in the market where it is traded daily","SYSTEMATIC (market/non-diversifiable) risk of a security relative to the market","The total risk of the security, including every kind of risk whatever"],"answer":2,"explanation":"Beta = covariance with market / market variance; beta > 1 means more volatile than the market.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA225","number":225,"module":"M7","moduleTitle":"Cost of Capital","question":"Beta measures:","options":[{"key":"A","text":"The unsystematic risk of the security, specific to the firm and its own affairs"},{"key":"B","text":"The liquidity of the security, in the market where it is traded daily"},{"key":"C","text":"SYSTEMATIC (market/non-diversifiable) risk of a security relative to the market"},{"key":"D","text":"The total risk of the security, including every kind of risk whatever"}],"answer":"C","explanation":"Beta = covariance with market / market variance; beta > 1 means more volatile than the market.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Beta measures:","options":["Unsystematic risk","Liquidity","SYSTEMATIC (market/non-diversifiable) risk of a security relative to the market","Total risk"],"answer":2,"explanation":"Beta = covariance with market / market variance; beta > 1 means more volatile than the market.","revision":"original","contentSignature":"2976f1b647f3b3be03a1db9e5365cf69c5a939abedb422ba6bd1f5daadf0f4ba"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA225","optionFormat":"letter"},"contentSignature":"74e9ca8795c99eda513bb1958d41fa79bfad23194e08058c6717f6c402c8413b","kind":"mcq"},{"id":"deep-management-MA226","sourceNumber":226,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M7 · Cost of Capital","question":"As the proportion of CHEAP DEBT rises initially, the overall cost of capital (Ko) typically:","options":["FALLS (up to a prudent limit), because cheaper after-tax debt replaces costly equity - beyond a point rising financial risk reverses it","Stays fixed at the same level, whatever the proportion of the debt in the structure of the capital of the firm may be","Becomes zero at once, as soon as the debt is introduced into the structure of the capital of the firm at all","Rises at once, as soon as the debt is introduced into the structure of the capital of the firm at all"],"answer":0,"explanation":"Moderate leverage lowers WACC (the tax-shield benefit); excessive leverage raises both Ke and Kd, pushing WACC back up.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA226","number":226,"module":"M7","moduleTitle":"Cost of Capital","question":"As the proportion of CHEAP DEBT rises initially, the overall cost of capital (Ko) typically:","options":[{"key":"A","text":"FALLS (up to a prudent limit), because cheaper after-tax debt replaces costly equity - beyond a point rising financial risk reverses it"},{"key":"B","text":"Stays fixed at the same level, whatever the proportion of the debt in the structure of the capital of the firm may be"},{"key":"C","text":"Becomes zero at once, as soon as the debt is introduced into the structure of the capital of the firm at all"},{"key":"D","text":"Rises at once, as soon as the debt is introduced into the structure of the capital of the firm at all"}],"answer":"A","explanation":"Moderate leverage lowers WACC (the tax-shield benefit); excessive leverage raises both Ke and Kd, pushing WACC back up.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"As the proportion of CHEAP DEBT rises initially, the overall cost of capital (Ko) typically:","options":["FALLS (up to a prudent limit), because cheaper after-tax debt replaces costly equity - beyond a point rising financial risk reverses it","Stays fixed","Becomes zero","Rises"],"answer":0,"explanation":"Moderate leverage lowers WACC (the tax-shield benefit); excessive leverage raises both Ke and Kd, pushing WACC back up.","revision":"original","contentSignature":"da80720107027cdbc7a176e58d582e10ca7e836471c1eb9da52f831d9b1b9a4e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA226","optionFormat":"letter"},"contentSignature":"4475ad072ef62ff3c8f17664ee8fe341a257af6e170dd7841f38f28c93b3b915","kind":"mcq"},{"id":"deep-management-MA227","sourceNumber":227,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"CAPITAL STRUCTURE refers to:","options":["The total assets of the firm, at their balance-sheet values as on the date of the accounts","The current liabilities of the firm, as on the date of the balance sheet of the year","The share capital of the firm taken by itself, apart from its debt and its reserves and surplus","The MIX/PROPORTION of LONG-TERM sources of funds - debt, preference and equity - used by a firm"],"answer":3,"explanation":"Capital structure is the composition of long-term financing; the decision trades off cheaper debt against financial risk.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA227","number":227,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"CAPITAL STRUCTURE refers to:","options":[{"key":"A","text":"The total assets of the firm, at their balance-sheet values as on the date of the accounts"},{"key":"B","text":"The current liabilities of the firm, as on the date of the balance sheet of the year"},{"key":"C","text":"The share capital of the firm taken by itself, apart from its debt and its reserves and surplus"},{"key":"D","text":"The MIX/PROPORTION of LONG-TERM sources of funds - debt, preference and equity - used by a firm"}],"answer":"D","explanation":"Capital structure is the composition of long-term financing; the decision trades off cheaper debt against financial risk.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CAPITAL STRUCTURE refers to:","options":["Total assets","Current liabilities","Share capital only","The MIX/PROPORTION of LONG-TERM sources of funds - debt, preference and equity - used by a firm"],"answer":3,"explanation":"Capital structure is the composition of long-term financing; the decision trades off cheaper debt against financial risk.","revision":"original","contentSignature":"f48d07615974effb7255322774a82b58862da942464097fa504a3cc2850388a3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA227","optionFormat":"letter"},"contentSignature":"60ffe68f8c6a204c07cb751d92d2ea729f6e7c9a69c1a23c3b53f4ea193fa0e2","kind":"mcq"},{"id":"deep-management-MA228","sourceNumber":228,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The CAPITALISATION of a firm includes:","options":["Only the long-term debt raised by the firm from the market, and not its share capital or reserves at all","ALL long-term securities issued plus reserves and surplus (the total long-term funds raised)","The current assets of the firm, at their balance-sheet values as on the date of accounts","Only the equity capital raised by the firm"],"answer":1,"explanation":"Capitalisation = total long-term capital employed (share capital, reserves, long-term debt); capital structure is its composition.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA228","number":228,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The CAPITALISATION of a firm includes:","options":[{"key":"A","text":"Only the long-term debt raised by the firm from the market, and not its share capital or reserves at all"},{"key":"B","text":"ALL long-term securities issued plus reserves and surplus (the total long-term funds raised)"},{"key":"C","text":"The current assets of the firm, at their balance-sheet values as on the date of accounts"},{"key":"D","text":"Only the equity capital raised by the firm"}],"answer":"B","explanation":"Capitalisation = total long-term capital employed (share capital, reserves, long-term debt); capital structure is its composition.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The CAPITALISATION of a firm includes:","options":["Only debt","ALL long-term securities issued plus reserves and surplus (the total long-term funds raised)","Current assets","Only equity"],"answer":1,"explanation":"Capitalisation = total long-term capital employed (share capital, reserves, long-term debt); capital structure is its composition.","revision":"original","contentSignature":"b3c0af14a6da8cf6a67193880bc21406f0f523e38a95fb09443eae547ca0232e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA228","optionFormat":"letter"},"contentSignature":"fdf1a302449ed7cb4bf192c4f65aa958a5619fd4b7e34773f2fe15756f7c08ed","kind":"mcq"},{"id":"deep-management-MA229","sourceNumber":229,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"An OPTIMAL capital structure is one that:","options":["Ignores the risks of the business altogether and entirely in its working","Uses only debt in the financing mix","MAXIMISES the value of the firm / MINIMISES the overall cost of capital","Uses only equity in the financing mix"],"answer":2,"explanation":"The optimum balances the tax-shield benefit of debt against rising bankruptcy/agency costs so that WACC is lowest and value highest.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA229","number":229,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"An OPTIMAL capital structure is one that:","options":[{"key":"A","text":"Ignores the risks of the business altogether and entirely in its working"},{"key":"B","text":"Uses only debt in the financing mix"},{"key":"C","text":"MAXIMISES the value of the firm / MINIMISES the overall cost of capital"},{"key":"D","text":"Uses only equity in the financing mix"}],"answer":"C","explanation":"The optimum balances the tax-shield benefit of debt against rising bankruptcy/agency costs so that WACC is lowest and value highest.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An OPTIMAL capital structure is one that:","options":["Ignores risk","Uses only debt","MAXIMISES the value of the firm / MINIMISES the overall cost of capital","Uses only equity"],"answer":2,"explanation":"The optimum balances the tax-shield benefit of debt against rising bankruptcy/agency costs so that WACC is lowest and value highest.","revision":"original","contentSignature":"3877a46b9ea02ac2ccaf28b8fdc0ce7f18ad2c4b08756652e9c9ed8e159dbb8f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA229","optionFormat":"letter"},"contentSignature":"6f56b136e078d58f99462b7ff054b4e45f07120a9923ac67ed9b98bf496677fd","kind":"mcq"},{"id":"deep-management-MA230","sourceNumber":230,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"Under the NET INCOME (NI) approach (Durand), the value of the firm:","options":["Independent of the degree of leverage employed","Always zero, irrespective of the leverage employed","Falls as the leverage of the firm rises","INCREASES with leverage - since debt is cheaper and Ke and Kd are assumed CONSTANT, WACC falls as debt rises"],"answer":3,"explanation":"NI assumes constant Ke and Kd, so more cheap debt always lowers Ko; the optimum is (nearly) 100% debt.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA230","number":230,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"Under the NET INCOME (NI) approach (Durand), the value of the firm:","options":[{"key":"A","text":"Independent of the degree of leverage employed"},{"key":"B","text":"Always zero, irrespective of the leverage employed"},{"key":"C","text":"Falls as the leverage of the firm rises"},{"key":"D","text":"INCREASES with leverage - since debt is cheaper and Ke and Kd are assumed CONSTANT, WACC falls as debt rises"}],"answer":"D","explanation":"NI assumes constant Ke and Kd, so more cheap debt always lowers Ko; the optimum is (nearly) 100% debt.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the NET INCOME (NI) approach (Durand), the value of the firm:","options":["Is independent of leverage","Is zero","Falls with leverage","INCREASES with leverage - since debt is cheaper and Ke and Kd are assumed CONSTANT, WACC falls as debt rises"],"answer":3,"explanation":"NI assumes constant Ke and Kd, so more cheap debt always lowers Ko; the optimum is (nearly) 100% debt.","revision":"original","contentSignature":"ddeaf42b79d7663b0b57f052692e41d8ae441fc390e8881b8e8a10db25e5b162"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA230","optionFormat":"letter"},"contentSignature":"ab3e90a3eccfbebeb709b6765ab92927a294d0d97d64d6a6989b693cd6edd2c6","kind":"mcq"},{"id":"deep-management-MA231","sourceNumber":231,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"Under the NET OPERATING INCOME (NOI) approach, the value of the firm is:","options":["Zero always, whatever the structure of the capital of the firm may be in the year of account","Decreased by the use of debt in the structure, since the lenders charge a heavy price for the risk they are asked to bear","Increased by the use of debt in the structure","INDEPENDENT of the capital structure - Ko stays constant because Ke rises exactly enough to offset cheaper debt"],"answer":3,"explanation":"NOI holds that the market capitalises operating income at a constant Ko; leverage only shifts risk to equity (Ke rises), leaving V unchanged.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA231","number":231,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"Under the NET OPERATING INCOME (NOI) approach, the value of the firm is:","options":[{"key":"A","text":"Zero always, whatever the structure of the capital of the firm may be in the year of account"},{"key":"B","text":"Decreased by the use of debt in the structure, since the lenders charge a heavy price for the risk they are asked to bear"},{"key":"C","text":"Increased by the use of debt in the structure"},{"key":"D","text":"INDEPENDENT of the capital structure - Ko stays constant because Ke rises exactly enough to offset cheaper debt"}],"answer":"D","explanation":"NOI holds that the market capitalises operating income at a constant Ko; leverage only shifts risk to equity (Ke rises), leaving V unchanged.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the NET OPERATING INCOME (NOI) approach, the value of the firm is:","options":["Zero","Decreased by debt","Increased by debt","INDEPENDENT of the capital structure - Ko stays constant because Ke rises exactly enough to offset cheaper debt"],"answer":3,"explanation":"NOI holds that the market capitalises operating income at a constant Ko; leverage only shifts risk to equity (Ke rises), leaving V unchanged.","revision":"original","contentSignature":"bc310aa9a0a18d393a464f0e7333053df3e265624c0d7d75de00e56ab13ac5bc"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA231","optionFormat":"letter"},"contentSignature":"587b5a460a2ac45a5e4fd7e759260e464c20c5a3bc4fa641481a733b396c0108","kind":"mcq"},{"id":"deep-management-MA232","sourceNumber":232,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The TRADITIONAL approach to capital structure says:","options":["Ko FIRST FALLS with moderate leverage, then RISES beyond a point - an OPTIMAL structure exists where Ko is minimum","The structure has no effect at all on the value of the firm, in any case whatever the level of debt","Debt should form the whole of the capital structure of the firm, equity being avoided altogether because of its heavy cost","The Ko of the firm is constant, whatever the leverage of the firm may be in the year of account"],"answer":0,"explanation":"The traditional view is intermediate: moderate debt lowers Ko, but beyond a limit Ke (and Kd) rise sharply, so an optimum exists.","source":"PYQ: UGC NET Commerce, 2022- Oct-29M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA232","number":232,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The TRADITIONAL approach to capital structure says:","options":[{"key":"A","text":"Ko FIRST FALLS with moderate leverage, then RISES beyond a point - an OPTIMAL structure exists where Ko is minimum"},{"key":"B","text":"The structure has no effect at all on the value of the firm, in any case whatever the level of debt"},{"key":"C","text":"Debt should form the whole of the capital structure of the firm, equity being avoided altogether because of its heavy cost"},{"key":"D","text":"The Ko of the firm is constant, whatever the leverage of the firm may be in the year of account"}],"answer":"A","explanation":"The traditional view is intermediate: moderate debt lowers Ko, but beyond a limit Ke (and Kd) rise sharply, so an optimum exists.","source":"PYQ: UGC NET Commerce, 2022- Oct-29M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The TRADITIONAL approach to capital structure says:","options":["Ko FIRST FALLS with moderate leverage, then RISES beyond a point - an OPTIMAL structure exists where Ko is minimum","Structure is irrelevant","Debt should be 100%","Ko is constant"],"answer":0,"explanation":"The traditional view is intermediate: moderate debt lowers Ko, but beyond a limit Ke (and Kd) rise sharply, so an optimum exists.","revision":"original","contentSignature":"179ebc1a0a07dfb0d1d3e438d7d235df9c841fe3e7181d7785c94bbba58c699b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA232","optionFormat":"letter"},"contentSignature":"68914484739824a8857b5727262521b0be5a1d61172c24b75d82732bf6685c64","kind":"pyq"},{"id":"deep-management-MA233","sourceNumber":233,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"Under the MODIGLIANI-MILLER (MM) hypothesis WITHOUT taxes, the value of the firm:","options":["Increases as the debt of the firm rises","Decreases as the debt of the firm rises","Equals the value of the debt of the firm","Is INDEPENDENT of capital structure (value depends on operating income and business risk only); ARBITRAGE enforces this"],"answer":3,"explanation":"MM-no-tax: identical firms must have identical total value regardless of leverage; homemade leverage/arbitrage drives them together.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA233","number":233,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"Under the MODIGLIANI-MILLER (MM) hypothesis WITHOUT taxes, the value of the firm:","options":[{"key":"A","text":"Increases as the debt of the firm rises"},{"key":"B","text":"Decreases as the debt of the firm rises"},{"key":"C","text":"Equals the value of the debt of the firm"},{"key":"D","text":"Is INDEPENDENT of capital structure (value depends on operating income and business risk only); ARBITRAGE enforces this"}],"answer":"D","explanation":"MM-no-tax: identical firms must have identical total value regardless of leverage; homemade leverage/arbitrage drives them together.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the MODIGLIANI-MILLER (MM) hypothesis WITHOUT taxes, the value of the firm:","options":["Increases with debt","Decreases with debt","Equals debt value","Is INDEPENDENT of capital structure (value depends on operating income and business risk only); ARBITRAGE enforces this"],"answer":3,"explanation":"MM-no-tax: identical firms must have identical total value regardless of leverage; homemade leverage/arbitrage drives them together.","revision":"original","contentSignature":"56064a63fd7fa5024dcce758b84d609186f8e875c06635be464c07480a7f6ea9"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA233","optionFormat":"letter"},"contentSignature":"1690b0d8e1a09480520e07f0c7687b404fd48faa42c6bc3d43cd724ac6f2244f","kind":"mcq"},{"id":"deep-management-MA234","sourceNumber":234,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"Under MM WITH corporate taxes, the value of a LEVERED firm is:","options":["Zero always, since the tax shield does not exist at all for the firm","VALUE OF UNLEVERED FIRM + PV OF THE TAX SHIELD (Vl = Vu + Debt x Tax rate)","Lower than the value of the unlevered firm, since debt adds greatly to risk","Equal to the value of the unlevered firm"],"answer":1,"explanation":"Interest deductibility adds a tax-shield value; under pure MM with taxes, value keeps rising with debt - tempered in practice by bankruptcy costs.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA234","number":234,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"Under MM WITH corporate taxes, the value of a LEVERED firm is:","options":[{"key":"A","text":"Zero always, since the tax shield does not exist at all for the firm"},{"key":"B","text":"VALUE OF UNLEVERED FIRM + PV OF THE TAX SHIELD (Vl = Vu + Debt x Tax rate)"},{"key":"C","text":"Lower than the value of the unlevered firm, since debt adds greatly to risk"},{"key":"D","text":"Equal to the value of the unlevered firm"}],"answer":"B","explanation":"Interest deductibility adds a tax-shield value; under pure MM with taxes, value keeps rising with debt - tempered in practice by bankruptcy costs.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under MM WITH corporate taxes, the value of a LEVERED firm is:","options":["Zero","VALUE OF UNLEVERED FIRM + PV OF THE TAX SHIELD (Vl = Vu + Debt x Tax rate)","Lower than unlevered","Equal to unlevered"],"answer":1,"explanation":"Interest deductibility adds a tax-shield value; under pure MM with taxes, value keeps rising with debt - tempered in practice by bankruptcy costs.","revision":"original","contentSignature":"294e55726c362b486939a1825af187f0bb7a7b8af13b51f68577de84a020d0d4"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA234","optionFormat":"letter"},"contentSignature":"7599679d7669f5e98da238df060ab9f8f3f93c15be72057e1ff7b962a27f9f97","kind":"mcq"},{"id":"deep-management-MA235","sourceNumber":235,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The proposition \"the cost of equity is a linear function of the debt-equity ratio\" belongs to:","options":["MM approach (Proposition II) - Ke = Ko + (Ko - Kd)(D/E)","The NI approach of Durand, as propounded by him","The Gordon model of the dividends, as propounded by him","The Walter model of the dividends, as propounded by him"],"answer":0,"explanation":"MM Proposition II: Ke rises linearly with leverage as shareholders demand compensation for financial risk.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA235","number":235,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The proposition \"the cost of equity is a linear function of the debt-equity ratio\" belongs to:","options":[{"key":"A","text":"MM approach (Proposition II) - Ke = Ko + (Ko - Kd)(D/E)"},{"key":"B","text":"The NI approach of Durand, as propounded by him"},{"key":"C","text":"The Gordon model of the dividends, as propounded by him"},{"key":"D","text":"The Walter model of the dividends, as propounded by him"}],"answer":"A","explanation":"MM Proposition II: Ke rises linearly with leverage as shareholders demand compensation for financial risk.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The proposition \"the cost of equity is a linear function of the debt-equity ratio\" belongs to:","options":["MM approach (Proposition II) - Ke = Ko + (Ko - Kd)(D/E)","NI approach","Gordon model","Walter model"],"answer":0,"explanation":"MM Proposition II: Ke rises linearly with leverage as shareholders demand compensation for financial risk.","revision":"original","contentSignature":"33e7d0b31555fc23ffb457be4d6d44debd79c55c44bf9d0dbf320db7577b2de5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA235","optionFormat":"letter"},"contentSignature":"7a5de3240283eff5b5fccb535708508b9ffee420d4ce5c70000409720c113169","kind":"mcq"},{"id":"deep-management-MA236","sourceNumber":236,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"ARBITRAGE in the MM model means:","options":["Trading in the shares of the company with inside information","Hedging of the positions taken by the investors","The merger of the firms in the same industry","Investors sell overpriced (levered) shares and create homemade leverage to buy underpriced (unlevered) shares, equalising values"],"answer":3,"explanation":"Personal (homemade) leverage substitutes for corporate leverage, so levered and unlevered firms cannot sell at different total values.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA236","number":236,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"ARBITRAGE in the MM model means:","options":[{"key":"A","text":"Trading in the shares of the company with inside information"},{"key":"B","text":"Hedging of the positions taken by the investors"},{"key":"C","text":"The merger of the firms in the same industry"},{"key":"D","text":"Investors sell overpriced (levered) shares and create homemade leverage to buy underpriced (unlevered) shares, equalising values"}],"answer":"D","explanation":"Personal (homemade) leverage substitutes for corporate leverage, so levered and unlevered firms cannot sell at different total values.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ARBITRAGE in the MM model means:","options":["Insider trading","Hedging only","Mergers","Investors sell overpriced (levered) shares and create homemade leverage to buy underpriced (unlevered) shares, equalising values"],"answer":3,"explanation":"Personal (homemade) leverage substitutes for corporate leverage, so levered and unlevered firms cannot sell at different total values.","revision":"original","contentSignature":"4b999ec371517c3d958c39a3d170820e1a83dc412e31dd068f340f675ab91d79"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA236","optionFormat":"letter"},"contentSignature":"e052e9484f338273652507578903a414bced0de8bc1d404501488a532a003704","kind":"mcq"},{"id":"deep-management-MA237","sourceNumber":237,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The TRADE-OFF theory of capital structure balances:","options":["The dividends against the retentions of the profits of the year, as the balance","The cost against the revenue of the business of the year, as the balance","The TAX-SHIELD BENEFIT of debt against the COSTS OF FINANCIAL DISTRESS/bankruptcy","The assets against the liabilities of the firm, as on the date, as the balance"],"answer":2,"explanation":"Firms add debt until the marginal tax advantage equals the marginal expected distress cost - an interior optimum.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA237","number":237,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The TRADE-OFF theory of capital structure balances:","options":[{"key":"A","text":"The dividends against the retentions of the profits of the year, as the balance"},{"key":"B","text":"The cost against the revenue of the business of the year, as the balance"},{"key":"C","text":"The TAX-SHIELD BENEFIT of debt against the COSTS OF FINANCIAL DISTRESS/bankruptcy"},{"key":"D","text":"The assets against the liabilities of the firm, as on the date, as the balance"}],"answer":"C","explanation":"Firms add debt until the marginal tax advantage equals the marginal expected distress cost - an interior optimum.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The TRADE-OFF theory of capital structure balances:","options":["Dividends vs retentions","Cost vs revenue","The TAX-SHIELD BENEFIT of debt against the COSTS OF FINANCIAL DISTRESS/bankruptcy","Assets vs liabilities"],"answer":2,"explanation":"Firms add debt until the marginal tax advantage equals the marginal expected distress cost - an interior optimum.","revision":"original","contentSignature":"d80056706b83618906d96a46e87431888a7989857e9739558aa3097a656fe508"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA237","optionFormat":"letter"},"contentSignature":"0d504e923f94767980a331db5c7d042b2cd43e6dd941a22b5c6f804b7dac79e0","kind":"mcq"},{"id":"deep-management-MA238","sourceNumber":238,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The PECKING ORDER theory (Myers) ranks financing preference as:","options":["Any order at all, as the management may please from time to time in the year of the finance","The debt first, then the equity, and the retained earnings last of all in the order","INTERNAL FUNDS (retained earnings) first, then DEBT, and NEW EQUITY LAST (due to information asymmetry)","The equity first, then the debt, and the retained earnings last of all in the order"],"answer":2,"explanation":"Managers prefer internal funds, then safe debt, issuing equity only as a last resort because new equity signals overvaluation.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA238","number":238,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The PECKING ORDER theory (Myers) ranks financing preference as:","options":[{"key":"A","text":"Any order at all, as the management may please from time to time in the year of the finance"},{"key":"B","text":"The debt first, then the equity, and the retained earnings last of all in the order"},{"key":"C","text":"INTERNAL FUNDS (retained earnings) first, then DEBT, and NEW EQUITY LAST (due to information asymmetry)"},{"key":"D","text":"The equity first, then the debt, and the retained earnings last of all in the order"}],"answer":"C","explanation":"Managers prefer internal funds, then safe debt, issuing equity only as a last resort because new equity signals overvaluation.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PECKING ORDER theory (Myers) ranks financing preference as:","options":["Any order","Debt, equity, retained","INTERNAL FUNDS (retained earnings) first, then DEBT, and NEW EQUITY LAST (due to information asymmetry)","Equity, debt, retained earnings"],"answer":2,"explanation":"Managers prefer internal funds, then safe debt, issuing equity only as a last resort because new equity signals overvaluation.","revision":"original","contentSignature":"504746a63769ad2098ddf6a3be6194916aa99fa489dccf6dd78bcd5c65806d63"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA238","optionFormat":"letter"},"contentSignature":"b9cefce30971aa38f77a74e724a2e5d0d42b50a0f750ff4b59288b38e396443d","kind":"mcq"},{"id":"deep-management-MA239","sourceNumber":239,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"EBIT-EPS analysis is used to:","options":["Prepare the budgets of the firm, year after year, as a routine of the management always","Compute the tax of the firm, year after year, as required by the law always","FIND the INDIFFERENCE POINT - the EBIT at which EPS is the SAME under alternative financing plans","Value the assets of the firm, from time to time, as required by the board always"],"answer":2,"explanation":"At the indifference EBIT the EPS of the competing plans are equal; above it, higher-debt plans give higher EPS.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA239","number":239,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"EBIT-EPS analysis is used to:","options":[{"key":"A","text":"Prepare the budgets of the firm, year after year, as a routine of the management always"},{"key":"B","text":"Compute the tax of the firm, year after year, as required by the law always"},{"key":"C","text":"FIND the INDIFFERENCE POINT - the EBIT at which EPS is the SAME under alternative financing plans"},{"key":"D","text":"Value the assets of the firm, from time to time, as required by the board always"}],"answer":"C","explanation":"At the indifference EBIT the EPS of the competing plans are equal; above it, higher-debt plans give higher EPS.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"EBIT-EPS analysis is used to:","options":["Prepare budgets","Compute tax","FIND the INDIFFERENCE POINT - the EBIT at which EPS is the SAME under alternative financing plans","Value assets"],"answer":2,"explanation":"At the indifference EBIT the EPS of the competing plans are equal; above it, higher-debt plans give higher EPS.","revision":"original","contentSignature":"0fa22df61d47b95c90b267bb42104e174b16751f248e48672cb9b8b952cf43ad"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA239","optionFormat":"letter"},"contentSignature":"8d43cbc4ae2dbef488b5753fc14eb40048b1ed46cc6ddb627eba2361d1da016a","kind":"mcq"},{"id":"deep-management-MA240","sourceNumber":240,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The EBIT-EPS indifference point between an all-equity plan and a debt plan is the EBIT at which:","options":["The tax payable by the firm works out to zero","EPS under both plans is EQUAL","The EBIT of the firm is at its maximum","The interest payable by the firm is zero"],"answer":1,"explanation":"Equate [(EBIT - I)(1 - t)]/N for the two plans; beyond the indifference EBIT, the levered plan yields higher EPS (trading on equity).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA240","number":240,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The EBIT-EPS indifference point between an all-equity plan and a debt plan is the EBIT at which:","options":[{"key":"A","text":"The tax payable by the firm works out to zero"},{"key":"B","text":"EPS under both plans is EQUAL"},{"key":"C","text":"The EBIT of the firm is at its maximum"},{"key":"D","text":"The interest payable by the firm is zero"}],"answer":"B","explanation":"Equate [(EBIT - I)(1 - t)]/N for the two plans; beyond the indifference EBIT, the levered plan yields higher EPS (trading on equity).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The EBIT-EPS indifference point between an all-equity plan and a debt plan is the EBIT at which:","options":["Tax is zero","EPS under both plans is EQUAL","EBIT is maximum","Interest is zero"],"answer":1,"explanation":"Equate [(EBIT - I)(1 - t)]/N for the two plans; beyond the indifference EBIT, the levered plan yields higher EPS (trading on equity).","revision":"original","contentSignature":"ede383183767be843cef4d670fdfb95356f03b9044b2d5a58a337b6810466c29"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA240","optionFormat":"letter"},"contentSignature":"fae2e5bccf6da2817601501d85848b78c67f2a94983e1d8a2fc29df9065e792a","kind":"mcq"},{"id":"deep-management-MA241","sourceNumber":241,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"A firm needs Rs.10,00,000: Plan A all-equity (1,00,000 shares); Plan B 50% equity + 10% debt of Rs.5,00,000; tax 50%. The indifference EBIT is:","options":["Rs.50,000","Rs.1,00,000","Rs.2,00,000","Rs.5,00,000"],"answer":1,"explanation":"Plan A EPS = EBIT x 0.5/1,00,000; Plan B EPS = (EBIT - 50,000) x 0.5/50,000. Equating: EBIT = Rs.1,00,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA241","number":241,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"A firm needs Rs.10,00,000: Plan A all-equity (1,00,000 shares); Plan B 50% equity + 10% debt of Rs.5,00,000; tax 50%. The indifference EBIT is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.2,00,000"},{"key":"D","text":"Rs.5,00,000"}],"answer":"B","explanation":"Plan A EPS = EBIT x 0.5/1,00,000; Plan B EPS = (EBIT - 50,000) x 0.5/50,000. Equating: EBIT = Rs.1,00,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA241","optionFormat":"letter"},"contentSignature":"8a19f044fe6ee8f25e4d2247e288435da5295afd5149a593d757923e317a1fbc","kind":"mcq"},{"id":"deep-management-MA242","sourceNumber":242,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"TRADING ON EQUITY means:","options":["Speculating in the shares of the company, for the quick gains of the market players of the day","Buying back the shares of the company, from the market at the prices prevailing there","Issuing the bonus shares to the shareholders of the company, free of any cost to them","Using FIXED-COST funds (debt/preference) to MAGNIFY the return on equity when ROI exceeds the cost of debt"],"answer":3,"explanation":"Financial leverage: when the return on investment exceeds the borrowing rate, the surplus belongs to equity holders, raising their return.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA242","number":242,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"TRADING ON EQUITY means:","options":[{"key":"A","text":"Speculating in the shares of the company, for the quick gains of the market players of the day"},{"key":"B","text":"Buying back the shares of the company, from the market at the prices prevailing there"},{"key":"C","text":"Issuing the bonus shares to the shareholders of the company, free of any cost to them"},{"key":"D","text":"Using FIXED-COST funds (debt/preference) to MAGNIFY the return on equity when ROI exceeds the cost of debt"}],"answer":"D","explanation":"Financial leverage: when the return on investment exceeds the borrowing rate, the surplus belongs to equity holders, raising their return.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TRADING ON EQUITY means:","options":["Speculating in shares","Buying back shares","Issuing bonus shares","Using FIXED-COST funds (debt/preference) to MAGNIFY the return on equity when ROI exceeds the cost of debt"],"answer":3,"explanation":"Financial leverage: when the return on investment exceeds the borrowing rate, the surplus belongs to equity holders, raising their return.","revision":"original","contentSignature":"e8aaaf1ca4e776b365c36dbfa76e69e29345d58951d10fd668be1d5d5082e3d8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA242","optionFormat":"letter"},"contentSignature":"b5849f9dd66e3535793caf0d08cf059006b367c3f6fd4ad72c11947b2159c331","kind":"mcq"},{"id":"deep-management-MA243","sourceNumber":243,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"Trading on equity is FAVOURABLE when:","options":["Never favourable at all, whatever the rates may be","ROI EXCEEDS the rate of interest on debt","The ROI falls short of the cost of the debt","The ROI exactly equals the interest rate on the debt"],"answer":1,"explanation":"Only when the firm earns more on assets than it pays on debt does leverage lift EPS; otherwise it cuts EPS.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA243","number":243,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"Trading on equity is FAVOURABLE when:","options":[{"key":"A","text":"Never favourable at all, whatever the rates may be"},{"key":"B","text":"ROI EXCEEDS the rate of interest on debt"},{"key":"C","text":"The ROI falls short of the cost of the debt"},{"key":"D","text":"The ROI exactly equals the interest rate on the debt"}],"answer":"B","explanation":"Only when the firm earns more on assets than it pays on debt does leverage lift EPS; otherwise it cuts EPS.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Trading on equity is FAVOURABLE when:","options":["Never","ROI EXCEEDS the rate of interest on debt","ROI < cost of debt","ROI = interest"],"answer":1,"explanation":"Only when the firm earns more on assets than it pays on debt does leverage lift EPS; otherwise it cuts EPS.","revision":"original","contentSignature":"4ce665e99f022bdd9458bb5ab7590344e68ecf8b1c4c585584195af1a5de56aa"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA243","optionFormat":"letter"},"contentSignature":"823fb9da69389aa6a7e18fa582e1e4c961fea6ecdbc51ed18502e65405f11eca","kind":"mcq"},{"id":"deep-management-MA244","sourceNumber":244,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"OVER-CAPITALISATION means:","options":["The excess of the assets of the firm, over its liabilities, as on the date of the balance sheet of the year","The capital is less than what is needed by the firm, for the scale of its business of the year whatever","The high profits of the firm, year after year, beyond the expectations of the management of the firm","The capital employed EXCEEDS what is needed - earnings cannot justify it, so the RATE OF RETURN IS LOW and shares quote below par"],"answer":3,"explanation":"Over-capitalisation: watered capital, low earnings per share, depressed market value, poor dividend capacity.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA244","number":244,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"OVER-CAPITALISATION means:","options":[{"key":"A","text":"The excess of the assets of the firm, over its liabilities, as on the date of the balance sheet of the year"},{"key":"B","text":"The capital is less than what is needed by the firm, for the scale of its business of the year whatever"},{"key":"C","text":"The high profits of the firm, year after year, beyond the expectations of the management of the firm"},{"key":"D","text":"The capital employed EXCEEDS what is needed - earnings cannot justify it, so the RATE OF RETURN IS LOW and shares quote below par"}],"answer":"D","explanation":"Over-capitalisation: watered capital, low earnings per share, depressed market value, poor dividend capacity.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"OVER-CAPITALISATION means:","options":["Excess of assets","Capital is less than needed","High profits","The capital employed EXCEEDS what is needed - earnings cannot justify it, so the RATE OF RETURN IS LOW and shares quote below par"],"answer":3,"explanation":"Over-capitalisation: watered capital, low earnings per share, depressed market value, poor dividend capacity.","revision":"original","contentSignature":"104c7fb57df3918bdba058aa777b327144f5b9ae661c1f86342a464ea29e2fbe"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA244","optionFormat":"letter"},"contentSignature":"9ca45776d14fe9b7be24e94cfb0e55d82ca8ff344312d3871feee0eb8c061182","kind":"mcq"},{"id":"deep-management-MA245","sourceNumber":245,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"CAUSES of over-capitalisation include:","options":["Issuing the shares at a high premium in the boom times of the market","Over-valuation of assets acquired, raising capital in times of boom/inflation, LIBERAL DIVIDEND POLICY (too little retained), high promotion expenses","The low level of the fixed assets of the firm","The success of the underwriting of the issue"],"answer":1,"explanation":"Buying assets at inflated prices, floating in boom times, inadequate depreciation and excessive dividend payouts all dilute earning power per rupee of capital.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA245","number":245,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"CAUSES of over-capitalisation include:","options":[{"key":"A","text":"Issuing the shares at a high premium in the boom times of the market"},{"key":"B","text":"Over-valuation of assets acquired, raising capital in times of boom/inflation, LIBERAL DIVIDEND POLICY (too little retained), high promotion expenses"},{"key":"C","text":"The low level of the fixed assets of the firm"},{"key":"D","text":"The success of the underwriting of the issue"}],"answer":"B","explanation":"Buying assets at inflated prices, floating in boom times, inadequate depreciation and excessive dividend payouts all dilute earning power per rupee of capital.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CAUSES of over-capitalisation include:","options":["Issuing shares at a high premium","Over-valuation of assets acquired, raising capital in times of boom/inflation, LIBERAL DIVIDEND POLICY (too little retained), high promotion expenses","Low fixed assets","Under-writing success"],"answer":1,"explanation":"Buying assets at inflated prices, floating in boom times, inadequate depreciation and excessive dividend payouts all dilute earning power per rupee of capital.","revision":"original","contentSignature":"4a2e078859fbf8bb9a3df9388481e137c40b0a8c1342a108fff429e091fbaacb"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA245","optionFormat":"letter"},"contentSignature":"f8c8158d8274bf568f8c78491ce247320d6d77b182e7f0c95431874b3090097a","kind":"mcq"},{"id":"deep-management-MA246","sourceNumber":246,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"CONSEQUENCES of over-capitalisation include all EXCEPT:","options":["Fall in share market price","Loss of goodwill/reputation","INCREASED rate of return","Reduced dividend rate"],"answer":2,"explanation":"The rate of return FALLS under over-capitalisation; the firm may be forced into reorganisation/capital reduction.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA246","number":246,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"CONSEQUENCES of over-capitalisation include all EXCEPT:","options":[{"key":"A","text":"Fall in share market price"},{"key":"B","text":"Loss of goodwill/reputation"},{"key":"C","text":"INCREASED rate of return"},{"key":"D","text":"Reduced dividend rate"}],"answer":"C","explanation":"The rate of return FALLS under over-capitalisation; the firm may be forced into reorganisation/capital reduction.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA246","optionFormat":"letter"},"contentSignature":"b99d7555ba873da785917618f4081e9ed0375ff904434afc811eafe15592fc22","kind":"mcq"},{"id":"deep-management-MA247","sourceNumber":247,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The REMEDY for over-capitalisation is:","options":["CAPITAL REDUCTION/reorganisation - write down assets and capital, redeem high-cost preference debt, improve efficiency","More borrowing by the firm, at ever higher rates of interest, as the remedy of the state always","Higher dividends to the shareholders, year after year, as the remedy of the state always","Issue of more shares by the firm, to the public at large, as the remedy of the state always"],"answer":0,"explanation":"Restructuring (reducing the par value, redeeming costly securities) realigns capital with earning capacity.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA247","number":247,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The REMEDY for over-capitalisation is:","options":[{"key":"A","text":"CAPITAL REDUCTION/reorganisation - write down assets and capital, redeem high-cost preference debt, improve efficiency"},{"key":"B","text":"More borrowing by the firm, at ever higher rates of interest, as the remedy of the state always"},{"key":"C","text":"Higher dividends to the shareholders, year after year, as the remedy of the state always"},{"key":"D","text":"Issue of more shares by the firm, to the public at large, as the remedy of the state always"}],"answer":"A","explanation":"Restructuring (reducing the par value, redeeming costly securities) realigns capital with earning capacity.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The REMEDY for over-capitalisation is:","options":["CAPITAL REDUCTION/reorganisation - write down assets and capital, redeem high-cost preference debt, improve efficiency","More borrowing","Higher dividends","Issue more shares"],"answer":0,"explanation":"Restructuring (reducing the par value, redeeming costly securities) realigns capital with earning capacity.","revision":"original","contentSignature":"3a63238cdde9688bae34f17127c386d1db82ec070685e5490de01b43f063779f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA247","optionFormat":"letter"},"contentSignature":"55f1609c1d907940f00bec8d1dc61a0d733d17e1af12351ab22c7ec5597bbe9f","kind":"mcq"},{"id":"deep-management-MA248","sourceNumber":248,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"UNDER-CAPITALISATION means:","options":["The excess capital of the firm, beyond its needs, with the earnings unable to justify it at all whatever the case","The low profits of the firm, year after year, with the shares quoting below the par value always in the market","Capital is INSUFFICIENT relative to the scale and earning power - the rate of return is ABNORMALLY HIGH and shares quote ABOVE par","The high idle funds of the firm, lying unused in the banks, with the shares quoting below par always in the market"],"answer":2,"explanation":"Under-capitalisation: too little owned capital for the business, so earnings and market price per share are high; often remedied by bonus issues.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA248","number":248,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"UNDER-CAPITALISATION means:","options":[{"key":"A","text":"The excess capital of the firm, beyond its needs, with the earnings unable to justify it at all whatever the case"},{"key":"B","text":"The low profits of the firm, year after year, with the shares quoting below the par value always in the market"},{"key":"C","text":"Capital is INSUFFICIENT relative to the scale and earning power - the rate of return is ABNORMALLY HIGH and shares quote ABOVE par"},{"key":"D","text":"The high idle funds of the firm, lying unused in the banks, with the shares quoting below par always in the market"}],"answer":"C","explanation":"Under-capitalisation: too little owned capital for the business, so earnings and market price per share are high; often remedied by bonus issues.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"UNDER-CAPITALISATION means:","options":["Excess capital","Low profits","Capital is INSUFFICIENT relative to the scale and earning power - the rate of return is ABNORMALLY HIGH and shares quote ABOVE par","High idle funds"],"answer":2,"explanation":"Under-capitalisation: too little owned capital for the business, so earnings and market price per share are high; often remedied by bonus issues.","revision":"original","contentSignature":"9faa45259fec863be221e8a294d39a56761edcabff733911dfb51d058de13e56"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA248","optionFormat":"letter"},"contentSignature":"21be3676b8371a5d8c1c854d46e4532cd916c9e53a9773dc1d2a64574ac3d66a","kind":"mcq"},{"id":"deep-management-MA249","sourceNumber":249,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"A REMEDY for under-capitalisation is:","options":["Cutting the wages of the workers of the firm, as a remedy of the state","The capital reduction of the firm, as a remedy of the state","Selling the assets of the firm, as a remedy of the state","ISSUE OF BONUS SHARES / fresh capital to normalise the rate of return"],"answer":3,"explanation":"Bonus issues enlarge the share capital base without affecting cash, bringing the reported return to normal.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA249","number":249,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"A REMEDY for under-capitalisation is:","options":[{"key":"A","text":"Cutting the wages of the workers of the firm, as a remedy of the state"},{"key":"B","text":"The capital reduction of the firm, as a remedy of the state"},{"key":"C","text":"Selling the assets of the firm, as a remedy of the state"},{"key":"D","text":"ISSUE OF BONUS SHARES / fresh capital to normalise the rate of return"}],"answer":"D","explanation":"Bonus issues enlarge the share capital base without affecting cash, bringing the reported return to normal.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A REMEDY for under-capitalisation is:","options":["Cutting wages","Capital reduction","Selling assets","ISSUE OF BONUS SHARES / fresh capital to normalise the rate of return"],"answer":3,"explanation":"Bonus issues enlarge the share capital base without affecting cash, bringing the reported return to normal.","revision":"original","contentSignature":"db5a0b3e77b4f5da0348c50010a28d67bad030b808126dfee8fcd95450d96f22"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA249","optionFormat":"letter"},"contentSignature":"476ff77b5fabe67c9fcf39e36897ac730940a669025a0799f37214a00ad18e52","kind":"mcq"},{"id":"deep-management-MA250","sourceNumber":250,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"OVER-CAPITALISATION vs UNDER-CAPITALISATION - which is considered MORE DANGEROUS for a firm?","options":["OVER-CAPITALISATION - it signals idle/watered assets and chronic low returns, harder to cure than shortage","The under-capitalisation of the firm, as the more dangerous state of the two for the firm itself","Both of them equally, as the more dangerous states of the two for the firm itself always","Neither of them at all, as the more dangerous states of the two for the firm itself always"],"answer":0,"explanation":"Under-capitalisation is cured easily (bonus/fresh issue) and may even indicate efficiency; over-capitalisation reflects deep-seated weakness.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA250","number":250,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"OVER-CAPITALISATION vs UNDER-CAPITALISATION - which is considered MORE DANGEROUS for a firm?","options":[{"key":"A","text":"OVER-CAPITALISATION - it signals idle/watered assets and chronic low returns, harder to cure than shortage"},{"key":"B","text":"The under-capitalisation of the firm, as the more dangerous state of the two for the firm itself"},{"key":"C","text":"Both of them equally, as the more dangerous states of the two for the firm itself always"},{"key":"D","text":"Neither of them at all, as the more dangerous states of the two for the firm itself always"}],"answer":"A","explanation":"Under-capitalisation is cured easily (bonus/fresh issue) and may even indicate efficiency; over-capitalisation reflects deep-seated weakness.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"OVER-CAPITALISATION vs UNDER-CAPITALISATION - which is considered MORE DANGEROUS for a firm?","options":["OVER-CAPITALISATION - it signals idle/watered assets and chronic low returns, harder to cure than shortage","Under-capitalisation","Both equally","Neither"],"answer":0,"explanation":"Under-capitalisation is cured easily (bonus/fresh issue) and may even indicate efficiency; over-capitalisation reflects deep-seated weakness.","revision":"original","contentSignature":"3f447b1c16eae0e22dab8a445130b0bdd0dc566b643b5af260c20c7f247b7c3b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA250","optionFormat":"letter"},"contentSignature":"8e70238649513379b8079f0f0636bddcec78000cc98163bdefcc784578986760","kind":"mcq"},{"id":"deep-management-MA251","sourceNumber":251,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"WATERED CAPITAL arises when:","options":["The reserves of the firm are high, year after year, so that the book value of the assets is fully justified at all times","The BOOK VALUE of assets is overstated - assets are worth less than the capital raised against them (a symptom of over-capitalisation)","The shares are sold at par in the market, so that the book value of the assets is fully justified at all times","The capital of the firm is fully paid up and its assets fully justified by the profits earned and the reserves built up over the years of working"],"answer":1,"explanation":"Watered stock: the real worth of assets is below the face value of securities issued - the excess is \"water\".","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA251","number":251,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"WATERED CAPITAL arises when:","options":[{"key":"A","text":"The reserves of the firm are high, year after year, so that the book value of the assets is fully justified at all times"},{"key":"B","text":"The BOOK VALUE of assets is overstated - assets are worth less than the capital raised against them (a symptom of over-capitalisation)"},{"key":"C","text":"The shares are sold at par in the market, so that the book value of the assets is fully justified at all times"},{"key":"D","text":"The capital of the firm is fully paid up and its assets fully justified by the profits earned and the reserves built up over the years of working"}],"answer":"B","explanation":"Watered stock: the real worth of assets is below the face value of securities issued - the excess is \"water\".","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"WATERED CAPITAL arises when:","options":["Reserves are high","The BOOK VALUE of assets is overstated - assets are worth less than the capital raised against them (a symptom of over-capitalisation)","Shares are sold at par","Capital is fully paid"],"answer":1,"explanation":"Watered stock: the real worth of assets is below the face value of securities issued - the excess is \"water\".","revision":"original","contentSignature":"5c3dd4762899c5117e4f5a4fde26d70be4b23f325a7d869c74e95e3aa9518757"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA251","optionFormat":"letter"},"contentSignature":"891688b5f2e30232b738d7265229f8f3ec6564107967b270f43c4a8f5eba5524","kind":"mcq"},{"id":"deep-management-MA252","sourceNumber":252,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"FAIR/OPTIMUM CAPITALISATION exists when:","options":["The dividend declared absorbs the whole of the earnings","The debt in the capital structure is nil","The capitalisation equals the sum that the earnings can reasonably service - market value approximates par","The shares of the firm quote below their par value"],"answer":2,"explanation":"Neither over- nor under-capitalised: earnings justify the capital employed.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA252","number":252,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"FAIR/OPTIMUM CAPITALISATION exists when:","options":[{"key":"A","text":"The dividend declared absorbs the whole of the earnings"},{"key":"B","text":"The debt in the capital structure is nil"},{"key":"C","text":"The capitalisation equals the sum that the earnings can reasonably service - market value approximates par"},{"key":"D","text":"The shares of the firm quote below their par value"}],"answer":"C","explanation":"Neither over- nor under-capitalised: earnings justify the capital employed.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"FAIR/OPTIMUM CAPITALISATION exists when:","options":["Dividend is 100%","Debt is zero","The capitalisation equals the sum that the earnings can reasonably service - market value approximates par","Shares quote below par"],"answer":2,"explanation":"Neither over- nor under-capitalised: earnings justify the capital employed.","revision":"original","contentSignature":"17b569743fa51a4208dc0bb8df30918ba67a77405889c3e17aff8afc0638855c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA252","optionFormat":"letter"},"contentSignature":"5079cf7f412948de3d28b262a41ac0c77bab79306f45c8650a6129a61fe1012d","kind":"mcq"},{"id":"deep-management-MA253","sourceNumber":253,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The NET INCOME approach was propounded by:","options":["Modigliani and Miller, as the propounders of the approach","DAVID DURAND (he proposed both the NI and NOI approaches)","Gordon, as the propounder of the approach","Walter, as the propounder of the approach"],"answer":1,"explanation":"Durand (1952) set out the two extreme views - NI and NOI - on the leverage-value relationship.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA253","number":253,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The NET INCOME approach was propounded by:","options":[{"key":"A","text":"Modigliani and Miller, as the propounders of the approach"},{"key":"B","text":"DAVID DURAND (he proposed both the NI and NOI approaches)"},{"key":"C","text":"Gordon, as the propounder of the approach"},{"key":"D","text":"Walter, as the propounder of the approach"}],"answer":"B","explanation":"Durand (1952) set out the two extreme views - NI and NOI - on the leverage-value relationship.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The NET INCOME approach was propounded by:","options":["Modigliani and Miller","DAVID DURAND (he proposed both the NI and NOI approaches)","Gordon","Walter"],"answer":1,"explanation":"Durand (1952) set out the two extreme views - NI and NOI - on the leverage-value relationship.","revision":"original","contentSignature":"c5fe7f08d7a71dab69b0edeb299334820a6ba13f881f1af676b76647e153d105"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA253","optionFormat":"letter"},"contentSignature":"c3deaecacab54a05a69ce769dd7ac75c1e24a42d4cdd8632bc2c812c04f1667d","kind":"mcq"},{"id":"deep-management-MA254","sourceNumber":254,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The assumptions of the MM hypothesis include all EXCEPT:","options":["No transaction costs of any kind, in the perfect markets assumed by the model","Perfect capital markets, in which the investors are free to arbitrage at will","Homogeneous expectations of the investors about the earnings of the firm","CORPORATE TAXES with interest deductibility (in the original 1958 proposition)"],"answer":3,"explanation":"The original MM (1958) assumed NO taxes; taxes were introduced in the 1963 correction, which changed the conclusion.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA254","number":254,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The assumptions of the MM hypothesis include all EXCEPT:","options":[{"key":"A","text":"No transaction costs of any kind, in the perfect markets assumed by the model"},{"key":"B","text":"Perfect capital markets, in which the investors are free to arbitrage at will"},{"key":"C","text":"Homogeneous expectations of the investors about the earnings of the firm"},{"key":"D","text":"CORPORATE TAXES with interest deductibility (in the original 1958 proposition)"}],"answer":"D","explanation":"The original MM (1958) assumed NO taxes; taxes were introduced in the 1963 correction, which changed the conclusion.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The assumptions of the MM hypothesis include all EXCEPT:","options":["No transaction costs","Perfect capital markets","Homogeneous expectations","CORPORATE TAXES with interest deductibility (in the original 1958 proposition)"],"answer":3,"explanation":"The original MM (1958) assumed NO taxes; taxes were introduced in the 1963 correction, which changed the conclusion.","revision":"original","contentSignature":"56abca8c3ab31a03597e52bb5953714be3c2ca053caee8f3ea2bf6d186fb5598"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA254","optionFormat":"letter"},"contentSignature":"d5ae525d99cbd19bf5d5349152773d77a5f95c0face4a0a8147dda5581ed8bb9","kind":"mcq"},{"id":"deep-management-MA255","sourceNumber":255,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"The formula for the value of a firm under the NOI approach is V =","options":["EBIT (or NOI) / Ko - operating income capitalised at the overall cost of capital","The dividend of the year divided by the Ke of the firm, as computed","The EBIT of the year divided by the Ke of the firm, as computed","The net profit of the year divided by the Kd of the firm, as computed"],"answer":0,"explanation":"V = NOI/Ko with Ko constant; debt value changes but total value does not.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA255","number":255,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"The formula for the value of a firm under the NOI approach is V =","options":[{"key":"A","text":"EBIT (or NOI) / Ko - operating income capitalised at the overall cost of capital"},{"key":"B","text":"The dividend of the year divided by the Ke of the firm, as computed"},{"key":"C","text":"The EBIT of the year divided by the Ke of the firm, as computed"},{"key":"D","text":"The net profit of the year divided by the Kd of the firm, as computed"}],"answer":"A","explanation":"V = NOI/Ko with Ko constant; debt value changes but total value does not.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The formula for the value of a firm under the NOI approach is V =","options":["EBIT (or NOI) / Ko - operating income capitalised at the overall cost of capital","Dividend / Ke","EBIT / Ke","Net profit / Kd"],"answer":0,"explanation":"V = NOI/Ko with Ko constant; debt value changes but total value does not.","revision":"original","contentSignature":"20bb5acbd54124bac1159e96e3390afd8a6cdcef4015b59a947660761e4683b6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA255","optionFormat":"letter"},"contentSignature":"175a8fae756f42a7d71a1dbb0c801f7c4e8523a764fbe6ab981650f6dc22127a","kind":"mcq"},{"id":"deep-management-MA256","sourceNumber":256,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M8 · Capital Structure, Capitalisation & Theories","question":"A firm expects EBIT of Rs.4,00,000; Ko (capitalisation rate) 10%; debt Rs.5,00,000 at 6%. Under NOI, total value V and equity value E are:","options":["V Rs.45,00,000; E Rs.35,00,000","V Rs.35,00,000; E Rs.40,00,000","V Rs.40,00,000; E Rs.40,00,000","V Rs.40,00,000; E Rs.35,00,000"],"answer":3,"explanation":"V = 4,00,000/0.10 = 40,00,000; E = V - Debt = 40,00,000 - 5,00,000 = 35,00,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA256","number":256,"module":"M8","moduleTitle":"Capital Structure, Capitalisation & Theories","question":"A firm expects EBIT of Rs.4,00,000; Ko (capitalisation rate) 10%; debt Rs.5,00,000 at 6%. Under NOI, total value V and equity value E are:","options":[{"key":"A","text":"V Rs.45,00,000; E Rs.35,00,000"},{"key":"B","text":"V Rs.35,00,000; E Rs.40,00,000"},{"key":"C","text":"V Rs.40,00,000; E Rs.40,00,000"},{"key":"D","text":"V Rs.40,00,000; E Rs.35,00,000"}],"answer":"D","explanation":"V = 4,00,000/0.10 = 40,00,000; E = V - Debt = 40,00,000 - 5,00,000 = 35,00,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA256","optionFormat":"letter"},"contentSignature":"d61aae0fee21616cef440f40ca6417ba719e05b1a40554ec7ee1b9f8184f25b9","kind":"mcq"},{"id":"deep-management-MA257","sourceNumber":257,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"LEVERAGE in financial management refers to:","options":["The use of FIXED-COST assets or funds to MAGNIFY returns (the employment of an asset/source for which the firm pays a fixed cost/return)","The control of the costs of the business, year by year, as a routine of the management of the firm itself always","The paying of the dividends to the shareholders of the company, year after year, as a routine of the board always","The borrowing of the money from the banks, as and when the need of the business arises for the funds always"],"answer":0,"explanation":"Leverage = fixed costs/funds whose use magnifies the effect of changes in sales/EBIT on profits/EPS.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA257","number":257,"module":"M9","moduleTitle":"Leverages","question":"LEVERAGE in financial management refers to:","options":[{"key":"A","text":"The use of FIXED-COST assets or funds to MAGNIFY returns (the employment of an asset/source for which the firm pays a fixed cost/return)"},{"key":"B","text":"The control of the costs of the business, year by year, as a routine of the management of the firm itself always"},{"key":"C","text":"The paying of the dividends to the shareholders of the company, year after year, as a routine of the board always"},{"key":"D","text":"The borrowing of the money from the banks, as and when the need of the business arises for the funds always"}],"answer":"A","explanation":"Leverage = fixed costs/funds whose use magnifies the effect of changes in sales/EBIT on profits/EPS.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"LEVERAGE in financial management refers to:","options":["The use of FIXED-COST assets or funds to MAGNIFY returns (the employment of an asset/source for which the firm pays a fixed cost/return)","Cost control","Paying dividends","Borrowing money"],"answer":0,"explanation":"Leverage = fixed costs/funds whose use magnifies the effect of changes in sales/EBIT on profits/EPS.","revision":"original","contentSignature":"640e3682af9b4cdce92ab98a778e2dfb1c036d6b0c2b503add79c627d1d340d0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA257","optionFormat":"letter"},"contentSignature":"b3f40cb471cff7c6d2d71808ba85cdc30a97d532a433cfd56f2dca4386c85b33","kind":"mcq"},{"id":"deep-management-MA258","sourceNumber":258,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The THREE types of leverage are:","options":["The trading, the equity and the debt leverages of the firm","The simple, the compound and the complex leverages of the firm","OPERATING, FINANCIAL and COMBINED leverage","The fixed, the variable and the total leverages of the firm"],"answer":2,"explanation":"Operating leverage comes from fixed operating costs; financial leverage from fixed financial charges (interest/pref dividend); combined is their product.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA258","number":258,"module":"M9","moduleTitle":"Leverages","question":"The THREE types of leverage are:","options":[{"key":"A","text":"The trading, the equity and the debt leverages of the firm"},{"key":"B","text":"The simple, the compound and the complex leverages of the firm"},{"key":"C","text":"OPERATING, FINANCIAL and COMBINED leverage"},{"key":"D","text":"The fixed, the variable and the total leverages of the firm"}],"answer":"C","explanation":"Operating leverage comes from fixed operating costs; financial leverage from fixed financial charges (interest/pref dividend); combined is their product.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The THREE types of leverage are:","options":["Trading, equity, debt","Simple, compound, complex","OPERATING, FINANCIAL and COMBINED leverage","Fixed, variable, total"],"answer":2,"explanation":"Operating leverage comes from fixed operating costs; financial leverage from fixed financial charges (interest/pref dividend); combined is their product.","revision":"original","contentSignature":"7113ad1d32677ee7d767bcd6ae705e396a83a3b497638f3daa79cff5d53b7f52"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA258","optionFormat":"letter"},"contentSignature":"b5ec18944d35c568a4d3363a091c3a2ed3f5d2d35181fe979c5b92274f176830","kind":"mcq"},{"id":"deep-management-MA259","sourceNumber":259,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"OPERATING LEVERAGE arises from:","options":["The equity of the firm, as the source of the leverage","FIXED OPERATING COSTS in the cost structure","The interest on the debt of the firm, as the source","The preference dividend of the firm, as the source"],"answer":1,"explanation":"Fixed operating costs (not varying with output) create operating leverage: a given sales change produces a larger EBIT change.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA259","number":259,"module":"M9","moduleTitle":"Leverages","question":"OPERATING LEVERAGE arises from:","options":[{"key":"A","text":"The equity of the firm, as the source of the leverage"},{"key":"B","text":"FIXED OPERATING COSTS in the cost structure"},{"key":"C","text":"The interest on the debt of the firm, as the source"},{"key":"D","text":"The preference dividend of the firm, as the source"}],"answer":"B","explanation":"Fixed operating costs (not varying with output) create operating leverage: a given sales change produces a larger EBIT change.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"OPERATING LEVERAGE arises from:","options":["Equity","FIXED OPERATING COSTS in the cost structure","Interest on debt","Preference dividend"],"answer":1,"explanation":"Fixed operating costs (not varying with output) create operating leverage: a given sales change produces a larger EBIT change.","revision":"original","contentSignature":"6d9fdefa171df5350a784f9e7ad14aafd4bfd8862cca5bd9b66ef0ad112741f5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA259","optionFormat":"letter"},"contentSignature":"0e652e427544ca55fc723d526e574f19dcf9b21deaeb63d3ea4b8cbbb7db299a","kind":"mcq"},{"id":"deep-management-MA260","sourceNumber":260,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The DEGREE OF OPERATING LEVERAGE (DOL) at a sales level =","options":["Sales / EBIT","Fixed cost / Sales","CONTRIBUTION / EBIT","EBIT / Sales"],"answer":2,"explanation":"DOL = Contribution/EBIT = % change in EBIT / % change in sales. High fixed costs give high DOL.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA260","number":260,"module":"M9","moduleTitle":"Leverages","question":"The DEGREE OF OPERATING LEVERAGE (DOL) at a sales level =","options":[{"key":"A","text":"Sales / EBIT"},{"key":"B","text":"Fixed cost / Sales"},{"key":"C","text":"CONTRIBUTION / EBIT"},{"key":"D","text":"EBIT / Sales"}],"answer":"C","explanation":"DOL = Contribution/EBIT = % change in EBIT / % change in sales. High fixed costs give high DOL.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA260","optionFormat":"letter"},"contentSignature":"8f58e046c2f354e4656da720cfa6a89ba0607a06cb198e696be54679e9ba6e4a","kind":"mcq"},{"id":"deep-management-MA261","sourceNumber":261,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Contribution is Rs.6,00,000 and EBIT is Rs.4,00,000. DOL is:","options":["1.0","0.67","2.5","1.5"],"answer":3,"explanation":"DOL = 6,00,000/4,00,000 = 1.5: a 10% sales change moves EBIT by 15%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA261","number":261,"module":"M9","moduleTitle":"Leverages","question":"Contribution is Rs.6,00,000 and EBIT is Rs.4,00,000. DOL is:","options":[{"key":"A","text":"1.0"},{"key":"B","text":"0.67"},{"key":"C","text":"2.5"},{"key":"D","text":"1.5"}],"answer":"D","explanation":"DOL = 6,00,000/4,00,000 = 1.5: a 10% sales change moves EBIT by 15%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA261","optionFormat":"letter"},"contentSignature":"291a7a3bb4417eac3226051100c9d63660bcf54e399436ff298e28ec2b1aabfd","kind":"mcq"},{"id":"deep-management-MA262","sourceNumber":262,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"If DOL is 3 and sales increase by 10%, EBIT will:","options":["RISE BY 30%","Rise by 3%","Rise by 10%","Fall by 30%"],"answer":0,"explanation":"% change in EBIT = DOL x % change in sales = 3 x 10% = 30%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA262","number":262,"module":"M9","moduleTitle":"Leverages","question":"If DOL is 3 and sales increase by 10%, EBIT will:","options":[{"key":"A","text":"RISE BY 30%"},{"key":"B","text":"Rise by 3%"},{"key":"C","text":"Rise by 10%"},{"key":"D","text":"Fall by 30%"}],"answer":"A","explanation":"% change in EBIT = DOL x % change in sales = 3 x 10% = 30%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA262","optionFormat":"letter"},"contentSignature":"4d74077dd82ce06080f8782832f6ecabfd3416ac7e46cc92adc7a7136be2f5d5","kind":"mcq"},{"id":"deep-management-MA263","sourceNumber":263,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"FINANCIAL LEVERAGE (trading on equity) arises from:","options":["The variable costs of the business, as the source of it","The fixed operating costs of the business, as the source of it","FIXED FINANCIAL CHARGES - interest on debt and preference dividend","The dividend on the equity of the firm, as the source of it"],"answer":2,"explanation":"Fixed-charge securities magnify the effect of EBIT changes on EPS.","source":"PYQ: NABARD Grade A, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA263","number":263,"module":"M9","moduleTitle":"Leverages","question":"FINANCIAL LEVERAGE (trading on equity) arises from:","options":[{"key":"A","text":"The variable costs of the business, as the source of it"},{"key":"B","text":"The fixed operating costs of the business, as the source of it"},{"key":"C","text":"FIXED FINANCIAL CHARGES - interest on debt and preference dividend"},{"key":"D","text":"The dividend on the equity of the firm, as the source of it"}],"answer":"C","explanation":"Fixed-charge securities magnify the effect of EBIT changes on EPS.","source":"PYQ: NABARD Grade A, 2020","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"FINANCIAL LEVERAGE (trading on equity) arises from:","options":["Variable costs","Fixed operating costs","FIXED FINANCIAL CHARGES - interest on debt and preference dividend","Dividend on equity"],"answer":2,"explanation":"Fixed-charge securities magnify the effect of EBIT changes on EPS.","revision":"original","contentSignature":"594b7e216823b49563008c19f930a52028bf14ef33fe57bfff483ff6ce669d07"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA263","optionFormat":"letter"},"contentSignature":"1c052dc7d294f5121987d8f40f6f45c7590557cf9e037a7f51ec5a5e3562c552","kind":"pyq"},{"id":"deep-management-MA264","sourceNumber":264,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The DEGREE OF FINANCIAL LEVERAGE (DFL) =","options":["EBIT / EBT (EBIT divided by earnings before tax)","The EBT divided by the EBIT of the year, as computed","The contribution divided by the EBIT of the year, as computed","The EBIT divided by the sales of the year, as computed"],"answer":0,"explanation":"DFL = EBIT/EBT = % change in EPS / % change in EBIT. With preference dividend, divide EBT further by (1 - t).","source":"PYQ: NABARD Grade A, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA264","number":264,"module":"M9","moduleTitle":"Leverages","question":"The DEGREE OF FINANCIAL LEVERAGE (DFL) =","options":[{"key":"A","text":"EBIT / EBT (EBIT divided by earnings before tax)"},{"key":"B","text":"The EBT divided by the EBIT of the year, as computed"},{"key":"C","text":"The contribution divided by the EBIT of the year, as computed"},{"key":"D","text":"The EBIT divided by the sales of the year, as computed"}],"answer":"A","explanation":"DFL = EBIT/EBT = % change in EPS / % change in EBIT. With preference dividend, divide EBT further by (1 - t).","source":"PYQ: NABARD Grade A, 2020","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The DEGREE OF FINANCIAL LEVERAGE (DFL) =","options":["EBIT / EBT (EBIT divided by earnings before tax)","EBT / EBIT","Contribution / EBIT","EBIT / Sales"],"answer":0,"explanation":"DFL = EBIT/EBT = % change in EPS / % change in EBIT. With preference dividend, divide EBT further by (1 - t).","revision":"original","contentSignature":"2654861008bda434bbda3cc79ec87a1363422b65146ca0f1ae5d984772e4dd1d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA264","optionFormat":"letter"},"contentSignature":"3c4b3901d06b348f1e09ebe082f3649f76e1a98838f544d8b74236e8045cfbb9","kind":"pyq"},{"id":"deep-management-MA265","sourceNumber":265,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"A firm has EBIT Rs.2,00,000 and interest Rs.50,000 (no preference shares). DFL is:","options":["1.33","2","0.75","4"],"answer":0,"explanation":"DFL = 2,00,000/(2,00,000 - 50,000) = 2,00,000/1,50,000 = 1.33.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA265","number":265,"module":"M9","moduleTitle":"Leverages","question":"A firm has EBIT Rs.2,00,000 and interest Rs.50,000 (no preference shares). DFL is:","options":[{"key":"A","text":"1.33"},{"key":"B","text":"2"},{"key":"C","text":"0.75"},{"key":"D","text":"4"}],"answer":"A","explanation":"DFL = 2,00,000/(2,00,000 - 50,000) = 2,00,000/1,50,000 = 1.33.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA265","optionFormat":"letter"},"contentSignature":"f8d53b50ad258505cc943faded686a9df22daaa07a323b1389b30bddf8d56375","kind":"mcq"},{"id":"deep-management-MA266","sourceNumber":266,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"COMBINED (composite) leverage DCL =","options":["The DOL plus the DFL of the firm, as computed","The DOL divided by the DFL of the firm, as computed","The DOL minus the DFL of the firm, as computed","DOL x DFL = CONTRIBUTION / EBT"],"answer":3,"explanation":"DCL = Contribution/EBT = % change in EPS / % change in sales - the total magnification from sales to EPS.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA266","number":266,"module":"M9","moduleTitle":"Leverages","question":"COMBINED (composite) leverage DCL =","options":[{"key":"A","text":"The DOL plus the DFL of the firm, as computed"},{"key":"B","text":"The DOL divided by the DFL of the firm, as computed"},{"key":"C","text":"The DOL minus the DFL of the firm, as computed"},{"key":"D","text":"DOL x DFL = CONTRIBUTION / EBT"}],"answer":"D","explanation":"DCL = Contribution/EBT = % change in EPS / % change in sales - the total magnification from sales to EPS.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"COMBINED (composite) leverage DCL =","options":["DOL + DFL","DOL / DFL","DOL - DFL","DOL x DFL = CONTRIBUTION / EBT"],"answer":3,"explanation":"DCL = Contribution/EBT = % change in EPS / % change in sales - the total magnification from sales to EPS.","revision":"original","contentSignature":"6c048c3e53b9a026c6a811c005a26721dcd21000d5bb84368eac4b88d818ff20"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA266","optionFormat":"letter"},"contentSignature":"0d583afa09cd44fca8d91ffd6cdae480540959d4c291f4e9764a4567650419c9","kind":"mcq"},{"id":"deep-management-MA267","sourceNumber":267,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Contribution Rs.8,00,000; EBIT Rs.5,00,000; EBT Rs.3,00,000. DCL is:","options":["2.67","4.27","1.6","0.6"],"answer":0,"explanation":"DCL = 8,00,000/3,00,000 = 2.67 (also DOL 1.6 x DFL 1.67).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA267","number":267,"module":"M9","moduleTitle":"Leverages","question":"Contribution Rs.8,00,000; EBIT Rs.5,00,000; EBT Rs.3,00,000. DCL is:","options":[{"key":"A","text":"2.67"},{"key":"B","text":"4.27"},{"key":"C","text":"1.6"},{"key":"D","text":"0.6"}],"answer":"A","explanation":"DCL = 8,00,000/3,00,000 = 2.67 (also DOL 1.6 x DFL 1.67).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA267","optionFormat":"letter"},"contentSignature":"cb422840a94b9028f243cdaf66fd6c9be682410d7e944f9afb0d238f475eb77f","kind":"mcq"},{"id":"deep-management-MA268","sourceNumber":268,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"A HIGH degree of operating leverage means:","options":["There are no fixed costs in the business of the firm","There is a high proportion of debt in the capital structure","SMALL changes in sales cause LARGE changes in EBIT - high BUSINESS RISK (typical of capital-intensive firms)","There is a low level of risk in the business of the firm"],"answer":2,"explanation":"High fixed operating costs near the break-even zone make EBIT very sensitive to volume - riskier in downturns.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA268","number":268,"module":"M9","moduleTitle":"Leverages","question":"A HIGH degree of operating leverage means:","options":[{"key":"A","text":"There are no fixed costs in the business of the firm"},{"key":"B","text":"There is a high proportion of debt in the capital structure"},{"key":"C","text":"SMALL changes in sales cause LARGE changes in EBIT - high BUSINESS RISK (typical of capital-intensive firms)"},{"key":"D","text":"There is a low level of risk in the business of the firm"}],"answer":"C","explanation":"High fixed operating costs near the break-even zone make EBIT very sensitive to volume - riskier in downturns.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A HIGH degree of operating leverage means:","options":["No fixed costs","High debt","SMALL changes in sales cause LARGE changes in EBIT - high BUSINESS RISK (typical of capital-intensive firms)","Low risk"],"answer":2,"explanation":"High fixed operating costs near the break-even zone make EBIT very sensitive to volume - riskier in downturns.","revision":"original","contentSignature":"0a08eaa06eb4b04a4cfa64e38b84b7668cf74506b3224f56cdb19b0b00c5374a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA268","optionFormat":"letter"},"contentSignature":"d2d5274e56ff94d8021937b89a5cae1e3ef27fcc372931087638df913c112dd6","kind":"mcq"},{"id":"deep-management-MA269","sourceNumber":269,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Operating leverage is NIL (= 1) when:","options":["THERE ARE NO FIXED OPERATING COSTS (all costs variable), so EBIT moves in the same proportion as sales","The EBIT of the firm works out to zero","The sales of the firm are nil","The fixed costs of the firm are at their maximum"],"answer":0,"explanation":"Without fixed costs, contribution and EBIT move together; DOL = 1.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA269","number":269,"module":"M9","moduleTitle":"Leverages","question":"Operating leverage is NIL (= 1) when:","options":[{"key":"A","text":"THERE ARE NO FIXED OPERATING COSTS (all costs variable), so EBIT moves in the same proportion as sales"},{"key":"B","text":"The EBIT of the firm works out to zero"},{"key":"C","text":"The sales of the firm are nil"},{"key":"D","text":"The fixed costs of the firm are at their maximum"}],"answer":"A","explanation":"Without fixed costs, contribution and EBIT move together; DOL = 1.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Operating leverage is NIL (= 1) when:","options":["THERE ARE NO FIXED OPERATING COSTS (all costs variable), so EBIT moves in the same proportion as sales","EBIT is zero","Sales are zero","Fixed costs are maximum"],"answer":0,"explanation":"Without fixed costs, contribution and EBIT move together; DOL = 1.","revision":"original","contentSignature":"d036357445698f28ca74c5db6fad1a466f6f309623e0e67969af7d0cce756d1f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA269","optionFormat":"letter"},"contentSignature":"e5f5fdc330acd74eaab297a1d8eb51019b55e0e5e72ceeb57236d2c9723936de","kind":"mcq"},{"id":"deep-management-MA270","sourceNumber":270,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Which statement about leverage and risk is correct?","options":["HIGH OPERATING LEVERAGE SHOULD BE PAIRED WITH LOW FINANCIAL LEVERAGE (and vice versa) to keep total risk manageable","A high DOL combined with a high DFL is the safest position for the firm","Leverage removes the risks of the firm altogether","The risks of the firm are unaffected by its leverage"],"answer":0,"explanation":"Firms with high business risk should use less debt; combined leverage should stay within acceptable bounds.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA270","number":270,"module":"M9","moduleTitle":"Leverages","question":"Which statement about leverage and risk is correct?","options":[{"key":"A","text":"HIGH OPERATING LEVERAGE SHOULD BE PAIRED WITH LOW FINANCIAL LEVERAGE (and vice versa) to keep total risk manageable"},{"key":"B","text":"A high DOL combined with a high DFL is the safest position for the firm"},{"key":"C","text":"Leverage removes the risks of the firm altogether"},{"key":"D","text":"The risks of the firm are unaffected by its leverage"}],"answer":"A","explanation":"Firms with high business risk should use less debt; combined leverage should stay within acceptable bounds.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which statement about leverage and risk is correct?","options":["HIGH OPERATING LEVERAGE SHOULD BE PAIRED WITH LOW FINANCIAL LEVERAGE (and vice versa) to keep total risk manageable","High DOL + high DFL is safest","Leverage removes risk","Risk is unaffected"],"answer":0,"explanation":"Firms with high business risk should use less debt; combined leverage should stay within acceptable bounds.","revision":"original","contentSignature":"40183495843b435e6b24ebe8d852dfc3de6ea80a88cff0f01c617db0db9b69d5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA270","optionFormat":"letter"},"contentSignature":"416060e1aec18ae0c063d29ed54a56f1b381375506eeae6ab0b49c0a963cd0eb","kind":"mcq"},{"id":"deep-management-MA271","sourceNumber":271,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The INDIFFERENCE POINT in leverage analysis is the level of EBIT at which:","options":["The contribution of the firm works out to zero level","EPS is the SAME under alternative financial plans","The interest payable by the firm is zero","The EPS of the firm works out to zero"],"answer":1,"explanation":"It is the crossover EBIT where financing plans yield identical EPS - the pivot of EBIT-EPS analysis.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA271","number":271,"module":"M9","moduleTitle":"Leverages","question":"The INDIFFERENCE POINT in leverage analysis is the level of EBIT at which:","options":[{"key":"A","text":"The contribution of the firm works out to zero level"},{"key":"B","text":"EPS is the SAME under alternative financial plans"},{"key":"C","text":"The interest payable by the firm is zero"},{"key":"D","text":"The EPS of the firm works out to zero"}],"answer":"B","explanation":"It is the crossover EBIT where financing plans yield identical EPS - the pivot of EBIT-EPS analysis.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The INDIFFERENCE POINT in leverage analysis is the level of EBIT at which:","options":["Contribution is zero","EPS is the SAME under alternative financial plans","Interest is zero","EPS is zero"],"answer":1,"explanation":"It is the crossover EBIT where financing plans yield identical EPS - the pivot of EBIT-EPS analysis.","revision":"original","contentSignature":"26fb3dcb398fb5f70318f0a801d579197bd0ca5c521d4b180ca9fd7027362762"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA271","optionFormat":"letter"},"contentSignature":"487e0ac1611dfeecc49c10aef4720c09d3918ceb4d0c7da1ea9cd97977c3f72e","kind":"mcq"},{"id":"deep-management-MA272","sourceNumber":272,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The FINANCIAL BREAK-EVEN point is the EBIT at which:","options":["The DOL of the firm equals one","The EPS of the firm is at its maximum","The sales of the firm are at their maximum","EPS equals zero (EBIT just covers fixed financial charges: interest + preference dividend/(1-t))"],"answer":3,"explanation":"Financial BEP = interest + pref dividend/(1-t); below it EPS is negative, at it EPS = 0.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA272","number":272,"module":"M9","moduleTitle":"Leverages","question":"The FINANCIAL BREAK-EVEN point is the EBIT at which:","options":[{"key":"A","text":"The DOL of the firm equals one"},{"key":"B","text":"The EPS of the firm is at its maximum"},{"key":"C","text":"The sales of the firm are at their maximum"},{"key":"D","text":"EPS equals zero (EBIT just covers fixed financial charges: interest + preference dividend/(1-t))"}],"answer":"D","explanation":"Financial BEP = interest + pref dividend/(1-t); below it EPS is negative, at it EPS = 0.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The FINANCIAL BREAK-EVEN point is the EBIT at which:","options":["DOL = 1","EPS is maximum","Sales are maximum","EPS equals zero (EBIT just covers fixed financial charges: interest + preference dividend/(1-t))"],"answer":3,"explanation":"Financial BEP = interest + pref dividend/(1-t); below it EPS is negative, at it EPS = 0.","revision":"original","contentSignature":"af6a923aad09b9131c3d936a245972596c51cd18f3c3f5b5497963f24ed736cc"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA272","optionFormat":"letter"},"contentSignature":"d686df3529a89cf82a23e26439d85f4d20e2f68fafab88c9d4604fc4cc189662","kind":"mcq"},{"id":"deep-management-MA273","sourceNumber":273,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Given: Sales Rs.10,00,000; variable cost 60%; fixed cost Rs.2,00,000; interest Rs.50,000. DOL and DFL are:","options":["DOL 2; DFL 2","DOL 1.33; DFL 2","DOL 1.6; DFL 1.33","DOL 2; DFL 1.33"],"answer":3,"explanation":"Contribution = 4,00,000; EBIT = 4,00,000 - 2,00,000 = 2,00,000; EBT = 1,50,000. DOL = 4,00,000/2,00,000 = 2; DFL = 2,00,000/1,50,000 = 1.33.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA273","number":273,"module":"M9","moduleTitle":"Leverages","question":"Given: Sales Rs.10,00,000; variable cost 60%; fixed cost Rs.2,00,000; interest Rs.50,000. DOL and DFL are:","options":[{"key":"A","text":"DOL 2; DFL 2"},{"key":"B","text":"DOL 1.33; DFL 2"},{"key":"C","text":"DOL 1.6; DFL 1.33"},{"key":"D","text":"DOL 2; DFL 1.33"}],"answer":"D","explanation":"Contribution = 4,00,000; EBIT = 4,00,000 - 2,00,000 = 2,00,000; EBT = 1,50,000. DOL = 4,00,000/2,00,000 = 2; DFL = 2,00,000/1,50,000 = 1.33.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA273","optionFormat":"letter"},"contentSignature":"89b302a59d4e8173d0e91ed620dd93905aa98b7e5e784483d0564b6072064562","kind":"mcq"},{"id":"deep-management-MA274","sourceNumber":274,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"In the above data, DCL and the effect of a 20% sales rise on EPS are:","options":["DCL 1.33; EPS rises 26.6%","DCL 2; EPS rises 40%","DCL 3.33; EPS rises 66.6%","DCL 2.67; EPS rises 53.3%"],"answer":3,"explanation":"DCL = 4,00,000/1,50,000 = 2.67; EPS change = 2.67 x 20% = 53.3%.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA274","number":274,"module":"M9","moduleTitle":"Leverages","question":"In the above data, DCL and the effect of a 20% sales rise on EPS are:","options":[{"key":"A","text":"DCL 1.33; EPS rises 26.6%"},{"key":"B","text":"DCL 2; EPS rises 40%"},{"key":"C","text":"DCL 3.33; EPS rises 66.6%"},{"key":"D","text":"DCL 2.67; EPS rises 53.3%"}],"answer":"D","explanation":"DCL = 4,00,000/1,50,000 = 2.67; EPS change = 2.67 x 20% = 53.3%.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA274","optionFormat":"letter"},"contentSignature":"1e354d4dcf3f6c929f4bd40a6abe12de4d73efe8dd4e870563ec91802c12c116","kind":"mcq"},{"id":"deep-management-MA275","sourceNumber":275,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"If a firm has NO debt and NO preference capital, its DFL is:","options":["Two","Infinite","ONE (DFL = EBIT/EBT = 1, since EBIT = EBT)","Zero"],"answer":2,"explanation":"With no fixed financial charges, EBT = EBIT and financial leverage is absent.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA275","number":275,"module":"M9","moduleTitle":"Leverages","question":"If a firm has NO debt and NO preference capital, its DFL is:","options":[{"key":"A","text":"Two"},{"key":"B","text":"Infinite"},{"key":"C","text":"ONE (DFL = EBIT/EBT = 1, since EBIT = EBT)"},{"key":"D","text":"Zero"}],"answer":"C","explanation":"With no fixed financial charges, EBT = EBIT and financial leverage is absent.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If a firm has NO debt and NO preference capital, its DFL is:","options":["Two","Infinite","ONE (DFL = EBIT/EBT = 1, since EBIT = EBT)","Zero"],"answer":2,"explanation":"With no fixed financial charges, EBT = EBIT and financial leverage is absent.","revision":"original","contentSignature":"569b2bfd87800b73847478d866a198af65018f4679865165a9b8137fd66ac817"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA275","optionFormat":"letter"},"contentSignature":"569b2bfd87800b73847478d866a198af65018f4679865165a9b8137fd66ac817","kind":"mcq"},{"id":"deep-management-MA276","sourceNumber":276,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"EPS-based leverage plans are compared using:","options":["The payback periods of the two plans","The ROI of the two plans alone","The net return ratios of the two plans","The EBIT-EPS chart/indifference analysis - above the indifference EBIT the DEBT plan is preferable (higher EPS)"],"answer":3,"explanation":"Beyond the crossover, fixed-charge financing yields higher EPS; below it, equity financing is safer.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA276","number":276,"module":"M9","moduleTitle":"Leverages","question":"EPS-based leverage plans are compared using:","options":[{"key":"A","text":"The payback periods of the two plans"},{"key":"B","text":"The ROI of the two plans alone"},{"key":"C","text":"The net return ratios of the two plans"},{"key":"D","text":"The EBIT-EPS chart/indifference analysis - above the indifference EBIT the DEBT plan is preferable (higher EPS)"}],"answer":"D","explanation":"Beyond the crossover, fixed-charge financing yields higher EPS; below it, equity financing is safer.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"EPS-based leverage plans are compared using:","options":["Payback","ROI only","NRR","The EBIT-EPS chart/indifference analysis - above the indifference EBIT the DEBT plan is preferable (higher EPS)"],"answer":3,"explanation":"Beyond the crossover, fixed-charge financing yields higher EPS; below it, equity financing is safer.","revision":"original","contentSignature":"694683589f0fd154a6753b89023b3c446fa4ab68285df888b2dbcc1a41fd73a1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA276","optionFormat":"letter"},"contentSignature":"9ab97858be1b124bcc3a6b6052967c31f3a7071ba90aed1a79c49f8ca91b343e","kind":"mcq"},{"id":"deep-management-MA277","sourceNumber":277,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"The relationship: when ROI > cost of debt, EPS ________ with more debt:","options":["Stays flat at the same level, whatever the debt of the firm may be","Falls as the firm borrows more debt","Is zero always, whatever the debt of the firm may be","RISES (favourable financial leverage / positive trading on equity)"],"answer":3,"explanation":"Earning above the borrowing rate on borrowed funds adds the surplus to equity holders.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA277","number":277,"module":"M9","moduleTitle":"Leverages","question":"The relationship: when ROI > cost of debt, EPS ________ with more debt:","options":[{"key":"A","text":"Stays flat at the same level, whatever the debt of the firm may be"},{"key":"B","text":"Falls as the firm borrows more debt"},{"key":"C","text":"Is zero always, whatever the debt of the firm may be"},{"key":"D","text":"RISES (favourable financial leverage / positive trading on equity)"}],"answer":"D","explanation":"Earning above the borrowing rate on borrowed funds adds the surplus to equity holders.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The relationship: when ROI > cost of debt, EPS ________ with more debt:","options":["Stays flat","Falls","Is zero","RISES (favourable financial leverage / positive trading on equity)"],"answer":3,"explanation":"Earning above the borrowing rate on borrowed funds adds the surplus to equity holders.","revision":"original","contentSignature":"71104bc76ee440653291c111853d8cddfe0558704e3580175925ba3bfcd7df50"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA277","optionFormat":"letter"},"contentSignature":"bcfbdf86ae53596249bf23056d978861444deaeddd7cfe842e9240fb870d999c","kind":"mcq"},{"id":"deep-management-MA278","sourceNumber":278,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Operating leverage is computed from the:","options":["The cash flow statement of the firm, as the source of the computation","The fund flow statement of the firm, as the source of the computation","Income statement (cost structure: fixed vs variable operating costs)","The balance sheet of the firm only, as the source of the computation"],"answer":2,"explanation":"DOL uses contribution and EBIT from the income statement.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA278","number":278,"module":"M9","moduleTitle":"Leverages","question":"Operating leverage is computed from the:","options":[{"key":"A","text":"The cash flow statement of the firm, as the source of the computation"},{"key":"B","text":"The fund flow statement of the firm, as the source of the computation"},{"key":"C","text":"Income statement (cost structure: fixed vs variable operating costs)"},{"key":"D","text":"The balance sheet of the firm only, as the source of the computation"}],"answer":"C","explanation":"DOL uses contribution and EBIT from the income statement.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Operating leverage is computed from the:","options":["Cash flow statement","Fund flow","Income statement (cost structure: fixed vs variable operating costs)","Balance sheet only"],"answer":2,"explanation":"DOL uses contribution and EBIT from the income statement.","revision":"original","contentSignature":"83b75ba3b80d6635ac3833b70460115b4c4399b9c9f91e44b830ac1980b60985"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA278","optionFormat":"letter"},"contentSignature":"931bfc13474a3be5fed930968db4f0d0e954b127a41a38555912c84d8e9a25a4","kind":"mcq"},{"id":"deep-management-MA279","sourceNumber":279,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"Which is TRUE of combined leverage?","options":["It reflects only the debt content of the capital structure of the concern","It equals the DOL minus the DFL of the firm","It multiplies business and financial risk - the total risk of the firm","It ignores the fixed costs of the firm altogether"],"answer":2,"explanation":"DCL = DOL x DFL captures the total sensitivity of EPS to sales - the combined effect of operating and financial risk.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA279","number":279,"module":"M9","moduleTitle":"Leverages","question":"Which is TRUE of combined leverage?","options":[{"key":"A","text":"It reflects only the debt content of the capital structure of the concern"},{"key":"B","text":"It equals the DOL minus the DFL of the firm"},{"key":"C","text":"It multiplies business and financial risk - the total risk of the firm"},{"key":"D","text":"It ignores the fixed costs of the firm altogether"}],"answer":"C","explanation":"DCL = DOL x DFL captures the total sensitivity of EPS to sales - the combined effect of operating and financial risk.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is TRUE of combined leverage?","options":["It only reflects debt","It equals DOL minus DFL","It multiplies business and financial risk - the total risk of the firm","It ignores fixed costs"],"answer":2,"explanation":"DCL = DOL x DFL captures the total sensitivity of EPS to sales - the combined effect of operating and financial risk.","revision":"original","contentSignature":"a2ffff6bcd18e5b835a63fe3f8b9981cf317a80e1770d7348722dc8b127532f8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA279","optionFormat":"letter"},"contentSignature":"9fccb6e8bafd1f096fc9a3cdcf8d13d83ed634420e49a549e373772676dea875","kind":"mcq"},{"id":"deep-management-MA280","sourceNumber":280,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M9 · Leverages","question":"A firm with high DFL has:","options":["No interest at all in the structure of the capital of the firm","A LARGE PROPORTION OF DEBT/fixed-charge funds - high FINANCIAL RISK","A low level of EBIT in relation to its size and its turnover in the year","High fixed operating costs in its business"],"answer":1,"explanation":"High debt means small EBIT swings cause large EPS swings, and insolvency risk is higher.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA280","number":280,"module":"M9","moduleTitle":"Leverages","question":"A firm with high DFL has:","options":[{"key":"A","text":"No interest at all in the structure of the capital of the firm"},{"key":"B","text":"A LARGE PROPORTION OF DEBT/fixed-charge funds - high FINANCIAL RISK"},{"key":"C","text":"A low level of EBIT in relation to its size and its turnover in the year"},{"key":"D","text":"High fixed operating costs in its business"}],"answer":"B","explanation":"High debt means small EBIT swings cause large EPS swings, and insolvency risk is higher.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A firm with high DFL has:","options":["No interest","A LARGE PROPORTION OF DEBT/fixed-charge funds - high FINANCIAL RISK","Low EBIT","High fixed operating costs"],"answer":1,"explanation":"High debt means small EBIT swings cause large EPS swings, and insolvency risk is higher.","revision":"original","contentSignature":"e98694b3819002677c7b99f61521a73751d20fbf58d2e422f8ab3d6ad6fe5274"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA280","optionFormat":"letter"},"contentSignature":"1d5ea28f8cc747804d236d9eac0719ee17c60cb1632181e58f6f2c21ad0ca695","kind":"mcq"},{"id":"deep-management-MA281","sourceNumber":281,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"WORKING CAPITAL means:","options":["The reserves of the company, built out of the profits of the earlier years of the business, as the working capital","The capital invested in CURRENT ASSETS (gross working capital); net working capital = CURRENT ASSETS - CURRENT LIABILITIES","The fixed capital of the company, invested in the fixed assets of the business, as the working capital","The share capital of the company, contributed by the shareholders of the company, as the working capital"],"answer":1,"explanation":"Gross WC = total current assets; net WC = CA - CL. Management focus is on both.","source":"PYQ: NABARD Grade A, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA281","number":281,"module":"M10","moduleTitle":"Working Capital Management","question":"WORKING CAPITAL means:","options":[{"key":"A","text":"The reserves of the company, built out of the profits of the earlier years of the business, as the working capital"},{"key":"B","text":"The capital invested in CURRENT ASSETS (gross working capital); net working capital = CURRENT ASSETS - CURRENT LIABILITIES"},{"key":"C","text":"The fixed capital of the company, invested in the fixed assets of the business, as the working capital"},{"key":"D","text":"The share capital of the company, contributed by the shareholders of the company, as the working capital"}],"answer":"B","explanation":"Gross WC = total current assets; net WC = CA - CL. Management focus is on both.","source":"PYQ: NABARD Grade A, 2020","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"WORKING CAPITAL means:","options":["Reserves","The capital invested in CURRENT ASSETS (gross working capital); net working capital = CURRENT ASSETS - CURRENT LIABILITIES","Fixed capital","Share capital"],"answer":1,"explanation":"Gross WC = total current assets; net WC = CA - CL. Management focus is on both.","revision":"original","contentSignature":"ef18664d0f6ed7f824219fa6ac9a1ab27dab5921d3e3b25387231795e6f1f38e"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA281","optionFormat":"letter"},"contentSignature":"fe6326373dbb77caf246d645f6d0fad653b0ffdfb34ce984aa77fd11dcd3a827","kind":"pyq"},{"id":"deep-management-MA282","sourceNumber":282,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"NET WORKING CAPITAL =","options":["CURRENT ASSETS MINUS CURRENT LIABILITIES","The capital plus the reserves of the company, as computed","Only the cash of the business, in hand and at bank","The total assets minus the fixed assets of the company"],"answer":0,"explanation":"Net WC measures the cushion of short-term assets over short-term obligations - a liquidity indicator.","source":"PYQ: NABARD Grade A, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA282","number":282,"module":"M10","moduleTitle":"Working Capital Management","question":"NET WORKING CAPITAL =","options":[{"key":"A","text":"CURRENT ASSETS MINUS CURRENT LIABILITIES"},{"key":"B","text":"The capital plus the reserves of the company, as computed"},{"key":"C","text":"Only the cash of the business, in hand and at bank"},{"key":"D","text":"The total assets minus the fixed assets of the company"}],"answer":"A","explanation":"Net WC measures the cushion of short-term assets over short-term obligations - a liquidity indicator.","source":"PYQ: NABARD Grade A, 2020","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"NET WORKING CAPITAL =","options":["CURRENT ASSETS MINUS CURRENT LIABILITIES","Capital + reserves","Cash only","Total assets - fixed assets"],"answer":0,"explanation":"Net WC measures the cushion of short-term assets over short-term obligations - a liquidity indicator.","revision":"original","contentSignature":"5c2e58f48707507d321e07e76a9700187ebfb6b51fa2a38f94b23574a35ccc4a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA282","optionFormat":"letter"},"contentSignature":"bfb6c87c11e24e7859e376be516940f951bcaa2f1342169353d63fce4b559231","kind":"pyq"},{"id":"deep-management-MA283","sourceNumber":283,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"PERMANENT (fixed/core) working capital is:","options":["The seasonal working capital of the business, rising and falling with the season of the trade","Zero working capital at all times, since the operations need no current assets at all","The MINIMUM level of current assets needed at all times to keep operations going (financed from long-term sources)","The working capital that fluctuates with the special demands of the trade, year by year"],"answer":2,"explanation":"Core current assets (minimum inventory, receivables, cash) must be carried year-round; they are semi-fixed in nature.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA283","number":283,"module":"M10","moduleTitle":"Working Capital Management","question":"PERMANENT (fixed/core) working capital is:","options":[{"key":"A","text":"The seasonal working capital of the business, rising and falling with the season of the trade"},{"key":"B","text":"Zero working capital at all times, since the operations need no current assets at all"},{"key":"C","text":"The MINIMUM level of current assets needed at all times to keep operations going (financed from long-term sources)"},{"key":"D","text":"The working capital that fluctuates with the special demands of the trade, year by year"}],"answer":"C","explanation":"Core current assets (minimum inventory, receivables, cash) must be carried year-round; they are semi-fixed in nature.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"PERMANENT (fixed/core) working capital is:","options":["Seasonal WC","Zero WC","The MINIMUM level of current assets needed at all times to keep operations going (financed from long-term sources)","WC that fluctuates"],"answer":2,"explanation":"Core current assets (minimum inventory, receivables, cash) must be carried year-round; they are semi-fixed in nature.","revision":"original","contentSignature":"5f0de8027a2548ed0f4726d0cbefb106ab2dc29233a25005e20e3b06efcb59d6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA283","optionFormat":"letter"},"contentSignature":"d73e1820dbb109073e43f6ca053ae79f0d2c8165bab14f354243f2c326bf5902","kind":"mcq"},{"id":"deep-management-MA284","sourceNumber":284,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"TEMPORARY (variable/fluctuating) working capital:","options":["Is financed by the equity of the company only, and by no other source at all whatever","Is constant at the same level at all times, whatever the season of the trade may be","Is negative at all times, whatever the season of the trade of the business may be","Varies with SEASONAL or special demands - the extra current assets needed over the permanent level"],"answer":3,"explanation":"Temporary WC rises in peak season and falls in slack; it is best financed by short-term sources.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA284","number":284,"module":"M10","moduleTitle":"Working Capital Management","question":"TEMPORARY (variable/fluctuating) working capital:","options":[{"key":"A","text":"Is financed by the equity of the company only, and by no other source at all whatever"},{"key":"B","text":"Is constant at the same level at all times, whatever the season of the trade may be"},{"key":"C","text":"Is negative at all times, whatever the season of the trade of the business may be"},{"key":"D","text":"Varies with SEASONAL or special demands - the extra current assets needed over the permanent level"}],"answer":"D","explanation":"Temporary WC rises in peak season and falls in slack; it is best financed by short-term sources.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"TEMPORARY (variable/fluctuating) working capital:","options":["Is financed by equity only","Is constant","Is negative","Varies with SEASONAL or special demands - the extra current assets needed over the permanent level"],"answer":3,"explanation":"Temporary WC rises in peak season and falls in slack; it is best financed by short-term sources.","revision":"original","contentSignature":"30481994b287ad48269cc754a5945bbc3965b93a35b45a750bd1ebf7495bb3f6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA284","optionFormat":"letter"},"contentSignature":"762fd551e7311d07feb76d1ebf9d0a9bb58cb79b8ff49e67e28cd58f1461c91d","kind":"mcq"},{"id":"deep-management-MA285","sourceNumber":285,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The OPERATING (working capital) CYCLE is:","options":["The TIME between acquisition of raw material and COLLECTION OF CASH from sale of finished goods (RM period + WIP + FG + receivables - creditors period)","The accounting period of the business, as fixed by the management for its accounts, whatever the operations of the business may be at all","One year fixed for every business, whatever the nature of its operations and its trade cycle may be at all in the year","The credit period allowed to the customers of the business alone, ignoring the time spent on production, storage and collection of the sale proceeds from the debtors"],"answer":0,"explanation":"Operating cycle = inventory conversion period + receivables collection period - payables deferral period; longer cycle = more WC needed.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA285","number":285,"module":"M10","moduleTitle":"Working Capital Management","question":"The OPERATING (working capital) CYCLE is:","options":[{"key":"A","text":"The TIME between acquisition of raw material and COLLECTION OF CASH from sale of finished goods (RM period + WIP + FG + receivables - creditors period)"},{"key":"B","text":"The accounting period of the business, as fixed by the management for its accounts, whatever the operations of the business may be at all"},{"key":"C","text":"One year fixed for every business, whatever the nature of its operations and its trade cycle may be at all in the year"},{"key":"D","text":"The credit period allowed to the customers of the business alone, ignoring the time spent on production, storage and collection of the sale proceeds from the debtors"}],"answer":"A","explanation":"Operating cycle = inventory conversion period + receivables collection period - payables deferral period; longer cycle = more WC needed.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The OPERATING (working capital) CYCLE is:","options":["The TIME between acquisition of raw material and COLLECTION OF CASH from sale of finished goods (RM period + WIP + FG + receivables - creditors period)","The accounting period","One year fixed","The credit period only"],"answer":0,"explanation":"Operating cycle = inventory conversion period + receivables collection period - payables deferral period; longer cycle = more WC needed.","revision":"original","contentSignature":"7ad5cda7d649dae2a6d06f5ac03a04d6bca671fe8d78b8eb01200ffaa8c12c28"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA285","optionFormat":"letter"},"contentSignature":"8c99fcd3a4d5a1f378ad6454ed64e37d0871c25fc88b75356baff363b2611d18","kind":"mcq"},{"id":"deep-management-MA286","sourceNumber":286,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The LENGTH of the operating cycle and working capital needs are:","options":["Equal always, whatever the length of the cycle of the business may be in the year","Inversely related, so that a longer cycle needs less funds of the business","Unrelated to each other, whatever the length of the cycle of the business may be","DIRECTLY related - a longer cycle locks up more funds in inventories and receivables"],"answer":3,"explanation":"More days blocked in each stage means a larger working capital investment.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA286","number":286,"module":"M10","moduleTitle":"Working Capital Management","question":"The LENGTH of the operating cycle and working capital needs are:","options":[{"key":"A","text":"Equal always, whatever the length of the cycle of the business may be in the year"},{"key":"B","text":"Inversely related, so that a longer cycle needs less funds of the business"},{"key":"C","text":"Unrelated to each other, whatever the length of the cycle of the business may be"},{"key":"D","text":"DIRECTLY related - a longer cycle locks up more funds in inventories and receivables"}],"answer":"D","explanation":"More days blocked in each stage means a larger working capital investment.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The LENGTH of the operating cycle and working capital needs are:","options":["Equal","Inversely related","Unrelated","DIRECTLY related - a longer cycle locks up more funds in inventories and receivables"],"answer":3,"explanation":"More days blocked in each stage means a larger working capital investment.","revision":"original","contentSignature":"1747f6e6c7dff3f18c8a3c31dea39e10732caa4710b3c8ea84e91823a23ebb9d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA286","optionFormat":"letter"},"contentSignature":"117f9dd458addee74d892f4f7c28a36a3d26307e7ee5cae4de9b7fe75df1b260","kind":"mcq"},{"id":"deep-management-MA287","sourceNumber":287,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"FACTORS determining working capital needs include all EXCEPT:","options":["Seasonal fluctuations and production policy","Nature of business (trading vs manufacturing vs service)","PAID-UP SHARE CAPITAL","Credit policy and availability of raw materials"],"answer":2,"explanation":"Determinants: nature/size of business, production cycle, seasonal swings, credit terms, growth, price changes, dividend policy - not the paid-up capital figure.","source":"PYQ: UGC NET Commerce, 2023-Mar-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA287","number":287,"module":"M10","moduleTitle":"Working Capital Management","question":"FACTORS determining working capital needs include all EXCEPT:","options":[{"key":"A","text":"Seasonal fluctuations and production policy"},{"key":"B","text":"Nature of business (trading vs manufacturing vs service)"},{"key":"C","text":"PAID-UP SHARE CAPITAL"},{"key":"D","text":"Credit policy and availability of raw materials"}],"answer":"C","explanation":"Determinants: nature/size of business, production cycle, seasonal swings, credit terms, growth, price changes, dividend policy - not the paid-up capital figure.","source":"PYQ: UGC NET Commerce, 2023-Mar-M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA287","optionFormat":"letter"},"contentSignature":"13cb921949ddfcb5d0fe32002b522408d905bf1d9753eb459755422de002b638","kind":"pyq"},{"id":"deep-management-MA288","sourceNumber":288,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"A MANUFACTURING concern generally needs MORE working capital than a TRADING concern because:","options":["Its operating cycle includes RAW MATERIAL, WORK-IN-PROCESS AND FINISHED GOODS stages","It pays more tax than a trading concern pays","It is bigger in size than a trading concern","It carries more debt than a trading concern"],"answer":0,"explanation":"Manufacturing lengthens the conversion cycle with WIP; trading holds only finished stock.","source":"PYQ: UGC NET Commerce, 2023-Mar-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA288","number":288,"module":"M10","moduleTitle":"Working Capital Management","question":"A MANUFACTURING concern generally needs MORE working capital than a TRADING concern because:","options":[{"key":"A","text":"Its operating cycle includes RAW MATERIAL, WORK-IN-PROCESS AND FINISHED GOODS stages"},{"key":"B","text":"It pays more tax than a trading concern pays"},{"key":"C","text":"It is bigger in size than a trading concern"},{"key":"D","text":"It carries more debt than a trading concern"}],"answer":"A","explanation":"Manufacturing lengthens the conversion cycle with WIP; trading holds only finished stock.","source":"PYQ: UGC NET Commerce, 2023-Mar-M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A MANUFACTURING concern generally needs MORE working capital than a TRADING concern because:","options":["Its operating cycle includes RAW MATERIAL, WORK-IN-PROCESS AND FINISHED GOODS stages","It pays more tax","It is bigger","It has more debt"],"answer":0,"explanation":"Manufacturing lengthens the conversion cycle with WIP; trading holds only finished stock.","revision":"original","contentSignature":"c7ad0dcc216cc20acf6e3be2b0d1793375eb362a242811b572291c2846e1a6de"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA288","optionFormat":"letter"},"contentSignature":"ff837c3dd92c3e696f77469d97cc1af36ba4a18985db7d3eccd299fc01af2bc5","kind":"pyq"},{"id":"deep-management-MA289","sourceNumber":289,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The MATCHING (hedging) approach to financing working capital says:","options":["Use only the equity of the company to finance the working capital","Use only the creditors of the business to finance the working capital","Finance the whole of the working capital with short-term debt","MATCH the LIFE of the asset with the MATURITY of the financing - permanent WC from long-term funds, temporary WC from short-term funds"],"answer":3,"explanation":"Maturity matching balances risk and return; it is the moderate course between conservative and aggressive approaches.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA289","number":289,"module":"M10","moduleTitle":"Working Capital Management","question":"The MATCHING (hedging) approach to financing working capital says:","options":[{"key":"A","text":"Use only the equity of the company to finance the working capital"},{"key":"B","text":"Use only the creditors of the business to finance the working capital"},{"key":"C","text":"Finance the whole of the working capital with short-term debt"},{"key":"D","text":"MATCH the LIFE of the asset with the MATURITY of the financing - permanent WC from long-term funds, temporary WC from short-term funds"}],"answer":"D","explanation":"Maturity matching balances risk and return; it is the moderate course between conservative and aggressive approaches.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MATCHING (hedging) approach to financing working capital says:","options":["Use only equity","Use only creditors","Finance everything with short-term debt","MATCH the LIFE of the asset with the MATURITY of the financing - permanent WC from long-term funds, temporary WC from short-term funds"],"answer":3,"explanation":"Maturity matching balances risk and return; it is the moderate course between conservative and aggressive approaches.","revision":"original","contentSignature":"145bb2ef6edd3c6dd6f76be6e357528e832ffe69f219653094ee8ec3234c9af9"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA289","optionFormat":"letter"},"contentSignature":"ced488826382cc9dafead1cb5c19d627fd620c6a93acb08a98075c0c4c9e9d73","kind":"pyq"},{"id":"deep-management-MA290","sourceNumber":290,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Under the CONSERVATIVE approach to WC financing:","options":["LONG-TERM funds finance permanent WC, fixed assets AND PART OF temporary WC - low risk, low return","No reserves are kept by the firm at all, whatever the needs of the business may be","Only the short-term debt of the business is used to finance the working capital","The creditors of the business finance the whole of the working capital, both permanent and temporary, throughout the year"],"answer":0,"explanation":"Conservative policy keeps high liquidity cushions and relies on long-term money even for some seasonal needs.","source":"PYQ: UGC NET Commerce, 2025-Dec · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA290","number":290,"module":"M10","moduleTitle":"Working Capital Management","question":"Under the CONSERVATIVE approach to WC financing:","options":[{"key":"A","text":"LONG-TERM funds finance permanent WC, fixed assets AND PART OF temporary WC - low risk, low return"},{"key":"B","text":"No reserves are kept by the firm at all, whatever the needs of the business may be"},{"key":"C","text":"Only the short-term debt of the business is used to finance the working capital"},{"key":"D","text":"The creditors of the business finance the whole of the working capital, both permanent and temporary, throughout the year"}],"answer":"A","explanation":"Conservative policy keeps high liquidity cushions and relies on long-term money even for some seasonal needs.","source":"PYQ: UGC NET Commerce, 2025-Dec","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the CONSERVATIVE approach to WC financing:","options":["LONG-TERM funds finance permanent WC, fixed assets AND PART OF temporary WC - low risk, low return","No reserves are kept","Only short-term debt is used","Creditors finance all"],"answer":0,"explanation":"Conservative policy keeps high liquidity cushions and relies on long-term money even for some seasonal needs.","revision":"original","contentSignature":"f0f1279d235cd6b046138be55d1eaf3d84e53e8f0ac9a4091e656e959fcff13d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA290","optionFormat":"letter"},"contentSignature":"ece64be433c4fc62ba4d674017aeb397becc7b7b212235aa3976673bf9d6895d","kind":"pyq"},{"id":"deep-management-MA291","sourceNumber":291,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Under the AGGRESSIVE approach to WC financing:","options":["The long-term funds finance the whole of the working capital","The cash balance of the business is kept high at all times","SHORT-TERM funds finance temporary WC AND PART OF PERMANENT WC - higher return but higher risk of renewal/default","The equity of the company is avoided altogether"],"answer":2,"explanation":"Aggressive policy rolls short-term credit into permanent needs: cheaper, but refinancing and liquidity risk is high.","source":"PYQ: UGC NET Commerce, 2025-Dec · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA291","number":291,"module":"M10","moduleTitle":"Working Capital Management","question":"Under the AGGRESSIVE approach to WC financing:","options":[{"key":"A","text":"The long-term funds finance the whole of the working capital"},{"key":"B","text":"The cash balance of the business is kept high at all times"},{"key":"C","text":"SHORT-TERM funds finance temporary WC AND PART OF PERMANENT WC - higher return but higher risk of renewal/default"},{"key":"D","text":"The equity of the company is avoided altogether"}],"answer":"C","explanation":"Aggressive policy rolls short-term credit into permanent needs: cheaper, but refinancing and liquidity risk is high.","source":"PYQ: UGC NET Commerce, 2025-Dec","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the AGGRESSIVE approach to WC financing:","options":["Long-term funds finance everything","Cash is high","SHORT-TERM funds finance temporary WC AND PART OF PERMANENT WC - higher return but higher risk of renewal/default","Equity is avoided"],"answer":2,"explanation":"Aggressive policy rolls short-term credit into permanent needs: cheaper, but refinancing and liquidity risk is high.","revision":"original","contentSignature":"3c729c53e523694654307a07bac162939354e1fc8c45be3919bc83ec31326f40"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA291","optionFormat":"letter"},"contentSignature":"05d1ebfeb5e1cd96f72aa7768be90e728cb353425825b3ac101127935f191db9","kind":"pyq"},{"id":"deep-management-MA292","sourceNumber":292,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"EXCESS working capital leads to:","options":["The insolvency of the business as its certain result","A higher turnover of the business as its certain result","IDLE funds earning nothing, unnecessary inventory accumulation, slack credit policy and speculative tendencies","Stagnation in the growth of the business alone"],"answer":2,"explanation":"Too much WC breeds inefficiency and waste; too little causes stagnation and insolvency - both extremes are harmful.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA292","number":292,"module":"M10","moduleTitle":"Working Capital Management","question":"EXCESS working capital leads to:","options":[{"key":"A","text":"The insolvency of the business as its certain result"},{"key":"B","text":"A higher turnover of the business as its certain result"},{"key":"C","text":"IDLE funds earning nothing, unnecessary inventory accumulation, slack credit policy and speculative tendencies"},{"key":"D","text":"Stagnation in the growth of the business alone"}],"answer":"C","explanation":"Too much WC breeds inefficiency and waste; too little causes stagnation and insolvency - both extremes are harmful.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"EXCESS working capital leads to:","options":["Insolvency","Higher turnover","IDLE funds earning nothing, unnecessary inventory accumulation, slack credit policy and speculative tendencies","Stagnant growth only"],"answer":2,"explanation":"Too much WC breeds inefficiency and waste; too little causes stagnation and insolvency - both extremes are harmful.","revision":"original","contentSignature":"8bd3cc2d392d8cec5a945ca8dfd7dc90d1dbdaa883eadc0fe0d805c592da72e3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA292","optionFormat":"letter"},"contentSignature":"9b9f71f99fd137a3559912b36f0b6531fc945975ac53a22d36b5507ee59ba26c","kind":"mcq"},{"id":"deep-management-MA293","sourceNumber":293,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"INADEQUATE working capital causes:","options":["High dividends for the shareholders as its certain result","STAGNANT GROWTH, inability to avail discounts, loss of credit reputation, and risk of INSOLVENCY","Excess liquidity of the business as its certain result","Excessive stocks of the business as its certain result"],"answer":1,"explanation":"Shortage starves operations: missed discounts, broken production schedules and damaged credit standing.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA293","number":293,"module":"M10","moduleTitle":"Working Capital Management","question":"INADEQUATE working capital causes:","options":[{"key":"A","text":"High dividends for the shareholders as its certain result"},{"key":"B","text":"STAGNANT GROWTH, inability to avail discounts, loss of credit reputation, and risk of INSOLVENCY"},{"key":"C","text":"Excess liquidity of the business as its certain result"},{"key":"D","text":"Excessive stocks of the business as its certain result"}],"answer":"B","explanation":"Shortage starves operations: missed discounts, broken production schedules and damaged credit standing.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"INADEQUATE working capital causes:","options":["High dividends","STAGNANT GROWTH, inability to avail discounts, loss of credit reputation, and risk of INSOLVENCY","Excess liquidity","Excess stock"],"answer":1,"explanation":"Shortage starves operations: missed discounts, broken production schedules and damaged credit standing.","revision":"original","contentSignature":"c23f73c323df718299b5a27e2c48b753771093afcf4d9317d0cfd33651d1d258"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA293","optionFormat":"letter"},"contentSignature":"4cc32c6a902940bfa2b6453dde4c8b4b4aa7a976b26bf553c9d24e00bdf526e3","kind":"mcq"},{"id":"deep-management-MA294","sourceNumber":294,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"A WORKING CAPITAL SCHEDULE (statement of changes in WC) is prepared to estimate needs by:","options":["Estimating EACH CURRENT ASSET and CURRENT LIABILITY (at the holding-period basis) and finding the difference - the WC requirement","Only the cash of the business, in hand and at bank","Only the profit of the year shown by the accounts","The trial balance extracted from the books"],"answer":0,"explanation":"The projection schedules inventories, receivables, cash against creditors and accruals for the budget period; the gap is the WC need.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA294","number":294,"module":"M10","moduleTitle":"Working Capital Management","question":"A WORKING CAPITAL SCHEDULE (statement of changes in WC) is prepared to estimate needs by:","options":[{"key":"A","text":"Estimating EACH CURRENT ASSET and CURRENT LIABILITY (at the holding-period basis) and finding the difference - the WC requirement"},{"key":"B","text":"Only the cash of the business, in hand and at bank"},{"key":"C","text":"Only the profit of the year shown by the accounts"},{"key":"D","text":"The trial balance extracted from the books"}],"answer":"A","explanation":"The projection schedules inventories, receivables, cash against creditors and accruals for the budget period; the gap is the WC need.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A WORKING CAPITAL SCHEDULE (statement of changes in WC) is prepared to estimate needs by:","options":["Estimating EACH CURRENT ASSET and CURRENT LIABILITY (at the holding-period basis) and finding the difference - the WC requirement","Cash only","Profit only","Trial balance"],"answer":0,"explanation":"The projection schedules inventories, receivables, cash against creditors and accruals for the budget period; the gap is the WC need.","revision":"original","contentSignature":"3db1d8f99d15f121986a15e4e1e75808925e1512b5d70aedd669d1c7dd9b3624"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA294","optionFormat":"letter"},"contentSignature":"2cf02da73b0df79aff8699d03c706ae6e0c5515f478caae22a1d132dcd17bbcd","kind":"pyq"},{"id":"deep-management-MA295","sourceNumber":295,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"In estimating working capital, PROFIT is normally EXCLUDED from the WC computation because:","options":["Profit is IGNORED unless specifically stated - WC estimation is done at COST level (profit margin is not part of the funds blocked)","Depreciation is a cash expense of the year blocking the funds, so it is deducted again from the profit in the working capital computation","The profit is not a cash item of the year, so the funds are never generated by it at all in the estimation","Profit doubles the working capital required by the business"],"answer":0,"explanation":"Standard convention: current assets are valued at cost; profit is not included unless the question says selling price basis.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA295","number":295,"module":"M10","moduleTitle":"Working Capital Management","question":"In estimating working capital, PROFIT is normally EXCLUDED from the WC computation because:","options":[{"key":"A","text":"Profit is IGNORED unless specifically stated - WC estimation is done at COST level (profit margin is not part of the funds blocked)"},{"key":"B","text":"Depreciation is a cash expense of the year blocking the funds, so it is deducted again from the profit in the working capital computation"},{"key":"C","text":"The profit is not a cash item of the year, so the funds are never generated by it at all in the estimation"},{"key":"D","text":"Profit doubles the working capital required by the business"}],"answer":"A","explanation":"Standard convention: current assets are valued at cost; profit is not included unless the question says selling price basis.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In estimating working capital, PROFIT is normally EXCLUDED from the WC computation because:","options":["Profit is IGNORED unless specifically stated - WC estimation is done at COST level (profit margin is not part of the funds blocked)","Depreciation is cash","Profit is not cash","Profit doubles WC"],"answer":0,"explanation":"Standard convention: current assets are valued at cost; profit is not included unless the question says selling price basis.","revision":"original","contentSignature":"5791fc44fe52598c70f596dd979dcef414b99b52d5964e9400d7a6e008661f37"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA295","optionFormat":"letter"},"contentSignature":"4e2d33a82aaa9c5369e6999e7b7626991f2c94321537736f23c861baa5d0d39f","kind":"pyq"},{"id":"deep-management-MA296","sourceNumber":296,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"In a WC estimation, the CREDITORS period (payment lag) is:","options":["Multiplied into the requirement, so that the need rises with the creditors period","DEDUCTED - creditors finance part of the operating cycle, reducing the net WC requirement","Ignored altogether in the estimation","Added to the working capital requirement of the business for the whole year under computation"],"answer":1,"explanation":"Raw-material credit from suppliers offsets the inventory-holding block.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA296","number":296,"module":"M10","moduleTitle":"Working Capital Management","question":"In a WC estimation, the CREDITORS period (payment lag) is:","options":[{"key":"A","text":"Multiplied into the requirement, so that the need rises with the creditors period"},{"key":"B","text":"DEDUCTED - creditors finance part of the operating cycle, reducing the net WC requirement"},{"key":"C","text":"Ignored altogether in the estimation"},{"key":"D","text":"Added to the working capital requirement of the business for the whole year under computation"}],"answer":"B","explanation":"Raw-material credit from suppliers offsets the inventory-holding block.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In a WC estimation, the CREDITORS period (payment lag) is:","options":["Multiplied","DEDUCTED - creditors finance part of the operating cycle, reducing the net WC requirement","Ignored","Added to WC need"],"answer":1,"explanation":"Raw-material credit from suppliers offsets the inventory-holding block.","revision":"original","contentSignature":"75a3ce202a0551a42069080d2d4c7547edc42d55e56d3f1d610e61abd4725938"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA296","optionFormat":"letter"},"contentSignature":"069928163f1aa9f5ed2066331a24d60ce4068bb930b09475239cbc46b9737d65","kind":"pyq"},{"id":"deep-management-MA297","sourceNumber":297,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"RECEIVABLES in WC estimation are usually taken at:","options":["COST (cash cost) of sales - unless the question directs selling price","Zero always, since the receivables are not yet collected at all","The scrap value of the receivables standing in the books at the year end","The selling price of the goods"],"answer":0,"explanation":"Funds actually blocked in debtors equal the cost of goods sold on credit, not the profit element.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA297","number":297,"module":"M10","moduleTitle":"Working Capital Management","question":"RECEIVABLES in WC estimation are usually taken at:","options":[{"key":"A","text":"COST (cash cost) of sales - unless the question directs selling price"},{"key":"B","text":"Zero always, since the receivables are not yet collected at all"},{"key":"C","text":"The scrap value of the receivables standing in the books at the year end"},{"key":"D","text":"The selling price of the goods"}],"answer":"A","explanation":"Funds actually blocked in debtors equal the cost of goods sold on credit, not the profit element.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RECEIVABLES in WC estimation are usually taken at:","options":["COST (cash cost) of sales - unless the question directs selling price","Zero","Scrap value","Selling price"],"answer":0,"explanation":"Funds actually blocked in debtors equal the cost of goods sold on credit, not the profit element.","revision":"original","contentSignature":"ad6a07342d6867abc360960c1c6596d845136288afdd49cfe64e6b66dfa61232"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA297","optionFormat":"letter"},"contentSignature":"cdd0ad6aa5660d639ee2bd1c6411d1c7bb89e14aea4986b270fd2510f4ad77fc","kind":"pyq"},{"id":"deep-management-MA298","sourceNumber":298,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"A firm estimates annual COGS of Rs.36,00,000 and wants 2 months of finished-goods stock. The FG stock investment is:","options":["Rs.18,00,000","Rs.6,00,000","Rs.72,00,000","Rs.3,00,000"],"answer":1,"explanation":"36,00,000 x 2/12 = Rs.6,00,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA298","number":298,"module":"M10","moduleTitle":"Working Capital Management","question":"A firm estimates annual COGS of Rs.36,00,000 and wants 2 months of finished-goods stock. The FG stock investment is:","options":[{"key":"A","text":"Rs.18,00,000"},{"key":"B","text":"Rs.6,00,000"},{"key":"C","text":"Rs.72,00,000"},{"key":"D","text":"Rs.3,00,000"}],"answer":"B","explanation":"36,00,000 x 2/12 = Rs.6,00,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA298","optionFormat":"letter"},"contentSignature":"bbb6318a524df4253a273558196b153fa26ba43aeab72584405337687501afb3","kind":"mcq"},{"id":"deep-management-MA299","sourceNumber":299,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Annual credit purchases Rs.24,00,000; payment period 1.5 months. Creditors deducted in the WC schedule:","options":["Rs.6,00,000","Rs.3,00,000","Rs.2,00,000","Rs.4,00,000"],"answer":1,"explanation":"24,00,000 x 1.5/12 = Rs.3,00,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA299","number":299,"module":"M10","moduleTitle":"Working Capital Management","question":"Annual credit purchases Rs.24,00,000; payment period 1.5 months. Creditors deducted in the WC schedule:","options":[{"key":"A","text":"Rs.6,00,000"},{"key":"B","text":"Rs.3,00,000"},{"key":"C","text":"Rs.2,00,000"},{"key":"D","text":"Rs.4,00,000"}],"answer":"B","explanation":"24,00,000 x 1.5/12 = Rs.3,00,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA299","optionFormat":"letter"},"contentSignature":"25a815095ae2629ca0cb2265dd74062e9578229a259c5dafeba22bedaea82202","kind":"mcq"},{"id":"deep-management-MA300","sourceNumber":300,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"CASH MANAGEMENT objectives are:","options":["Avoid all the cash holdings of the business, since the idle cash earns nothing at all for the firm","Maximise the cash balance of the business, since the cash is the safest of the assets of the firm","Meet payment obligations (transactions motive) while MINIMISING idle cash - balancing liquidity against profitability","Maximise the float of the business, as the main objective of the cash management of the firm"],"answer":2,"explanation":"Cash is a non-earning asset; hold enough for transactions, precaution and speculation, but invest the surplus.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA300","number":300,"module":"M10","moduleTitle":"Working Capital Management","question":"CASH MANAGEMENT objectives are:","options":[{"key":"A","text":"Avoid all the cash holdings of the business, since the idle cash earns nothing at all for the firm"},{"key":"B","text":"Maximise the cash balance of the business, since the cash is the safest of the assets of the firm"},{"key":"C","text":"Meet payment obligations (transactions motive) while MINIMISING idle cash - balancing liquidity against profitability"},{"key":"D","text":"Maximise the float of the business, as the main objective of the cash management of the firm"}],"answer":"C","explanation":"Cash is a non-earning asset; hold enough for transactions, precaution and speculation, but invest the surplus.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CASH MANAGEMENT objectives are:","options":["Avoid all cash","Maximise cash balance","Meet payment obligations (transactions motive) while MINIMISING idle cash - balancing liquidity against profitability","Maximise float"],"answer":2,"explanation":"Cash is a non-earning asset; hold enough for transactions, precaution and speculation, but invest the surplus.","revision":"original","contentSignature":"20286abde753fa223b8ecf52e1188b0dbbeccb912722a0b9d05b9e16c587df40"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA300","optionFormat":"letter"},"contentSignature":"172b375b194eaf4b130b865e20a05313d33f429860689496adea993caba978a8","kind":"mcq"},{"id":"deep-management-MA301","sourceNumber":301,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The MOTIVES for holding cash (Keynes) are:","options":["Only the speculative motive of holding the cash, as Keynes taught","The transactions and the profit motives of holding the cash, as Keynes taught","The precautionary motive only of holding the cash, as Keynes taught","TRANSACTION, PRECAUTIONARY and SPECULATIVE motives"],"answer":3,"explanation":"Transactions for routine payments, precautionary for contingencies, speculative for sudden opportunities.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA301","number":301,"module":"M10","moduleTitle":"Working Capital Management","question":"The MOTIVES for holding cash (Keynes) are:","options":[{"key":"A","text":"Only the speculative motive of holding the cash, as Keynes taught"},{"key":"B","text":"The transactions and the profit motives of holding the cash, as Keynes taught"},{"key":"C","text":"The precautionary motive only of holding the cash, as Keynes taught"},{"key":"D","text":"TRANSACTION, PRECAUTIONARY and SPECULATIVE motives"}],"answer":"D","explanation":"Transactions for routine payments, precautionary for contingencies, speculative for sudden opportunities.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MOTIVES for holding cash (Keynes) are:","options":["Only speculative","Transactions and profit","Precautionary only","TRANSACTION, PRECAUTIONARY and SPECULATIVE motives"],"answer":3,"explanation":"Transactions for routine payments, precautionary for contingencies, speculative for sudden opportunities.","revision":"original","contentSignature":"52494f6c2910ae92fd1555d8ca85da4922c0fc92d03c2ad90158e942f347039f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA301","optionFormat":"letter"},"contentSignature":"ad41d8fd1aa473c9c5beb4dc913a2c35eb3ea40e312a5c53e52c8cd6555241ca","kind":"mcq"},{"id":"deep-management-MA302","sourceNumber":302,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The BAUMOL model of cash management applies:","options":["The ratio analysis of the cash flows of the business, as the model of the optimum cash balance of the firm itself always","The ABC analysis of the cash holdings of the business, as the model of the optimum cash balance of the firm always","The EOQ logic to cash - optimal cash conversion size C = SQRT(2bT/i), balancing transaction (brokerage) cost against opportunity (interest) cost","The trend analysis of the cash flows of the business, as the model of the optimum cash balance of the firm itself"],"answer":2,"explanation":"Baumol treats cash like inventory: total cost = conversion cost + holding cost, minimised at C* = sqrt(2 x fixed cost per conversion x total cash needed / interest rate).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA302","number":302,"module":"M10","moduleTitle":"Working Capital Management","question":"The BAUMOL model of cash management applies:","options":[{"key":"A","text":"The ratio analysis of the cash flows of the business, as the model of the optimum cash balance of the firm itself always"},{"key":"B","text":"The ABC analysis of the cash holdings of the business, as the model of the optimum cash balance of the firm always"},{"key":"C","text":"The EOQ logic to cash - optimal cash conversion size C = SQRT(2bT/i), balancing transaction (brokerage) cost against opportunity (interest) cost"},{"key":"D","text":"The trend analysis of the cash flows of the business, as the model of the optimum cash balance of the firm itself"}],"answer":"C","explanation":"Baumol treats cash like inventory: total cost = conversion cost + holding cost, minimised at C* = sqrt(2 x fixed cost per conversion x total cash needed / interest rate).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The BAUMOL model of cash management applies:","options":["Ratio analysis","ABC analysis","The EOQ logic to cash - optimal cash conversion size C = SQRT(2bT/i), balancing transaction (brokerage) cost against opportunity (interest) cost","Trend analysis"],"answer":2,"explanation":"Baumol treats cash like inventory: total cost = conversion cost + holding cost, minimised at C* = sqrt(2 x fixed cost per conversion x total cash needed / interest rate).","revision":"original","contentSignature":"5c9b9eddd6f4e15ae8da52ff6eeef191f164ce18d252f371c7343b6406e7f8a9"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA302","optionFormat":"letter"},"contentSignature":"be25e9d03b2f65eedec1a2f0167d83cfad2a8a56be01127bea91f6528e75631a","kind":"mcq"},{"id":"deep-management-MA303","sourceNumber":303,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Annual cash need Rs.16,00,000; cost per conversion Rs.100; opportunity cost 10% p.a. Baumol optimal cash balance is:","options":["Rs.40,000","Rs.80,000","Rs.1,60,000","Rs.56,569"],"answer":3,"explanation":"C = sqrt(2 x 100 x 16,00,000 / 0.10) = sqrt(3,200,000,000) = Rs.56,569 (approx).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA303","number":303,"module":"M10","moduleTitle":"Working Capital Management","question":"Annual cash need Rs.16,00,000; cost per conversion Rs.100; opportunity cost 10% p.a. Baumol optimal cash balance is:","options":[{"key":"A","text":"Rs.40,000"},{"key":"B","text":"Rs.80,000"},{"key":"C","text":"Rs.1,60,000"},{"key":"D","text":"Rs.56,569"}],"answer":"D","explanation":"C = sqrt(2 x 100 x 16,00,000 / 0.10) = sqrt(3,200,000,000) = Rs.56,569 (approx).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA303","optionFormat":"letter"},"contentSignature":"9d9da56ffdc514e62726fe787e9c253daeedb7a211f0868094267cc81b4416d2","kind":"mcq"},{"id":"deep-management-MA304","sourceNumber":304,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The MILLER-ORR model is used when cash flows are:","options":["RANDOM/uncertain - it sets UPPER and LOWER control limits with a return point for buying/selling securities","Certain and predictable from day to day","Received once a week only","Constant at the same level throughout"],"answer":0,"explanation":"Miller-Orr handles stochastic cash balances with an upper limit, lower limit and return point (spread formula).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA304","number":304,"module":"M10","moduleTitle":"Working Capital Management","question":"The MILLER-ORR model is used when cash flows are:","options":[{"key":"A","text":"RANDOM/uncertain - it sets UPPER and LOWER control limits with a return point for buying/selling securities"},{"key":"B","text":"Certain and predictable from day to day"},{"key":"C","text":"Received once a week only"},{"key":"D","text":"Constant at the same level throughout"}],"answer":"A","explanation":"Miller-Orr handles stochastic cash balances with an upper limit, lower limit and return point (spread formula).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MILLER-ORR model is used when cash flows are:","options":["RANDOM/uncertain - it sets UPPER and LOWER control limits with a return point for buying/selling securities","Certain","Weekly only","Constant"],"answer":0,"explanation":"Miller-Orr handles stochastic cash balances with an upper limit, lower limit and return point (spread formula).","revision":"original","contentSignature":"79da0242bedfa258ca315ad33ea85fe7b04c0a7422283048e4de0297f62dd0bc"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA304","optionFormat":"letter"},"contentSignature":"88e8f1aaa4490a2b26dd9a3241c052b39410b1087aba70c8fe453dcc2970d980","kind":"mcq"},{"id":"deep-management-MA305","sourceNumber":305,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"RECEIVABLES management aims to:","options":["Balance PROFITABILITY of extra sales against the COSTS (collection, default, capital cost) of granting credit","Give the credit to all the customers of the business, without any check at all on their worth","Avoid debtors altogether by selling only for cash, however much of the sales of the business may be lost in the process","Maximise the credit sales of the business, whatever the cost of the credit may be at all"],"answer":0,"explanation":"Liberal credit raises sales but also carrying cost and bad debts; the optimum trades the two off.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA305","number":305,"module":"M10","moduleTitle":"Working Capital Management","question":"RECEIVABLES management aims to:","options":[{"key":"A","text":"Balance PROFITABILITY of extra sales against the COSTS (collection, default, capital cost) of granting credit"},{"key":"B","text":"Give the credit to all the customers of the business, without any check at all on their worth"},{"key":"C","text":"Avoid debtors altogether by selling only for cash, however much of the sales of the business may be lost in the process"},{"key":"D","text":"Maximise the credit sales of the business, whatever the cost of the credit may be at all"}],"answer":"A","explanation":"Liberal credit raises sales but also carrying cost and bad debts; the optimum trades the two off.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"RECEIVABLES management aims to:","options":["Balance PROFITABILITY of extra sales against the COSTS (collection, default, capital cost) of granting credit","Give credit to all","Avoid debtors","Maximise credit sales"],"answer":0,"explanation":"Liberal credit raises sales but also carrying cost and bad debts; the optimum trades the two off.","revision":"original","contentSignature":"4ea433bbbe3495f26b0bdb7b1942cbf7905d13e6d7c0f64885d58acca199b319"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA305","optionFormat":"letter"},"contentSignature":"7c05ab313e1f56ded151adf90734619001ebcdf628aebd8bf9b41c63dbcb2ce1","kind":"mcq"},{"id":"deep-management-MA306","sourceNumber":306,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The FIVE Cs of credit evaluation include:","options":["Cost, Cash, Credit, Capital, Collection","Character, Cheque, Cash, Capital, Conditions","None of these","Character, Capacity, Capital, Collateral, Conditions"],"answer":3,"explanation":"The 5 Cs - character, capacity, capital, collateral and conditions - appraise the creditworthiness of a customer.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA306","number":306,"module":"M10","moduleTitle":"Working Capital Management","question":"The FIVE Cs of credit evaluation include:","options":[{"key":"A","text":"Cost, Cash, Credit, Capital, Collection"},{"key":"B","text":"Character, Cheque, Cash, Capital, Conditions"},{"key":"C","text":"None of these"},{"key":"D","text":"Character, Capacity, Capital, Collateral, Conditions"}],"answer":"D","explanation":"The 5 Cs - character, capacity, capital, collateral and conditions - appraise the creditworthiness of a customer.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA306","optionFormat":"letter"},"contentSignature":"deb071ae4730682538b719ad424148f752fffaa3ae114297191fa8d7bf6c1bb8","kind":"mcq"},{"id":"deep-management-MA307","sourceNumber":307,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"CREDIT POLICY variables are:","options":["CREDIT STANDARDS, CREDIT PERIOD (terms), CASH DISCOUNT and COLLECTION POLICY","Only the credit standards of the business","Only the cash discount offered by the business to the customers for early payment","Only the credit period allowed by the business"],"answer":0,"explanation":"The four variables - how strict, how long, what discount for early pay, and how hard to chase - jointly set receivables levels.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA307","number":307,"module":"M10","moduleTitle":"Working Capital Management","question":"CREDIT POLICY variables are:","options":[{"key":"A","text":"CREDIT STANDARDS, CREDIT PERIOD (terms), CASH DISCOUNT and COLLECTION POLICY"},{"key":"B","text":"Only the credit standards of the business"},{"key":"C","text":"Only the cash discount offered by the business to the customers for early payment"},{"key":"D","text":"Only the credit period allowed by the business"}],"answer":"A","explanation":"The four variables - how strict, how long, what discount for early pay, and how hard to chase - jointly set receivables levels.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"CREDIT POLICY variables are:","options":["CREDIT STANDARDS, CREDIT PERIOD (terms), CASH DISCOUNT and COLLECTION POLICY","Only standards","Only discount","Only credit period"],"answer":0,"explanation":"The four variables - how strict, how long, what discount for early pay, and how hard to chase - jointly set receivables levels.","revision":"original","contentSignature":"f2b18cac6cc980dd6477ef81036bd8b69d8fecfc5239158e13fd835ac74dcba7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA307","optionFormat":"letter"},"contentSignature":"bda2686929caaf34b227f0c62a78babf40e547f1c356412b6a1555a7b9e25e7a","kind":"mcq"},{"id":"deep-management-MA308","sourceNumber":308,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"A firm offers terms \"2/10, net 30\". This means:","options":["A 10% discount if the payment is made within 2 days of the invoice; otherwise the full amount is due in 30 days","A 30% penalty on the amount if the payment is not made at once; otherwise nothing is charged","A 2% DISCOUNT if payment is made within 10 DAYS; otherwise the full amount is due in 30 days","A 2% discount if the payment is made within 30 days of the invoice; otherwise nothing is charged"],"answer":2,"explanation":"Standard trade-credit notation: take 2% off for paying by day 10, else pay full by day 30.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA308","number":308,"module":"M10","moduleTitle":"Working Capital Management","question":"A firm offers terms \"2/10, net 30\". This means:","options":[{"key":"A","text":"A 10% discount if the payment is made within 2 days of the invoice; otherwise the full amount is due in 30 days"},{"key":"B","text":"A 30% penalty on the amount if the payment is not made at once; otherwise nothing is charged"},{"key":"C","text":"A 2% DISCOUNT if payment is made within 10 DAYS; otherwise the full amount is due in 30 days"},{"key":"D","text":"A 2% discount if the payment is made within 30 days of the invoice; otherwise nothing is charged"}],"answer":"C","explanation":"Standard trade-credit notation: take 2% off for paying by day 10, else pay full by day 30.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A firm offers terms \"2/10, net 30\". This means:","options":["10% discount in 2 days","30% penalty","A 2% DISCOUNT if payment is made within 10 DAYS; otherwise the full amount is due in 30 days","2% discount if paid in 30 days"],"answer":2,"explanation":"Standard trade-credit notation: take 2% off for paying by day 10, else pay full by day 30.","revision":"original","contentSignature":"fdc2cb9a7464e7ae86145b699c7c4c545877dfbb71de953a38c27f6efc6e40e4"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA308","optionFormat":"letter"},"contentSignature":"7c0347aa3515ac672b065e86cf8708b53b64931ffc2232a24875fd80ca3e6719","kind":"mcq"},{"id":"deep-management-MA309","sourceNumber":309,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The COST of NOT taking a cash discount of 2/10 net 30 approximates:","options":["10% per annum, as the cost of the discount foregone","20% per annum, as the cost of the discount foregone","2% per annum, as the cost of the discount foregone","About 37% p.a. - [2/(100-2)] x [365/(30-10)] = 2.04% x 18.25"],"answer":3,"explanation":"Forgoing the discount means paying 2% extra for 20 extra days of credit - an effective annual cost near 37%, far above bank rates.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA309","number":309,"module":"M10","moduleTitle":"Working Capital Management","question":"The COST of NOT taking a cash discount of 2/10 net 30 approximates:","options":[{"key":"A","text":"10% per annum, as the cost of the discount foregone"},{"key":"B","text":"20% per annum, as the cost of the discount foregone"},{"key":"C","text":"2% per annum, as the cost of the discount foregone"},{"key":"D","text":"About 37% p.a. - [2/(100-2)] x [365/(30-10)] = 2.04% x 18.25"}],"answer":"D","explanation":"Forgoing the discount means paying 2% extra for 20 extra days of credit - an effective annual cost near 37%, far above bank rates.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The COST of NOT taking a cash discount of 2/10 net 30 approximates:","options":["10% p.a","20% p.a","2% p.a","About 37% p.a. - [2/(100-2)] x [365/(30-10)] = 2.04% x 18.25"],"answer":3,"explanation":"Forgoing the discount means paying 2% extra for 20 extra days of credit - an effective annual cost near 37%, far above bank rates.","revision":"original","contentSignature":"71d98a9996a6e21f40c78b20cd702da8b8a5aca688a89c619ec47c8da8a5a289"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA309","optionFormat":"letter"},"contentSignature":"84ece8a96ed931dc8add0e664c973217b2a4397c1f107a00b9b4c60fbcf17358","kind":"mcq"},{"id":"deep-management-MA310","sourceNumber":310,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"INVENTORY management techniques include:","options":["Only the FIFO method of valuing the stock","Only the LIFO method of valuing the stock","EOQ, reorder level, ABC analysis, safety stock","The payback period of the investment in stock held"],"answer":2,"explanation":"EOQ fixes order size; reorder level and safety stock time the order; ABC analysis classifies items by value for selective control.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA310","number":310,"module":"M10","moduleTitle":"Working Capital Management","question":"INVENTORY management techniques include:","options":[{"key":"A","text":"Only the FIFO method of valuing the stock"},{"key":"B","text":"Only the LIFO method of valuing the stock"},{"key":"C","text":"EOQ, reorder level, ABC analysis, safety stock"},{"key":"D","text":"The payback period of the investment in stock held"}],"answer":"C","explanation":"EOQ fixes order size; reorder level and safety stock time the order; ABC analysis classifies items by value for selective control.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"INVENTORY management techniques include:","options":["Only FIFO","Only LIFO","EOQ, reorder level, ABC analysis, safety stock","Payback"],"answer":2,"explanation":"EOQ fixes order size; reorder level and safety stock time the order; ABC analysis classifies items by value for selective control.","revision":"original","contentSignature":"c14142f461c1261e78c62b62a342c7723b66a928d2a9cc6b8ebb04b864004b62"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA310","optionFormat":"letter"},"contentSignature":"081ea210904888adf612e903ce58dd87a33ab36572817362a838f3f3bca7f2fa","kind":"mcq"},{"id":"deep-management-MA311","sourceNumber":311,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"ECONOMIC ORDER QUANTITY (EOQ) =","options":["The carrying cost divided by the ordering cost of the year, as the formula of the EOQ","SQRT(2AB/C) - where A = annual demand, B = ordering cost per order, C = carrying cost per unit p.a","The annual demand of the item divided by two, as the formula of the EOQ","The safety stock of the item multiplied by two, as the formula of the EOQ"],"answer":1,"explanation":"EOQ minimises total ordering plus carrying cost: Q = sqrt(2 x annual usage x ordering cost / carrying cost per unit).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA311","number":311,"module":"M10","moduleTitle":"Working Capital Management","question":"ECONOMIC ORDER QUANTITY (EOQ) =","options":[{"key":"A","text":"The carrying cost divided by the ordering cost of the year, as the formula of the EOQ"},{"key":"B","text":"SQRT(2AB/C) - where A = annual demand, B = ordering cost per order, C = carrying cost per unit p.a"},{"key":"C","text":"The annual demand of the item divided by two, as the formula of the EOQ"},{"key":"D","text":"The safety stock of the item multiplied by two, as the formula of the EOQ"}],"answer":"B","explanation":"EOQ minimises total ordering plus carrying cost: Q = sqrt(2 x annual usage x ordering cost / carrying cost per unit).","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ECONOMIC ORDER QUANTITY (EOQ) =","options":["Carrying cost / ordering cost","SQRT(2AB/C) - where A = annual demand, B = ordering cost per order, C = carrying cost per unit p.a","Annual demand / 2","Safety stock x 2"],"answer":1,"explanation":"EOQ minimises total ordering plus carrying cost: Q = sqrt(2 x annual usage x ordering cost / carrying cost per unit).","revision":"original","contentSignature":"9daff62a6bf96200457b9dc9da2f8141d1bf6e28d0887ba9fe30fd513e430934"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA311","optionFormat":"letter"},"contentSignature":"22e43518af3fb718f7684b9f83e4bc7015c8e7475163ae2ba0bf728d4eaeeb2c","kind":"mcq"},{"id":"deep-management-MA312","sourceNumber":312,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Annual demand 4,000 units; ordering cost Rs.50 per order; carrying cost Rs.4 per unit p.a. EOQ is:","options":["200 units","100 units","400 units","316 units"],"answer":3,"explanation":"EOQ = sqrt(2 x 4,000 x 50 / 4) = sqrt(1,00,000) = 316 units (approx).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA312","number":312,"module":"M10","moduleTitle":"Working Capital Management","question":"Annual demand 4,000 units; ordering cost Rs.50 per order; carrying cost Rs.4 per unit p.a. EOQ is:","options":[{"key":"A","text":"200 units"},{"key":"B","text":"100 units"},{"key":"C","text":"400 units"},{"key":"D","text":"316 units"}],"answer":"D","explanation":"EOQ = sqrt(2 x 4,000 x 50 / 4) = sqrt(1,00,000) = 316 units (approx).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA312","optionFormat":"letter"},"contentSignature":"77038fda963ef053abe1e0d1bfa6c570dfe3dc7dce8b980a723ebc9815b9c3f7","kind":"mcq"},{"id":"deep-management-MA313","sourceNumber":313,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"ABC analysis classifies inventory by:","options":["VALUE OF CONSUMPTION - \"A\" items (few, high value) get tight control; \"C\" items (many, low value) get simple control","The supplier from whom the goods are bought","The alphabetical order of the item names","The date on which the goods are received"],"answer":0,"explanation":"Pareto logic: A items (~10-20% of items, ~70-80% of value) merit close attention; C items need only loose control.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA313","number":313,"module":"M10","moduleTitle":"Working Capital Management","question":"ABC analysis classifies inventory by:","options":[{"key":"A","text":"VALUE OF CONSUMPTION - \"A\" items (few, high value) get tight control; \"C\" items (many, low value) get simple control"},{"key":"B","text":"The supplier from whom the goods are bought"},{"key":"C","text":"The alphabetical order of the item names"},{"key":"D","text":"The date on which the goods are received"}],"answer":"A","explanation":"Pareto logic: A items (~10-20% of items, ~70-80% of value) merit close attention; C items need only loose control.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"ABC analysis classifies inventory by:","options":["VALUE OF CONSUMPTION - \"A\" items (few, high value) get tight control; \"C\" items (many, low value) get simple control","Supplier","Alphabetical order","Date of receipt"],"answer":0,"explanation":"Pareto logic: A items (~10-20% of items, ~70-80% of value) merit close attention; C items need only loose control.","revision":"original","contentSignature":"c6fe63f9a0fc1bc9b0e0df4d3c4ef5843e0f7a482b37e69e33998f4e4ddb2567"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA313","optionFormat":"letter"},"contentSignature":"96f2519543df3f297100bf9eb97aa24f2d3f7c335e8b93803dc853328d1da434","kind":"mcq"},{"id":"deep-management-MA314","sourceNumber":314,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"The REORDER LEVEL =","options":["Minimum stock + safety stock","Maximum consumption x maximum reorder period (lead time)","EOQ / 2","Maximum usage x maximum lead time"],"answer":3,"explanation":"Reorder level = max usage x max lead time; it triggers a fresh order so stock does not run out before delivery.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA314","number":314,"module":"M10","moduleTitle":"Working Capital Management","question":"The REORDER LEVEL =","options":[{"key":"A","text":"Minimum stock + safety stock"},{"key":"B","text":"Maximum consumption x maximum reorder period (lead time)"},{"key":"C","text":"EOQ / 2"},{"key":"D","text":"Maximum usage x maximum lead time"}],"answer":"D","explanation":"Reorder level = max usage x max lead time; it triggers a fresh order so stock does not run out before delivery.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA314","optionFormat":"letter"},"contentSignature":"60c9037a28dd72035afcb6bd901c9e87e5c0f3a36e3179c3730f81ad12b99c16","kind":"mcq"},{"id":"deep-management-MA315","sourceNumber":315,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"SAFETY (buffer) stock is held to:","options":["Increase the carrying cost of the inventory, as the purpose of the buffer","Guard against STOCK-OUTS from demand/lead-time fluctuations","Avoid the ordering of the goods, as the purpose of the buffer","Increase the EOQ of the item, as the purpose of the buffer"],"answer":1,"explanation":"Safety stock is the cushion below the reorder level absorbing unexpected usage or delayed supply.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA315","number":315,"module":"M10","moduleTitle":"Working Capital Management","question":"SAFETY (buffer) stock is held to:","options":[{"key":"A","text":"Increase the carrying cost of the inventory, as the purpose of the buffer"},{"key":"B","text":"Guard against STOCK-OUTS from demand/lead-time fluctuations"},{"key":"C","text":"Avoid the ordering of the goods, as the purpose of the buffer"},{"key":"D","text":"Increase the EOQ of the item, as the purpose of the buffer"}],"answer":"B","explanation":"Safety stock is the cushion below the reorder level absorbing unexpected usage or delayed supply.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"SAFETY (buffer) stock is held to:","options":["Increase carrying cost","Guard against STOCK-OUTS from demand/lead-time fluctuations","Avoid ordering","Increase EOQ"],"answer":1,"explanation":"Safety stock is the cushion below the reorder level absorbing unexpected usage or delayed supply.","revision":"original","contentSignature":"533bfde7d2a68c64ec91c2f3ebb71cb8179a33c5f04c8adedb7dc483c20e5eb7"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA315","optionFormat":"letter"},"contentSignature":"39e78547175c7c8518b8fefc85459d965899b0a1ab10b4d3306b80c96b9003e8","kind":"mcq"},{"id":"deep-management-MA316","sourceNumber":316,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M10 · Working Capital Management","question":"Spontaneous sources of working capital finance include:","options":["The debentures of the company, as the spontaneous source of the finance","TRADE CREDITORS and ACCRUED EXPENSES (they arise automatically with operations)","The term loans of the banks, as the spontaneous source of the finance","The equity shares of the company, as the spontaneous source of the finance"],"answer":1,"explanation":"Creditors and outstanding expenses finance part of WC without negotiation - the spontaneous sources.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA316","number":316,"module":"M10","moduleTitle":"Working Capital Management","question":"Spontaneous sources of working capital finance include:","options":[{"key":"A","text":"The debentures of the company, as the spontaneous source of the finance"},{"key":"B","text":"TRADE CREDITORS and ACCRUED EXPENSES (they arise automatically with operations)"},{"key":"C","text":"The term loans of the banks, as the spontaneous source of the finance"},{"key":"D","text":"The equity shares of the company, as the spontaneous source of the finance"}],"answer":"B","explanation":"Creditors and outstanding expenses finance part of WC without negotiation - the spontaneous sources.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Spontaneous sources of working capital finance include:","options":["Debentures","TRADE CREDITORS and ACCRUED EXPENSES (they arise automatically with operations)","Term loans","Equity shares"],"answer":1,"explanation":"Creditors and outstanding expenses finance part of WC without negotiation - the spontaneous sources.","revision":"original","contentSignature":"9dd5a9010ade795c38f2d5e706a1b0e4c94562bfb402e6a3509ebad9afafdf63"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA316","optionFormat":"letter"},"contentSignature":"5a503d0e06928aa24b3632bf7c2ee773fa64d1ff724d8cee8b587c33edce01f6","kind":"mcq"},{"id":"deep-management-MA317","sourceNumber":317,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A BUDGET is:","options":["A ledger of the business, in which the transactions of the year are recorded day by day","A QUANTITATIVE (financial/quantitative) plan of action for a definite future period, prepared in advance","A final account of the business, prepared at the end of the year for the members","An audit report of the business, issued by the auditor of the year for the members"],"answer":1,"explanation":"A budget expresses plans for a future period in money/physical terms and serves planning and control.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA317","number":317,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A BUDGET is:","options":[{"key":"A","text":"A ledger of the business, in which the transactions of the year are recorded day by day"},{"key":"B","text":"A QUANTITATIVE (financial/quantitative) plan of action for a definite future period, prepared in advance"},{"key":"C","text":"A final account of the business, prepared at the end of the year for the members"},{"key":"D","text":"An audit report of the business, issued by the auditor of the year for the members"}],"answer":"B","explanation":"A budget expresses plans for a future period in money/physical terms and serves planning and control.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A BUDGET is:","options":["A ledger","A QUANTITATIVE (financial/quantitative) plan of action for a definite future period, prepared in advance","A final account","An audit report"],"answer":1,"explanation":"A budget expresses plans for a future period in money/physical terms and serves planning and control.","revision":"original","contentSignature":"34901c7384391e9503bb586a6f56d51fc7deb1fef3f9f78fe5bc340fb717792b"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA317","optionFormat":"letter"},"contentSignature":"cb2855e6a42d7039687a97ce934a7c19eecc410125fdcad3326cd2105223efe9","kind":"mcq"},{"id":"deep-management-MA318","sourceNumber":318,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"BUDGETARY CONTROL is:","options":["An audit technique of the auditor, used in the verification of the accounts of the year of the audit work","Only the preparation of the budgets of the business, with no comparison of the actual results against the budgeted figures at any stage","Only the costing of the products of the business","A SYSTEM of using budgets as a means of planning and CONTROLLING - comparing actuals with budgeted figures and acting on variances"],"answer":3,"explanation":"Budgetary control = prepare budgets, record actuals, compare, analyse variances, take corrective action.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA318","number":318,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"BUDGETARY CONTROL is:","options":[{"key":"A","text":"An audit technique of the auditor, used in the verification of the accounts of the year of the audit work"},{"key":"B","text":"Only the preparation of the budgets of the business, with no comparison of the actual results against the budgeted figures at any stage"},{"key":"C","text":"Only the costing of the products of the business"},{"key":"D","text":"A SYSTEM of using budgets as a means of planning and CONTROLLING - comparing actuals with budgeted figures and acting on variances"}],"answer":"D","explanation":"Budgetary control = prepare budgets, record actuals, compare, analyse variances, take corrective action.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"BUDGETARY CONTROL is:","options":["An audit technique","Only budget preparation","Costing only","A SYSTEM of using budgets as a means of planning and CONTROLLING - comparing actuals with budgeted figures and acting on variances"],"answer":3,"explanation":"Budgetary control = prepare budgets, record actuals, compare, analyse variances, take corrective action.","revision":"original","contentSignature":"ec9af73b8dde308083d608e1f91432aba82d4b47bc8da64d8a620497e4718036"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA318","optionFormat":"letter"},"contentSignature":"fcfd441ceafe7ca9f049dd0f72b1011abd76ea60d634b5a4e7bf2b018ecc4d93","kind":"mcq"},{"id":"deep-management-MA319","sourceNumber":319,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The ESSENTIALS of an effective budgetary control system include all EXCEPT:","options":["FLEXIBLE TARGETS THAT CHANGE DAILY","Clear objectives and budget centres","A sound organisation with defined responsibilities","Top management support and participation"],"answer":0,"explanation":"Sound budgetary control needs defined objectives, centres, a budget manual, a budget committee, and management commitment - not daily-changing targets.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA319","number":319,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The ESSENTIALS of an effective budgetary control system include all EXCEPT:","options":[{"key":"A","text":"FLEXIBLE TARGETS THAT CHANGE DAILY"},{"key":"B","text":"Clear objectives and budget centres"},{"key":"C","text":"A sound organisation with defined responsibilities"},{"key":"D","text":"Top management support and participation"}],"answer":"A","explanation":"Sound budgetary control needs defined objectives, centres, a budget manual, a budget committee, and management commitment - not daily-changing targets.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA319","optionFormat":"letter"},"contentSignature":"f4952ccb145197f127b82df107aaa95563e6e1a2bde4db3b58d396cd0a7e2818","kind":"mcq"},{"id":"deep-management-MA320","sourceNumber":320,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A BUDGET CENTRE is:","options":["A SECTION/department of the organisation for which a separate budget is prepared and responsibility fixed","The cash desk of the business, where the money is received and paid day by day by the cashier","The audit cell of the business, where the audit work of the year is done by the staff","The head office of the business, where the management of the company sits and works"],"answer":0,"explanation":"Budget centres are responsibility units whose performance is measured against their own budgets.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA320","number":320,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A BUDGET CENTRE is:","options":[{"key":"A","text":"A SECTION/department of the organisation for which a separate budget is prepared and responsibility fixed"},{"key":"B","text":"The cash desk of the business, where the money is received and paid day by day by the cashier"},{"key":"C","text":"The audit cell of the business, where the audit work of the year is done by the staff"},{"key":"D","text":"The head office of the business, where the management of the company sits and works"}],"answer":"A","explanation":"Budget centres are responsibility units whose performance is measured against their own budgets.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A BUDGET CENTRE is:","options":["A SECTION/department of the organisation for which a separate budget is prepared and responsibility fixed","The cash desk","The audit cell","The head office"],"answer":0,"explanation":"Budget centres are responsibility units whose performance is measured against their own budgets.","revision":"original","contentSignature":"ce3c5f5b3fd29c723f2c18ae13cf2ad7470cbccdad3b042a22915ab2c0347cb3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA320","optionFormat":"letter"},"contentSignature":"9623e9572282fd4e8b85cdf3e8acda7e0bee5cda8a2374600f7a3c57a7d7e0d6","kind":"mcq"},{"id":"deep-management-MA321","sourceNumber":321,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The BUDGET PERIOD is:","options":["Indefinite, extending as far as the management pleases, with no fixed time frame laid down for it in the rules made","Always one year in length, for every kind of the budget whatever its type may be in the case","A quarter only in length, for every kind of the budget whatever its type may be in the case","The LENGTH OF TIME covered by a budget - it depends on the type (sales budgets shorter, capital budgets longer)"],"answer":3,"explanation":"Budget periods vary with the purpose: long for capital expenditure, commonly a year broken into months for operating budgets.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA321","number":321,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The BUDGET PERIOD is:","options":[{"key":"A","text":"Indefinite, extending as far as the management pleases, with no fixed time frame laid down for it in the rules made"},{"key":"B","text":"Always one year in length, for every kind of the budget whatever its type may be in the case"},{"key":"C","text":"A quarter only in length, for every kind of the budget whatever its type may be in the case"},{"key":"D","text":"The LENGTH OF TIME covered by a budget - it depends on the type (sales budgets shorter, capital budgets longer)"}],"answer":"D","explanation":"Budget periods vary with the purpose: long for capital expenditure, commonly a year broken into months for operating budgets.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The BUDGET PERIOD is:","options":["Indefinite","Always one year","A quarter only","The LENGTH OF TIME covered by a budget - it depends on the type (sales budgets shorter, capital budgets longer)"],"answer":3,"explanation":"Budget periods vary with the purpose: long for capital expenditure, commonly a year broken into months for operating budgets.","revision":"original","contentSignature":"69cc2e99ab0da22ed197b2930a7c1626f4919e63f57cc0cc243cd8620a2d4f13"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA321","optionFormat":"letter"},"contentSignature":"259ff26b16f25b67d3f4f4ee21bb65e04e0030365bdb5cb0f042e85a9e935474","kind":"mcq"},{"id":"deep-management-MA322","sourceNumber":322,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The KEY (LIMITING/PRINCIPAL BUDGET) FACTOR is:","options":["The sales of the business for the period, without fail","The profit of the business for the year","The factor whose SHORTAGE LIMITS activity (e.g. sales demand, capacity, material, labour) - it is budgeted FIRST","The capital employed in the business, without fail"],"answer":2,"explanation":"The principal budget factor governs all other budgets; sales is the usual key factor, but capacity or materials can be.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA322","number":322,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The KEY (LIMITING/PRINCIPAL BUDGET) FACTOR is:","options":[{"key":"A","text":"The sales of the business for the period, without fail"},{"key":"B","text":"The profit of the business for the year"},{"key":"C","text":"The factor whose SHORTAGE LIMITS activity (e.g. sales demand, capacity, material, labour) - it is budgeted FIRST"},{"key":"D","text":"The capital employed in the business, without fail"}],"answer":"C","explanation":"The principal budget factor governs all other budgets; sales is the usual key factor, but capacity or materials can be.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The KEY (LIMITING/PRINCIPAL BUDGET) FACTOR is:","options":["Sales always","Profit","The factor whose SHORTAGE LIMITS activity (e.g. sales demand, capacity, material, labour) - it is budgeted FIRST","Capital always"],"answer":2,"explanation":"The principal budget factor governs all other budgets; sales is the usual key factor, but capacity or materials can be.","revision":"original","contentSignature":"9fc2f769e065bfb2eaba33be9224286ffc5ef6291342ea15efeba6f9dcd112d0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA322","optionFormat":"letter"},"contentSignature":"c6f17563a8ffedfb13d0206eba531a62d62744928e9819c460258ce21251cbac","kind":"mcq"},{"id":"deep-management-MA323","sourceNumber":323,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The MASTER BUDGET is:","options":["The purchase budget of the business alone","The SUMMARY/CONSOLIDATED budget - the budgeted income statement, balance sheet and cash budget incorporating all functional budgets","The cash budget of the business alone","The sales budget of the business alone"],"answer":1,"explanation":"The master budget aggregates all functional budgets into projected financial statements.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA323","number":323,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The MASTER BUDGET is:","options":[{"key":"A","text":"The purchase budget of the business alone"},{"key":"B","text":"The SUMMARY/CONSOLIDATED budget - the budgeted income statement, balance sheet and cash budget incorporating all functional budgets"},{"key":"C","text":"The cash budget of the business alone"},{"key":"D","text":"The sales budget of the business alone"}],"answer":"B","explanation":"The master budget aggregates all functional budgets into projected financial statements.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MASTER BUDGET is:","options":["The purchase budget","The SUMMARY/CONSOLIDATED budget - the budgeted income statement, balance sheet and cash budget incorporating all functional budgets","The cash budget only","The sales budget"],"answer":1,"explanation":"The master budget aggregates all functional budgets into projected financial statements.","revision":"original","contentSignature":"5f74ec64089b18177b8223442a1f3b09454c9512086f75ac29321877c805767d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA323","optionFormat":"letter"},"contentSignature":"77dcf51c30c525b1cfc9e74bc95d9308660d28480720c5b3843c0399c723e16f","kind":"mcq"},{"id":"deep-management-MA324","sourceNumber":324,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A FIXED (static) budget:","options":["Covers only the cash flows of the business","Is prepared for ONE LEVEL of activity and does NOT change with actual volume","Changes with the actual output of the business, rising and falling along with it","Is of no use for any purpose of control"],"answer":1,"explanation":"A fixed budget remains at the planned activity level; variance analysis is distorted if actual volume differs.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA324","number":324,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A FIXED (static) budget:","options":[{"key":"A","text":"Covers only the cash flows of the business"},{"key":"B","text":"Is prepared for ONE LEVEL of activity and does NOT change with actual volume"},{"key":"C","text":"Changes with the actual output of the business, rising and falling along with it"},{"key":"D","text":"Is of no use for any purpose of control"}],"answer":"B","explanation":"A fixed budget remains at the planned activity level; variance analysis is distorted if actual volume differs.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A FIXED (static) budget:","options":["Covers cash only","Is prepared for ONE LEVEL of activity and does NOT change with actual volume","Changes with output","Is useless"],"answer":1,"explanation":"A fixed budget remains at the planned activity level; variance analysis is distorted if actual volume differs.","revision":"original","contentSignature":"2a4bf72417653e4586947437f2c735777683026f2cfcc64937802e622085b48a"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA324","optionFormat":"letter"},"contentSignature":"f6b9f4f08cfdcd5c26738323f56dd79874c6aabb4641b8777db3b30e88d5356e","kind":"mcq"},{"id":"deep-management-MA325","sourceNumber":325,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A FLEXIBLE budget:","options":["Stays rigid at the budgeted level, whatever the actual activity of the period may be in the case","Is only for the cash of the business, and for nothing else at all in the system of the budgets","Is prepared once for all, and never revised thereafter at all in the system of the budgets","ADJUSTS/RECASTS costs for the ACTUAL LEVEL of activity (recognising fixed, variable and semi-variable behaviour)"],"answer":3,"explanation":"Flexible budgets show what costs SHOULD be at the actual volume - the fair basis for comparing with actuals.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA325","number":325,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A FLEXIBLE budget:","options":[{"key":"A","text":"Stays rigid at the budgeted level, whatever the actual activity of the period may be in the case"},{"key":"B","text":"Is only for the cash of the business, and for nothing else at all in the system of the budgets"},{"key":"C","text":"Is prepared once for all, and never revised thereafter at all in the system of the budgets"},{"key":"D","text":"ADJUSTS/RECASTS costs for the ACTUAL LEVEL of activity (recognising fixed, variable and semi-variable behaviour)"}],"answer":"D","explanation":"Flexible budgets show what costs SHOULD be at the actual volume - the fair basis for comparing with actuals.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A FLEXIBLE budget:","options":["Stays rigid","Is only for cash","Is prepared once","ADJUSTS/RECASTS costs for the ACTUAL LEVEL of activity (recognising fixed, variable and semi-variable behaviour)"],"answer":3,"explanation":"Flexible budgets show what costs SHOULD be at the actual volume - the fair basis for comparing with actuals.","revision":"original","contentSignature":"2e77121debc3490eaf774e8e87ffbee35b3817807b2ef27d9e59012bcd3c7451"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA325","optionFormat":"letter"},"contentSignature":"c563270566f3c8c879ceb6fa4ab1c1618fce96c67fb213304f3c7e26d1d33392","kind":"mcq"},{"id":"deep-management-MA326","sourceNumber":326,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A ZERO-BASE BUDGET (ZBB) requires:","options":["The budget of the last year plus 10% of every figure, as the base of the new budget of it","Only the capital budgets of the business to be re-justified each year, the revenue budgets being taken as given","EVERY ACTIVITY to be JUSTIFIED FROM SCRATCH (zero base) each period - nothing is carried forward automatically","No budgets at all for any activity of the business, in any period of the requirement of it"],"answer":2,"explanation":"ZBB (Peter Pyhrr) makes managers re-justify each decision package and rank them, instead of incremental budgeting.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA326","number":326,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A ZERO-BASE BUDGET (ZBB) requires:","options":[{"key":"A","text":"The budget of the last year plus 10% of every figure, as the base of the new budget of it"},{"key":"B","text":"Only the capital budgets of the business to be re-justified each year, the revenue budgets being taken as given"},{"key":"C","text":"EVERY ACTIVITY to be JUSTIFIED FROM SCRATCH (zero base) each period - nothing is carried forward automatically"},{"key":"D","text":"No budgets at all for any activity of the business, in any period of the requirement of it"}],"answer":"C","explanation":"ZBB (Peter Pyhrr) makes managers re-justify each decision package and rank them, instead of incremental budgeting.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A ZERO-BASE BUDGET (ZBB) requires:","options":["Last year budget plus 10%","Only capital budgets","EVERY ACTIVITY to be JUSTIFIED FROM SCRATCH (zero base) each period - nothing is carried forward automatically","No budgets"],"answer":2,"explanation":"ZBB (Peter Pyhrr) makes managers re-justify each decision package and rank them, instead of incremental budgeting.","revision":"original","contentSignature":"30e815335764d7d4432131f836a40fd61927c04654241bafc55714ea93f63c97"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA326","optionFormat":"letter"},"contentSignature":"893233e32d8b72eb63520830f738ef2d531484bcbfa71680c77db58433185523","kind":"mcq"},{"id":"deep-management-MA327","sourceNumber":327,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"PERFORMANCE BUDGETING emphasises:","options":["Line-item control of the expenditure, item by item","OUTPUTS/RESULTS of programmes - linking expenditure to functions and activities and their performance","Only the cash flows of the business","Only the departments of the business"],"answer":1,"explanation":"Performance budgets present purposes and objectives for which funds are sought, with measured outcomes.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA327","number":327,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"PERFORMANCE BUDGETING emphasises:","options":[{"key":"A","text":"Line-item control of the expenditure, item by item"},{"key":"B","text":"OUTPUTS/RESULTS of programmes - linking expenditure to functions and activities and their performance"},{"key":"C","text":"Only the cash flows of the business"},{"key":"D","text":"Only the departments of the business"}],"answer":"B","explanation":"Performance budgets present purposes and objectives for which funds are sought, with measured outcomes.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"PERFORMANCE BUDGETING emphasises:","options":["Line-item control","OUTPUTS/RESULTS of programmes - linking expenditure to functions and activities and their performance","Cash only","Departments only"],"answer":1,"explanation":"Performance budgets present purposes and objectives for which funds are sought, with measured outcomes.","revision":"original","contentSignature":"c5ab9e352c908da62c73ac62a528e587e3817d523599e4f025dcfddd50e49f48"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA327","optionFormat":"letter"},"contentSignature":"250549923717f51450c7a04dd04ddceebe2b9e843905befb14c62084f6d4980b","kind":"mcq"},{"id":"deep-management-MA328","sourceNumber":328,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The SALES BUDGET is usually the:","options":["The master budget of the business, as the first of all the budgets","FIRST/STARTING budget - because sales is the usual principal budget factor","The cash budget of the business, as the first of all the budgets","The last budget of the business, prepared after everything else"],"answer":1,"explanation":"Production and all other budgets are built on the sales forecast when demand is the limiting factor.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA328","number":328,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The SALES BUDGET is usually the:","options":[{"key":"A","text":"The master budget of the business, as the first of all the budgets"},{"key":"B","text":"FIRST/STARTING budget - because sales is the usual principal budget factor"},{"key":"C","text":"The cash budget of the business, as the first of all the budgets"},{"key":"D","text":"The last budget of the business, prepared after everything else"}],"answer":"B","explanation":"Production and all other budgets are built on the sales forecast when demand is the limiting factor.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The SALES BUDGET is usually the:","options":["Master budget","FIRST/STARTING budget - because sales is the usual principal budget factor","Cash budget","Last budget"],"answer":1,"explanation":"Production and all other budgets are built on the sales forecast when demand is the limiting factor.","revision":"original","contentSignature":"bc9e79b99fd0dcbb0ca864efb1030aec8cc91db89b3929e4b3a154e8406c7bf6"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA328","optionFormat":"letter"},"contentSignature":"8a39a40126fa284bf1028fec0fb5f2b7cc31244009ee807b813401252eb99fb4","kind":"mcq"},{"id":"deep-management-MA329","sourceNumber":329,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The PRODUCTION BUDGET is expressed in:","options":["Rupees only, and never the physical units of the goods at all","PHYSICAL UNITS (quantity of goods to be produced)","Percentages only, and never the physical units of the goods at all","Hours only, and never the physical units of the goods at all"],"answer":1,"explanation":"Production budget = sales units + desired closing stock - opening stock, in quantities.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA329","number":329,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The PRODUCTION BUDGET is expressed in:","options":[{"key":"A","text":"Rupees only, and never the physical units of the goods at all"},{"key":"B","text":"PHYSICAL UNITS (quantity of goods to be produced)"},{"key":"C","text":"Percentages only, and never the physical units of the goods at all"},{"key":"D","text":"Hours only, and never the physical units of the goods at all"}],"answer":"B","explanation":"Production budget = sales units + desired closing stock - opening stock, in quantities.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PRODUCTION BUDGET is expressed in:","options":["Rupees only","PHYSICAL UNITS (quantity of goods to be produced)","Percentages","Hours only"],"answer":1,"explanation":"Production budget = sales units + desired closing stock - opening stock, in quantities.","revision":"original","contentSignature":"3ddc05a061a8d8f960a5e8031e05532aab4ee566ce734174aa3812cb63241cff"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA329","optionFormat":"letter"},"contentSignature":"648fa0a34b96b77b0f3fdea1e2d1fbe31d50917c7d47566633480e50a1f2c5e0","kind":"mcq"},{"id":"deep-management-MA330","sourceNumber":330,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"Budgeted sales 10,000 units; desired closing stock 2,000; opening stock 1,500. Production required is:","options":["11,500","8,500","10,500","10,000"],"answer":2,"explanation":"10,000 + 2,000 - 1,500 = 10,500 units.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA330","number":330,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"Budgeted sales 10,000 units; desired closing stock 2,000; opening stock 1,500. Production required is:","options":[{"key":"A","text":"11,500"},{"key":"B","text":"8,500"},{"key":"C","text":"10,500"},{"key":"D","text":"10,000"}],"answer":"C","explanation":"10,000 + 2,000 - 1,500 = 10,500 units.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA330","optionFormat":"letter"},"contentSignature":"c3e0ac5fe8e374acfd463a5758939d717b29ed9212676873e96ce64c900c063c","kind":"mcq"},{"id":"deep-management-MA331","sourceNumber":331,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A CASH BUDGET shows:","options":["Estimated CASH RECEIPTS AND PAYMENTS and the resulting CASH BALANCE over the budget period","The fund flow of the business between the two dates of the period of the budget","Only the capital of the business, raised during the period of the budget of it","The profit of the business, earned during the period of the budget of the year"],"answer":0,"explanation":"The cash budget forecasts inflows, outflows and the closing cash position month by month - highlighting shortages/surpluses.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA331","number":331,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A CASH BUDGET shows:","options":[{"key":"A","text":"Estimated CASH RECEIPTS AND PAYMENTS and the resulting CASH BALANCE over the budget period"},{"key":"B","text":"The fund flow of the business between the two dates of the period of the budget"},{"key":"C","text":"Only the capital of the business, raised during the period of the budget of it"},{"key":"D","text":"The profit of the business, earned during the period of the budget of the year"}],"answer":"A","explanation":"The cash budget forecasts inflows, outflows and the closing cash position month by month - highlighting shortages/surpluses.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A CASH BUDGET shows:","options":["Estimated CASH RECEIPTS AND PAYMENTS and the resulting CASH BALANCE over the budget period","Fund flow","Capital only","Profit"],"answer":0,"explanation":"The cash budget forecasts inflows, outflows and the closing cash position month by month - highlighting shortages/surpluses.","revision":"original","contentSignature":"55f4380ad25c061714e13393fb9b6b6db670d98d897b2dffc64be0347bed87f2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA331","optionFormat":"letter"},"contentSignature":"088376250289cb7aacac0d6b71a6368786aed2326214a61287da05419a782366","kind":"mcq"},{"id":"deep-management-MA332","sourceNumber":332,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"Which items are EXCLUDED from a cash budget?","options":["The loan receipts of the business, during the period of the budget of the year","The dividend paid by the company, during the period of the budget of the year","The cash sales of the business, during the period of the budget of the year","NON-CASH items like DEPRECIATION and outstanding accruals (only actual cash flows enter)"],"answer":3,"explanation":"Depreciation, provisions and accrued-but-unpaid items never touch cash and stay out of the cash budget.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA332","number":332,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"Which items are EXCLUDED from a cash budget?","options":[{"key":"A","text":"The loan receipts of the business, during the period of the budget of the year"},{"key":"B","text":"The dividend paid by the company, during the period of the budget of the year"},{"key":"C","text":"The cash sales of the business, during the period of the budget of the year"},{"key":"D","text":"NON-CASH items like DEPRECIATION and outstanding accruals (only actual cash flows enter)"}],"answer":"D","explanation":"Depreciation, provisions and accrued-but-unpaid items never touch cash and stay out of the cash budget.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which items are EXCLUDED from a cash budget?","options":["Loan receipts","Dividend paid","Cash sales","NON-CASH items like DEPRECIATION and outstanding accruals (only actual cash flows enter)"],"answer":3,"explanation":"Depreciation, provisions and accrued-but-unpaid items never touch cash and stay out of the cash budget.","revision":"original","contentSignature":"6618b231fe4097f0b36278758b045c2c8f144fcd5bc284af79aaad690ac51d88"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA332","optionFormat":"letter"},"contentSignature":"6a11fe598a9c197fbd556b28bbfcf7b9d608bf677b7b83da0715f3543456e9c8","kind":"mcq"},{"id":"deep-management-MA333","sourceNumber":333,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A cash budget opens with Rs.20,000; receipts Rs.1,50,000; payments Rs.1,40,000. The closing cash balance is:","options":["Rs.40,000","Rs.50,000","Rs.10,000","Rs.30,000"],"answer":3,"explanation":"20,000 + 1,50,000 - 1,40,000 = Rs.30,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA333","number":333,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A cash budget opens with Rs.20,000; receipts Rs.1,50,000; payments Rs.1,40,000. The closing cash balance is:","options":[{"key":"A","text":"Rs.40,000"},{"key":"B","text":"Rs.50,000"},{"key":"C","text":"Rs.10,000"},{"key":"D","text":"Rs.30,000"}],"answer":"D","explanation":"20,000 + 1,50,000 - 1,40,000 = Rs.30,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA333","optionFormat":"letter"},"contentSignature":"76ee531c1436b91846631355ca9521157b12c8565cabae33bd2ce79d30f7e1a7","kind":"mcq"},{"id":"deep-management-MA334","sourceNumber":334,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A firm pays wages with a HALF-MONTH LAG. January wages are Rs.60,000 and February wages Rs.80,000. The February CASH PAYMENT for wages is:","options":["Rs.60,000","Rs.80,000","Rs.70,000","Rs.40,000"],"answer":2,"explanation":"Half-month lag: pay half of January (30,000) + half of February (40,000) = Rs.70,000 in February.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA334","number":334,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A firm pays wages with a HALF-MONTH LAG. January wages are Rs.60,000 and February wages Rs.80,000. The February CASH PAYMENT for wages is:","options":[{"key":"A","text":"Rs.60,000"},{"key":"B","text":"Rs.80,000"},{"key":"C","text":"Rs.70,000"},{"key":"D","text":"Rs.40,000"}],"answer":"C","explanation":"Half-month lag: pay half of January (30,000) + half of February (40,000) = Rs.70,000 in February.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA334","optionFormat":"letter"},"contentSignature":"3c8692459f26f2f230d6d5327e15784500a3e18842e89c8b2adaf252b87f16b8","kind":"mcq"},{"id":"deep-management-MA335","sourceNumber":335,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The main OBJECTIVE of a cash budget is to:","options":["Ensure the firm has NEITHER A SHORTAGE NOR IDLE SURPLUS of cash - plan borrowing/investment in advance","Maximise the profit of the business, as the main objective of the cash budget of the year","Fix the prices of the products of the business, as the main objective of the cash budget","Avoid the budgets altogether, as the main objective of the cash budget of the year"],"answer":0,"explanation":"It forewarns of deficits (arrange finance) and surpluses (invest them) - central to liquidity management.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA335","number":335,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The main OBJECTIVE of a cash budget is to:","options":[{"key":"A","text":"Ensure the firm has NEITHER A SHORTAGE NOR IDLE SURPLUS of cash - plan borrowing/investment in advance"},{"key":"B","text":"Maximise the profit of the business, as the main objective of the cash budget of the year"},{"key":"C","text":"Fix the prices of the products of the business, as the main objective of the cash budget"},{"key":"D","text":"Avoid the budgets altogether, as the main objective of the cash budget of the year"}],"answer":"A","explanation":"It forewarns of deficits (arrange finance) and surpluses (invest them) - central to liquidity management.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The main OBJECTIVE of a cash budget is to:","options":["Ensure the firm has NEITHER A SHORTAGE NOR IDLE SURPLUS of cash - plan borrowing/investment in advance","Maximise profit","Fix prices","Avoid budgets"],"answer":0,"explanation":"It forewarns of deficits (arrange finance) and surpluses (invest them) - central to liquidity management.","revision":"original","contentSignature":"09da100e982221c529a796733c9a2ce383d150f44f99be6b9f159d28a88d6204"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA335","optionFormat":"letter"},"contentSignature":"3cedfc7b039ac275f5cd06c89cf9700fd919077d8645c75c2723f173808e4431","kind":"mcq"},{"id":"deep-management-MA336","sourceNumber":336,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"Methods of preparing a cash budget include:","options":["Only the funds flow method of preparation, and no other method at all","Only the ratio method of preparation, and no other method at all","Only the trial balance method of preparation, and no other method at all","Receipts & payments method, adjusted profit & loss method, balance sheet method"],"answer":3,"explanation":"The receipts-and-payments method lists cash items directly; the adjusted-P&L and balance-sheet methods work from projected statements.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA336","number":336,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"Methods of preparing a cash budget include:","options":[{"key":"A","text":"Only the funds flow method of preparation, and no other method at all"},{"key":"B","text":"Only the ratio method of preparation, and no other method at all"},{"key":"C","text":"Only the trial balance method of preparation, and no other method at all"},{"key":"D","text":"Receipts & payments method, adjusted profit & loss method, balance sheet method"}],"answer":"D","explanation":"The receipts-and-payments method lists cash items directly; the adjusted-P&L and balance-sheet methods work from projected statements.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Methods of preparing a cash budget include:","options":["Only funds flow","Only ratio method","Only trial balance method","Receipts & payments method, adjusted profit & loss method, balance sheet method"],"answer":3,"explanation":"The receipts-and-payments method lists cash items directly; the adjusted-P&L and balance-sheet methods work from projected statements.","revision":"original","contentSignature":"f183de6935aa019404ac766844e5aa92a5fcf64ed5bb2786a6d620f191e3896d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA336","optionFormat":"letter"},"contentSignature":"a5a77d90776d8e620c9eb57624670def69002f513e8f8514dfe19cb881b7f07a","kind":"mcq"},{"id":"deep-management-MA337","sourceNumber":337,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"Which is NOT a functional (operating) budget?","options":["BALANCE SHEET (it is part of the master budget, not a functional budget)","The purchase budget of the business, as the odd one of the list","The production budget of the business, as the odd one of the list","The sales budget of the business, as the odd one of the list"],"answer":0,"explanation":"Functional budgets cover sales, production, materials, labour, overheads; the projected balance sheet is a master-budget component.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA337","number":337,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"Which is NOT a functional (operating) budget?","options":[{"key":"A","text":"BALANCE SHEET (it is part of the master budget, not a functional budget)"},{"key":"B","text":"The purchase budget of the business, as the odd one of the list"},{"key":"C","text":"The production budget of the business, as the odd one of the list"},{"key":"D","text":"The sales budget of the business, as the odd one of the list"}],"answer":"A","explanation":"Functional budgets cover sales, production, materials, labour, overheads; the projected balance sheet is a master-budget component.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which is NOT a functional (operating) budget?","options":["BALANCE SHEET (it is part of the master budget, not a functional budget)","Purchase budget","Production budget","Sales budget"],"answer":0,"explanation":"Functional budgets cover sales, production, materials, labour, overheads; the projected balance sheet is a master-budget component.","revision":"original","contentSignature":"8f6131a5757e04b611abc1418acee879e0239e9deb0351e3180357aae7a11866"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA337","optionFormat":"letter"},"contentSignature":"d9bfb36dab2ee0dae21a5017bae6d1e9f0ec4f6951ee174fe0bc1c965bf87515","kind":"mcq"},{"id":"deep-management-MA338","sourceNumber":338,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The BUDGET MANUAL is:","options":["The audit manual of the business, setting out the audit procedures of the year for the audit staff of it","The annual report of the business, presented to the shareholders at the annual meeting of the year of it","A DOCUMENT setting out the RESPONSIBILITIES and PROCEDURES for budget preparation and administration (who does what, when, how)","The costing manual of the business, setting out the costing procedures of the year for the cost staff of it"],"answer":2,"explanation":"The budget manual codifies forms, timetables, responsibilities and procedures of the budget programme.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA338","number":338,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The BUDGET MANUAL is:","options":[{"key":"A","text":"The audit manual of the business, setting out the audit procedures of the year for the audit staff of it"},{"key":"B","text":"The annual report of the business, presented to the shareholders at the annual meeting of the year of it"},{"key":"C","text":"A DOCUMENT setting out the RESPONSIBILITIES and PROCEDURES for budget preparation and administration (who does what, when, how)"},{"key":"D","text":"The costing manual of the business, setting out the costing procedures of the year for the cost staff of it"}],"answer":"C","explanation":"The budget manual codifies forms, timetables, responsibilities and procedures of the budget programme.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The BUDGET MANUAL is:","options":["The audit manual","The annual report","A DOCUMENT setting out the RESPONSIBILITIES and PROCEDURES for budget preparation and administration (who does what, when, how)","The costing manual"],"answer":2,"explanation":"The budget manual codifies forms, timetables, responsibilities and procedures of the budget programme.","revision":"original","contentSignature":"40d52f6dea53dbad7d41d833d74058fbc7afd861daa9414349fd762764d26084"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA338","optionFormat":"letter"},"contentSignature":"ec0cc6fd4a6e205da8d52b11b9724e4b50265a572395a344cedbee089c358a9e","kind":"mcq"},{"id":"deep-management-MA339","sourceNumber":339,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"The BUDGET COMMITTEE is usually headed by:","options":["The auditor of the company","The cashier of the company","A shareholder of the company","The CHIEF EXECUTIVE/managing director, with functional heads as members; the BUDGET OFFICER/controller coordinates"],"answer":3,"explanation":"The committee (top management) formulates policy and resolves inter-department issues; the budget officer is the coordinator.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA339","number":339,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"The BUDGET COMMITTEE is usually headed by:","options":[{"key":"A","text":"The auditor of the company"},{"key":"B","text":"The cashier of the company"},{"key":"C","text":"A shareholder of the company"},{"key":"D","text":"The CHIEF EXECUTIVE/managing director, with functional heads as members; the BUDGET OFFICER/controller coordinates"}],"answer":"D","explanation":"The committee (top management) formulates policy and resolves inter-department issues; the budget officer is the coordinator.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The BUDGET COMMITTEE is usually headed by:","options":["The auditor","The cashier","A shareholder","The CHIEF EXECUTIVE/managing director, with functional heads as members; the BUDGET OFFICER/controller coordinates"],"answer":3,"explanation":"The committee (top management) formulates policy and resolves inter-department issues; the budget officer is the coordinator.","revision":"original","contentSignature":"144672cf88d766bfc112bfc3314fa323cd1796e5ac518eae2aafd56065a0e2f3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA339","optionFormat":"letter"},"contentSignature":"3975cb36a93a3a3319538d77dfa9fb20871250cc3416b159d33385bc781df588","kind":"mcq"},{"id":"deep-management-MA340","sourceNumber":340,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"Responsibility accounting under budgetary control fixes:","options":["The collective blame for every deviation, shared by all the managers of the business","Only the top-level control of the business, with nothing fixed at the lower levels at all","INDIVIDUAL responsibility for each budget centre, with costs reported by the manager who CONTROLS them","No accountability at all for any deviation of the budget of the year of the control"],"answer":2,"explanation":"Reports follow responsibility: controllable items are charged to the manager able to influence them.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA340","number":340,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"Responsibility accounting under budgetary control fixes:","options":[{"key":"A","text":"The collective blame for every deviation, shared by all the managers of the business"},{"key":"B","text":"Only the top-level control of the business, with nothing fixed at the lower levels at all"},{"key":"C","text":"INDIVIDUAL responsibility for each budget centre, with costs reported by the manager who CONTROLS them"},{"key":"D","text":"No accountability at all for any deviation of the budget of the year of the control"}],"answer":"C","explanation":"Reports follow responsibility: controllable items are charged to the manager able to influence them.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Responsibility accounting under budgetary control fixes:","options":["Collective blame","Only top-level control","INDIVIDUAL responsibility for each budget centre, with costs reported by the manager who CONTROLS them","No accountability"],"answer":2,"explanation":"Reports follow responsibility: controllable items are charged to the manager able to influence them.","revision":"original","contentSignature":"830b20c180765187ec71b746dce6e8600ec8da36fd615306319200cea2498c5c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA340","optionFormat":"letter"},"contentSignature":"4a0450cac6ff9dfb600d258c931a75f1fc9c0c481d1b7cb89d31c6a8f04890de","kind":"mcq"},{"id":"deep-management-MA341","sourceNumber":341,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"A CONTROL RATIO used in budgetary control is the:","options":["The debt-equity ratio of the company, as the control ratio of the budgetary control","The current ratio of the company, as the control ratio of the budgetary control","The quick ratio of the company, as the control ratio of the budgetary control","Activity ratio = (standard hours for actual production / budgeted hours) x 100"],"answer":3,"explanation":"Activity, capacity and efficiency ratios measure how the actual output/hours compare with budgeted levels.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA341","number":341,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"A CONTROL RATIO used in budgetary control is the:","options":[{"key":"A","text":"The debt-equity ratio of the company, as the control ratio of the budgetary control"},{"key":"B","text":"The current ratio of the company, as the control ratio of the budgetary control"},{"key":"C","text":"The quick ratio of the company, as the control ratio of the budgetary control"},{"key":"D","text":"Activity ratio = (standard hours for actual production / budgeted hours) x 100"}],"answer":"D","explanation":"Activity, capacity and efficiency ratios measure how the actual output/hours compare with budgeted levels.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A CONTROL RATIO used in budgetary control is the:","options":["Debt-equity ratio","Current ratio","Quick ratio","Activity ratio = (standard hours for actual production / budgeted hours) x 100"],"answer":3,"explanation":"Activity, capacity and efficiency ratios measure how the actual output/hours compare with budgeted levels.","revision":"original","contentSignature":"abbfe59e78b9c3b79deb4edff4bdc58000147807f6608335f035b6922d5fd664"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA341","optionFormat":"letter"},"contentSignature":"5aaa0afbe650e0bba81933d6d759b573d654633cc11c7082303754a857988b0e","kind":"mcq"},{"id":"deep-management-MA342","sourceNumber":342,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M11 · Budgets & Budgetary Control","question":"REVISED (current) budget vs BASIC budget: a BASIC budget is:","options":["Updated every month to reflect current conditions in the business and the circumstances of its working","Never used at all in the practice of the budgetary control, in any case of it","Prepared for use UNALTERED over a long period; a CURRENT budget relates to current conditions","Always flexible with the level of activity"],"answer":2,"explanation":"Basic budgets stay as benchmarks; current budgets reflect current-period conditions and are revised.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA342","number":342,"module":"M11","moduleTitle":"Budgets & Budgetary Control","question":"REVISED (current) budget vs BASIC budget: a BASIC budget is:","options":[{"key":"A","text":"Updated every month to reflect current conditions in the business and the circumstances of its working"},{"key":"B","text":"Never used at all in the practice of the budgetary control, in any case of it"},{"key":"C","text":"Prepared for use UNALTERED over a long period; a CURRENT budget relates to current conditions"},{"key":"D","text":"Always flexible with the level of activity"}],"answer":"C","explanation":"Basic budgets stay as benchmarks; current budgets reflect current-period conditions and are revised.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"REVISED (current) budget vs BASIC budget: a BASIC budget is:","options":["Updated monthly","Never used","Prepared for use UNALTERED over a long period; a CURRENT budget relates to current conditions","Always flexible"],"answer":2,"explanation":"Basic budgets stay as benchmarks; current budgets reflect current-period conditions and are revised.","revision":"original","contentSignature":"956c2732b32ea03bbb98d995874d1313162e4a503be3506d35853cadd030d7f2"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA342","optionFormat":"letter"},"contentSignature":"5b5938f9fa2084b950a0b84954a6d7cbc9cf586ab34ea7d0a2b0bcd89600b568","kind":"mcq"},{"id":"deep-management-MA343","sourceNumber":343,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"In decision-making, a RELEVANT cost is:","options":["A past cost of the business, already incurred and gone","A fixed cost only of the business, whatever the decision","A sunk cost of the business, already incurred and gone","A FUTURE cost that DIFFERS between alternatives"],"answer":3,"explanation":"Only future costs (and revenues) that change with the choice are relevant; identical or past items are irrelevant.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA343","number":343,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"In decision-making, a RELEVANT cost is:","options":[{"key":"A","text":"A past cost of the business, already incurred and gone"},{"key":"B","text":"A fixed cost only of the business, whatever the decision"},{"key":"C","text":"A sunk cost of the business, already incurred and gone"},{"key":"D","text":"A FUTURE cost that DIFFERS between alternatives"}],"answer":"D","explanation":"Only future costs (and revenues) that change with the choice are relevant; identical or past items are irrelevant.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In decision-making, a RELEVANT cost is:","options":["A past cost","A fixed cost only","A sunk cost","A FUTURE cost that DIFFERS between alternatives"],"answer":3,"explanation":"Only future costs (and revenues) that change with the choice are relevant; identical or past items are irrelevant.","revision":"original","contentSignature":"e7269e7cce1a003eacda68cd27d123ed41ddd98e61bb65edb97bc013856ba1d3"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA343","optionFormat":"letter"},"contentSignature":"f0e48078dc36df3c184b013a6aaca8544b0fabf66b02a968901b44a13c6dd022","kind":"mcq"},{"id":"deep-management-MA344","sourceNumber":344,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"A SUNK cost is:","options":["An avoidable cost of the business, which can be escaped by the decision of the management","A cost ALREADY INCURRED that cannot be changed by any current/future decision - hence IRRELEVANT","Relevant to the decisions of the management and counted in every project appraisal made by the firm","A variable cost of the business, varying with the output of the business of it"],"answer":1,"explanation":"Book value of old machinery, past R&D - sunk costs must be ignored in decisions.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA344","number":344,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"A SUNK cost is:","options":[{"key":"A","text":"An avoidable cost of the business, which can be escaped by the decision of the management"},{"key":"B","text":"A cost ALREADY INCURRED that cannot be changed by any current/future decision - hence IRRELEVANT"},{"key":"C","text":"Relevant to the decisions of the management and counted in every project appraisal made by the firm"},{"key":"D","text":"A variable cost of the business, varying with the output of the business of it"}],"answer":"B","explanation":"Book value of old machinery, past R&D - sunk costs must be ignored in decisions.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A SUNK cost is:","options":["An avoidable cost","A cost ALREADY INCURRED that cannot be changed by any current/future decision - hence IRRELEVANT","Relevant to decisions","A variable cost"],"answer":1,"explanation":"Book value of old machinery, past R&D - sunk costs must be ignored in decisions.","revision":"original","contentSignature":"7eff49d58835a37d2581c96e0eaa72730c0313e8bd0d9e5f4e344395b6019182"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA344","optionFormat":"letter"},"contentSignature":"84f84a1e63ad36c19f56a33a40d5dab9be74bd919e1c9e312bab683d7799bf3c","kind":"mcq"},{"id":"deep-management-MA345","sourceNumber":345,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"An OPPORTUNITY cost is:","options":["A sunk cost of the business, already incurred and gone","The BENEFIT FORGONE from the next best alternative given up","A direct cost of the product, traceable to it directly","A cash payment of the business, made in money at once"],"answer":1,"explanation":"Using owned premises for a project sacrifices rent; that forgone rent is an opportunity cost and IS relevant.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA345","number":345,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"An OPPORTUNITY cost is:","options":[{"key":"A","text":"A sunk cost of the business, already incurred and gone"},{"key":"B","text":"The BENEFIT FORGONE from the next best alternative given up"},{"key":"C","text":"A direct cost of the product, traceable to it directly"},{"key":"D","text":"A cash payment of the business, made in money at once"}],"answer":"B","explanation":"Using owned premises for a project sacrifices rent; that forgone rent is an opportunity cost and IS relevant.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"An OPPORTUNITY cost is:","options":["A sunk cost","The BENEFIT FORGONE from the next best alternative given up","A direct cost","A cash payment"],"answer":1,"explanation":"Using owned premises for a project sacrifices rent; that forgone rent is an opportunity cost and IS relevant.","revision":"original","contentSignature":"c3679d0bbf9e7210d457e321cecdbea1a66fc7a93a24e6567ff491c8ae326c6c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA345","optionFormat":"letter"},"contentSignature":"6771c4a8fd9990c2a136b69b6ef3decaf945c5ae2d9fdb718d0e0f5706809e9d","kind":"mcq"},{"id":"deep-management-MA346","sourceNumber":346,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"DIFFERENTIAL (incremental) cost is:","options":["The DIFFERENCE in total cost between two alternatives (the change due to the decision)","The historical cost of the asset, as recorded in the books of the business of it","The total cost of the alternative, as computed in full for the comparison of it","The fixed cost of the alternative, as computed in full for the comparison of it"],"answer":0,"explanation":"Differential costing compares the change in costs/revenues under each option; the option with the best net differential wins.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA346","number":346,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"DIFFERENTIAL (incremental) cost is:","options":[{"key":"A","text":"The DIFFERENCE in total cost between two alternatives (the change due to the decision)"},{"key":"B","text":"The historical cost of the asset, as recorded in the books of the business of it"},{"key":"C","text":"The total cost of the alternative, as computed in full for the comparison of it"},{"key":"D","text":"The fixed cost of the alternative, as computed in full for the comparison of it"}],"answer":"A","explanation":"Differential costing compares the change in costs/revenues under each option; the option with the best net differential wins.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"DIFFERENTIAL (incremental) cost is:","options":["The DIFFERENCE in total cost between two alternatives (the change due to the decision)","Historical cost","Total cost","Fixed cost"],"answer":0,"explanation":"Differential costing compares the change in costs/revenues under each option; the option with the best net differential wins.","revision":"original","contentSignature":"ce2dde06b27965afdce83348cd00559733d93b690b227606da23f9827633556d"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA346","optionFormat":"letter"},"contentSignature":"2fe5f9fd9dcb48f86f2962454899a9a008246083aa5e1a31840dc8f019f7e940","kind":"mcq"},{"id":"deep-management-MA347","sourceNumber":347,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"In a MAKE-OR-BUY decision with no alternative use of capacity, the comparison is:","options":["MARGINAL (variable) COST of making vs the PURCHASE PRICE (fixed costs that continue anyway are irrelevant)","The sales of the product against the cost of making it","The full cost of making against the price of buying","The overheads of making against the price of buying"],"answer":0,"explanation":"Make if variable cost of making < purchase price; unavoidable fixed overheads are common to both and excluded.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA347","number":347,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"In a MAKE-OR-BUY decision with no alternative use of capacity, the comparison is:","options":[{"key":"A","text":"MARGINAL (variable) COST of making vs the PURCHASE PRICE (fixed costs that continue anyway are irrelevant)"},{"key":"B","text":"The sales of the product against the cost of making it"},{"key":"C","text":"The full cost of making against the price of buying"},{"key":"D","text":"The overheads of making against the price of buying"}],"answer":"A","explanation":"Make if variable cost of making < purchase price; unavoidable fixed overheads are common to both and excluded.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In a MAKE-OR-BUY decision with no alternative use of capacity, the comparison is:","options":["MARGINAL (variable) COST of making vs the PURCHASE PRICE (fixed costs that continue anyway are irrelevant)","Sales vs cost","Full cost vs price","Overheads vs price"],"answer":0,"explanation":"Make if variable cost of making < purchase price; unavoidable fixed overheads are common to both and excluded.","revision":"original","contentSignature":"b03edac1f53f9f00b31e8d1b82275ce25d8b94ce1d22b3da6746a4cf9f4f40b1"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA347","optionFormat":"letter"},"contentSignature":"424ab3bdc8ba9d26437b8a8f7cf6a0c09a58fbadb6c63382fa029a99537e3383","kind":"mcq"},{"id":"deep-management-MA348","sourceNumber":348,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"A component can be made at variable cost Rs.30 (unavoidable fixed cost Rs.10 allocated) or bought at Rs.35. With spare capacity, the firm should:","options":["Be indifferent, since the costs of the two are equal","MAKE - variable cost Rs.30 is below the Rs.35 price; the Rs.10 fixed cost continues either way","Buy, since buying saves Rs.15 per unit","Buy, since buying saves Rs.5 per unit"],"answer":1,"explanation":"Relevant cost of making = Rs.30 < Rs.35; buying adds Rs.5 per unit of avoidable spend.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA348","number":348,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"A component can be made at variable cost Rs.30 (unavoidable fixed cost Rs.10 allocated) or bought at Rs.35. With spare capacity, the firm should:","options":[{"key":"A","text":"Be indifferent, since the costs of the two are equal"},{"key":"B","text":"MAKE - variable cost Rs.30 is below the Rs.35 price; the Rs.10 fixed cost continues either way"},{"key":"C","text":"Buy, since buying saves Rs.15 per unit"},{"key":"D","text":"Buy, since buying saves Rs.5 per unit"}],"answer":"B","explanation":"Relevant cost of making = Rs.30 < Rs.35; buying adds Rs.5 per unit of avoidable spend.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A component can be made at variable cost Rs.30 (unavoidable fixed cost Rs.10 allocated) or bought at Rs.35. With spare capacity, the firm should:","options":["Be indifferent","MAKE - variable cost Rs.30 is below the Rs.35 price; the Rs.10 fixed cost continues either way","Buy (saves Rs.15)","Buy (saves Rs.5)"],"answer":1,"explanation":"Relevant cost of making = Rs.30 < Rs.35; buying adds Rs.5 per unit of avoidable spend.","revision":"original","contentSignature":"5b30a49ea8944321e1845e5a4262e0f5a87bfb485fe461999e14a5b1f59a8b15"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA348","optionFormat":"letter"},"contentSignature":"b85a6845556a901b0d78e2a5574732060bba9cc10f7c8df3b7d0e3e7a17ad5b3","kind":"mcq"},{"id":"deep-management-MA349","sourceNumber":349,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"In deciding whether to SHUT DOWN in the SHORT RUN, a firm should continue if:","options":["The price covers the total cost of the product","The fixed costs of the firm are high","The price falls below the variable cost of the product","PRICE COVERS VARIABLE COST (contribution is positive) - it then contributes something toward fixed costs"],"answer":3,"explanation":"Short-run shutdown rule: operate while contribution is positive; shut down if price falls below variable cost.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA349","number":349,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"In deciding whether to SHUT DOWN in the SHORT RUN, a firm should continue if:","options":[{"key":"A","text":"The price covers the total cost of the product"},{"key":"B","text":"The fixed costs of the firm are high"},{"key":"C","text":"The price falls below the variable cost of the product"},{"key":"D","text":"PRICE COVERS VARIABLE COST (contribution is positive) - it then contributes something toward fixed costs"}],"answer":"D","explanation":"Short-run shutdown rule: operate while contribution is positive; shut down if price falls below variable cost.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In deciding whether to SHUT DOWN in the SHORT RUN, a firm should continue if:","options":["Price > total cost","Fixed costs are high","Price < variable cost","PRICE COVERS VARIABLE COST (contribution is positive) - it then contributes something toward fixed costs"],"answer":3,"explanation":"Short-run shutdown rule: operate while contribution is positive; shut down if price falls below variable cost.","revision":"original","contentSignature":"537170b8ea009b591eb9f2beb8ae6b77b1d7dc23bfc0b02451dc4d9a8fc10b08"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA349","optionFormat":"letter"},"contentSignature":"2e24566d22ebf23393657467719ebe23f09bb12a549eb2813f303f9a55800e72","kind":"mcq"},{"id":"deep-management-MA350","sourceNumber":350,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The SHUT-DOWN POINT occurs at the output where:","options":["CONTRIBUTION EQUALS AVOIDABLE FIXED COSTS (price = average variable cost at minimum)","The sales of the firm are at their maximum","The break-even point of the firm is reached","The profit of the firm is at its maximum"],"answer":0,"explanation":"Below it, even avoidable fixed costs are not covered, so closing saves money.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA350","number":350,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The SHUT-DOWN POINT occurs at the output where:","options":[{"key":"A","text":"CONTRIBUTION EQUALS AVOIDABLE FIXED COSTS (price = average variable cost at minimum)"},{"key":"B","text":"The sales of the firm are at their maximum"},{"key":"C","text":"The break-even point of the firm is reached"},{"key":"D","text":"The profit of the firm is at its maximum"}],"answer":"A","explanation":"Below it, even avoidable fixed costs are not covered, so closing saves money.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The SHUT-DOWN POINT occurs at the output where:","options":["CONTRIBUTION EQUALS AVOIDABLE FIXED COSTS (price = average variable cost at minimum)","Sales are maximum","BEP is reached","Profit is maximum"],"answer":0,"explanation":"Below it, even avoidable fixed costs are not covered, so closing saves money.","revision":"original","contentSignature":"27b86b797383e18c7b854907c73126b8eaa3416262a0af11d446e80a395faa16"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA350","optionFormat":"letter"},"contentSignature":"780a4552cfccdb6d2df151a76f5874334c356b7654e4ad7d6aa001db6c84e030","kind":"mcq"},{"id":"deep-management-MA351","sourceNumber":351,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"In accepting a SPECIAL (one-time) ORDER below normal price, the order is acceptable if:","options":["The price exceeds the fixed cost of the product, even if it does not cover the variable cost incurred in making and supplying it","The price exceeds the full cost of the product","Never acceptable at all, whatever the price of the order may be in any case of the business at all","PRICE EXCEEDS the INCREMENTAL COST and spare capacity exists (contribution is positive, no displacement of regular sales)"],"answer":3,"explanation":"With idle capacity, any price above marginal cost adds profit; if regular sales are displaced, lost contribution must also be covered.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA351","number":351,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"In accepting a SPECIAL (one-time) ORDER below normal price, the order is acceptable if:","options":[{"key":"A","text":"The price exceeds the fixed cost of the product, even if it does not cover the variable cost incurred in making and supplying it"},{"key":"B","text":"The price exceeds the full cost of the product"},{"key":"C","text":"Never acceptable at all, whatever the price of the order may be in any case of the business at all"},{"key":"D","text":"PRICE EXCEEDS the INCREMENTAL COST and spare capacity exists (contribution is positive, no displacement of regular sales)"}],"answer":"D","explanation":"With idle capacity, any price above marginal cost adds profit; if regular sales are displaced, lost contribution must also be covered.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"In accepting a SPECIAL (one-time) ORDER below normal price, the order is acceptable if:","options":["Price exceeds fixed cost","Price exceeds full cost","Never acceptable","PRICE EXCEEDS the INCREMENTAL COST and spare capacity exists (contribution is positive, no displacement of regular sales)"],"answer":3,"explanation":"With idle capacity, any price above marginal cost adds profit; if regular sales are displaced, lost contribution must also be covered.","revision":"original","contentSignature":"e970435b9129213403b8e4427fd740af8e917ec19943c831ef11b829c8c653cf"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA351","optionFormat":"letter"},"contentSignature":"75e9b29dc951a816b89c6183c1acacf8ea70643868949eab559cdaa53f3c3c71","kind":"mcq"},{"id":"deep-management-MA352","sourceNumber":352,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The EXPECTED VALUE of a decision under uncertainty =","options":["The SUM of each possible outcome MULTIPLIED BY its PROBABILITY","The worst outcome of the decision, whatever its probability of occurring","The best outcome of the decision, whatever its probability of occurring","The average outcome of the decision, without any weights of the probabilities"],"answer":0,"explanation":"EV = sum of (payoff x probability); it is the long-run average and the standard criterion under risk.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA352","number":352,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The EXPECTED VALUE of a decision under uncertainty =","options":[{"key":"A","text":"The SUM of each possible outcome MULTIPLIED BY its PROBABILITY"},{"key":"B","text":"The worst outcome of the decision, whatever its probability of occurring"},{"key":"C","text":"The best outcome of the decision, whatever its probability of occurring"},{"key":"D","text":"The average outcome of the decision, without any weights of the probabilities"}],"answer":"A","explanation":"EV = sum of (payoff x probability); it is the long-run average and the standard criterion under risk.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The EXPECTED VALUE of a decision under uncertainty =","options":["The SUM of each possible outcome MULTIPLIED BY its PROBABILITY","The worst outcome","The best outcome","The average outcome without weights"],"answer":0,"explanation":"EV = sum of (payoff x probability); it is the long-run average and the standard criterion under risk.","revision":"original","contentSignature":"84f0c3cde82861f1db7198dced5174590ca52221e13d0f8f4b2c093ed07c3fc0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA352","optionFormat":"letter"},"contentSignature":"b35549698b3d553ebea6a1d6a7be1b4ca673fce84e5ccc12635a9e7953592424","kind":"mcq"},{"id":"deep-management-MA353","sourceNumber":353,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"A project pays Rs.50,000 with probability 0.4 and Rs.20,000 with probability 0.6. Expected value is:","options":["Rs.70,000","Rs.35,000","Rs.32,000","Rs.30,000"],"answer":2,"explanation":"50,000 x 0.4 + 20,000 x 0.6 = 20,000 + 12,000 = Rs.32,000.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA353","number":353,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"A project pays Rs.50,000 with probability 0.4 and Rs.20,000 with probability 0.6. Expected value is:","options":[{"key":"A","text":"Rs.70,000"},{"key":"B","text":"Rs.35,000"},{"key":"C","text":"Rs.32,000"},{"key":"D","text":"Rs.30,000"}],"answer":"C","explanation":"50,000 x 0.4 + 20,000 x 0.6 = 20,000 + 12,000 = Rs.32,000.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA353","optionFormat":"letter"},"contentSignature":"b045511390a748c1cdb2add28d1626fd4097dc7373f656f0564991c0c9fa66c3","kind":"mcq"},{"id":"deep-management-MA354","sourceNumber":354,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The COEFFICIENT OF VARIATION (CV) measures:","options":["The total risk of the project taken by itself","The skewness of the distribution of the returns","STANDARD DEVIATION PER UNIT OF MEAN (CV = SD/Mean x 100) - RELATIVE risk, used to compare projects of different sizes","The central tendency of the returns"],"answer":2,"explanation":"CV normalises dispersion by the mean, making risk comparable across alternatives of different scale.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA354","number":354,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The COEFFICIENT OF VARIATION (CV) measures:","options":[{"key":"A","text":"The total risk of the project taken by itself"},{"key":"B","text":"The skewness of the distribution of the returns"},{"key":"C","text":"STANDARD DEVIATION PER UNIT OF MEAN (CV = SD/Mean x 100) - RELATIVE risk, used to compare projects of different sizes"},{"key":"D","text":"The central tendency of the returns"}],"answer":"C","explanation":"CV normalises dispersion by the mean, making risk comparable across alternatives of different scale.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The COEFFICIENT OF VARIATION (CV) measures:","options":["Total risk only","Skewness","STANDARD DEVIATION PER UNIT OF MEAN (CV = SD/Mean x 100) - RELATIVE risk, used to compare projects of different sizes","Central tendency"],"answer":2,"explanation":"CV normalises dispersion by the mean, making risk comparable across alternatives of different scale.","revision":"original","contentSignature":"dfe154b854f45399f76643687730cc7df85215d8531863ce128c3ef5f55e4ceb"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA354","optionFormat":"letter"},"contentSignature":"947a94394314d8e492946ccfae877b1a4e322a9fb27eb91df16bc365f9f239fa","kind":"mcq"},{"id":"deep-management-MA355","sourceNumber":355,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"For data 10, 20, 30, 40, 50, the arithmetic MEAN is:","options":["35","25","20","30"],"answer":3,"explanation":"Sum = 150; 150/5 = 30.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA355","number":355,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"For data 10, 20, 30, 40, 50, the arithmetic MEAN is:","options":[{"key":"A","text":"35"},{"key":"B","text":"25"},{"key":"C","text":"20"},{"key":"D","text":"30"}],"answer":"D","explanation":"Sum = 150; 150/5 = 30.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA355","optionFormat":"letter"},"contentSignature":"0ecab6c9ae7854e0ac6c0e5d371c3af140227ca59ab37286a693504dede20384","kind":"mcq"},{"id":"deep-management-MA356","sourceNumber":356,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The MEDIAN of 5, 15, 8, 25, 12 is:","options":["13","12","15","8"],"answer":1,"explanation":"Ordered: 5, 8, 12, 15, 25; the middle (3rd) value is 12.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA356","number":356,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The MEDIAN of 5, 15, 8, 25, 12 is:","options":[{"key":"A","text":"13"},{"key":"B","text":"12"},{"key":"C","text":"15"},{"key":"D","text":"8"}],"answer":"B","explanation":"Ordered: 5, 8, 12, 15, 25; the middle (3rd) value is 12.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA356","optionFormat":"letter"},"contentSignature":"99ce47d8d69fb719e985eb099625047167d8647ad5f194f2839c574336f3f33c","kind":"mcq"},{"id":"deep-management-MA357","sourceNumber":357,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The MODE is:","options":["The middle value of the series of data","The MOST FREQUENTLY OCCURRING value","The range of the series","The average of the series"],"answer":1,"explanation":"Mode = value with the highest frequency; a series can have no mode or more than one.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA357","number":357,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The MODE is:","options":[{"key":"A","text":"The middle value of the series of data"},{"key":"B","text":"The MOST FREQUENTLY OCCURRING value"},{"key":"C","text":"The range of the series"},{"key":"D","text":"The average of the series"}],"answer":"B","explanation":"Mode = value with the highest frequency; a series can have no mode or more than one.","source":"Original","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The MODE is:","options":["The middle value","The MOST FREQUENTLY OCCURRING value","The range","The average"],"answer":1,"explanation":"Mode = value with the highest frequency; a series can have no mode or more than one.","revision":"original","contentSignature":"eb982244ab672d637f7bb5a27c3d77b2dc5b98d3e702c7336ffdcf809a3b568c"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA357","optionFormat":"letter"},"contentSignature":"7ddf61847e923a00731b3c8d06317e5b3dba710eaafd69fc9a4d008bdb9f42d1","kind":"mcq"},{"id":"deep-management-MA358","sourceNumber":358,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The empirical relationship among mean, median and mode for a moderately skewed distribution is:","options":["Mode = Mean + Median","Mean = 3 Mode","Mean = Median = Mode","MODE = 3 MEDIAN - 2 MEAN"],"answer":3,"explanation":"Mode = 3 Median - 2 Mean (Karl Pearson empirical relation).","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA358","number":358,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The empirical relationship among mean, median and mode for a moderately skewed distribution is:","options":[{"key":"A","text":"Mode = Mean + Median"},{"key":"B","text":"Mean = 3 Mode"},{"key":"C","text":"Mean = Median = Mode"},{"key":"D","text":"MODE = 3 MEDIAN - 2 MEAN"}],"answer":"D","explanation":"Mode = 3 Median - 2 Mean (Karl Pearson empirical relation).","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA358","optionFormat":"letter"},"contentSignature":"040e3aaf6f19ed6dc7cc24d59c98eb8c3605158b1925fa46abe7314f09f42973","kind":"mcq"},{"id":"deep-management-MA359","sourceNumber":359,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"CORRELATION coefficient (r) ranges between:","options":["-1 AND +1","0 and 1","-100 and +100","0 and 100"],"answer":0,"explanation":"r = -1 is perfect negative, +1 perfect positive, 0 no linear correlation.","source":"Original · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA359","number":359,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"CORRELATION coefficient (r) ranges between:","options":[{"key":"A","text":"-1 AND +1"},{"key":"B","text":"0 and 1"},{"key":"C","text":"-100 and +100"},{"key":"D","text":"0 and 100"}],"answer":"A","explanation":"r = -1 is perfect negative, +1 perfect positive, 0 no linear correlation.","source":"Original","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA359","optionFormat":"letter"},"contentSignature":"b4baf3be2d9196e3dda739f4c17fc6ce4a0bcbbc32323542cb65e1f88190b05a","kind":"mcq"},{"id":"deep-management-MA360","sourceNumber":360,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M12 · Decision-Making & Statistical Basics","question":"The PAYBACK PERIOD method of evaluating decisions IGNORES:","options":["The initial cost of the project, as the thing ignored by the method of the payback","Cash flows BEYOND the payback period (post-payback profitability) and the time value of money","The cash outflows of the project, as the thing ignored by the method of the payback","The revenue of the project, as the thing ignored by the method of the payback"],"answer":1,"explanation":"Its two classic defects: no discounting, and total disregard of flows after the cut-off.","source":"Recall 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA360","number":360,"module":"M12","moduleTitle":"Decision-Making & Statistical Basics","question":"The PAYBACK PERIOD method of evaluating decisions IGNORES:","options":[{"key":"A","text":"The initial cost of the project, as the thing ignored by the method of the payback"},{"key":"B","text":"Cash flows BEYOND the payback period (post-payback profitability) and the time value of money"},{"key":"C","text":"The cash outflows of the project, as the thing ignored by the method of the payback"},{"key":"D","text":"The revenue of the project, as the thing ignored by the method of the payback"}],"answer":"B","explanation":"Its two classic defects: no discounting, and total disregard of flows after the cut-off.","source":"Recall 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The PAYBACK PERIOD method of evaluating decisions IGNORES:","options":["Initial cost","Cash flows BEYOND the payback period (post-payback profitability) and the time value of money","Cash outflows","Revenue"],"answer":1,"explanation":"Its two classic defects: no discounting, and total disregard of flows after the cut-off.","revision":"original","contentSignature":"d2080a411112f56236c1c4f2a59cc4f25208b4fa0ad69d817942cd46a1c68ba5"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA360","optionFormat":"letter"},"contentSignature":"7d9316345932333a2ff04f0d4ba6a02786209d3e0eb923255f0e4d5fcef647a6","kind":"mcq"},{"id":"deep-management-MA361","sourceNumber":361,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"When current ratio is 2:1 and if there are EQUAL increases in current assets and current liabilities then what would be the result?","options":["Current ratio will double","Increase in current ratio","DECREASE in current ratio","No change in current ratio"],"answer":2,"explanation":"Check: CA 200, CL 100 (CR 2). Add 50 to both: 250/150 = 1.67. An equal addition lowers a ratio above 1.","source":"PYQ: UGC NET Commerce, 2020-Oct-E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA361","number":361,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"When current ratio is 2:1 and if there are EQUAL increases in current assets and current liabilities then what would be the result?","options":[{"key":"A","text":"Current ratio will double"},{"key":"B","text":"Increase in current ratio"},{"key":"C","text":"DECREASE in current ratio"},{"key":"D","text":"No change in current ratio"}],"answer":"C","explanation":"Check: CA 200, CL 100 (CR 2). Add 50 to both: 250/150 = 1.67. An equal addition lowers a ratio above 1.","source":"PYQ: UGC NET Commerce, 2020-Oct-E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA361","optionFormat":"letter"},"contentSignature":"6dff3cdb07975bca7055cd4a5cd6c9ab88183930c9b34c2c445fc6af7190b114","kind":"pyq"},{"id":"deep-management-MA362","sourceNumber":362,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match: (I) Inability to pay interest (II) Liquidity crisis (III) Inefficient collection of receivables (IV) Return of shareholders fund being much higher than the overall return on investment - with ratios: (1) Current ratio (2) Debtors turnover ratio (3) Interest coverage ratio (4) Debt-equity ratio","options":["I-2, II-3, III-1, IV-4","I-3, II-2, III-1, IV-4","I-3, II-1, III-2, IV-4","I-1, II-2, III-3, IV-4"],"answer":2,"explanation":"Interest payment ability is tested by interest coverage (I-3); liquidity by current ratio (II-1); collection efficiency by debtors turnover (III-2); equity return far above ROI signals high leverage, shown by debt-equity (IV-4).","source":"PYQ: UGC NET Commerce, 2020-Oct-E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA362","number":362,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match: (I) Inability to pay interest (II) Liquidity crisis (III) Inefficient collection of receivables (IV) Return of shareholders fund being much higher than the overall return on investment - with ratios: (1) Current ratio (2) Debtors turnover ratio (3) Interest coverage ratio (4) Debt-equity ratio","options":[{"key":"A","text":"I-2, II-3, III-1, IV-4"},{"key":"B","text":"I-3, II-2, III-1, IV-4"},{"key":"C","text":"I-3, II-1, III-2, IV-4"},{"key":"D","text":"I-1, II-2, III-3, IV-4"}],"answer":"C","explanation":"Interest payment ability is tested by interest coverage (I-3); liquidity by current ratio (II-1); collection efficiency by debtors turnover (III-2); equity return far above ROI signals high leverage, shown by debt-equity (IV-4).","source":"PYQ: UGC NET Commerce, 2020-Oct-E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA362","optionFormat":"letter"},"contentSignature":"5418e5a442a88a73b74673bfaeebb837eb84c720a4c12959c34e10f8b2ff2c4a","kind":"pyq"},{"id":"deep-management-MA363","sourceNumber":363,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"In which situations is the PAYBACK PERIOD method advised for evaluating investment opportunities? I. Overleveraged businesses II. Cash rich businesses III. Uncertain market conditions IV. Stable market conditions","options":["I and III only","III and IV only","I and II only","II and III only"],"answer":0,"explanation":"Payback suits firms that need quick cash recovery (for example overleveraged firms) and firms facing uncertain markets, because early recovery cuts risk. Stable market conditions by themselves do not make payback preferable. The correct combination is **I and III**.","source":"PYQ: UGC NET Commerce, 2020-Oct-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA363","number":363,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"In which situations is the PAYBACK PERIOD method advised for evaluating investment opportunities? I. Overleveraged businesses II. Cash rich businesses III. Uncertain market conditions IV. Stable market conditions","options":[{"key":"A","text":"I and III only"},{"key":"B","text":"III and IV only"},{"key":"C","text":"I and II only"},{"key":"D","text":"II and III only"}],"answer":"A","explanation":"Payback suits firms that need quick cash recovery (for example overleveraged firms) and firms facing uncertain markets, because early recovery cuts risk. Stable market conditions by themselves do not make payback preferable. The correct combination is **I and III**.","source":"PYQ: UGC NET Commerce, 2020-Oct-M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA363","optionFormat":"letter"},"contentSignature":"21563164a1ba9cfe086aeb96d6e780d2dde4a1063fb1a22cf04fe4b08b304f97","kind":"pyq"},{"id":"deep-management-MA364","sourceNumber":364,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"NPV and IRR methods yield CONFLICTING outcomes due to: I. Unconventional cash flows II. Investment size disparity III. Investment life disparity IV. Cash flow pattern disparity","options":["II and III only","II, III and IV only","I and II only","I, II and III only"],"answer":1,"explanation":"Conflicts arise from differences in scale (size), life and the timing pattern of flows. Unconventional flows cause MULTIPLE IRRs, a different problem.","source":"PYQ: UGC NET Commerce, 2020-Oct-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA364","number":364,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"NPV and IRR methods yield CONFLICTING outcomes due to: I. Unconventional cash flows II. Investment size disparity III. Investment life disparity IV. Cash flow pattern disparity","options":[{"key":"A","text":"II and III only"},{"key":"B","text":"II, III and IV only"},{"key":"C","text":"I and II only"},{"key":"D","text":"I, II and III only"}],"answer":"B","explanation":"Conflicts arise from differences in scale (size), life and the timing pattern of flows. Unconventional flows cause MULTIPLE IRRs, a different problem.","source":"PYQ: UGC NET Commerce, 2020-Oct-M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA364","optionFormat":"letter"},"contentSignature":"7729baf277b9abe5647de8f2be1d531865d3817b9622f3110704c614c0708624","kind":"pyq"},{"id":"deep-management-MA365","sourceNumber":365,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The value of the firm in the wealth maximisation objective is measured by:","options":["Present value of all expected future profits","All expected future profits","All expected future cash flows","PRESENT VALUE OF ALL EXPECTED FUTURE CASH FLOWS"],"answer":3,"explanation":"Wealth maximisation discounts expected future **cash flows** (not accounting profits) at an appropriate rate. Benefits are measured as cash flows because profit figures include non-cash items and accounting conventions.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA365","number":365,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The value of the firm in the wealth maximisation objective is measured by:","options":[{"key":"A","text":"Present value of all expected future profits"},{"key":"B","text":"All expected future profits"},{"key":"C","text":"All expected future cash flows"},{"key":"D","text":"PRESENT VALUE OF ALL EXPECTED FUTURE CASH FLOWS"}],"answer":"D","explanation":"Wealth maximisation discounts expected future **cash flows** (not accounting profits) at an appropriate rate. Benefits are measured as cash flows because profit figures include non-cash items and accounting conventions.","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA365","optionFormat":"letter"},"contentSignature":"66bcd6cb6a163611922ad8738326c6dd8d1ee03b251b78a47721fbd894f2345d","kind":"pyq"},{"id":"deep-management-MA366","sourceNumber":366,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which rules stand true while preparing a schedule of changes in working capital? 1. An increase in current assets increases working capital 2. An increase in current assets decreases working capital 3. An increase in current liabilities decreases working capital 4. An increase in current liabilities increases working capital","options":["1, 2 and 3 only","2 and 4 only","1 and 4 only","1 and 3 only"],"answer":3,"explanation":"WC = CA - CL: more current assets raise it (1 true); more current liabilities reduce it (3 true).","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA366","number":366,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which rules stand true while preparing a schedule of changes in working capital? 1. An increase in current assets increases working capital 2. An increase in current assets decreases working capital 3. An increase in current liabilities decreases working capital 4. An increase in current liabilities increases working capital","options":[{"key":"A","text":"1, 2 and 3 only"},{"key":"B","text":"2 and 4 only"},{"key":"C","text":"1 and 4 only"},{"key":"D","text":"1 and 3 only"}],"answer":"D","explanation":"WC = CA - CL: more current assets raise it (1 true); more current liabilities reduce it (3 true).","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA366","optionFormat":"letter"},"contentSignature":"07c8a9a5e2735292aa3d3129e705041dad6ed75a8e00a332975bfc8eaa15de97","kind":"pyq"},{"id":"deep-management-MA367","sourceNumber":367,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match the risk types: (a) Market risk (b) Financial risk (c) External business risk (d) Internal business risk - with: (i) efficiency with which a firm conducts its operations (ii) change in operating conditions thrust upon the firm beyond its control (iii) price variations sparked by real, social, political and economic events (iv) associated with the capital structure","options":["(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)","(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)","(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)","(a)-(iii), (b)-(i), (c)-(ii), (d)-(iv)"],"answer":2,"explanation":"Market risk = price changes from external events (iii); financial risk = capital structure (iv); external business risk = uncontrollable operating conditions (ii); internal business risk = operational efficiency (i).","source":"PYQ: UGC NET Commerce, 2021-Nov-25M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA367","number":367,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match the risk types: (a) Market risk (b) Financial risk (c) External business risk (d) Internal business risk - with: (i) efficiency with which a firm conducts its operations (ii) change in operating conditions thrust upon the firm beyond its control (iii) price variations sparked by real, social, political and economic events (iv) associated with the capital structure","options":[{"key":"A","text":"(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)"},{"key":"B","text":"(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)"},{"key":"C","text":"(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)"},{"key":"D","text":"(a)-(iii), (b)-(i), (c)-(ii), (d)-(iv)"}],"answer":"C","explanation":"Market risk = price changes from external events (iii); financial risk = capital structure (iv); external business risk = uncontrollable operating conditions (ii); internal business risk = operational efficiency (i).","source":"PYQ: UGC NET Commerce, 2021-Nov-25M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA367","optionFormat":"letter"},"contentSignature":"a577839964c8aca1fa3020428666f3fc1669c5b89d68131a9194b2bc4b15860d","kind":"pyq"},{"id":"deep-management-MA368","sourceNumber":368,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The cash flow approach to assessing DEBT CAPACITY involves these steps - arrange in sequence: (1) Specify the tolerance limit on probability of default (2) Estimate the probability distribution of cash flows (3) Calculate fixed charges (interest + principal) at various debt levels (4) Estimate debt capacity as the highest acceptable level of debt","options":["2, 3, 4, 1","4, 3, 1, 2","4, 1, 3, 2","1, 2, 3, 4"],"answer":3,"explanation":"Policy first: set the acceptable default probability (1), then estimate the cash flow distribution (2), compute fixed charges at each debt level (3), and pick the highest acceptable debt (4).","source":"PYQ: UGC NET Commerce, 2021-Nov-25E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA368","number":368,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The cash flow approach to assessing DEBT CAPACITY involves these steps - arrange in sequence: (1) Specify the tolerance limit on probability of default (2) Estimate the probability distribution of cash flows (3) Calculate fixed charges (interest + principal) at various debt levels (4) Estimate debt capacity as the highest acceptable level of debt","options":[{"key":"A","text":"2, 3, 4, 1"},{"key":"B","text":"4, 3, 1, 2"},{"key":"C","text":"4, 1, 3, 2"},{"key":"D","text":"1, 2, 3, 4"}],"answer":"D","explanation":"Policy first: set the acceptable default probability (1), then estimate the cash flow distribution (2), compute fixed charges at each debt level (3), and pick the highest acceptable debt (4).","source":"PYQ: UGC NET Commerce, 2021-Nov-25E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA368","optionFormat":"letter"},"contentSignature":"21dc1707c304fd2f193ecdc1697fdf0ca7ef7a6cbc25bc4d5d10700edce598c1","kind":"pyq"},{"id":"deep-management-MA369","sourceNumber":369,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Select the right option with reference to working capital:","options":["The TRADE-OFF plan, in general, is considered an appropriate financing strategy for working capital","Higher net working capital leads to higher liquidity and higher profitability","There is an inverse relationship between the length of the operating cycle and working capital requirements","According to the hedging approach, current assets should be financed from long-term sources"],"answer":0,"explanation":"The other options fail: higher net WC raises liquidity but CUTS profitability; the hedging approach finances only the PERMANENT part from long-term sources; and cycle length is DIRECTLY related to WC needs. The trade-off/matching plan is the generally appropriate strategy.","source":"PYQ: UGC NET Commerce, 2022-Oct-29E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA369","number":369,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Select the right option with reference to working capital:","options":[{"key":"A","text":"The TRADE-OFF plan, in general, is considered an appropriate financing strategy for working capital"},{"key":"B","text":"Higher net working capital leads to higher liquidity and higher profitability"},{"key":"C","text":"There is an inverse relationship between the length of the operating cycle and working capital requirements"},{"key":"D","text":"According to the hedging approach, current assets should be financed from long-term sources"}],"answer":"A","explanation":"The other options fail: higher net WC raises liquidity but CUTS profitability; the hedging approach finances only the PERMANENT part from long-term sources; and cycle length is DIRECTLY related to WC needs. The trade-off/matching plan is the generally appropriate strategy.","source":"PYQ: UGC NET Commerce, 2022-Oct-29E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA369","optionFormat":"letter"},"contentSignature":"349659fa8bebb87084c24bdb29cd5068f566545a1b9a468d35d3eb50fd61e82e","kind":"pyq"},{"id":"deep-management-MA370","sourceNumber":370,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Arrange in ASCENDING order of significance in predicting industrial sickness (Altman, 1966): A. Working Capital/Total Assets B. Retained Earnings/Total Assets C. EBIT/Total Assets D. Market Value of Equity/Book Value of Debt E. Sales/Total Assets","options":["C, E, B, D, A","E, B, D, C, A","D, E, A, B, C","B, D, C, A, E"],"answer":2,"explanation":"Altman weights: D 0.6 < E 1.0 < A 1.2 < B 1.4 < C 3.3 - ascending D, E, A, B, C.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA370","number":370,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Arrange in ASCENDING order of significance in predicting industrial sickness (Altman, 1966): A. Working Capital/Total Assets B. Retained Earnings/Total Assets C. EBIT/Total Assets D. Market Value of Equity/Book Value of Debt E. Sales/Total Assets","options":[{"key":"A","text":"C, E, B, D, A"},{"key":"B","text":"E, B, D, C, A"},{"key":"C","text":"D, E, A, B, C"},{"key":"D","text":"B, D, C, A, E"}],"answer":"C","explanation":"Altman weights: D 0.6 < E 1.0 < A 1.2 < B 1.4 < C 3.3 - ascending D, E, A, B, C.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA370","optionFormat":"letter"},"contentSignature":"126653f44c6321a38ae26100e3a7bbaae213a9d21ec01e8fc2889e5d76b76542","kind":"pyq"},{"id":"deep-management-MA371","sourceNumber":371,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"As per which approach does a firm finance a part of its PERMANENT working capital with SHORT-TERM financing?","options":["AGGRESSIVE approach","Conservative approach","Matching approach","Traditional approach"],"answer":0,"explanation":"The aggressive approach funds even part of the permanent WC need with short-term credit - higher return, higher risk.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA371","number":371,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"As per which approach does a firm finance a part of its PERMANENT working capital with SHORT-TERM financing?","options":[{"key":"A","text":"AGGRESSIVE approach"},{"key":"B","text":"Conservative approach"},{"key":"C","text":"Matching approach"},{"key":"D","text":"Traditional approach"}],"answer":"A","explanation":"The aggressive approach funds even part of the permanent WC need with short-term credit - higher return, higher risk.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA371","optionFormat":"letter"},"contentSignature":"14118c43d7ae9d65c078705ebb8c87313caa9377fa5efd1b276843e8305d7b3c","kind":"pyq"},{"id":"deep-management-MA372","sourceNumber":372,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which approach of capital structure pleads that debt financing INITIALLY INCREASES the value of the firm, but excess debt beyond a point REDUCES it?","options":["Net income approach","Net operating income approach","TRADITIONAL approach","Modigliani-Miller approach"],"answer":2,"explanation":"The traditional (intermediate) approach: Ko falls then rises with leverage, so an optimal structure exists.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA372","number":372,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which approach of capital structure pleads that debt financing INITIALLY INCREASES the value of the firm, but excess debt beyond a point REDUCES it?","options":[{"key":"A","text":"Net income approach"},{"key":"B","text":"Net operating income approach"},{"key":"C","text":"TRADITIONAL approach"},{"key":"D","text":"Modigliani-Miller approach"}],"answer":"C","explanation":"The traditional (intermediate) approach: Ko falls then rises with leverage, so an optimal structure exists.","source":"PYQ: UGC NET Commerce, 2022-Oct-29M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA372","optionFormat":"letter"},"contentSignature":"75123b73579152f25551cae2d0e7db39a28851edbd1cf601e61c47e0ae312a70","kind":"pyq"},{"id":"deep-management-MA373","sourceNumber":373,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"According to the TRADITIONAL approach, what is the effect of an increase in the degree of leverage on the valuation of a firm?","options":["INCREASES FIRST AND THEN DECREASES","Decreases as the level of activity rises","Remains unaffected by the change","Increases as the level of activity rises"],"answer":0,"explanation":"Under the traditional approach, moderate leverage raises firm value as cheaper debt replaces equity, but excessive leverage cuts value as Ke and Kd climb with financial risk. Saying value simply “increases” with leverage is the net income view, not the traditional view.","source":"PYQ: UGC NET Commerce, 2023-Mar-E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA373","number":373,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"According to the TRADITIONAL approach, what is the effect of an increase in the degree of leverage on the valuation of a firm?","options":[{"key":"A","text":"INCREASES FIRST AND THEN DECREASES"},{"key":"B","text":"Decreases as the level of activity rises"},{"key":"C","text":"Remains unaffected by the change"},{"key":"D","text":"Increases as the level of activity rises"}],"answer":"A","explanation":"Under the traditional approach, moderate leverage raises firm value as cheaper debt replaces equity, but excessive leverage cuts value as Ke and Kd climb with financial risk. Saying value simply “increases” with leverage is the net income view, not the traditional view.","source":"PYQ: UGC NET Commerce, 2023-Mar-E","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"According to the TRADITIONAL approach, what is the effect of an increase in the degree of leverage on the valuation of a firm?","options":["INCREASES FIRST AND THEN DECREASES","Decreases","Remains unaffected","Increases"],"answer":0,"explanation":"Moderate leverage raises value; excessive leverage cuts it as Ke and Kd climb. NOTE: the official key said \"increases\" - wrong; that is the NET INCOME view.","revision":"original","contentSignature":"b1a6f86a0441a9ccb64cb157c8d89134279763b956b03a1565e401caf6ba93d0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA373","optionFormat":"letter"},"contentSignature":"883f32d1caedff0f2b619d7ee3aeb9379f00976aa21e436589f184fe6e151394","kind":"pyq"},{"id":"deep-management-MA374","sourceNumber":374,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which activities are included under INVESTING activities in the cash flow statement? a. Cash receipts from disposal of fixed assets (including intangibles) b. Cash advances and loans made to third parties (other than by a financial enterprise) c. Cash receipts from repayment of such advances and loans d. Cash repayments of amounts borrowed e. Cash payments to suppliers for goods and services","options":["a, c and d only","c, d and e only","c and d only","a, b and c only"],"answer":3,"explanation":"Disposal of fixed assets, and third-party advances/loans made and repaid, are investing; (d) borrowing repayment is financing and (e) supplier payment is operating.","source":"PYQ: UGC NET Commerce, 2023-Mar-E · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA374","number":374,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which activities are included under INVESTING activities in the cash flow statement? a. Cash receipts from disposal of fixed assets (including intangibles) b. Cash advances and loans made to third parties (other than by a financial enterprise) c. Cash receipts from repayment of such advances and loans d. Cash repayments of amounts borrowed e. Cash payments to suppliers for goods and services","options":[{"key":"A","text":"a, c and d only"},{"key":"B","text":"c, d and e only"},{"key":"C","text":"c and d only"},{"key":"D","text":"a, b and c only"}],"answer":"D","explanation":"Disposal of fixed assets, and third-party advances/loans made and repaid, are investing; (d) borrowing repayment is financing and (e) supplier payment is operating.","source":"PYQ: UGC NET Commerce, 2023-Mar-E","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA374","optionFormat":"letter"},"contentSignature":"1333d5f27d9e7ff988bfb21185c95ca742b34c0bb2fa0b211e09e921371f1cd0","kind":"pyq"},{"id":"deep-management-MA375","sourceNumber":375,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which factors determine the working capital requirements of a firm? a. Nature of business b. Technology and manufacturing policy c. Management skills d. Credit policy e. Market and demand conditions","options":["a, b and e only","c, d and e only","a, b, d and e only","a, b, c and d only"],"answer":2,"explanation":"WC needs depend on the nature of business, technology/manufacturing policy, credit policy, and market/demand conditions - management skill is not a listed determinant.","source":"PYQ: UGC NET Commerce, 2023-Mar-M · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA375","number":375,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which factors determine the working capital requirements of a firm? a. Nature of business b. Technology and manufacturing policy c. Management skills d. Credit policy e. Market and demand conditions","options":[{"key":"A","text":"a, b and e only"},{"key":"B","text":"c, d and e only"},{"key":"C","text":"a, b, d and e only"},{"key":"D","text":"a, b, c and d only"}],"answer":"C","explanation":"WC needs depend on the nature of business, technology/manufacturing policy, credit policy, and market/demand conditions - management skill is not a listed determinant.","source":"PYQ: UGC NET Commerce, 2023-Mar-M","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA375","optionFormat":"letter"},"contentSignature":"803aa5400335f9a58663404107291d098a66e528bef817cdea8144e280e8dd1e","kind":"pyq"},{"id":"deep-management-MA376","sourceNumber":376,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which are the approaches of determining the financing mix for working capital? A. Matching approach B. Conservative approach C. Operating cycle approach D. Aggressive approach","options":["B, C and D only","A, C and D only","A, B and D only","A, B and C only"],"answer":2,"explanation":"The three financing-mix approaches are matching, conservative and aggressive; the operating cycle approach estimates the QUANTUM of WC, not its financing mix.","source":"PYQ: UGC NET Commerce, 2025-Dec · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA376","number":376,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which are the approaches of determining the financing mix for working capital? A. Matching approach B. Conservative approach C. Operating cycle approach D. Aggressive approach","options":[{"key":"A","text":"B, C and D only"},{"key":"B","text":"A, C and D only"},{"key":"C","text":"A, B and D only"},{"key":"D","text":"A, B and C only"}],"answer":"C","explanation":"The three financing-mix approaches are matching, conservative and aggressive; the operating cycle approach estimates the QUANTUM of WC, not its financing mix.","source":"PYQ: UGC NET Commerce, 2025-Dec","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA376","optionFormat":"letter"},"contentSignature":"e3603be4846ef2f7ce7e01309662b566dc1d1095a7dd85fa1f6f85b489d1aad9","kind":"pyq"},{"id":"deep-management-MA377","sourceNumber":377,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"An infinite series of equal cash flows occurring at regular time intervals is known as:","options":["A PERPETUITY","An annuity due","An annuity","Future value"],"answer":0,"explanation":"A perpetuity never ends; an annuity has a fixed term.","source":"PYQ: UGC NET Commerce, 2025-Dec · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA377","number":377,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"An infinite series of equal cash flows occurring at regular time intervals is known as:","options":[{"key":"A","text":"A PERPETUITY"},{"key":"B","text":"An annuity due"},{"key":"C","text":"An annuity"},{"key":"D","text":"Future value"}],"answer":"A","explanation":"A perpetuity never ends; an annuity has a fixed term.","source":"PYQ: UGC NET Commerce, 2025-Dec","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA377","optionFormat":"letter"},"contentSignature":"c14374c74286a573867e6196389a13c8e6e7d7aa9fe50c3621ad621fde7d87de","kind":"pyq"},{"id":"deep-management-MA378","sourceNumber":378,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which of the following ratios is also termed a LEVERAGE ratio?","options":["Solvency ratio","Proprietary ratio","DEBT-EQUITY RATIO","Interest coverage ratio"],"answer":2,"explanation":"Debt-equity expresses the relative claims of outsiders and owners - the classic capital-gearing/leverage measure.","source":"PYQ: SSC CGL AAO, 2017 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA378","number":378,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which of the following ratios is also termed a LEVERAGE ratio?","options":[{"key":"A","text":"Solvency ratio"},{"key":"B","text":"Proprietary ratio"},{"key":"C","text":"DEBT-EQUITY RATIO"},{"key":"D","text":"Interest coverage ratio"}],"answer":"C","explanation":"Debt-equity expresses the relative claims of outsiders and owners - the classic capital-gearing/leverage measure.","source":"PYQ: SSC CGL AAO, 2017","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA378","optionFormat":"letter"},"contentSignature":"1113edabf073589a911daf1e67612a110af309da436a81045c476fd82e10bcdc","kind":"pyq"},{"id":"deep-management-MA379","sourceNumber":379,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Proceeds from the sale of a PATENT are classified under which activity in the cash flow statement?","options":["Financing","Operating","INVESTING","Cash equivalents"],"answer":2,"explanation":"A patent is an intangible fixed asset; its disposal proceeds are an investing inflow under AS-3.","source":"PYQ: SSC CGL AAO, 2017 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA379","number":379,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Proceeds from the sale of a PATENT are classified under which activity in the cash flow statement?","options":[{"key":"A","text":"Financing"},{"key":"B","text":"Operating"},{"key":"C","text":"INVESTING"},{"key":"D","text":"Cash equivalents"}],"answer":"C","explanation":"A patent is an intangible fixed asset; its disposal proceeds are an investing inflow under AS-3.","source":"PYQ: SSC CGL AAO, 2017","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA379","optionFormat":"letter"},"contentSignature":"2f9972572d9537b527d252a9f3568d0a244b0a80c3a293036b4f79cbda313f2f","kind":"pyq"},{"id":"deep-management-MA380","sourceNumber":380,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which statements are correct about the PAYBACK PERIOD? I. It is expressed in number of years II. Acceptable payback may vary across industries by risk tolerance and capital structure III. It takes into account the time value of money IV. It ignores profitability measures V. It considers cash flows beyond the payback period","options":["I, II and IV only","I, III and V only","I, III and IV only","I, II and V only"],"answer":0,"explanation":"Payback is in years (I), norms vary by industry (II) and it ignores both profitability and post-payback flows (IV true, III and V false).","source":"PYQ: JAIIB AFM, 2023 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA380","number":380,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which statements are correct about the PAYBACK PERIOD? I. It is expressed in number of years II. Acceptable payback may vary across industries by risk tolerance and capital structure III. It takes into account the time value of money IV. It ignores profitability measures V. It considers cash flows beyond the payback period","options":[{"key":"A","text":"I, II and IV only"},{"key":"B","text":"I, III and V only"},{"key":"C","text":"I, III and IV only"},{"key":"D","text":"I, II and V only"}],"answer":"A","explanation":"Payback is in years (I), norms vary by industry (II) and it ignores both profitability and post-payback flows (IV true, III and V false).","source":"PYQ: JAIIB AFM, 2023","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA380","optionFormat":"letter"},"contentSignature":"d1446e5cc0edb6c2c1b6ee999c22d1d7811d0d28aec579c61611045fa5547259","kind":"pyq"},{"id":"deep-management-MA381","sourceNumber":381,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Cash payment for SELF-CONSTRUCTED property is classified as:","options":["Cash flow from INVESTING activities","Cash flow from operating activities","Either investing or operating","Cash flow from financing activities"],"answer":0,"explanation":"Payments to acquire/construct fixed assets - including self-constructed property - are investing outflows.","source":"PYQ: JAIIB AFM, 2023 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA381","number":381,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Cash payment for SELF-CONSTRUCTED property is classified as:","options":[{"key":"A","text":"Cash flow from INVESTING activities"},{"key":"B","text":"Cash flow from operating activities"},{"key":"C","text":"Either investing or operating"},{"key":"D","text":"Cash flow from financing activities"}],"answer":"A","explanation":"Payments to acquire/construct fixed assets - including self-constructed property - are investing outflows.","source":"PYQ: JAIIB AFM, 2023","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA381","optionFormat":"letter"},"contentSignature":"f6407f47c57482fc3ae072c9bf91785f99ea97dd3bbfa8008ecd2f392f495a4a","kind":"pyq"},{"id":"deep-management-MA382","sourceNumber":382,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The DEGREE OF FINANCIAL LEVERAGE may be defined as:","options":["Percent change in EPS / percent change in sales","Percent change in sales / percent change in volume","Percent change in EPS / percent change in net income","PERCENT CHANGE IN EPS / PERCENT CHANGE IN EBIT"],"answer":3,"explanation":"DFL = % change in EPS / % change in EBIT = EBIT/EBT.","source":"PYQ: NABARD Grade A Finance, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA382","number":382,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The DEGREE OF FINANCIAL LEVERAGE may be defined as:","options":[{"key":"A","text":"Percent change in EPS / percent change in sales"},{"key":"B","text":"Percent change in sales / percent change in volume"},{"key":"C","text":"Percent change in EPS / percent change in net income"},{"key":"D","text":"PERCENT CHANGE IN EPS / PERCENT CHANGE IN EBIT"}],"answer":"D","explanation":"DFL = % change in EPS / % change in EBIT = EBIT/EBT.","source":"PYQ: NABARD Grade A Finance, 2020","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA382","optionFormat":"letter"},"contentSignature":"b31d8d954ee6e884f17358587d34234d3db33ff044d5bbc3845305e404fd74e8","kind":"pyq"},{"id":"deep-management-MA383","sourceNumber":383,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which of the following best describes WORKING CAPITAL?","options":["Cash + inventory","Capital contributed by the owners","CURRENT ASSETS - CURRENT LIABILITIES","Total assets - liabilities"],"answer":2,"explanation":"Net working capital = CA - CL.","source":"PYQ: NABARD Grade A Finance, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA383","number":383,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Which of the following best describes WORKING CAPITAL?","options":[{"key":"A","text":"Cash + inventory"},{"key":"B","text":"Capital contributed by the owners"},{"key":"C","text":"CURRENT ASSETS - CURRENT LIABILITIES"},{"key":"D","text":"Total assets - liabilities"}],"answer":"C","explanation":"Net working capital = CA - CL.","source":"PYQ: NABARD Grade A Finance, 2020","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA383","optionFormat":"letter"},"contentSignature":"7c326638458ab502a72937c99d47f6128722da76471499ddc8c1d8a84903d7f3","kind":"pyq"},{"id":"deep-management-MA384","sourceNumber":384,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match the tests: I. Test of liquidity II. Test of profitability III. Test of solvency IV. Test of activity - with: A. ROI B. Debtors turnover C. Acid- test ratio D. Debt-equity ratio","options":["I-A, II-B, III-C, IV-D","I-C, II-D, III-B, IV-A","I-B, II-C, III-A, IV-D","I-C, II-A, III-D, IV-B"],"answer":3,"explanation":"Liquidity - acid test (I-C); profitability - ROI (II-A); solvency - debt-equity (III-D); activity - debtors turnover (IV-B).","source":"PYQ: NABARD Grade A Finance, 2020 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA384","number":384,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Match the tests: I. Test of liquidity II. Test of profitability III. Test of solvency IV. Test of activity - with: A. ROI B. Debtors turnover C. Acid- test ratio D. Debt-equity ratio","options":[{"key":"A","text":"I-A, II-B, III-C, IV-D"},{"key":"B","text":"I-C, II-D, III-B, IV-A"},{"key":"C","text":"I-B, II-C, III-A, IV-D"},{"key":"D","text":"I-C, II-A, III-D, IV-B"}],"answer":"D","explanation":"Liquidity - acid test (I-C); profitability - ROI (II-A); solvency - debt-equity (III-D); activity - debtors turnover (IV-B).","source":"PYQ: NABARD Grade A Finance, 2020","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA384","optionFormat":"letter"},"contentSignature":"f6b0f859607a0e38fda6c0091a9b537e34784171a431b1f55f02d2110bb243f7","kind":"pyq"},{"id":"deep-management-MA385","sourceNumber":385,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Payback period is the time required to:","options":["Earn the maximum profit from the project","RECOVER the ORIGINAL INVESTMENT out of the project cash inflows","Reach the break-even point of the project at the earliest date possible","Pay all the taxes relating to the project"],"answer":1,"explanation":"Payback = years for cumulative cash inflows to equal the initial outlay.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA385","number":385,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Payback period is the time required to:","options":[{"key":"A","text":"Earn the maximum profit from the project"},{"key":"B","text":"RECOVER the ORIGINAL INVESTMENT out of the project cash inflows"},{"key":"C","text":"Reach the break-even point of the project at the earliest date possible"},{"key":"D","text":"Pay all the taxes relating to the project"}],"answer":"B","explanation":"Payback = years for cumulative cash inflows to equal the initial outlay.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Payback period is the time required to:","options":["Earn maximum profit","RECOVER the ORIGINAL INVESTMENT out of the project cash inflows","Reach BEP","Pay all taxes"],"answer":1,"explanation":"Payback = years for cumulative cash inflows to equal the initial outlay.","revision":"original","contentSignature":"660ef0835ecf809f12925bbe89702a9346458729c7eaa9f78342760462086246"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA385","optionFormat":"letter"},"contentSignature":"9377545fc3d054c45e0a353746fd87b240d65b2de7e112dbbf6dfb7b84581c13","kind":"mcq"},{"id":"deep-management-MA386","sourceNumber":386,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Post-payback profitability is:","options":["The ARR of the project, as the accounting rate of return earned on the investment over its life","The earnings/cash inflows generated AFTER the payback period - IGNORED by the payback method","The total profit earned by the project","Zero in the case of every project"],"answer":1,"explanation":"The payback method cuts off at recovery; later inflows (post-payback profitability) are invisible to it - its classic weakness.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA386","number":386,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Post-payback profitability is:","options":[{"key":"A","text":"The ARR of the project, as the accounting rate of return earned on the investment over its life"},{"key":"B","text":"The earnings/cash inflows generated AFTER the payback period - IGNORED by the payback method"},{"key":"C","text":"The total profit earned by the project"},{"key":"D","text":"Zero in the case of every project"}],"answer":"B","explanation":"The payback method cuts off at recovery; later inflows (post-payback profitability) are invisible to it - its classic weakness.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Post-payback profitability is:","options":["The ARR","The earnings/cash inflows generated AFTER the payback period - IGNORED by the payback method","Total profit","Zero"],"answer":1,"explanation":"The payback method cuts off at recovery; later inflows (post-payback profitability) are invisible to it - its classic weakness.","revision":"original","contentSignature":"64f887e409694e9822b72466d33f5d6c4887e2405ae215d2b08264a82456f45f"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA386","optionFormat":"letter"},"contentSignature":"53c06f041e97e53999d2c3e4529177ce9d24db64c88384615d1f5dd44cdb3f11","kind":"mcq"},{"id":"deep-management-MA387","sourceNumber":387,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Discounting is the inverse of:","options":["The amortisation of an asset","The leverage of the firm","The depreciation of an asset","COMPOUNDING (compounding finds future value; discounting finds present value)"],"answer":3,"explanation":"FV = PV(1+r)^n and PV = FV/(1+r)^n are mirror processes.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA387","number":387,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Discounting is the inverse of:","options":[{"key":"A","text":"The amortisation of an asset"},{"key":"B","text":"The leverage of the firm"},{"key":"C","text":"The depreciation of an asset"},{"key":"D","text":"COMPOUNDING (compounding finds future value; discounting finds present value)"}],"answer":"D","explanation":"FV = PV(1+r)^n and PV = FV/(1+r)^n are mirror processes.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Discounting is the inverse of:","options":["Amortisation","Leverage","Depreciation","COMPOUNDING (compounding finds future value; discounting finds present value)"],"answer":3,"explanation":"FV = PV(1+r)^n and PV = FV/(1+r)^n are mirror processes.","revision":"original","contentSignature":"9a76c120cb1e66cd26e703972a7c829f07252be2fd37acb09a9ca6046ac84ca8"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA387","optionFormat":"letter"},"contentSignature":"510b58694f9302eecc70d5a96dc04c009d3cfc6b3adf0f9db835797c4e370d46","kind":"mcq"},{"id":"deep-management-MA388","sourceNumber":388,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Purchase of a MACHINE for cash in a cash flow statement is:","options":["A financing activity of the business, shown on the financing side of the statement","An INVESTING activity (it is NOT part of operating cash flow)","Ignored altogether in the statement","An operating activity of the business, shown on the operating side of it"],"answer":1,"explanation":"Capital expenditure on machinery is investing; it never enters operating cash flow directly.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA388","number":388,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Purchase of a MACHINE for cash in a cash flow statement is:","options":[{"key":"A","text":"A financing activity of the business, shown on the financing side of the statement"},{"key":"B","text":"An INVESTING activity (it is NOT part of operating cash flow)"},{"key":"C","text":"Ignored altogether in the statement"},{"key":"D","text":"An operating activity of the business, shown on the operating side of it"}],"answer":"B","explanation":"Capital expenditure on machinery is investing; it never enters operating cash flow directly.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Purchase of a MACHINE for cash in a cash flow statement is:","options":["A financing activity","An INVESTING activity (it is NOT part of operating cash flow)","Ignored","An operating activity"],"answer":1,"explanation":"Capital expenditure on machinery is investing; it never enters operating cash flow directly.","revision":"original","contentSignature":"384147369ab5814a6fabdfe5c15add2323b949aa788c35ef3481ebceb33e88a0"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA388","optionFormat":"letter"},"contentSignature":"fe7037db1fb8762caf75fa0ce57e74982bea384b9798bf2365ca0d6e32c3d13d","kind":"mcq"},{"id":"deep-management-MA389","sourceNumber":389,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Income TAX PAID is shown in the cash flow statement under:","options":["The financing activities of the business concerned","Nowhere in the statement at all","OPERATING activities (tax on operating income)","The investing activities of the business"],"answer":2,"explanation":"AS-3 treats tax paid on operating profits as an operating outflow (tax attributable to investing/financing items goes with those items).","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA389","number":389,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"Income TAX PAID is shown in the cash flow statement under:","options":[{"key":"A","text":"The financing activities of the business concerned"},{"key":"B","text":"Nowhere in the statement at all"},{"key":"C","text":"OPERATING activities (tax on operating income)"},{"key":"D","text":"The investing activities of the business"}],"answer":"C","explanation":"AS-3 treats tax paid on operating profits as an operating outflow (tax attributable to investing/financing items goes with those items).","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Income TAX PAID is shown in the cash flow statement under:","options":["Financing activities","Nowhere","OPERATING activities (tax on operating income)","Investing activities"],"answer":2,"explanation":"AS-3 treats tax paid on operating profits as an operating outflow (tax attributable to investing/financing items goes with those items).","revision":"original","contentSignature":"2190429f8023f6b3da844a51911c81b38ef913b79ada2051c87c10e388d10657"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA389","optionFormat":"letter"},"contentSignature":"2a46ed40cb680372287c0ebf759079bc1654c61fbe634c279e174e7ad5ead992","kind":"mcq"},{"id":"deep-management-MA390","sourceNumber":390,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"If the NPV of a project is greater than zero, the project should be:","options":["Rejected at once","ACCEPTED (it adds to the wealth of shareholders)","Deferred to the following year for a fresh review","Recomputed afresh"],"answer":1,"explanation":"Positive NPV = return above the required rate; accept.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA390","number":390,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"If the NPV of a project is greater than zero, the project should be:","options":[{"key":"A","text":"Rejected at once"},{"key":"B","text":"ACCEPTED (it adds to the wealth of shareholders)"},{"key":"C","text":"Deferred to the following year for a fresh review"},{"key":"D","text":"Recomputed afresh"}],"answer":"B","explanation":"Positive NPV = return above the required rate; accept.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"If the NPV of a project is greater than zero, the project should be:","options":["Rejected","ACCEPTED (it adds to the wealth of shareholders)","Deferred","Recomputed"],"answer":1,"explanation":"Positive NPV = return above the required rate; accept.","revision":"original","contentSignature":"83e231d1738c78559e5504264e94b9944e07f6630872d048ff94ce28109de737"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA390","optionFormat":"letter"},"contentSignature":"395b939074519d2c62ba42a114cd64ddec641521cba89a1d49b0b17d9b35355a","kind":"mcq"},{"id":"deep-management-MA391","sourceNumber":391,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"A company reports EPS of Rs.8.20 and a P/E ratio of 8. The market price per share is:","options":["Rs.0.98","Rs.65.60","Rs.1.03","Rs.16.20"],"answer":1,"explanation":"MPS = EPS x P/E = 8.20 x 8 = Rs.65.60.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA391","number":391,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"A company reports EPS of Rs.8.20 and a P/E ratio of 8. The market price per share is:","options":[{"key":"A","text":"Rs.0.98"},{"key":"B","text":"Rs.65.60"},{"key":"C","text":"Rs.1.03"},{"key":"D","text":"Rs.16.20"}],"answer":"B","explanation":"MPS = EPS x P/E = 8.20 x 8 = Rs.65.60.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified"},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA391","optionFormat":"letter"},"contentSignature":"b7f70b81b1ecb2b0e97ceedf145f3a06dde8841191d23c3c23619c47804e70b5","kind":"mcq"},{"id":"deep-management-MA392","sourceNumber":392,"subject":"management-accounting","subjectName":"Management Accounting","topic":"M13 · PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The inventory turnover ratio is computed as:","options":["COST OF GOODS SOLD / AVERAGE INVENTORY","The sales of the year divided by the closing stock of the year","The purchases of the year divided by the closing stock of the year","The sales of the year divided by the average inventory of the year"],"answer":0,"explanation":"Inventory turnover = COGS / average inventory; using sales inflates it by the profit margin.","source":"Recall: JVVNL JA 2021 · Management Accounting deep bank","sourceBank":"deep-management","auditStatus":"Source key not independently verified","auditNote":"","sourceReviewStatus":"Source key not independently verified","sourceRecord":{"id":"MA392","number":392,"module":"M13","moduleTitle":"PYQ Module - UGC NET, SSC AAO, JAIIB, NABARD + JVVNL Recalls","question":"The inventory turnover ratio is computed as:","options":[{"key":"A","text":"COST OF GOODS SOLD / AVERAGE INVENTORY"},{"key":"B","text":"The sales of the year divided by the closing stock of the year"},{"key":"C","text":"The purchases of the year divided by the closing stock of the year"},{"key":"D","text":"The sales of the year divided by the average inventory of the year"}],"answer":"A","explanation":"Inventory turnover = COGS / average inventory; using sales inflates it by the profit margin.","source":"Recall: JVVNL JA 2021","auditStatus":"Source key not independently verified","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The inventory turnover ratio is computed as:","options":["COST OF GOODS SOLD / AVERAGE INVENTORY","Sales / closing stock","Purchases / closing stock","Sales / average inventory"],"answer":0,"explanation":"Inventory turnover = COGS / average inventory; using sales inflates it by the profit margin.","revision":"original","contentSignature":"e6d4ea10f29f5b032e22f197f2cebb3acf2818929cdd8c21976c11863b72ad24"}]},"legacyProgress":{"storageKey":"jvvnl-deep-study-management-accounting-v1","questionId":"MA392","optionFormat":"letter"},"contentSignature":"6bb880026aa6764289296618b9b0c8710583e44e4390a162d94364196b6b44a7","kind":"mcq"}]};
